begin;

-- Match the local test harness (psql default) regardless of the SQL Editor's session search_path; the editor may also
-- impose a statement timeout that a full install can exceed.
set local search_path = "$user", public;
set local statement_timeout = 0;

-- ---------------------------------------------------------------------------------------------------------------------
-- Guard: refuse anything that is not a brand-new Supabase project. Raises before any change.
-- ---------------------------------------------------------------------------------------------------------------------
do $cvsrs_install_guard$
declare
  v_rows bigint;
  v_found text[];
begin
  if (select count(*) from pg_catalog.pg_roles where rolname in ('anon', 'authenticated', 'service_role')) <> 3
     or pg_catalog.to_regclass('auth.users') is null
     or pg_catalog.to_regprocedure('auth.uid()') is null
     or pg_catalog.to_regprocedure('auth.jwt()') is null
     or pg_catalog.to_regnamespace('extensions') is null then
    raise exception 'CVSRS install refused: Supabase roles/auth schema/extensions schema not found. This script targets a Supabase project (local PostgreSQL needs supabase/bootstrap.sql first).';
  end if;
  if pg_catalog.to_regclass('supabase_migrations.schema_migrations') is not null then
    execute 'select count(*) from supabase_migrations.schema_migrations' into v_rows;
    if v_rows > 0 then
      raise exception 'CVSRS install refused: supabase_migrations.schema_migrations already has % row(s). fresh-install.sql is for a brand-new empty project only; to upgrade, apply only the missing migration files (supabase/install/README.md).', v_rows;
    end if;
  end if;
  if pg_catalog.to_regnamespace('private') is not null then
    raise exception 'CVSRS install refused: schema "private" already exists. Use a brand-new project or the upgrade procedure.';
  end if;
  select pg_catalog.array_agg(t order by t) into v_found
    from pg_catalog.unnest(array['antigens', 'appointment_items', 'appointments', 'barangays', 'card_submissions', 'catchup_plan_items', 'catchup_plans', 'certificate_items', 'certificates', 'checkins', 'child_clinic_enrollments', 'child_programs', 'child_staff_notes', 'children', 'clinic_sessions', 'clinical_holds', 'clinics', 'cold_chain_limits', 'content_items', 'content_versions', 'dose_credits', 'encounters', 'followup_attempts', 'followup_snapshots', 'guardian_child_relationships', 'guardians', 'messages', 'ops_checks', 'organizations', 'paper_tallies', 'privacy_records', 'product_antigens', 'profiles', 'qr_passes', 'queue_entries', 'queue_events', 'record_attachments', 'record_review_cases', 'record_transfers', 'schedule_evaluations', 'schedule_fixtures', 'schedule_rule_dependencies', 'schedule_rules', 'schedule_versions', 'sms_consents', 'sms_events', 'sms_messages', 'staff_applications', 'staff_memberships', 'stock_balances', 'stock_locations', 'stock_movements', 'stock_transactions', 'stock_transfers', 'temperature_readings', 'temperature_reviews', 'vaccination_events', 'vaccination_revisions', 'vaccine_lots', 'vaccine_products']::text[]) t
   where pg_catalog.to_regclass(pg_catalog.format('public.%I', t)) is not null;
  if v_found is not null then
    raise exception 'CVSRS install refused: public already contains table(s) that CVSRS creates: %', pg_catalog.array_to_string(v_found, ', ');
  end if;
end
$cvsrs_install_guard$;

-- ---------------------------------------------------------------------------------------------------------------------
-- Extension prerequisites. Migrations call extensions.unaccent, extensions.similarity, extensions.gin_trgm_ops,
-- extensions.gen_random_bytes and extensions.hmac but never create the extensions. A copy installed in another schema
-- (e.g. public) would leave those names unresolved, so the check below refuses it.
-- ---------------------------------------------------------------------------------------------------------------------
create extension if not exists pg_trgm with schema extensions;
create extension if not exists pgcrypto with schema extensions;
create extension if not exists unaccent with schema extensions;
do $cvsrs_extension_check$
declare v_bad text;
begin
  select pg_catalog.string_agg(e.extname || ' in ' || n.nspname, ', ') into v_bad
    from pg_catalog.pg_extension e join pg_catalog.pg_namespace n on n.oid = e.extnamespace
   where e.extname = any (array['pg_trgm', 'pgcrypto', 'unaccent']::text[]) and n.nspname <> 'extensions';
  if v_bad is not null then
    raise exception 'CVSRS install refused: extension(s) installed outside schema extensions: %. Move them (alter extension ... set schema extensions) first.', v_bad;
  end if;
end
$cvsrs_extension_check$;

-- =====================================================================================================================
-- BEGIN 0000_extensions.sql  sha256=49f8fd6f47c3bc54c02965df122cd3500d4853ff213d488192b295dee51ce2f1
-- =====================================================================================================================
-- Extensions the migrations call as extensions.* (unaccent, similarity/gin_trgm_ops, gen_random_bytes/hmac).
-- Supabase provides the extensions schema (and pgcrypto in it); pg_trgm and unaccent are not enabled on a new project.
-- Local and demo databases already get all three from supabase/bootstrap.sql, so every statement here is a no-op there.
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create extension if not exists pg_trgm with schema extensions;
create extension if not exists unaccent with schema extensions;
-- END 0000_extensions.sql

-- =====================================================================================================================
-- BEGIN 0001_foundation.sql  sha256=d73114aead50dcdb8c137bf21bdc99fe5149258675a1e6806024bc8ebd82daf2
-- =====================================================================================================================
-- 0001 Foundation: tenancy, identity profiles, staff membership, capabilities, audit, idempotent command receipts.
-- Blueprint refs: BP14, BP28.1-28.2, BP31, BP32, BP34. Requirements: F01, F05, F24.
--
-- Conventions
--  * Tables that hold health/identity data live in `public` with RLS enabled and NO direct write grants.
--    All writes go through SECURITY DEFINER commands that authorize against live membership rows.
--  * Internal evidence (audit, receipts, settings) lives in the non-exposed `private` schema.
--  * Every SECURITY DEFINER function pins `search_path = ''` and schema-qualifies all references.
--  * Errors use stable SQLSTATEs: CV400 invalid, CV401 unauthenticated, CV403 forbidden,
--    CV404 not found / not visible, CV409 conflict, CV422 unprocessable.

create schema if not exists private;
revoke all on schema private from public, anon;
-- authenticated may resolve private.* names only to call explicitly-granted RLS helper functions; no private table is granted.
grant usage on schema private to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------
-- Settings (deployment switches, never clinical rules)
-- ---------------------------------------------------------------------------------------------
create table private.settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);
insert into private.settings(key, value) values
  ('require_staff_mfa', 'true'::jsonb),      -- staff capabilities need an aal2 session (BP32)
  ('demo_mode', 'false'::jsonb);              -- synthetic data + "DEMO - NOT FOR CLINICAL USE" banners

create function private.setting_bool(p_key text) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select (value)::text::boolean from private.settings where key = p_key), false)
$$;

-- ---------------------------------------------------------------------------------------------
-- Generic triggers
-- ---------------------------------------------------------------------------------------------
create function private.touch_row() returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  new.version := old.version + 1;
  return new;
end $$;

create function private.forbid_change() returns trigger language plpgsql set search_path = '' as $$
begin
  raise exception 'table % is append-only', tg_table_name using errcode = 'CV403';
end $$;

-- ---------------------------------------------------------------------------------------------
-- Organizations, profiles, geography, clinics
-- ---------------------------------------------------------------------------------------------
create table public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) > 0),
  status text not null default 'active' check (status in ('active','suspended')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0)
);
create trigger organizations_touch before update on public.organizations for each row execute function private.touch_row();

create table public.profiles (
  id uuid primary key references auth.users (id) on delete restrict,
  display_name text not null default '' ,
  locale text not null default 'en' check (locale in ('en','fil')),
  status text not null default 'active' check (status in ('active','suspended','deactivated')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0)
);
create trigger profiles_touch before update on public.profiles for each row execute function private.touch_row();

-- Profile row is created by the server side of sign-up only; users cannot choose status/role (BP30).
create function private.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, left(coalesce(new.raw_user_meta_data ->> 'display_name', ''), 120))
  on conflict (id) do nothing;
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();

create table public.barangays (
  id uuid primary key default gen_random_uuid(),
  official_code text,
  name text not null,
  municipality text not null,
  province text not null
);
create unique index barangays_official_code_uq on public.barangays (official_code) where official_code is not null;

create table public.clinics (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  name text not null check (length(btrim(name)) > 0),
  barangay_id uuid references public.barangays (id),
  timezone text not null default 'Asia/Manila',
  contact_text text,
  address text not null default '',
  status text not null default 'active' check (status in ('active','suspended','closed')),
  operational_policy jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  unique (organization_id, id)
);
create index clinics_org_status_idx on public.clinics (organization_id, status);
create trigger clinics_touch before update on public.clinics for each row execute function private.touch_row();
-- Timezone must be a real IANA zone (local-date semantics depend on it); enforced by trigger because CHECK cannot query.
create function private.check_clinic_timezone() returns trigger language plpgsql set search_path = '' as $$
begin
  if not exists (select 1 from pg_catalog.pg_timezone_names n where n.name = new.timezone) then
    raise exception 'invalid timezone %', new.timezone using errcode = 'CV422';
  end if;
  return new;
end $$;
create trigger clinics_timezone before insert or update of timezone on public.clinics for each row execute function private.check_clinic_timezone();

-- ---------------------------------------------------------------------------------------------
-- Capabilities and staff memberships (authoritative authorization source)
-- ---------------------------------------------------------------------------------------------
create function private.capability_vocab() returns text[] language sql immutable as $$
  select array[
    'child.search','child.register','child.read_clinical','guardian.verify',
    'appointment.manage','queue.manage','vaccination.record','evidence.verify',
    'correction.approve','inventory.manage','inventory.approve','rules.propose','rules.approve',
    'certificate.issue','review.resolve','admin.users','admin.config','grant.approve.clinical',
    'audit.read','report.run','export.identifiable','bhw.followup'
  ]
$$;

-- Capabilities whose grant requires clinical governance approval rather than technical-admin approval.
create function private.clinical_caps() returns text[] language sql immutable as $$
  select array[
    'child.read_clinical','vaccination.record','evidence.verify','correction.approve','inventory.approve',
    'rules.approve','certificate.issue','review.resolve','grant.approve.clinical','audit.read','export.identifiable'
  ]
$$;

create function private.role_preset(p_role text) returns text[] language sql immutable as $$
  select case p_role
    when 'assistant'      then array['child.search','child.register','guardian.verify','appointment.manage','queue.manage']
    when 'clinical_staff' then array['child.search','child.register','child.read_clinical','guardian.verify','appointment.manage',
                                     'queue.manage','vaccination.record','evidence.verify','rules.propose']
    when 'clinical_lead'  then array['child.search','child.register','child.read_clinical','guardian.verify','appointment.manage',
                                     'queue.manage','vaccination.record','evidence.verify','rules.propose','correction.approve',
                                     'rules.approve','review.resolve','certificate.issue','audit.read','export.identifiable',
                                     'inventory.approve','grant.approve.clinical','report.run']
    when 'inventory'      then array['inventory.manage']
    when 'bhw'            then array['bhw.followup']
    when 'tech_admin'     then array['admin.users','admin.config']
    else array[]::text[]
  end
$$;

create table public.staff_memberships (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  profile_id uuid not null references public.profiles (id),
  clinic_id uuid not null,
  role_code text not null check (role_code in ('assistant','clinical_staff','clinical_lead','inventory','bhw','tech_admin')),
  capabilities text[] not null default '{}' check (capabilities <@ private.capability_vocab()),
  valid_from timestamptz not null default now(),
  valid_until timestamptz,
  status text not null default 'pending_approval' check (status in ('pending_approval','active','suspended','revoked','rejected')),
  requested_by uuid references public.profiles (id),
  approved_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  unique (organization_id, id),
  check (valid_until is null or valid_until > valid_from),
  -- Two-person control: an active grant needs an approver who is not the grantee.
  check (status <> 'active' or approved_by is not null),
  check (approved_by is null or approved_by <> profile_id)
);
create unique index staff_memberships_one_live_uq
  on public.staff_memberships (profile_id, clinic_id, role_code) where status in ('pending_approval','active');
create index staff_memberships_lookup_idx on public.staff_memberships (profile_id, status, clinic_id);
create trigger staff_memberships_touch before update on public.staff_memberships for each row execute function private.touch_row();

-- ---------------------------------------------------------------------------------------------
-- Audit and idempotent command receipts (append-only, non-exposed)
-- ---------------------------------------------------------------------------------------------
create table private.audit_logs (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid,
  actor_id uuid references public.profiles (id),
  actor_capability text,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  before jsonb,
  after jsonb,
  reason text,
  server_time timestamptz not null default clock_timestamp(),
  request_id uuid not null,
  device_id uuid,
  session_reference text,
  outcome text not null check (outcome in ('success','denied','failed')),
  system_job_id text,
  check (actor_id is not null or system_job_id is not null)
);
create index audit_entity_idx on private.audit_logs (entity_type, entity_id, server_time desc);
create index audit_actor_idx on private.audit_logs (actor_id, server_time desc);
create index audit_request_idx on private.audit_logs (request_id);
create trigger audit_logs_immutable before update or delete on private.audit_logs for each row execute function private.forbid_change();
create trigger audit_logs_no_truncate before truncate on private.audit_logs for each statement execute function private.forbid_change();

create function private.request_id() returns uuid language sql stable set search_path = '' as $$
  select coalesce(nullif(pg_catalog.current_setting('app.request_id', true), '')::uuid, gen_random_uuid())
$$;

create function private.audit(
  p_org uuid, p_capability text, p_action text, p_entity_type text, p_entity_id uuid,
  p_before jsonb, p_after jsonb, p_reason text, p_outcome text default 'success'
) returns void language plpgsql security definer set search_path = '' as $$
begin
  insert into private.audit_logs (organization_id, actor_id, actor_capability, action, entity_type, entity_id,
                                  before, after, reason, request_id, outcome, system_job_id)
  values (p_org, auth.uid(), p_capability, p_action, p_entity_type, p_entity_id, p_before, p_after, p_reason,
          private.request_id(), p_outcome, case when auth.uid() is null then 'system' end);
end $$;

create table private.command_receipts (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  operation_key uuid not null,
  actor_id uuid not null references public.profiles (id),
  device_id uuid,
  command_type text not null,
  payload_hash text not null,
  status text not null default 'in_progress' check (status in ('in_progress','completed')),
  result jsonb,
  received_at timestamptz not null default now(),
  completed_at timestamptz,
  unique (organization_id, operation_key)
);
create function private.receipt_guard() returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_op = 'DELETE' then raise exception 'receipts cannot be deleted' using errcode = 'CV403'; end if;
  if old.status = 'completed' then raise exception 'completed receipts are immutable' using errcode = 'CV403'; end if;
  return new;
end $$;
create trigger command_receipts_guard before update or delete on private.command_receipts for each row execute function private.receipt_guard();

-- Returns the stored result when this operation already completed with the same payload (idempotent replay),
-- raises CV409 when the key is reused for a different payload or actor, and returns null for a new operation.
create function private.begin_command(p_org uuid, p_key uuid, p_type text, p_payload jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_hash text := encode(sha256(convert_to(coalesce(p_payload, '{}'::jsonb)::text, 'UTF8')), 'hex');
  v_id uuid;
  r private.command_receipts;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if p_key is null then raise exception 'operation key is required' using errcode = 'CV400'; end if;
  insert into private.command_receipts (organization_id, operation_key, actor_id, command_type, payload_hash)
  values (p_org, p_key, auth.uid(), p_type, v_hash)
  on conflict (organization_id, operation_key) do nothing
  returning id into v_id;
  if v_id is not null then return null; end if;
  select * into r from private.command_receipts where organization_id = p_org and operation_key = p_key;
  if r.actor_id <> auth.uid() or r.command_type <> p_type or r.payload_hash <> v_hash then
    raise exception 'operation key reused with different content' using errcode = 'CV409';
  end if;
  return r.result;
end $$;

create function private.finish_command(p_org uuid, p_key uuid, p_result jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  update private.command_receipts set status = 'completed', result = p_result, completed_at = now()
   where organization_id = p_org and operation_key = p_key and actor_id = auth.uid();
  return p_result;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Authorization helpers (authoritative membership checks; never trust client metadata)
-- ---------------------------------------------------------------------------------------------
create function private.session_ok() returns boolean language sql stable security definer set search_path = '' as $$
  select auth.uid() is not null
     and exists (select 1 from public.profiles p where p.id = auth.uid() and p.status = 'active')
$$;

create function private.mfa_ok() returns boolean language sql stable security definer set search_path = '' as $$
  select not private.setting_bool('require_staff_mfa') or coalesce(auth.jwt() ->> 'aal', '') = 'aal2'
$$;

create function private.has_capability(p_clinic uuid, p_cap text) returns boolean
language sql stable security definer set search_path = '' as $$
  select private.session_ok() and private.mfa_ok() and exists (
    select 1
      from public.staff_memberships m
      join public.clinics c on c.id = m.clinic_id and c.organization_id = m.organization_id
     where m.profile_id = auth.uid()
       and m.clinic_id = p_clinic
       and m.status = 'active'
       and c.status = 'active'
       and m.valid_from <= now() and (m.valid_until is null or m.valid_until > now())
       and (p_cap = any (private.role_preset(m.role_code)) or p_cap = any (m.capabilities))
  )
$$;

create function private.clinics_with(p_cap text) returns setof uuid
language sql stable security definer set search_path = '' as $$
  select m.clinic_id
    from public.staff_memberships m
    join public.clinics c on c.id = m.clinic_id and c.organization_id = m.organization_id
   where private.session_ok() and private.mfa_ok()
     and m.profile_id = auth.uid() and m.status = 'active' and c.status = 'active'
     and m.valid_from <= now() and (m.valid_until is null or m.valid_until > now())
     and (p_cap = any (private.role_preset(m.role_code)) or p_cap = any (m.capabilities))
$$;

create function private.require_capability(p_clinic uuid, p_cap text) returns void
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.has_capability(p_clinic, p_cap) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Public read surface for this migration
-- ---------------------------------------------------------------------------------------------
alter table public.organizations enable row level security;
alter table public.profiles enable row level security;
alter table public.barangays enable row level security;
alter table public.clinics enable row level security;
alter table public.staff_memberships enable row level security;

revoke all on public.organizations, public.profiles, public.barangays, public.clinics, public.staff_memberships from anon, authenticated;

-- Own profile: read, and edit only safe fields (no status/role escalation: column-level grant).
grant select on public.profiles to authenticated;
grant update (display_name, locale) on public.profiles to authenticated;
create policy profiles_read_own on public.profiles for select to authenticated using (id = auth.uid());
create policy profiles_update_own on public.profiles for update to authenticated
  using (id = auth.uid() and status = 'active') with check (id = auth.uid() and status = 'active');

-- Own memberships are visible to their holder (drives the UI's clinic/role context; not an authorization source).
grant select on public.staff_memberships to authenticated;
create policy memberships_read_own on public.staff_memberships for select to authenticated using (profile_id = auth.uid());

-- Reference geography is not sensitive.
grant select on public.barangays to anon, authenticated;
create policy barangays_read on public.barangays for select to anon, authenticated using (true);

-- Public service information (P01): a curated view exposes only non-sensitive clinic columns.
create view public.public_clinics as
  select id, name, address, contact_text, timezone from public.clinics where status = 'active';
revoke all on public.public_clinics from anon, authenticated;
grant select on public.public_clinics to anon, authenticated;

-- Caller context for the UI. Does not decide authorization; every command re-checks in the database.
create function public.get_my_context() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'profileId', p.id, 'displayName', p.display_name, 'locale', p.locale, 'status', p.status,
    'mfa', private.mfa_ok(),
    'demoMode', private.setting_bool('demo_mode'),
    'memberships', coalesce((
      select jsonb_agg(jsonb_build_object('membershipId', m.id, 'clinicId', m.clinic_id, 'clinicName', c.name, 'role', m.role_code,
                                          'status', m.status, 'validUntil', m.valid_until))
        from public.staff_memberships m join public.clinics c on c.id = m.clinic_id
       where m.profile_id = p.id and m.status in ('active','pending_approval')), '[]'::jsonb))
  from public.profiles p where p.id = auth.uid()
$$;
revoke all on function public.get_my_context() from public, anon, authenticated;
grant execute on function public.get_my_context() to authenticated;

-- Helper functions in `private` are not callable by API roles (schema usage revoked) but make that explicit:
revoke all on all functions in schema private from public, anon, authenticated;
-- RLS policy helpers must be executable by the querying role:
grant execute on function private.has_capability(uuid, text), private.clinics_with(text), private.session_ok() to authenticated;
-- END 0001_foundation.sql

-- =====================================================================================================================
-- BEGIN 0002_staff_access.sql  sha256=a562f185c108c894561409fbe411f4eb75d9563df060079a31a8bab2de711b8a
-- =====================================================================================================================
-- 0002 Staff access lifecycle: request -> independent approval -> revoke. Blueprint refs: BP14, BP32, F01, T32.
-- A technical administrator can request any grant, but grants that carry clinical capability need approval from a
-- different person holding grant.approve.clinical. Nobody approves their own grant.

create function private.membership_is_clinical(p_role text, p_caps text[]) returns boolean
language sql immutable set search_path = '' as $$
  select p_role in ('clinical_staff','clinical_lead')
      or (private.role_preset(p_role) || coalesce(p_caps, '{}')) && private.clinical_caps()
$$;

create function public.request_staff_membership(
  p_operation_key uuid, p_clinic_id uuid, p_profile_id uuid, p_role text, p_capabilities text[] default '{}',
  p_valid_until timestamptz default null
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid;
  v_payload jsonb := jsonb_build_object('clinic', p_clinic_id, 'profile', p_profile_id, 'role', p_role,
                                        'caps', to_jsonb(coalesce(p_capabilities, '{}')), 'until', p_valid_until);
  v_prev jsonb;
  v_id uuid;
  v_result jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if not (private.has_capability(p_clinic_id, 'admin.users') or private.has_capability(p_clinic_id, 'grant.approve.clinical')) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'staff_membership.request', v_payload);
  if v_prev is not null then return v_prev; end if;

  if not exists (select 1 from public.profiles where id = p_profile_id and status = 'active') then
    raise exception 'profile is not active' using errcode = 'CV422';
  end if;
  if p_valid_until is not null and p_valid_until <= now() then
    raise exception 'valid_until must be in the future' using errcode = 'CV422';
  end if;

  insert into public.staff_memberships (organization_id, profile_id, clinic_id, role_code, capabilities, valid_until,
                                        status, requested_by, created_by, updated_by)
  values (v_org, p_profile_id, p_clinic_id, p_role, coalesce(p_capabilities, '{}'), p_valid_until,
          'pending_approval', auth.uid(), auth.uid(), auth.uid())
  returning id into v_id;

  perform private.audit(v_org, 'admin.users', 'staff_membership.requested', 'staff_membership', v_id, null,
                        jsonb_build_object('profile', p_profile_id, 'role', p_role, 'capabilities', p_capabilities,
                                           'clinical', private.membership_is_clinical(p_role, p_capabilities)), null);
  v_result := jsonb_build_object('membershipId', v_id, 'status', 'pending_approval',
                                 'requiresClinicalApproval', private.membership_is_clinical(p_role, p_capabilities));
  return private.finish_command(v_org, p_operation_key, v_result);
end $$;

create function public.approve_staff_membership(p_operation_key uuid, p_membership_id uuid, p_expected_version integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  m public.staff_memberships;
  v_prev jsonb;
  v_clinical boolean;
  v_needed text;
begin
  select * into m from public.staff_memberships where id = p_membership_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_clinical := private.membership_is_clinical(m.role_code, m.capabilities);
  v_needed := case when v_clinical then 'grant.approve.clinical' else 'admin.users' end;
  if not private.has_capability(m.clinic_id, v_needed) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
  v_prev := private.begin_command(m.organization_id, p_operation_key, 'staff_membership.approve',
                                  jsonb_build_object('membership', p_membership_id, 'v', p_expected_version));
  if v_prev is not null then return v_prev; end if;

  if m.status <> 'pending_approval' then raise exception 'membership is not pending' using errcode = 'CV409'; end if;
  if m.version <> p_expected_version then raise exception 'stale version' using errcode = 'CV409'; end if;
  if m.profile_id = auth.uid() then raise exception 'cannot approve own grant' using errcode = 'CV403'; end if;
  if m.requested_by = auth.uid() then raise exception 'approver must differ from requester' using errcode = 'CV403'; end if;

  update public.staff_memberships set status = 'active', approved_by = auth.uid(), updated_by = auth.uid(), valid_from = now()
   where id = m.id;
  perform private.audit(m.organization_id, v_needed, 'staff_membership.approved', 'staff_membership', m.id,
                        jsonb_build_object('status', m.status), jsonb_build_object('status', 'active'), null);
  return private.finish_command(m.organization_id, p_operation_key, jsonb_build_object('membershipId', m.id, 'status', 'active'));
end $$;

create function public.revoke_staff_membership(p_operation_key uuid, p_membership_id uuid, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  m public.staff_memberships;
  v_prev jsonb;
  v_needed text;
begin
  select * into m from public.staff_memberships where id = p_membership_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_needed := case when private.membership_is_clinical(m.role_code, m.capabilities) then 'grant.approve.clinical' else 'admin.users' end;
  if not private.has_capability(m.clinic_id, v_needed) then raise exception 'forbidden' using errcode = 'CV403'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(m.organization_id, p_operation_key, 'staff_membership.revoke',
                                  jsonb_build_object('membership', p_membership_id, 'reason', p_reason));
  if v_prev is not null then return v_prev; end if;
  if m.status not in ('active','pending_approval','suspended') then raise exception 'already closed' using errcode = 'CV409'; end if;
  update public.staff_memberships set status = 'revoked', updated_by = auth.uid() where id = m.id;
  perform private.audit(m.organization_id, v_needed, 'staff_membership.revoked', 'staff_membership', m.id,
                        jsonb_build_object('status', m.status), jsonb_build_object('status', 'revoked'), p_reason);
  return private.finish_command(m.organization_id, p_operation_key, jsonb_build_object('membershipId', m.id, 'status', 'revoked'));
end $$;

revoke all on function public.request_staff_membership(uuid, uuid, uuid, text, text[], timestamptz) from public, anon, authenticated;
revoke all on function public.approve_staff_membership(uuid, uuid, integer) from public, anon, authenticated;
revoke all on function public.revoke_staff_membership(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.request_staff_membership(uuid, uuid, uuid, text, text[], timestamptz) to authenticated;
grant execute on function public.approve_staff_membership(uuid, uuid, integer) to authenticated;
grant execute on function public.revoke_staff_membership(uuid, uuid, text) to authenticated;
revoke all on function private.membership_is_clinical(text, text[]) from public, anon, authenticated;
-- END 0002_staff_access.sql

-- =====================================================================================================================
-- BEGIN 0003_registry.sql  sha256=19e4df31135e3b0f2cd8825e8897add131e66160d0ca6fb1c0afa61d30a6e196
-- =====================================================================================================================
-- 0003 Child & guardian registry, verified relationships, clinic enrollment, review cases, QR passes.
-- Blueprint refs: BP15.A/B, BP17, BP24(partly), BP28.2, BP30, F02, F03, T01, T10, T11(registry part), T22.
--
-- Invariants enforced here
--  * A phone/name/DOB never grants access to an existing child. Link requests create a review case only.
--  * A self-created child is provisional: the guardian sees identity they entered, nothing clinical, until staff verify.
--  * Staff see only children enrolled (pending/active) at a clinic where they hold the capability.
--  * Duplicate candidates are shown to staff only; twins are never merged automatically.

-- ---------------------------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------------------------
create function private.norm_name(p text) returns text language sql stable set search_path = '' as $$
  select lower(extensions.unaccent(regexp_replace(btrim(coalesce(p, '')), '\s+', ' ', 'g')))
$$;

-- ---------------------------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------------------------
create table public.guardians (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  profile_id uuid references public.profiles (id),
  full_name text not null check (length(btrim(full_name)) > 0),
  preferred_language text not null default 'en' check (preferred_language in ('en','fil')),
  contact_phone text,
  contact_email text,
  contact_verified_at timestamptz,
  contact_status text not null default 'unverified' check (contact_status in ('unverified','verified','invalid')),
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  unique (organization_id, id)
);
-- Contact is deliberately NOT unique: families share phones (BP28.2).
create unique index guardians_profile_uq on public.guardians (organization_id, profile_id) where profile_id is not null;
create trigger guardians_touch before update on public.guardians for each row execute function private.touch_row();

create table public.children (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  local_record_no text not null,
  display_name text not null check (length(btrim(display_name)) between 1 and 200),
  given_names text,
  family_name text,
  search_name text not null default '',
  dob date,
  birth_date_precision text not null default 'unknown' check (birth_date_precision in ('exact','estimated','unknown')),
  estimated_birth_start date,
  estimated_birth_end date,
  sex_for_clinical_reference text not null default 'not_recorded' check (sex_for_clinical_reference in ('female','male','not_recorded')),
  barangay_id uuid references public.barangays (id),
  address_text text,
  birth_details jsonb,
  record_status text not null default 'provisional' check (record_status in ('provisional','active','merged','inactive')),
  merged_into_id uuid,
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  unique (organization_id, id),
  unique (organization_id, local_record_no),
  foreign key (organization_id, merged_into_id) references public.children (organization_id, id),
  check (merged_into_id is null or merged_into_id <> id),
  check ((record_status = 'merged') = (merged_into_id is not null)),
  check (
    (birth_date_precision = 'exact' and dob is not null and estimated_birth_start is null and estimated_birth_end is null)
    or (birth_date_precision = 'estimated' and dob is null and estimated_birth_start is not null
        and estimated_birth_end is not null and estimated_birth_start <= estimated_birth_end)
    or (birth_date_precision = 'unknown' and dob is null and estimated_birth_start is null and estimated_birth_end is null)
  )
);
create index children_search_trgm_idx on public.children using gin (search_name extensions.gin_trgm_ops);
create index children_dob_idx on public.children (organization_id, dob);
create index children_status_idx on public.children (organization_id, record_status);

create function private.children_before_write() returns trigger language plpgsql set search_path = '' as $$
begin
  new.search_name := private.norm_name(new.display_name);
  if new.dob is not null and (new.dob > current_date + 1 or new.dob < date '1900-01-01') then
    raise exception 'date of birth out of range' using errcode = 'CV422';
  end if;
  return new;
end $$;
create trigger children_write before insert or update on public.children for each row execute function private.children_before_write();
create trigger children_touch before update on public.children for each row execute function private.touch_row();

create table private.record_counters (organization_id uuid primary key, next_value bigint not null default 1);

create function private.next_record_no(p_org uuid) returns text language plpgsql security definer set search_path = '' as $$
declare v bigint;
begin
  insert into private.record_counters (organization_id) values (p_org) on conflict (organization_id) do nothing;
  update private.record_counters set next_value = next_value + 1 where organization_id = p_org returning next_value - 1 into v;
  return 'CV-' || lpad(v::text, 6, '0');
end $$;

create table public.guardian_child_relationships (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  guardian_id uuid not null,
  child_id uuid not null,
  relationship text not null check (relationship in ('mother','father','grandparent','aunt_uncle','sibling','legal_guardian','other')),
  status text not null check (status in ('provisional','active','suspended','revoked','rejected')),
  access_scope text not null check (access_scope in ('identity_only','full')),
  verification_method text check (verification_method in ('in_person_id','clinic_record','invitation','court_document','other')),
  verified_by uuid references public.profiles (id),
  verified_at timestamptz,
  starts_at timestamptz not null default now(),
  ends_at timestamptz,
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, guardian_id) references public.guardians (organization_id, id),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  unique (organization_id, id),
  -- Full access requires a recorded verification basis (BP28.2).
  check (status <> 'active' or (verified_by is not null and verified_at is not null and verification_method is not null and access_scope = 'full')),
  check (status <> 'provisional' or access_scope = 'identity_only')
);
create unique index gcr_one_live_pair_uq on public.guardian_child_relationships (guardian_id, child_id)
  where status in ('provisional','active','suspended');
create index gcr_child_idx on public.guardian_child_relationships (child_id, status);
create index gcr_guardian_idx on public.guardian_child_relationships (guardian_id, status);
create trigger gcr_touch before update on public.guardian_child_relationships for each row execute function private.touch_row();

create table public.child_clinic_enrollments (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  child_id uuid not null,
  clinic_id uuid not null,
  status text not null check (status in ('pending','active','closed')),
  is_primary boolean not null default false,
  access_scope text not null default 'care' check (access_scope in ('care','review_only')),
  starts_at timestamptz not null default now(),
  ends_at timestamptz,
  basis text not null check (basis in ('guardian_self_registration','clinic_registration','transfer','merge')),
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  unique (organization_id, id)
);
create unique index enrollments_one_live_pair_uq on public.child_clinic_enrollments (child_id, clinic_id) where status in ('pending','active');
create unique index enrollments_one_primary_uq on public.child_clinic_enrollments (child_id) where status = 'active' and is_primary;
create index enrollments_clinic_idx on public.child_clinic_enrollments (clinic_id, status);
create trigger enrollments_touch before update on public.child_clinic_enrollments for each row execute function private.touch_row();

create table public.record_review_cases (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  kind text not null check (kind in ('duplicate','link','identity_edit','correction','clinical','stock','sync')),
  child_id uuid,
  candidate_child_id uuid,
  guardian_id uuid,
  assigned_to uuid references public.profiles (id),
  status text not null default 'open' check (status in ('open','in_review','resolved','rejected')),
  reason text not null default '',
  evidence jsonb not null default '{}'::jsonb,
  resolution jsonb,
  resolved_by uuid references public.profiles (id),
  resolved_at timestamptz,
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, candidate_child_id) references public.children (organization_id, id),
  foreign key (organization_id, guardian_id) references public.guardians (organization_id, id),
  unique (organization_id, id),
  check (kind <> 'duplicate' or (child_id is not null and candidate_child_id is not null and child_id <> candidate_child_id)),
  check (kind <> 'link' or guardian_id is not null),
  check (kind <> 'identity_edit' or child_id is not null),
  check (status not in ('resolved','rejected') or (resolved_by is not null and resolved_at is not null))
);
create index review_cases_scope_idx on public.record_review_cases (clinic_id, status, kind);
create unique index review_cases_dup_pair_uq on public.record_review_cases
  (least(child_id, candidate_child_id), greatest(child_id, candidate_child_id)) where kind = 'duplicate' and status in ('open','in_review');
create trigger review_cases_touch before update on public.record_review_cases for each row execute function private.touch_row();

create table public.qr_passes (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  child_id uuid not null,
  token_hash text not null unique,
  status text not null default 'active' check (status in ('active','revoked','expired')),
  issued_at timestamptz not null default now(),
  expires_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, child_id) references public.children (organization_id, id)
);
create unique index qr_one_active_uq on public.qr_passes (child_id) where status = 'active';
create trigger qr_touch before update on public.qr_passes for each row execute function private.touch_row();

create table public.privacy_records (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  guardian_id uuid,
  child_id uuid,
  purpose text not null,
  record_type text not null check (record_type in ('notice_acknowledgement','contact_preference','clinical_consent_evidence','lawful_basis_documentation','access_request','correction_request','deactivation_request')),
  notice_version text not null,
  decision text not null check (decision in ('acknowledged','granted','withdrawn','requested')),
  recorded_at timestamptz not null default now(),
  evidence_ref text,
  created_at timestamptz not null default now(),
  created_by uuid references public.profiles (id),
  foreign key (organization_id, guardian_id) references public.guardians (organization_id, id),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  check (guardian_id is not null or child_id is not null)
);
create trigger privacy_records_immutable before update or delete on public.privacy_records for each row execute function private.forbid_change();

-- ---------------------------------------------------------------------------------------------
-- Access helpers (definer so RLS policies do not recurse; executable by authenticated for policy evaluation)
-- ---------------------------------------------------------------------------------------------
create function private.my_guardian_ids() returns setof uuid language sql stable security definer set search_path = '' as $$
  select g.id from public.guardians g where g.profile_id = auth.uid() and g.deleted_at is null and private.session_ok()
$$;

create function private.guardian_can_read_child(p_child uuid) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.guardian_child_relationships r
     where r.child_id = p_child and r.guardian_id in (select private.my_guardian_ids())
       and r.status in ('provisional','active') and (r.ends_at is null or r.ends_at > now())
  )
$$;

create function private.guardian_has_full_access(p_child uuid) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.guardian_child_relationships r
     where r.child_id = p_child and r.guardian_id in (select private.my_guardian_ids())
       and r.status = 'active' and r.access_scope = 'full' and (r.ends_at is null or r.ends_at > now())
  )
$$;

create function private.child_in_clinic(p_child uuid, p_clinic uuid) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.child_clinic_enrollments e
                  where e.child_id = p_child and e.clinic_id = p_clinic and e.status in ('pending','active'))
$$;

-- Follows merge pointers (bounded) so aliases resolve to the canonical child (T11).
create function private.canonical_child(p_child uuid) returns uuid language plpgsql stable security definer set search_path = '' as $$
declare v uuid := p_child; nxt uuid; i int := 0;
begin
  loop
    select merged_into_id into nxt from public.children where id = v;
    exit when nxt is null or i >= 10;
    v := nxt; i := i + 1;
  end loop;
  return v;
end $$;

-- Validates and normalizes untrusted child input; returns typed-as-text jsonb or raises CV422.
create function private.clean_child_input(p jsonb) returns jsonb language plpgsql stable set search_path = '' as $$
declare
  v_given text := nullif(left(btrim(coalesce(p ->> 'givenNames', '')), 120), '');
  v_family text := nullif(left(btrim(coalesce(p ->> 'familyName', '')), 120), '');
  v_display text := nullif(left(regexp_replace(btrim(coalesce(p ->> 'displayName', '')), '\s+', ' ', 'g'), 200), '');
  v_prec text := coalesce(p ->> 'dobPrecision', case when p ? 'dob' and nullif(p ->> 'dob', '') is not null then 'exact' else 'unknown' end);
  v_dob date; v_es date; v_ee date;
  v_sex text := coalesce(nullif(p ->> 'sex', ''), 'not_recorded');
  v_bar uuid;
begin
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'child details required' using errcode = 'CV400'; end if;
  v_display := coalesce(v_display, nullif(btrim(concat_ws(' ', v_given, v_family)), ''));
  if v_display is null then raise exception 'child name is required' using errcode = 'CV422'; end if;
  if v_prec not in ('exact','estimated','unknown') then raise exception 'invalid dob precision' using errcode = 'CV422'; end if;
  begin
    if v_prec = 'exact' then v_dob := (p ->> 'dob')::date; end if;
    if v_prec = 'estimated' then v_es := (p ->> 'estimatedBirthStart')::date; v_ee := (p ->> 'estimatedBirthEnd')::date; end if;
    if p ->> 'barangayId' is not null and p ->> 'barangayId' <> '' then v_bar := (p ->> 'barangayId')::uuid; end if;
  exception when others then
    raise exception 'invalid date or identifier' using errcode = 'CV422';
  end;
  if v_prec = 'exact' and v_dob is null then raise exception 'date of birth required for exact precision' using errcode = 'CV422'; end if;
  if v_prec = 'estimated' and (v_es is null or v_ee is null or v_es > v_ee) then
    raise exception 'estimated birth range invalid' using errcode = 'CV422';
  end if;
  if v_sex not in ('female','male','not_recorded') then raise exception 'invalid sex code' using errcode = 'CV422'; end if;
  return jsonb_build_object(
    'displayName', v_display, 'givenNames', v_given, 'familyName', v_family, 'dobPrecision', v_prec,
    'dob', v_dob, 'estimatedBirthStart', v_es, 'estimatedBirthEnd', v_ee, 'sex', v_sex, 'barangayId', v_bar,
    'addressText', nullif(left(btrim(coalesce(p ->> 'addressText', '')), 500), ''));
end $$;

-- Candidate duplicates among children enrolled at the SAME clinic. Similar names on the same DOB (twins!) are
-- reported, never merged. Names are only a search aid, not identity (BP28.7).
create function private.child_candidates(p_clinic uuid, p_name text, p_dob date, p_exclude uuid default null)
returns table (child_id uuid, score real, same_dob boolean) language sql stable security definer set search_path = '' as $$
  select c.id, extensions.similarity(c.search_name, private.norm_name(p_name))::real,
         (p_dob is not null and c.dob = p_dob)
    from public.children c
   where c.record_status in ('provisional','active')
     and c.id is distinct from p_exclude
     and exists (select 1 from public.child_clinic_enrollments e where e.child_id = c.id and e.clinic_id = p_clinic and e.status in ('pending','active'))
     and ((p_dob is not null and c.dob = p_dob and extensions.similarity(c.search_name, private.norm_name(p_name)) >= 0.3)
          or extensions.similarity(c.search_name, private.norm_name(p_name)) >= 0.6)
   order by 2 desc, 1
   limit 5
$$;

create function private.ensure_guardian(p_org uuid, p_name text default null) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v uuid;
begin
  select id into v from public.guardians where organization_id = p_org and profile_id = auth.uid();
  if v is not null then return v; end if;
  insert into public.guardians (organization_id, profile_id, full_name, preferred_language, created_by, updated_by)
  select p_org, p.id, coalesce(nullif(btrim(p_name), ''), nullif(btrim(p.display_name), ''), 'Guardian'), p.locale, p.id, p.id
    from public.profiles p where p.id = auth.uid()
  returning id into v;
  return v;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Direct read policies (guardian-owned data only). Staff read identifiable data only via audited commands.
-- ---------------------------------------------------------------------------------------------
alter table public.guardians enable row level security;
alter table public.children enable row level security;
alter table public.guardian_child_relationships enable row level security;
alter table public.child_clinic_enrollments enable row level security;
alter table public.record_review_cases enable row level security;
alter table public.qr_passes enable row level security;
alter table public.privacy_records enable row level security;

revoke all on public.guardians, public.children, public.guardian_child_relationships, public.child_clinic_enrollments,
              public.record_review_cases, public.qr_passes, public.privacy_records from anon, authenticated;

grant select on public.guardians, public.children, public.guardian_child_relationships to authenticated;
create policy guardians_read_own on public.guardians for select to authenticated using (id in (select private.my_guardian_ids()));
create policy children_read_linked on public.children for select to authenticated using (private.guardian_can_read_child(id));
create policy gcr_read_own on public.guardian_child_relationships for select to authenticated using (guardian_id in (select private.my_guardian_ids()));

revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function private.has_capability(uuid, text), private.clinics_with(text), private.session_ok(),
  private.my_guardian_ids(), private.guardian_can_read_child(uuid) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- Commands
-- ---------------------------------------------------------------------------------------------

-- Guardian self-service: a NEW provisional child. Never reveals whether a similar record exists (BP15.A, T10).
create function public.create_child_provisional(p_operation_key uuid, p_clinic_id uuid, p_child jsonb, p_relationship text default 'mother')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_clean jsonb; v_prev jsonb; v_child uuid; v_no text; v_guardian uuid; v_cand record;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.session_ok() then raise exception 'forbidden' using errcode = 'CV403'; end if;
  select organization_id into v_org from public.clinics where id = p_clinic_id and status = 'active';
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'child.create_provisional',
                                  jsonb_build_object('clinic', p_clinic_id, 'child', p_child, 'rel', p_relationship));
  if v_prev is not null then return v_prev; end if;
  v_clean := private.clean_child_input(p_child);
  v_guardian := private.ensure_guardian(v_org);
  v_no := private.next_record_no(v_org);

  insert into public.children (organization_id, local_record_no, display_name, given_names, family_name, dob, birth_date_precision,
                               estimated_birth_start, estimated_birth_end, sex_for_clinical_reference, barangay_id, address_text,
                               record_status, created_by, updated_by)
  values (v_org, v_no, v_clean ->> 'displayName', v_clean ->> 'givenNames', v_clean ->> 'familyName', (v_clean ->> 'dob')::date,
          v_clean ->> 'dobPrecision', (v_clean ->> 'estimatedBirthStart')::date, (v_clean ->> 'estimatedBirthEnd')::date,
          v_clean ->> 'sex', (v_clean ->> 'barangayId')::uuid, v_clean ->> 'addressText', 'provisional', auth.uid(), auth.uid())
  returning id into v_child;

  insert into public.guardian_child_relationships (organization_id, guardian_id, child_id, relationship, status, access_scope, created_by, updated_by)
  values (v_org, v_guardian, v_child, p_relationship, 'provisional', 'identity_only', auth.uid(), auth.uid());
  insert into public.child_clinic_enrollments (organization_id, child_id, clinic_id, status, is_primary, access_scope, basis, created_by, updated_by)
  values (v_org, v_child, p_clinic_id, 'pending', false, 'review_only', 'guardian_self_registration', auth.uid(), auth.uid());

  for v_cand in select * from private.child_candidates(p_clinic_id, v_clean ->> 'displayName', (v_clean ->> 'dob')::date, v_child) loop
    insert into public.record_review_cases (organization_id, clinic_id, kind, child_id, candidate_child_id, reason, evidence, created_by, updated_by)
    values (v_org, p_clinic_id, 'duplicate', v_child, v_cand.child_id, 'possible duplicate on guardian self-registration',
            jsonb_build_object('score', v_cand.score, 'sameDob', v_cand.same_dob), auth.uid(), auth.uid())
    on conflict do nothing;
  end loop;

  perform private.audit(v_org, 'guardian', 'child.created_provisional', 'child', v_child, null,
                        jsonb_build_object('localRecordNo', v_no, 'status', 'provisional'), null);
  -- Identical shape whether or not candidates exist: no matching-record oracle for unverified users.
  return private.finish_command(v_org, p_operation_key, jsonb_build_object(
    'childId', v_child, 'localRecordNo', v_no, 'recordStatus', 'provisional', 'verificationPending', true));
end $$;

-- Staff registration (walk-in, assisted). Returns duplicate candidates first unless the registrar confirms none applies.
create function public.register_child_staff(
  p_operation_key uuid, p_clinic_id uuid, p_child jsonb, p_guardian jsonb default null,
  p_confirmed_distinct boolean default false, p_identity_confirmed boolean default false
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_clean jsonb; v_prev jsonb; v_child uuid; v_no text; v_guardian uuid; v_status text;
  v_cands jsonb; v_gname text; v_rel text; v_verified boolean;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'child.register');
  v_prev := private.begin_command(v_org, p_operation_key, 'child.register_staff',
    jsonb_build_object('clinic', p_clinic_id, 'child', p_child, 'guardian', p_guardian, 'distinct', p_confirmed_distinct, 'idc', p_identity_confirmed));
  if v_prev is not null then return v_prev; end if;
  v_clean := private.clean_child_input(p_child);

  select coalesce(jsonb_agg(jsonb_build_object('childId', c.id, 'displayName', c.display_name, 'localRecordNo', c.local_record_no,
                                               'dob', c.dob, 'score', k.score, 'sameDob', k.same_dob)), '[]'::jsonb)
    into v_cands
    from private.child_candidates(p_clinic_id, v_clean ->> 'displayName', (v_clean ->> 'dob')::date) k
    join public.children c on c.id = k.child_id;
  if jsonb_array_length(v_cands) > 0 and not p_confirmed_distinct then
    return private.finish_command(v_org, p_operation_key, jsonb_build_object('created', false, 'candidates', v_cands));
  end if;

  v_no := private.next_record_no(v_org);
  v_status := case when p_identity_confirmed then 'active' else 'provisional' end;
  insert into public.children (organization_id, local_record_no, display_name, given_names, family_name, dob, birth_date_precision,
                               estimated_birth_start, estimated_birth_end, sex_for_clinical_reference, barangay_id, address_text,
                               record_status, created_by, updated_by)
  values (v_org, v_no, v_clean ->> 'displayName', v_clean ->> 'givenNames', v_clean ->> 'familyName', (v_clean ->> 'dob')::date,
          v_clean ->> 'dobPrecision', (v_clean ->> 'estimatedBirthStart')::date, (v_clean ->> 'estimatedBirthEnd')::date,
          v_clean ->> 'sex', (v_clean ->> 'barangayId')::uuid, v_clean ->> 'addressText', v_status, auth.uid(), auth.uid())
  returning id into v_child;
  insert into public.child_clinic_enrollments (organization_id, child_id, clinic_id, status, is_primary, access_scope, basis, created_by, updated_by)
  values (v_org, v_child, p_clinic_id, case when p_identity_confirmed then 'active' else 'pending' end, p_identity_confirmed,
          case when p_identity_confirmed then 'care' else 'review_only' end, 'clinic_registration', auth.uid(), auth.uid());

  -- Accompanying adult (no account needed). Relationship is 'active' only if the registrar verified authority in person.
  if p_guardian is not null and nullif(btrim(p_guardian ->> 'fullName'), '') is not null then
    v_gname := left(btrim(p_guardian ->> 'fullName'), 200);
    v_rel := coalesce(nullif(p_guardian ->> 'relationship', ''), 'other');
    v_verified := coalesce((p_guardian ->> 'verifiedInPerson')::boolean, false);
    insert into public.guardians (organization_id, full_name, contact_phone, contact_email, created_by, updated_by)
    values (v_org, v_gname, nullif(left(btrim(coalesce(p_guardian ->> 'phone', '')), 40), ''), nullif(left(btrim(coalesce(p_guardian ->> 'email', '')), 200), ''), auth.uid(), auth.uid())
    returning id into v_guardian;
    if v_verified then
      insert into public.guardian_child_relationships (organization_id, guardian_id, child_id, relationship, status, access_scope,
                                                       verification_method, verified_by, verified_at, created_by, updated_by)
      values (v_org, v_guardian, v_child, v_rel, 'active', 'full', 'in_person_id', auth.uid(), now(), auth.uid(), auth.uid());
    else
      insert into public.guardian_child_relationships (organization_id, guardian_id, child_id, relationship, status, access_scope, created_by, updated_by)
      values (v_org, v_guardian, v_child, v_rel, 'provisional', 'identity_only', auth.uid(), auth.uid());
    end if;
  end if;

  if jsonb_array_length(v_cands) > 0 then
    insert into public.record_review_cases (organization_id, clinic_id, kind, child_id, candidate_child_id, reason, evidence, created_by, updated_by)
    select v_org, p_clinic_id, 'duplicate', v_child, (x ->> 'childId')::uuid, 'registrar confirmed distinct despite candidate',
           jsonb_build_object('score', x -> 'score', 'sameDob', x -> 'sameDob', 'registrarConfirmedDistinct', true), auth.uid(), auth.uid()
      from jsonb_array_elements(v_cands) x;
  end if;
  perform private.audit(v_org, 'child.register', 'child.registered', 'child', v_child, null,
                        jsonb_build_object('localRecordNo', v_no, 'status', v_status, 'candidates', jsonb_array_length(v_cands)), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('created', true, 'childId', v_child,
                                'localRecordNo', v_no, 'recordStatus', v_status, 'candidates', v_cands));
end $$;

-- Clinic-scoped search: bounded, audited (query text is never stored), never crosses clinics.
create function public.staff_search_children(p_clinic_id uuid, p_query text, p_dob date default null, p_limit integer default 20)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_q text := private.norm_name(p_query); v_like text; v_res jsonb; v_lim int := least(greatest(coalesce(p_limit, 20), 1), 25);
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'forbidden' using errcode = 'CV403'; end if;
  perform private.require_capability(p_clinic_id, 'child.search');
  if length(v_q) < 2 and p_dob is null then raise exception 'query too short' using errcode = 'CV422'; end if;
  v_like := '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  select coalesce(jsonb_agg(x order by (x ->> 'rank')::real desc, x ->> 'displayName'), '[]'::jsonb) into v_res from (
    select jsonb_build_object('childId', c.id, 'displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob,
                              'dobPrecision', c.birth_date_precision, 'recordStatus', c.record_status,
                              'rank', greatest(extensions.similarity(c.search_name, v_q), case when c.search_name like v_like then 0.9 else 0 end,
                                               case when upper(btrim(p_query)) = c.local_record_no then 1 else 0 end)) x
      from public.children c
     where c.record_status in ('provisional','active')
       and exists (select 1 from public.child_clinic_enrollments e where e.child_id = c.id and e.clinic_id = p_clinic_id and e.status in ('pending','active'))
       and (p_dob is null or c.dob = p_dob)
       and (length(v_q) < 2 or c.search_name like v_like or extensions.similarity(c.search_name, v_q) >= 0.3 or upper(btrim(p_query)) = c.local_record_no)
     limit v_lim) s;
  perform private.audit(v_org, 'child.search', 'child.search', 'clinic', p_clinic_id, null,
                        jsonb_build_object('queryLength', length(v_q), 'withDob', p_dob is not null, 'results', jsonb_array_length(v_res)), null);
  return v_res;
end $$;

create function public.staff_get_child(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; c public.children; v_canon uuid; v_can_verify boolean; v_out jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'child.search');
  v_canon := private.canonical_child(p_child_id);
  select * into c from public.children where id = v_canon and organization_id = v_org;
  -- Same response for "does not exist" and "not in your clinic": no existence oracle.
  if not found or not private.child_in_clinic(v_canon, p_clinic_id) then
    -- Return null instead of raising: an exception would roll back the denial audit row. The API maps null to 404.
    perform private.audit(v_org, 'child.search', 'child.open', 'child', p_child_id, null, null, null, 'denied');
    return null;
  end if;
  v_can_verify := private.has_capability(p_clinic_id, 'guardian.verify');
  select jsonb_build_object(
    'childId', c.id, 'requestedChildId', p_child_id, 'aliasResolved', c.id <> p_child_id,
    'localRecordNo', c.local_record_no, 'displayName', c.display_name, 'givenNames', c.given_names, 'familyName', c.family_name,
    'dob', c.dob, 'dobPrecision', c.birth_date_precision, 'estimatedBirthStart', c.estimated_birth_start, 'estimatedBirthEnd', c.estimated_birth_end,
    'sex', c.sex_for_clinical_reference, 'addressText', c.address_text, 'recordStatus', c.record_status, 'version', c.version,
    'guardians', coalesce((select jsonb_agg(jsonb_build_object(
        'relationshipId', r.id, 'name', g.full_name, 'relationship', r.relationship, 'status', r.status, 'hasAccount', g.profile_id is not null,
        'phone', case when v_can_verify then g.contact_phone end, 'email', case when v_can_verify then g.contact_email end))
      from public.guardian_child_relationships r join public.guardians g on g.id = r.guardian_id
      where r.child_id = c.id and r.status in ('provisional','active','suspended')), '[]'::jsonb),
    'enrollments', coalesce((select jsonb_agg(jsonb_build_object('clinicId', e.clinic_id, 'status', e.status, 'primary', e.is_primary))
      from public.child_clinic_enrollments e where e.child_id = c.id and e.clinic_id = p_clinic_id and e.status in ('pending','active')), '[]'::jsonb))
    into v_out;
  perform private.audit(v_org, 'child.search', 'child.open', 'child', c.id, null, null, null);
  return v_out;
end $$;

create function public.confirm_child_identity(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_expected_version integer, p_note text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; c public.children; v_prev jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'child.register');
  v_prev := private.begin_command(v_org, p_operation_key, 'child.confirm_identity',
                                  jsonb_build_object('clinic', p_clinic_id, 'child', p_child_id, 'v', p_expected_version));
  if v_prev is not null then return v_prev; end if;
  select * into c from public.children where id = p_child_id and organization_id = v_org for update;
  if not found or not private.child_in_clinic(p_child_id, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if c.version <> p_expected_version then raise exception 'stale version' using errcode = 'CV409'; end if;
  if c.record_status <> 'provisional' then raise exception 'child is not provisional' using errcode = 'CV409'; end if;
  update public.children set record_status = 'active', updated_by = auth.uid() where id = c.id;
  update public.child_clinic_enrollments set status = 'active', access_scope = 'care', updated_by = auth.uid()
   where child_id = c.id and clinic_id = p_clinic_id and status = 'pending';
  -- The first activated enrollment becomes primary if the child has none.
  update public.child_clinic_enrollments set is_primary = true
   where child_id = c.id and clinic_id = p_clinic_id and status = 'active'
     and not exists (select 1 from public.child_clinic_enrollments x where x.child_id = c.id and x.status = 'active' and x.is_primary);
  perform private.audit(v_org, 'child.register', 'child.identity_confirmed', 'child', c.id,
                        jsonb_build_object('recordStatus', c.record_status), jsonb_build_object('recordStatus', 'active'), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('childId', c.id, 'recordStatus', 'active'));
end $$;

-- Staff identity edits: optimistic versioning, reason for identity-defining fields, before/after audited.
create function public.update_child_identity(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_expected_version integer, p_patch jsonb, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; c public.children; v_prev jsonb; v_merged jsonb; v_clean jsonb; v_sensitive boolean;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'child.register');
  v_prev := private.begin_command(v_org, p_operation_key, 'child.update_identity',
                                  jsonb_build_object('clinic', p_clinic_id, 'child', p_child_id, 'v', p_expected_version, 'patch', p_patch, 'reason', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into c from public.children where id = p_child_id and organization_id = v_org for update;
  if not found or not private.child_in_clinic(p_child_id, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if c.version <> p_expected_version then raise exception 'stale version' using errcode = 'CV409'; end if;
  if c.record_status = 'merged' then raise exception 'record is merged' using errcode = 'CV409'; end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb then raise exception 'empty patch' using errcode = 'CV400'; end if;
  if exists (select 1 from jsonb_object_keys(p_patch) k where k not in
      ('displayName','givenNames','familyName','dob','dobPrecision','estimatedBirthStart','estimatedBirthEnd','sex','barangayId','addressText')) then
    raise exception 'patch contains fields that cannot be edited here' using errcode = 'CV422';
  end if;
  v_sensitive := p_patch ?| array['displayName','givenNames','familyName','dob','dobPrecision','estimatedBirthStart','estimatedBirthEnd','sex'];
  if v_sensitive and (p_reason is null or length(btrim(p_reason)) < 3) then raise exception 'reason required for identity changes' using errcode = 'CV422'; end if;

  -- Merge the patch over current values, then re-validate as a whole.
  v_merged := jsonb_build_object('displayName', c.display_name, 'givenNames', c.given_names, 'familyName', c.family_name,
    'dob', c.dob, 'dobPrecision', c.birth_date_precision, 'estimatedBirthStart', c.estimated_birth_start,
    'estimatedBirthEnd', c.estimated_birth_end, 'sex', c.sex_for_clinical_reference, 'barangayId', c.barangay_id, 'addressText', c.address_text) || p_patch;
  -- Changing precision must clear the fields that no longer apply.
  if p_patch ? 'dobPrecision' then
    if (p_patch ->> 'dobPrecision') <> 'exact' then v_merged := v_merged || jsonb_build_object('dob', null); end if;
    if (p_patch ->> 'dobPrecision') <> 'estimated' then v_merged := v_merged || jsonb_build_object('estimatedBirthStart', null, 'estimatedBirthEnd', null); end if;
  end if;
  v_clean := private.clean_child_input(v_merged);
  update public.children set display_name = v_clean ->> 'displayName', given_names = v_clean ->> 'givenNames', family_name = v_clean ->> 'familyName',
    dob = (v_clean ->> 'dob')::date, birth_date_precision = v_clean ->> 'dobPrecision',
    estimated_birth_start = (v_clean ->> 'estimatedBirthStart')::date, estimated_birth_end = (v_clean ->> 'estimatedBirthEnd')::date,
    sex_for_clinical_reference = v_clean ->> 'sex', barangay_id = (v_clean ->> 'barangayId')::uuid, address_text = v_clean ->> 'addressText',
    updated_by = auth.uid()
   where id = c.id;
  perform private.audit(v_org, 'child.register', 'child.identity_updated', 'child', c.id,
    jsonb_build_object('displayName', c.display_name, 'dob', c.dob, 'dobPrecision', c.birth_date_precision, 'sex', c.sex_for_clinical_reference, 'addressText', c.address_text),
    v_clean, p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('childId', c.id, 'version', c.version + 1));
end $$;

-- Guardian asks for a correction; staff decide. No direct guardian write to identity.
create function public.request_child_edit(p_operation_key uuid, p_child_id uuid, p_patch jsonb, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_clinic uuid; v_prev jsonb; v_case uuid; v_guardian uuid;
begin
  if not private.guardian_can_read_child(p_child_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  select organization_id into v_org from public.children where id = p_child_id;
  select clinic_id into v_clinic from public.child_clinic_enrollments where child_id = p_child_id and status in ('pending','active') order by is_primary desc, created_at limit 1;
  if v_clinic is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'child.request_edit', jsonb_build_object('child', p_child_id, 'patch', p_patch, 'reason', p_reason));
  if v_prev is not null then return v_prev; end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then raise exception 'patch required' using errcode = 'CV400'; end if;
  select id into v_guardian from public.guardians where organization_id = v_org and profile_id = auth.uid();
  insert into public.record_review_cases (organization_id, clinic_id, kind, child_id, guardian_id, reason, evidence, created_by, updated_by)
  values (v_org, v_clinic, 'identity_edit', p_child_id, v_guardian, left(coalesce(p_reason, ''), 500), jsonb_build_object('patch', p_patch), auth.uid(), auth.uid())
  returning id into v_case;
  perform private.audit(v_org, 'guardian', 'child.edit_requested', 'child', p_child_id, null, jsonb_build_object('caseId', v_case), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('caseId', v_case, 'status', 'open'));
end $$;

-- Guardian asks to be linked to an EXISTING child. The request never touches the child record and returns no matches.
create function public.request_guardian_link(p_operation_key uuid, p_clinic_id uuid, p_descriptor jsonb, p_relationship text default 'other')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_g uuid; v_case uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.session_ok() then raise exception 'forbidden' using errcode = 'CV403'; end if;
  select organization_id into v_org from public.clinics where id = p_clinic_id and status = 'active';
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'guardian.request_link',
                                  jsonb_build_object('clinic', p_clinic_id, 'descriptor', p_descriptor, 'rel', p_relationship));
  if v_prev is not null then return v_prev; end if;
  if p_descriptor is null or jsonb_typeof(p_descriptor) <> 'object' or nullif(btrim(p_descriptor ->> 'childName'), '') is null then
    raise exception 'child name is required' using errcode = 'CV422';
  end if;
  if p_relationship not in ('mother','father','grandparent','aunt_uncle','sibling','legal_guardian','other') then raise exception 'invalid relationship' using errcode = 'CV422'; end if;
  v_g := private.ensure_guardian(v_org);
  insert into public.record_review_cases (organization_id, clinic_id, kind, guardian_id, reason, evidence, created_by, updated_by)
  values (v_org, p_clinic_id, 'link', v_g, 'guardian requests link to existing record',
          jsonb_build_object('childName', left(btrim(p_descriptor ->> 'childName'), 200), 'dob', left(coalesce(p_descriptor ->> 'dob', ''), 10),
                             'relationship', p_relationship, 'note', left(coalesce(p_descriptor ->> 'note', ''), 500)), auth.uid(), auth.uid())
  returning id into v_case;
  perform private.audit(v_org, 'guardian', 'guardian.link_requested', 'review_case', v_case, null, jsonb_build_object('clinic', p_clinic_id), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('caseId', v_case, 'status', 'open'));
end $$;

-- Staff decision on a link request. Approval requires the child to be in the reviewer's clinic scope.
create function public.resolve_link_case(p_operation_key uuid, p_case_id uuid, p_decision text, p_child_id uuid default null,
                                         p_method text default 'in_person_id', p_reason text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_case public.record_review_cases; v_prev jsonb; v_rel text; v_existing uuid;
begin
  select * into v_case from public.record_review_cases where id = p_case_id and kind = 'link' for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(v_case.clinic_id, 'guardian.verify');
  v_prev := private.begin_command(v_case.organization_id, p_operation_key, 'guardian.resolve_link',
    jsonb_build_object('case', p_case_id, 'decision', p_decision, 'child', p_child_id, 'method', p_method, 'reason', p_reason));
  if v_prev is not null then return v_prev; end if;
  if v_case.status not in ('open','in_review') then raise exception 'case already resolved' using errcode = 'CV409'; end if;
  if p_decision not in ('approve','reject') then raise exception 'invalid decision' using errcode = 'CV422'; end if;
  if p_decision = 'reject' then
    if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
    update public.record_review_cases set status = 'rejected', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
           resolution = jsonb_build_object('decision', 'reject', 'reason', p_reason) where id = v_case.id;
    perform private.audit(v_case.organization_id, 'guardian.verify', 'guardian.link_rejected', 'review_case', v_case.id, null, null, p_reason);
    return private.finish_command(v_case.organization_id, p_operation_key, jsonb_build_object('caseId', v_case.id, 'status', 'rejected'));
  end if;
  if p_child_id is null or not private.child_in_clinic(p_child_id, v_case.clinic_id) then raise exception 'child not in clinic scope' using errcode = 'CV404'; end if;
  p_child_id := private.canonical_child(p_child_id);
  if p_method not in ('in_person_id','clinic_record','invitation','court_document','other') then raise exception 'invalid verification method' using errcode = 'CV422'; end if;
  v_rel := coalesce(v_case.evidence ->> 'relationship', 'other');
  select id into v_existing from public.guardian_child_relationships
   where guardian_id = v_case.guardian_id and child_id = p_child_id and status in ('provisional','active','suspended') for update;
  if v_existing is not null then
    update public.guardian_child_relationships set status = 'active', access_scope = 'full', verification_method = p_method,
           verified_by = auth.uid(), verified_at = now(), updated_by = auth.uid() where id = v_existing and status <> 'suspended';
  else
    insert into public.guardian_child_relationships (organization_id, guardian_id, child_id, relationship, status, access_scope, verification_method, verified_by, verified_at, created_by, updated_by)
    values (v_case.organization_id, v_case.guardian_id, p_child_id, v_rel, 'active', 'full', p_method, auth.uid(), now(), auth.uid(), auth.uid());
  end if;
  update public.record_review_cases set status = 'resolved', child_id = p_child_id, resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', 'approve', 'method', p_method) where id = v_case.id;
  perform private.audit(v_case.organization_id, 'guardian.verify', 'guardian.link_approved', 'child', p_child_id, null,
                        jsonb_build_object('guardian', v_case.guardian_id, 'method', p_method), p_reason);
  return private.finish_command(v_case.organization_id, p_operation_key, jsonb_build_object('caseId', v_case.id, 'status', 'resolved', 'childId', p_child_id));
end $$;

create function public.verify_relationship(p_operation_key uuid, p_clinic_id uuid, p_relationship_id uuid, p_method text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare r public.guardian_child_relationships; v_org uuid; v_prev jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'guardian.verify');
  v_prev := private.begin_command(v_org, p_operation_key, 'relationship.verify', jsonb_build_object('clinic', p_clinic_id, 'rel', p_relationship_id, 'method', p_method));
  if v_prev is not null then return v_prev; end if;
  select * into r from public.guardian_child_relationships where id = p_relationship_id and organization_id = v_org for update;
  if not found or not private.child_in_clinic(r.child_id, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if r.status <> 'provisional' then raise exception 'relationship is not provisional' using errcode = 'CV409'; end if;
  if p_method not in ('in_person_id','clinic_record','invitation','court_document','other') then raise exception 'invalid verification method' using errcode = 'CV422'; end if;
  update public.guardian_child_relationships set status = 'active', access_scope = 'full', verification_method = p_method,
         verified_by = auth.uid(), verified_at = now(), updated_by = auth.uid() where id = r.id;
  perform private.audit(v_org, 'guardian.verify', 'relationship.verified', 'relationship', r.id, jsonb_build_object('status', r.status), jsonb_build_object('status', 'active'), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('relationshipId', r.id, 'status', 'active'));
end $$;

-- Suspend (dispute) or revoke access without touching the care record or anyone else's relationship (BP41).
create function public.set_relationship_status(p_operation_key uuid, p_clinic_id uuid, p_relationship_id uuid, p_status text, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare r public.guardian_child_relationships; v_org uuid; v_prev jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'guardian.verify');
  if p_status not in ('suspended','revoked','active') then raise exception 'invalid status' using errcode = 'CV422'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'relationship.set_status', jsonb_build_object('clinic', p_clinic_id, 'rel', p_relationship_id, 'status', p_status, 'reason', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into r from public.guardian_child_relationships where id = p_relationship_id and organization_id = v_org for update;
  if not found or not private.child_in_clinic(r.child_id, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if r.status not in ('active','suspended','provisional') then raise exception 'relationship is closed' using errcode = 'CV409'; end if;
  if p_status = 'active' and r.verified_by is null then raise exception 'verify the relationship instead' using errcode = 'CV409'; end if;
  update public.guardian_child_relationships set status = p_status, ends_at = case when p_status = 'revoked' then now() else null end, updated_by = auth.uid() where id = r.id;
  perform private.audit(v_org, 'guardian.verify', 'relationship.status_changed', 'relationship', r.id, jsonb_build_object('status', r.status), jsonb_build_object('status', p_status), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('relationshipId', r.id, 'status', p_status));
end $$;

-- Merge a confirmed duplicate into a survivor. Names/DOB alone never trigger this; a reviewer decides (T10/T11).
create function public.merge_children(p_operation_key uuid, p_clinic_id uuid, p_survivor uuid, p_duplicate uuid, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; s public.children; d public.children; rel record;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'review.resolve');
  if p_survivor = p_duplicate then raise exception 'cannot merge a record into itself' using errcode = 'CV422'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'child.merge', jsonb_build_object('clinic', p_clinic_id, 's', p_survivor, 'd', p_duplicate, 'reason', p_reason));
  if v_prev is not null then return v_prev; end if;
  -- Lock in a stable order to avoid deadlocks between concurrent merges.
  perform 1 from public.children where id in (p_survivor, p_duplicate) order by id for update;
  select * into s from public.children where id = p_survivor and organization_id = v_org;
  select * into d from public.children where id = p_duplicate and organization_id = v_org;
  if s.id is null or d.id is null or not private.child_in_clinic(s.id, p_clinic_id) or not private.child_in_clinic(d.id, p_clinic_id) then
    raise exception 'not found' using errcode = 'CV404';
  end if;
  if s.record_status = 'merged' or d.record_status = 'merged' then raise exception 'record already merged' using errcode = 'CV409'; end if;

  -- Move relationships: keep the strongest status when the survivor already has the guardian.
  for rel in select * from public.guardian_child_relationships where child_id = d.id and status in ('provisional','active','suspended') for update loop
    if exists (select 1 from public.guardian_child_relationships x where x.child_id = s.id and x.guardian_id = rel.guardian_id and x.status in ('provisional','active','suspended')) then
      update public.guardian_child_relationships set status = 'revoked', ends_at = now(), updated_by = auth.uid() where id = rel.id;
    else
      update public.guardian_child_relationships set child_id = s.id, updated_by = auth.uid() where id = rel.id;
    end if;
  end loop;
  -- Enrollments: survivor inherits the clinic enrollment if missing; the duplicate's are closed.
  insert into public.child_clinic_enrollments (organization_id, child_id, clinic_id, status, is_primary, access_scope, basis, created_by, updated_by)
  select v_org, s.id, e.clinic_id, case when s.record_status = 'active' then 'active' else 'pending' end, false,
         case when s.record_status = 'active' then 'care' else 'review_only' end, 'merge', auth.uid(), auth.uid()
    from public.child_clinic_enrollments e
   where e.child_id = d.id and e.status in ('pending','active')
     and not exists (select 1 from public.child_clinic_enrollments y where y.child_id = s.id and y.clinic_id = e.clinic_id and y.status in ('pending','active'));
  update public.child_clinic_enrollments set status = 'closed', is_primary = false, ends_at = now(), updated_by = auth.uid()
   where child_id = d.id and status in ('pending','active');
  update public.qr_passes set status = 'revoked', revoked_at = now(), updated_by = auth.uid() where child_id = d.id and status = 'active';
  update public.children set record_status = 'merged', merged_into_id = s.id, updated_by = auth.uid() where id = d.id;
  update public.record_review_cases set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', 'merged', 'survivor', s.id, 'duplicate', d.id)
   where kind = 'duplicate' and status in ('open','in_review') and least(child_id, candidate_child_id) = least(s.id, d.id) and greatest(child_id, candidate_child_id) = greatest(s.id, d.id);
  perform private.audit(v_org, 'review.resolve', 'child.merged', 'child', d.id,
                        jsonb_build_object('localRecordNo', d.local_record_no), jsonb_build_object('mergedInto', s.id, 'survivorRecordNo', s.local_record_no), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('survivorId', s.id, 'mergedId', d.id));
end $$;

-- Reviewer decides two records are distinct (e.g. twins). Both remain; the pair is not re-flagged automatically.
create function public.resolve_review_case(p_operation_key uuid, p_case_id uuid, p_outcome text, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_case public.record_review_cases; v_prev jsonb;
begin
  select * into v_case from public.record_review_cases where id = p_case_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(v_case.clinic_id, case v_case.kind when 'link' then 'guardian.verify' when 'duplicate' then 'review.resolve' when 'identity_edit' then 'child.register' else 'review.resolve' end);
  if v_case.kind = 'link' then raise exception 'use resolve_link_case' using errcode = 'CV422'; end if;
  if p_outcome not in ('not_duplicate','rejected','no_action') then raise exception 'invalid outcome' using errcode = 'CV422'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_case.organization_id, p_operation_key, 'review.resolve', jsonb_build_object('case', p_case_id, 'outcome', p_outcome, 'reason', p_reason));
  if v_prev is not null then return v_prev; end if;
  if v_case.status not in ('open','in_review') then raise exception 'case already resolved' using errcode = 'CV409'; end if;
  update public.record_review_cases set status = case when p_outcome = 'not_duplicate' then 'resolved' else 'rejected' end,
         resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(), resolution = jsonb_build_object('outcome', p_outcome, 'reason', p_reason)
   where id = v_case.id;
  perform private.audit(v_case.organization_id, 'review.resolve', 'review_case.resolved', 'review_case', v_case.id, null, jsonb_build_object('outcome', p_outcome), p_reason);
  return private.finish_command(v_case.organization_id, p_operation_key, jsonb_build_object('caseId', v_case.id, 'outcome', p_outcome));
end $$;

create function public.list_review_cases(p_clinic_id uuid, p_status text default 'open', p_limit integer default 50)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_res jsonb;
begin
  if not (private.has_capability(p_clinic_id, 'guardian.verify') or private.has_capability(p_clinic_id, 'review.resolve')) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
  select coalesce(jsonb_agg(x order by x ->> 'createdAt'), '[]'::jsonb) into v_res from (
    select jsonb_build_object('caseId', k.id, 'kind', k.kind, 'status', k.status, 'reason', k.reason, 'createdAt', k.created_at, 'version', k.version,
             'evidence', k.evidence, 'childId', k.child_id, 'candidateChildId', k.candidate_child_id,
             'child', (select jsonb_build_object('displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob) from public.children c where c.id = k.child_id),
             'candidate', (select jsonb_build_object('displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob) from public.children c where c.id = k.candidate_child_id
                             and private.child_in_clinic(c.id, p_clinic_id)),
             'guardianName', (select g.full_name from public.guardians g where g.id = k.guardian_id)) x
      from public.record_review_cases k
     where k.clinic_id = p_clinic_id and k.status = p_status
     order by k.created_at limit least(greatest(coalesce(p_limit, 50), 1), 100)) s;
  return v_res;
end $$;

-- QR: opaque, hashed, revocable locator. Only the issuing response ever contains the token.
create function public.issue_qr_pass(p_operation_key uuid, p_child_id uuid, p_clinic_id uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_token text; v_id uuid; v_canon uuid; v_cap text;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  select organization_id into v_org from public.children where id = v_canon;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if p_clinic_id is not null then
    if not (private.has_capability(p_clinic_id, 'child.register') and private.child_in_clinic(v_canon, p_clinic_id)) then raise exception 'not found' using errcode = 'CV404'; end if;
    v_cap := 'child.register';
  else
    if not private.guardian_has_full_access(v_canon) then raise exception 'not found' using errcode = 'CV404'; end if;
    v_cap := 'guardian';
  end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'qr.issue', jsonb_build_object('child', p_child_id, 'clinic', p_clinic_id));
  if v_prev is not null then return v_prev; end if;  -- replay returns the original token once more: same key + same actor only
  update public.qr_passes set status = 'revoked', revoked_at = now(), updated_by = auth.uid() where child_id = v_canon and status = 'active';
  v_token := translate(encode(extensions.gen_random_bytes(32), 'base64'), '+/=', '-_');
  insert into public.qr_passes (organization_id, child_id, token_hash, created_by, updated_by)
  values (v_org, v_canon, encode(sha256(convert_to(v_token, 'UTF8')), 'hex'), auth.uid(), auth.uid()) returning id into v_id;
  perform private.audit(v_org, v_cap, 'qr.issued', 'child', v_canon, null, jsonb_build_object('passId', v_id), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('passId', v_id, 'token', v_token));
end $$;

create function public.revoke_qr_pass(p_operation_key uuid, p_child_id uuid, p_clinic_id uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_n int; v_canon uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  select organization_id into v_org from public.children where id = v_canon;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if p_clinic_id is not null then
    if not (private.has_capability(p_clinic_id, 'child.register') and private.child_in_clinic(v_canon, p_clinic_id)) then raise exception 'not found' using errcode = 'CV404'; end if;
  elsif not private.guardian_has_full_access(v_canon) then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'qr.revoke', jsonb_build_object('child', p_child_id, 'clinic', p_clinic_id));
  if v_prev is not null then return v_prev; end if;
  update public.qr_passes set status = 'revoked', revoked_at = now(), updated_by = auth.uid() where child_id = v_canon and status = 'active';
  get diagnostics v_n = row_count;
  perform private.audit(v_org, 'qr', 'qr.revoked', 'child', v_canon, null, jsonb_build_object('revoked', v_n), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('revoked', v_n));
end $$;

-- Staff QR resolution: generic null for every failure so a copied/expired/foreign token reveals nothing (T22).
create function public.resolve_qr(p_clinic_id uuid, p_token text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; q public.qr_passes; c public.children;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null or not private.has_capability(p_clinic_id, 'child.search') then raise exception 'forbidden' using errcode = 'CV403'; end if;
  select * into q from public.qr_passes where token_hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex')
     and status = 'active' and (expires_at is null or expires_at > now());
  if found then
    select * into c from public.children where id = q.child_id and organization_id = v_org and record_status in ('provisional','active');
  end if;
  if c.id is null or not private.child_in_clinic(c.id, p_clinic_id) then
    perform private.audit(v_org, 'child.search', 'qr.resolve', 'clinic', p_clinic_id, null, null, null, 'denied');
    return null;
  end if;
  perform private.audit(v_org, 'child.search', 'qr.resolve', 'child', c.id, null, null, null);
  return jsonb_build_object('childId', c.id, 'displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob, 'dobPrecision', c.birth_date_precision);
end $$;

create function public.acknowledge_privacy_notice(p_operation_key uuid, p_clinic_id uuid, p_notice_version text, p_purpose text default 'care_records')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_g uuid; v_id uuid;
begin
  if auth.uid() is null or not private.session_ok() then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select organization_id into v_org from public.clinics where id = p_clinic_id and status = 'active';
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'privacy.acknowledge', jsonb_build_object('clinic', p_clinic_id, 'v', p_notice_version, 'p', p_purpose));
  if v_prev is not null then return v_prev; end if;
  if p_notice_version is null or length(btrim(p_notice_version)) = 0 then raise exception 'notice version required' using errcode = 'CV422'; end if;
  v_g := private.ensure_guardian(v_org);
  insert into public.privacy_records (organization_id, guardian_id, purpose, record_type, notice_version, decision, created_by)
  values (v_org, v_g, left(p_purpose, 100), 'notice_acknowledgement', left(p_notice_version, 50), 'acknowledged', auth.uid()) returning id into v_id;
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('privacyRecordId', v_id));
end $$;

-- Guardian home data (D1/P03): only children this account is linked to, with relationship state.
create function public.my_children() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'childId', c.id, 'displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob, 'dobPrecision', c.birth_date_precision,
    'recordStatus', c.record_status, 'relationshipStatus', r.status, 'accessScope', r.access_scope, 'relationship', r.relationship,
    'clinicName', (select cl.name from public.child_clinic_enrollments e join public.clinics cl on cl.id = e.clinic_id
                    where e.child_id = c.id and e.status in ('pending','active') order by e.is_primary desc, e.created_at limit 1)
  ) order by c.display_name), '[]'::jsonb)
  from public.guardian_child_relationships r
  join public.children c on c.id = r.child_id
  where r.guardian_id in (select private.my_guardian_ids()) and r.status in ('provisional','active') and c.record_status <> 'merged'
$$;

-- Grants: commands are callable only by signed-in users; each re-authorizes internally.
do $$
declare f text;
begin
  foreach f in array array[
    'create_child_provisional(uuid,uuid,jsonb,text)',
    'register_child_staff(uuid,uuid,jsonb,jsonb,boolean,boolean)',
    'staff_search_children(uuid,text,date,integer)',
    'staff_get_child(uuid,uuid)',
    'confirm_child_identity(uuid,uuid,uuid,integer,text)',
    'update_child_identity(uuid,uuid,uuid,integer,jsonb,text)',
    'request_child_edit(uuid,uuid,jsonb,text)',
    'request_guardian_link(uuid,uuid,jsonb,text)',
    'resolve_link_case(uuid,uuid,text,uuid,text,text)',
    'verify_relationship(uuid,uuid,uuid,text)',
    'set_relationship_status(uuid,uuid,uuid,text,text)',
    'merge_children(uuid,uuid,uuid,uuid,text)',
    'resolve_review_case(uuid,uuid,text,text)',
    'list_review_cases(uuid,text,integer)',
    'issue_qr_pass(uuid,uuid,uuid)',
    'revoke_qr_pass(uuid,uuid,uuid)',
    'resolve_qr(uuid,text)',
    'acknowledge_privacy_notice(uuid,uuid,text,text)',
    'my_children()'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function private.has_capability(uuid, text), private.clinics_with(text), private.session_ok(),
  private.my_guardian_ids(), private.guardian_can_read_child(uuid) to authenticated;
-- END 0003_registry.sql

-- =====================================================================================================================
-- BEGIN 0004_public_surface.sql  sha256=32069a390792acd3779f71e1121afb9f894e06718fb304797ed4d410ece5c3ab
-- =====================================================================================================================
-- 0004 Public clinic listing as an RPC (P01) and request-id correlation via PostgREST's request.headers GUC.

create or replace function private.request_id() returns uuid language plpgsql stable set search_path = '' as $$
declare v text;
begin
  v := nullif(pg_catalog.current_setting('app.request_id', true), '');
  if v is null then
    -- PostgREST exposes request headers as JSON in request.headers; the app forwards x-request-id.
    begin
      v := nullif(nullif(pg_catalog.current_setting('request.headers', true), '')::json ->> 'x-request-id', '');
    exception when others then v := null;
    end;
  end if;
  begin
    return coalesce(v::uuid, gen_random_uuid());
  exception when others then
    return gen_random_uuid();
  end;
end $$;
revoke all on function private.request_id() from public, anon, authenticated;

create function public.list_public_clinics() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'address', address, 'contact', contact_text) order by name), '[]'::jsonb)
    from public.clinics where status = 'active'
$$;
revoke all on function public.list_public_clinics() from public, anon, authenticated;
grant execute on function public.list_public_clinics() to anon, authenticated;

-- Effective capabilities per membership let the UI show only relevant actions. This is presentation only:
-- every command still authorizes in the database.
create or replace function public.get_my_context() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'profileId', p.id, 'displayName', p.display_name, 'locale', p.locale, 'status', p.status,
    'mfa', private.mfa_ok(),
    'demoMode', private.setting_bool('demo_mode'),
    'memberships', coalesce((
      select jsonb_agg(jsonb_build_object('membershipId', m.id, 'clinicId', m.clinic_id, 'clinicName', c.name, 'role', m.role_code,
                                          'status', m.status, 'validUntil', m.valid_until,
                                          'capabilities', to_jsonb(private.role_preset(m.role_code) || m.capabilities)))
        from public.staff_memberships m join public.clinics c on c.id = m.clinic_id
       where m.profile_id = p.id and m.status in ('active','pending_approval')), '[]'::jsonb))
  from public.profiles p where p.id = auth.uid()
$$;
revoke all on function public.get_my_context() from public, anon, authenticated;
grant execute on function public.get_my_context() to authenticated;
-- END 0004_public_surface.sql

-- =====================================================================================================================
-- BEGIN 0005_staff_admin_reads.sql  sha256=347bda93479370a568838cb9ba80119e35060cf7d9f52954a3f64c2870a16ff6
-- =====================================================================================================================
-- 0005 Read/lookup commands for staff access administration (P33). Technical admins see membership metadata only.

create function public.list_staff_memberships(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_res jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if not (private.has_capability(p_clinic_id, 'admin.users') or private.has_capability(p_clinic_id, 'grant.approve.clinical')) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'membershipId', m.id, 'profileId', m.profile_id, 'displayName', p.display_name, 'role', m.role_code,
      'capabilities', to_jsonb(m.capabilities), 'status', m.status, 'version', m.version, 'validUntil', m.valid_until,
      'requestedBy', m.requested_by, 'approvedBy', m.approved_by, 'createdAt', m.created_at,
      'requiresClinicalApproval', private.membership_is_clinical(m.role_code, m.capabilities))
    order by m.created_at desc), '[]'::jsonb)
    into v_res
    from public.staff_memberships m join public.profiles p on p.id = m.profile_id
   where m.clinic_id = p_clinic_id and m.status in ('pending_approval','active','suspended');
  return v_res;
end $$;

-- Exact-email lookup for an administrator adding staff. Audited; returns null (not an error) so the denial/miss is recorded.
create function public.find_profile_for_grant(p_clinic_id uuid, p_email text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; r record;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if not (private.has_capability(p_clinic_id, 'admin.users') or private.has_capability(p_clinic_id, 'grant.approve.clinical')) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
  select p.id, p.display_name into r from auth.users u join public.profiles p on p.id = u.id
   where lower(u.email) = lower(btrim(coalesce(p_email, ''))) and p.status = 'active';
  perform private.audit(v_org, 'admin.users', 'staff.profile_lookup', 'clinic', p_clinic_id, null,
                        jsonb_build_object('found', r.id is not null), null);
  if r.id is null then return null; end if;
  return jsonb_build_object('profileId', r.id, 'displayName', r.display_name);
end $$;

revoke all on function public.list_staff_memberships(uuid) from public, anon, authenticated;
revoke all on function public.find_profile_for_grant(uuid, text) from public, anon, authenticated;
grant execute on function public.list_staff_memberships(uuid) to authenticated;
grant execute on function public.find_profile_for_grant(uuid, text) to authenticated;
-- END 0005_staff_admin_reads.sql

-- =====================================================================================================================
-- BEGIN 0006_clinical_master.sql  sha256=7cd2564a0dd7373ca6c34a322f158ae2917bdc9f7b35f329fd67faa61d981454
-- =====================================================================================================================
-- 0006 Clinical master data, schedule versions/rules, immutable vaccination history, evaluations.
-- Blueprint refs: BP28.3, BP16, F04, F06, F35; T07/T08/T09/T31 (engine + evidence part).
--
-- SAFETY: no clinical values live in this migration. Schedule content only ever enters through the reviewed
-- import/approval/activation commands (0007). Versions flagged is_demo can activate only when
-- private.settings.demo_mode = true, so fictional fixtures cannot become live clinical rules by accident.

-- ---------------------------------------------------------------------------------------------
-- Master data
-- ---------------------------------------------------------------------------------------------
create table public.antigens (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  code text not null check (code ~ '^[A-Za-z0-9._-]{1,40}$'),
  name text not null check (length(btrim(name)) > 0),
  status text not null default 'draft' check (status in ('draft','active','retired')),
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  unique (organization_id, id), unique (organization_id, code)
);
create trigger antigens_touch before update on public.antigens for each row execute function private.touch_row();

create table public.vaccine_products (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  code text not null check (code ~ '^[A-Za-z0-9._-]{1,40}$'),
  name text not null check (length(btrim(name)) > 0),
  manufacturer text,
  presentation text not null,
  stock_unit text not null,
  doses_per_container numeric not null check (doses_per_container > 0),
  administration_unit text not null,
  policy_reference text not null default '',
  status text not null default 'draft' check (status in ('draft','active','retired')),
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  unique (organization_id, id), unique (organization_id, code)
);
create trigger vaccine_products_touch before update on public.vaccine_products for each row execute function private.touch_row();

create table public.product_antigens (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  product_id uuid not null, antigen_id uuid not null,
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  foreign key (organization_id, product_id) references public.vaccine_products (organization_id, id),
  foreign key (organization_id, antigen_id) references public.antigens (organization_id, id),
  unique (product_id, antigen_id)
);
-- A product's presentation/conversion must not change once used (BP28.3): enforced in 0007 by trigger once history references it.

-- ---------------------------------------------------------------------------------------------
-- Schedule versions and typed rules
-- ---------------------------------------------------------------------------------------------
create table public.schedule_versions (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  program_code text not null check (program_code ~ '^[A-Za-z0-9._-]{1,40}$'),
  version_label text not null check (length(btrim(version_label)) > 0),
  status text not null default 'draft' check (status in ('draft','clinical_review','approved','active','retired')),
  is_demo boolean not null default false,
  effective_from date, effective_to date,
  cohort_predicate jsonb not null default '{}'::jsonb,
  source_reference text not null default '',
  source_hash text,
  proposed_by uuid references public.profiles (id),
  reviewed_by uuid references public.profiles (id),
  approved_by uuid references public.profiles (id),
  approved_at timestamptz,
  supersedes_id uuid references public.schedule_versions (id),
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  unique (organization_id, id), unique (organization_id, program_code, version_label),
  -- A retired version may end before it began (retired before its start date).
  check (status = 'retired' or effective_to is null or effective_from is null or effective_to >= effective_from),
  check (status not in ('approved','active') or (approved_by is not null and approved_at is not null)),
  check (status <> 'active' or effective_from is not null),
  -- Non-demo versions must cite their authority; demo versions must not pretend to.
  check (is_demo or status = 'draft' or length(btrim(source_reference)) > 0)
);
create trigger schedule_versions_touch before update on public.schedule_versions for each row execute function private.touch_row();
create unique index schedule_versions_one_live_uq on public.schedule_versions (organization_id, program_code) where status = 'active';

create table public.schedule_rules (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  schedule_version_id uuid not null,
  sequence_no integer not null check (sequence_no > 0),
  requirement_code text not null check (requirement_code ~ '^[A-Za-z0-9._-]{1,60}$'),
  antigen_id uuid not null,
  series_code text not null,
  dose_ordinal integer not null check (dose_ordinal > 0),
  target_offset jsonb,       -- {"value":int,"unit":"days|weeks|months"} calendar-age offset from birth
  minimum_age jsonb,
  maximum_age jsonb,
  due_window jsonb,          -- {"start":{..},"end":{..}} ages; either bound optional
  review_conditions jsonb not null default '[]'::jsonb,
  accepted_products jsonb not null default '[]'::jsonb,   -- product codes; empty = any product mapped to the antigen
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  foreign key (organization_id, schedule_version_id) references public.schedule_versions (organization_id, id),
  foreign key (organization_id, antigen_id) references public.antigens (organization_id, id),
  unique (schedule_version_id, requirement_code), unique (schedule_version_id, sequence_no),
  unique (schedule_version_id, series_code, dose_ordinal),
  unique (organization_id, id)
);
create index schedule_rules_version_idx on public.schedule_rules (schedule_version_id, sequence_no);

create table public.schedule_rule_dependencies (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  rule_id uuid not null, predecessor_rule_id uuid not null,
  minimum_interval_value integer not null check (minimum_interval_value >= 0),
  interval_unit text not null check (interval_unit in ('days','weeks','months')),
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  foreign key (organization_id, rule_id) references public.schedule_rules (organization_id, id),
  foreign key (organization_id, predecessor_rule_id) references public.schedule_rules (organization_id, id),
  unique (rule_id, predecessor_rule_id), check (rule_id <> predecessor_rule_id)
);

-- Fixture cases that gate approval: hypothetical child + doses + as-of date + expected requirement statuses.
create table public.schedule_fixtures (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  schedule_version_id uuid not null,
  name text not null,
  dob date not null,
  doses jsonb not null default '[]'::jsonb,   -- [{ "id": "d1", "antigens": ["CODE"], "product": "CODE", "on": "YYYY-MM-DD" }]
  as_of date not null,
  expected jsonb not null,                    -- { "REQ_CODE": "status", ... }
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  foreign key (organization_id, schedule_version_id) references public.schedule_versions (organization_id, id),
  unique (schedule_version_id, name)
);

-- Content of a version is frozen once it leaves draft (BP16: active version immutable).
create function private.freeze_schedule_content() returns trigger language plpgsql set search_path = '' as $$
declare v_status text; v_id uuid;
begin
  -- Separate statements: plpgsql resolves record fields at plan time, so one CASE over different row types would fail.
  if tg_table_name = 'schedule_rule_dependencies' then
    if tg_op = 'DELETE' then
      select r.schedule_version_id into v_id from public.schedule_rules r where r.id = old.rule_id;
    else
      select r.schedule_version_id into v_id from public.schedule_rules r where r.id = new.rule_id;
    end if;
  elsif tg_op = 'DELETE' then
    v_id := old.schedule_version_id;
  else
    v_id := new.schedule_version_id;
  end if;
  select status into v_status from public.schedule_versions where id = v_id;
  if v_status is distinct from 'draft' then
    raise exception 'schedule version content is frozen once it leaves draft' using errcode = 'CV409';
  end if;
  return coalesce(new, old);
end $$;
create trigger schedule_rules_freeze before insert or update or delete on public.schedule_rules for each row execute function private.freeze_schedule_content();
create trigger schedule_deps_freeze before insert or update or delete on public.schedule_rule_dependencies for each row execute function private.freeze_schedule_content();
create trigger schedule_fixtures_freeze before insert or update or delete on public.schedule_fixtures for each row execute function private.freeze_schedule_content();

create function private.schedule_version_guard() returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_op = 'DELETE' then
    if old.status <> 'draft' then raise exception 'only draft schedule versions can be deleted' using errcode = 'CV409'; end if;
    return old;
  end if;
  if old.status in ('active','retired','approved') then
    -- Only lifecycle fields may change on a frozen version.
    if (new.program_code, new.version_label, new.is_demo, new.cohort_predicate, new.source_reference, new.source_hash)
       is distinct from (old.program_code, old.version_label, old.is_demo, old.cohort_predicate, old.source_reference, old.source_hash) then
      raise exception 'approved/active schedule versions are immutable' using errcode = 'CV409';
    end if;
  end if;
  return new;
end $$;
create trigger schedule_versions_guard before update or delete on public.schedule_versions for each row execute function private.schedule_version_guard();

-- ---------------------------------------------------------------------------------------------
-- Child program assignment
-- ---------------------------------------------------------------------------------------------
create table public.child_programs (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  child_id uuid not null, schedule_version_id uuid not null,
  program_code text not null,
  starts_on date not null, ends_on date,
  status text not null default 'active' check (status in ('active','ended')),
  assignment_reason text not null default 'automatic',
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, schedule_version_id) references public.schedule_versions (organization_id, id)
);
create unique index child_programs_one_active_uq on public.child_programs (child_id, program_code) where status = 'active';
create trigger child_programs_touch before update on public.child_programs for each row execute function private.touch_row();

create table public.clinical_holds (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  child_id uuid not null, rule_id uuid,
  reason_code text not null check (length(btrim(reason_code)) > 0),
  restricted_note text,
  starts_at timestamptz not null default now(), review_on date,
  status text not null default 'active' check (status in ('active','resolved')),
  resolved_by uuid references public.profiles (id),
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, rule_id) references public.schedule_rules (organization_id, id)
);
create index clinical_holds_child_idx on public.clinical_holds (child_id, status);
create trigger clinical_holds_touch before update on public.clinical_holds for each row execute function private.touch_row();

-- ---------------------------------------------------------------------------------------------
-- Immutable vaccination history: event (occurrence) + revisions (signed/corrected descriptions)
-- ---------------------------------------------------------------------------------------------
create table public.vaccination_events (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  original_child_id uuid not null,
  encounter_id uuid,           -- FK added with the visits module (M05)
  origin text not null check (origin in ('clinic_administered','paper_reconciliation','external','parent_reported','bhw_reported','historical_import')),
  external_provider text, external_reference text, paper_reference text,
  source_operation_id uuid,
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  foreign key (organization_id, original_child_id) references public.children (organization_id, id),
  unique (organization_id, id), unique (source_operation_id)
);
create index vaccination_events_child_idx on public.vaccination_events (original_child_id);

create table public.vaccination_revisions (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  event_id uuid not null,
  revision_no integer not null check (revision_no > 0),
  child_id uuid not null,
  product_id uuid,
  reported_product_text text,
  administered_on date,
  administered_at timestamptz,
  date_precision text not null default 'exact' check (date_precision in ('exact','month','year','unknown')),
  lot_id uuid,                 -- FK added with the inventory module (M04)
  reported_lot text,
  expiry_snapshot date,
  quantity numeric, unit text, route text, site text,
  administered_by uuid references public.profiles (id),
  external_vaccinator text,
  clinic_id uuid,
  source text not null check (source in ('clinic_administered','paper_reconciliation','external_documented','parent_reported','bhw_reported','historical_import')),
  verification_status text not null check (verification_status in ('verified','pending_verification','rejected')),
  event_status text not null default 'active' check (event_status in ('active','voided')),
  reason text,
  approved_by uuid references public.profiles (id),
  signed_at timestamptz,
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  foreign key (organization_id, event_id) references public.vaccination_events (organization_id, id),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, product_id) references public.vaccine_products (organization_id, id),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  unique (event_id, revision_no),
  -- Reported/pending doses can never be "verified" without a verifier (BP15.C, T09).
  check (verification_status <> 'verified' or (approved_by is not null or source = 'clinic_administered')),
  check (date_precision <> 'exact' or administered_on is not null),
  check (source <> 'clinic_administered' or (product_id is not null and administered_on is not null and administered_by is not null and clinic_id is not null))
);
create index vaccination_revisions_child_idx on public.vaccination_revisions (child_id, administered_on);
create trigger vaccination_events_immutable before update or delete on public.vaccination_events for each row execute function private.forbid_change();
create trigger vaccination_revisions_immutable before update or delete on public.vaccination_revisions for each row execute function private.forbid_change();

-- Current authoritative facts: the highest revision per event (only accepted revisions exist).
create view private.current_revisions as
  select distinct on (r.event_id) r.* from public.vaccination_revisions r order by r.event_id, r.revision_no desc;

create table public.schedule_evaluations (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  child_id uuid not null, schedule_version_id uuid not null,
  as_of_date date not null, engine_version text not null, input_hash text not null,
  result jsonb not null,
  evaluated_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, schedule_version_id) references public.schedule_versions (organization_id, id),
  unique (child_id, schedule_version_id, as_of_date, engine_version, input_hash),
  unique (organization_id, id)
);
create index schedule_evaluations_child_idx on public.schedule_evaluations (child_id, evaluated_at desc);
create trigger schedule_evaluations_immutable before update or delete on public.schedule_evaluations for each row execute function private.forbid_change();

create table public.dose_credits (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  evaluation_id uuid not null, rule_id uuid not null, vaccination_revision_id uuid not null,
  credit_status text not null check (credit_status in ('credited','not_credited')),
  reason text not null,
  created_at timestamptz not null default now(),
  foreign key (organization_id, evaluation_id) references public.schedule_evaluations (organization_id, id),
  foreign key (organization_id, rule_id) references public.schedule_rules (organization_id, id),
  foreign key (vaccination_revision_id) references public.vaccination_revisions (id),
  unique (evaluation_id, rule_id)
);
create trigger dose_credits_immutable before update or delete on public.dose_credits for each row execute function private.forbid_change();

-- Evidence files: metadata table only. Upload/download needs Storage (blocked_external until a Supabase project exists).
create table public.record_attachments (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  child_id uuid not null, event_id uuid,
  storage_path text not null unique,
  mime_type text not null check (mime_type in ('image/jpeg','image/png','application/pdf')),
  byte_size integer not null check (byte_size > 0 and byte_size <= 10485760),
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  source text not null,
  verification_status text not null default 'pending_verification' check (verification_status in ('pending_verification','verified','rejected')),
  verified_by uuid references public.profiles (id),
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, event_id) references public.vaccination_events (organization_id, id)
);
create trigger record_attachments_touch before update on public.record_attachments for each row execute function private.touch_row();

-- ---------------------------------------------------------------------------------------------
-- Security posture: RLS on, no direct grants. Reads and writes are commands (0007).
-- ---------------------------------------------------------------------------------------------
alter table public.antigens enable row level security;
alter table public.vaccine_products enable row level security;
alter table public.product_antigens enable row level security;
alter table public.schedule_versions enable row level security;
alter table public.schedule_rules enable row level security;
alter table public.schedule_rule_dependencies enable row level security;
alter table public.schedule_fixtures enable row level security;
alter table public.child_programs enable row level security;
alter table public.clinical_holds enable row level security;
alter table public.vaccination_events enable row level security;
alter table public.vaccination_revisions enable row level security;
alter table public.schedule_evaluations enable row level security;
alter table public.dose_credits enable row level security;
alter table public.record_attachments enable row level security;

revoke all on public.antigens, public.vaccine_products, public.product_antigens, public.schedule_versions, public.schedule_rules,
              public.schedule_rule_dependencies, public.schedule_fixtures, public.child_programs, public.clinical_holds,
              public.vaccination_events, public.vaccination_revisions, public.schedule_evaluations, public.dose_credits,
              public.record_attachments from anon, authenticated;
revoke all on private.current_revisions from public, anon, authenticated;
-- END 0006_clinical_master.sql

-- =====================================================================================================================
-- BEGIN 0007_schedule_engine.sql  sha256=352ce69d12e6d5b7d37df7f76b7f1ac412e678e8adb3d5725905c29400351fe5
-- =====================================================================================================================
-- 0007 Deterministic schedule evaluation engine (pure function of rules + inputs) and child evaluation.
-- Blueprint refs: BP16 (evaluation sequence, status model), T07, T08, T09, T12(partly), T31.
--
-- The engine implements the SUPPORTED TYPED VOCABULARY only: calendar-age offsets, minimum/maximum age, per-predecessor
-- minimum intervals, accepted products, due windows. It contains no medical values. Interpretation of "valid dose"
-- is strictly what the approved rule text says (no grace periods, no invented catch-up branches): a dose outside the
-- rule limits is never credited automatically; it produces "staff review needed".

create function private.valid_age(p jsonb) returns boolean language sql immutable set search_path = '' as $$
  select p is null or (
    jsonb_typeof(p) = 'object'
    and (p ->> 'unit') in ('days','weeks','months')
    and (p ->> 'value') ~ '^[0-9]{1,4}$'
  )
$$;

-- Calendar arithmetic. Months are calendar months (PostgreSQL clamps to month end), never 30 days (BP16).
create function private.add_age(p_from date, p_age jsonb) returns date language sql stable set search_path = '' as $$
  select case
    when p_age is null or p_from is null then null
    when p_age ->> 'unit' = 'days'   then p_from + (p_age ->> 'value')::int
    when p_age ->> 'unit' = 'weeks'  then p_from + (p_age ->> 'value')::int * 7
    when p_age ->> 'unit' = 'months' then (p_from + make_interval(months => (p_age ->> 'value')::int))::date
  end
$$;

create function private.add_interval(p_from date, p_value integer, p_unit text) returns date language sql stable set search_path = '' as $$
  select private.add_age(p_from, jsonb_build_object('value', p_value, 'unit', p_unit))
$$;

-- p_doses: [{ "id": text, "antigens": [code], "product": code|null, "on": "YYYY-MM-DD" | null, "unresolved": bool }]
-- p_holds: [{ "ruleId": uuid|null, "reason": text }]
create function private.evaluate_rules(p_version uuid, p_dob date, p_dob_exact boolean, p_doses jsonb, p_holds jsonb, p_as_of date)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  r record; dep record; d record;
  v_state jsonb := '{}'::jsonb;         -- rule id -> {creditedOn, earliestEligibleOn}
  v_used text[] := '{}';
  v_flagged text[] := '{}';           -- doses already reported as outside limits: flagged once, at the first rule that rejects them
  v_out jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_unresolved jsonb := '[]'::jsonb;
  v_min_on date; v_max_on date; v_earliest date; v_cand date; v_projected boolean; v_pred_pending boolean;
  v_target date; v_ws date; v_we date; v_credit_id text; v_credit_on date; v_unval jsonb; v_status text; v_reasons jsonb;
  v_has_hold boolean; v_antigen text; v_dose_on date; v_bad text; v_recommended date; v_st jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_unresolved from jsonb_array_elements(p_doses) x where coalesce((x ->> 'unresolved')::boolean, false);

  for r in
    select sr.*, a.code as antigen_code from public.schedule_rules sr join public.antigens a on a.id = sr.antigen_id
     where sr.schedule_version_id = p_version order by sr.sequence_no
  loop
    v_reasons := '[]'::jsonb; v_unval := '[]'::jsonb; v_credit_id := null; v_credit_on := null;
    v_min_on := null; v_max_on := null; v_earliest := null; v_projected := false; v_pred_pending := false;
    v_target := null; v_ws := null; v_we := null; v_recommended := null;

    if p_dob_exact then
      v_min_on := private.add_age(p_dob, r.minimum_age);
      v_max_on := private.add_age(p_dob, r.maximum_age);
      v_earliest := v_min_on;
      for dep in select dd.*, dd.predecessor_rule_id as pid from public.schedule_rule_dependencies dd where dd.rule_id = r.id loop
        v_st := v_state -> dep.pid::text;
        if v_st ->> 'creditedOn' is not null then
          v_cand := private.add_interval((v_st ->> 'creditedOn')::date, dep.minimum_interval_value, dep.interval_unit);
        else
          v_pred_pending := true; v_projected := true;
          v_cand := private.add_interval((v_st ->> 'earliestEligibleOn')::date, dep.minimum_interval_value, dep.interval_unit);
        end if;
        v_earliest := greatest(v_earliest, v_cand);
      end loop;

      -- Credit the earliest unused dose that satisfies every limit of this rule.
      for d in
        select x.value as dose, (x.value ->> 'id') as did, (x.value ->> 'on')::date as don
          from jsonb_array_elements(p_doses) as x(value)
         where not coalesce((x.value ->> 'unresolved')::boolean, false)
           and (x.value -> 'antigens') ? r.antigen_code
           and (jsonb_array_length(r.accepted_products) = 0 or r.accepted_products ? (x.value ->> 'product'))
         order by (x.value ->> 'on')::date, x.value ->> 'id'
      loop
        -- One physical dose may credit one requirement per antigen it contains (combination products, T08), never the same antigen twice.
        continue when (d.did || ':' || r.antigen_code) = any (v_used);
        v_bad := null;
        if v_pred_pending then v_bad := 'predecessor_not_credited';
        elsif v_min_on is not null and d.don < v_min_on then v_bad := 'given_before_minimum_age';
        elsif v_earliest is not null and d.don < v_earliest then v_bad := 'given_before_minimum_interval';
        elsif v_max_on is not null and d.don > v_max_on then v_bad := 'given_after_maximum_age';
        end if;
        if v_bad is null then
          v_credit_id := d.did; v_credit_on := d.don; v_used := v_used || (d.did || ':' || r.antigen_code);
          exit;
        else
          if not ((d.did || ':' || r.antigen_code) = any (v_flagged)) then
            v_unval := v_unval || jsonb_build_object('doseId', d.did, 'on', d.don, 'reason', v_bad);
            v_flagged := v_flagged || (d.did || ':' || r.antigen_code);
          end if;
        end if;
      end loop;

      v_target := private.add_age(p_dob, r.target_offset);
      v_ws := coalesce(private.add_age(p_dob, r.due_window -> 'start'), v_target);
      v_we := private.add_age(p_dob, r.due_window -> 'end');
      v_recommended := greatest(v_target, v_earliest);
    end if;

    v_state := v_state || jsonb_build_object(r.id::text, jsonb_build_object('creditedOn', v_credit_on, 'earliestEligibleOn', v_earliest));

    select exists (select 1 from jsonb_array_elements(p_holds) h where h ->> 'ruleId' is null or (h ->> 'ruleId') = r.id::text) into v_has_hold;

    if v_credit_id is not null then
      v_status := 'completed';
      v_reasons := jsonb_build_array(jsonb_build_object('code', 'credited_by_verified_dose', 'doseId', v_credit_id, 'on', v_credit_on));
    elsif not p_dob_exact then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'birth_date_not_exact'));
    elsif v_has_hold then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'clinical_hold'));
    elsif jsonb_array_length(v_unval) > 0 then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'dose_outside_rule_limits', 'doses', v_unval));
    elsif exists (select 1 from jsonb_array_elements(v_unresolved) u where (u -> 'antigens') ? r.antigen_code) then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'unresolved_history'));
    elsif r.review_conditions <> '[]'::jsonb then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'rule_requires_review', 'conditions', r.review_conditions));
    elsif v_max_on is not null and p_as_of > v_max_on then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'beyond_maximum_age', 'on', v_max_on));
    elsif v_pred_pending then
      v_status := 'not_yet_eligible'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'predecessor_pending'));
    elsif v_earliest is not null and p_as_of < v_earliest then
      v_status := 'not_yet_eligible'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'before_earliest_eligible', 'on', v_earliest));
    elsif v_we is not null and p_as_of > v_we then
      v_status := 'overdue'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'after_due_window', 'on', v_we));
    elsif v_target is not null and p_as_of = v_target then
      v_status := 'due_today'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'target_date_is_today'));
    elsif v_ws is not null and v_we is not null and p_as_of >= v_ws then
      v_status := 'due_now'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'within_due_window'));
    elsif v_target is not null and p_as_of > v_target then
      -- No approved overdue threshold: never invent one (BP16). "Past recommended date — review with clinic".
      v_status := 'past_recommended_date'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'past_target_without_overdue_threshold', 'on', v_target));
    elsif v_ws is not null and p_as_of >= v_ws then
      v_status := 'due_now'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'window_open'));
    elsif v_target is null and v_ws is null then
      v_status := 'due_now'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'eligible_no_timing_guidance'));
    else
      v_status := 'upcoming'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'target_in_future'));
    end if;

    v_summary := v_summary || jsonb_build_object(v_status, coalesce((v_summary ->> v_status)::int, 0) + 1);
    v_out := v_out || jsonb_build_object(
      'ruleId', r.id, 'requirement', r.requirement_code, 'antigen', r.antigen_code, 'series', r.series_code, 'ordinal', r.dose_ordinal,
      'status', v_status, 'reasons', v_reasons, 'earliestEligibleOn', v_earliest, 'projected', v_projected,
      'targetOn', v_target, 'recommendedOn', v_recommended, 'windowStart', v_ws, 'windowEnd', v_we, 'maximumAgeOn', v_max_on,
      'creditedDoseId', v_credit_id, 'creditedOn', v_credit_on);
  end loop;

  return jsonb_build_object('engineVersion', 'plpgsql-1', 'versionId', p_version, 'asOf', p_as_of, 'birthDateExact', p_dob_exact,
                            'requirements', v_out, 'summary', v_summary, 'unresolvedHistory', v_unresolved);
end $$;

-- Runs the version's stored fixtures; used as an approval gate (BP16, BP38 P36).
create function private.run_fixtures(p_version uuid) returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare f record; v_res jsonb; v_out jsonb := '[]'::jsonb; v_pass boolean; v_diff jsonb; e record;
begin
  for f in select * from public.schedule_fixtures where schedule_version_id = p_version order by name loop
    v_res := private.evaluate_rules(p_version, f.dob, true, f.doses, '[]'::jsonb, f.as_of);
    v_diff := '[]'::jsonb;
    for e in select key, value from jsonb_each_text(f.expected) loop
      if coalesce((select x ->> 'status' from jsonb_array_elements(v_res -> 'requirements') x where x ->> 'requirement' = e.key), '(missing)') <> e.value then
        v_diff := v_diff || jsonb_build_object('requirement', e.key, 'expected', e.value,
          'actual', coalesce((select x ->> 'status' from jsonb_array_elements(v_res -> 'requirements') x where x ->> 'requirement' = e.key), '(missing)'));
      end if;
    end loop;
    v_pass := jsonb_array_length(v_diff) = 0;
    v_out := v_out || jsonb_build_object('name', f.name, 'passed', v_pass, 'differences', v_diff);
  end loop;
  return v_out;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Gathering child inputs and evaluating
-- ---------------------------------------------------------------------------------------------
create function private.local_today(p_clinic uuid) returns date language sql stable security definer set search_path = '' as $$
  select (now() at time zone coalesce((select c.timezone from public.clinics c where c.id = p_clinic), 'Asia/Manila'))::date
$$;

-- The child plus any records merged into it (aliases), bounded depth.
create function private.child_ids_with_aliases(p_child uuid) returns setof uuid language sql stable security definer set search_path = '' as $$
  with recursive t(id, depth) as (
    select p_child, 0
    union
    select c.id, t.depth + 1 from public.children c join t on c.merged_into_id = t.id where t.depth < 5
  ) select id from t
$$;

create function private.child_eval_inputs(p_child uuid) returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_dob date; v_prec text; v_doses jsonb; v_holds jsonb; v_pending int; v_rev jsonb;
begin
  select dob, birth_date_precision into v_dob, v_prec from public.children where id = p_child;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', cr.id::text,
      'revisionId', cr.id, 'eventId', cr.event_id,
      'product', p.code,
      'antigens', coalesce((select jsonb_agg(a.code order by a.code) from public.product_antigens pa join public.antigens a on a.id = pa.antigen_id where pa.product_id = cr.product_id), '[]'::jsonb),
      'on', case when cr.date_precision = 'exact' then cr.administered_on end,
      'unresolved', cr.date_precision <> 'exact' or cr.administered_on is null or cr.product_id is null)
    order by cr.administered_on nulls last, cr.id), '[]'::jsonb)
    into v_doses
    from private.current_revisions cr left join public.vaccine_products p on p.id = cr.product_id
   where cr.child_id in (select private.child_ids_with_aliases(p_child))
     and cr.event_status = 'active' and cr.verification_status = 'verified';
  select coalesce(jsonb_agg(jsonb_build_object('ruleId', h.rule_id, 'reason', h.reason_code)), '[]'::jsonb) into v_holds
    from public.clinical_holds h where h.child_id = p_child and h.status = 'active';
  -- Unverified/pending evidence is counted for staff visibility but NEVER credited (T09).
  select count(*) into v_pending from private.current_revisions cr
   where cr.child_id in (select private.child_ids_with_aliases(p_child)) and cr.event_status = 'active' and cr.verification_status = 'pending_verification';
  return jsonb_build_object('dob', v_dob, 'dobExact', v_prec = 'exact' and v_dob is not null, 'doses', v_doses, 'holds', v_holds, 'pendingEvidence', v_pending);
end $$;

-- Which approved, active version applies to a child on a date. Cohort predicate supports only dobFrom/dobTo.
create function private.active_schedule_for(p_org uuid, p_program text, p_dob date, p_as_of date) returns uuid
language sql stable security definer set search_path = '' as $$
  select v.id from public.schedule_versions v
   -- Retired versions still govern dates inside their own effective window (e.g. superseded but not yet ended).
   where v.organization_id = p_org and v.program_code = p_program and v.status in ('active','retired')
     and v.effective_from is not null and v.effective_from <= p_as_of and (v.effective_to is null or v.effective_to >= p_as_of)
     and (v.cohort_predicate ->> 'dobFrom' is null or (p_dob is not null and p_dob >= (v.cohort_predicate ->> 'dobFrom')::date))
     and (v.cohort_predicate ->> 'dobTo' is null or (p_dob is not null and p_dob <= (v.cohort_predicate ->> 'dobTo')::date))
   order by v.effective_from desc nulls last limit 1
$$;

-- Computes (and optionally persists) the child's evaluation. Returns {status:'no_active_schedule'} when nothing is approved.
create function private.compute_child_schedule(p_child uuid, p_as_of date, p_persist boolean, p_program text default 'routine') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.children; v_ver uuid; v_in jsonb; v_res jsonb; v_hash text; v_eval uuid; sv public.schedule_versions; x jsonb; rr jsonb; v_dose jsonb;
begin
  select * into c from public.children where id = p_child;
  v_in := private.child_eval_inputs(p_child);
  v_ver := private.active_schedule_for(c.organization_id, p_program, c.dob, p_as_of);
  if v_ver is null then
    return jsonb_build_object('status', 'no_active_schedule', 'pendingEvidence', v_in -> 'pendingEvidence');
  end if;
  select * into sv from public.schedule_versions where id = v_ver;
  v_res := private.evaluate_rules(v_ver, c.dob, (v_in ->> 'dobExact')::boolean, v_in -> 'doses', v_in -> 'holds', p_as_of);
  v_res := v_res || jsonb_build_object('status', 'evaluated', 'versionLabel', sv.version_label, 'programCode', sv.program_code, 'isDemo', sv.is_demo,
                                       'pendingEvidence', v_in -> 'pendingEvidence', 'childId', p_child, 'dob', c.dob);
  if p_persist then
    v_hash := encode(sha256(convert_to(jsonb_build_object('dob', c.dob, 'exact', v_in -> 'dobExact', 'doses', v_in -> 'doses', 'holds', v_in -> 'holds',
                                                          'version', v_ver, 'engine', 'plpgsql-1')::text, 'UTF8')), 'hex');
    insert into public.schedule_evaluations (organization_id, child_id, schedule_version_id, as_of_date, engine_version, input_hash, result, created_by)
    values (c.organization_id, p_child, v_ver, p_as_of, 'plpgsql-1', v_hash, v_res, auth.uid())
    on conflict (child_id, schedule_version_id, as_of_date, engine_version, input_hash) do nothing returning id into v_eval;
    if v_eval is null then
      select id into v_eval from public.schedule_evaluations
       where child_id = p_child and schedule_version_id = v_ver and as_of_date = p_as_of and engine_version = 'plpgsql-1' and input_hash = v_hash;
    else
      for rr in select * from jsonb_array_elements(v_res -> 'requirements') loop
        if rr ->> 'creditedDoseId' is not null then
          insert into public.dose_credits (organization_id, evaluation_id, rule_id, vaccination_revision_id, credit_status, reason)
          values (c.organization_id, v_eval, (rr ->> 'ruleId')::uuid, (rr ->> 'creditedDoseId')::uuid, 'credited', 'credited_by_verified_dose');
        elsif jsonb_array_length(coalesce(rr -> 'reasons' -> 0 -> 'doses', '[]'::jsonb)) > 0 then
          v_dose := rr -> 'reasons' -> 0 -> 'doses' -> 0;
          insert into public.dose_credits (organization_id, evaluation_id, rule_id, vaccination_revision_id, credit_status, reason)
          values (c.organization_id, v_eval, (rr ->> 'ruleId')::uuid, (v_dose ->> 'doseId')::uuid, 'not_credited', v_dose ->> 'reason');
        end if;
      end loop;
      -- Keep the child pointed at the version in force (old evaluations keep their own version reference).
      update public.child_programs set status = 'ended', ends_on = p_as_of, updated_by = auth.uid()
       where child_id = p_child and program_code = sv.program_code and status = 'active' and schedule_version_id <> v_ver;
      insert into public.child_programs (organization_id, child_id, schedule_version_id, program_code, starts_on, assignment_reason, created_by, updated_by)
      values (c.organization_id, p_child, v_ver, sv.program_code, p_as_of, 'automatic', auth.uid(), auth.uid())
      on conflict do nothing;
    end if;
    v_res := v_res || jsonb_build_object('evaluationId', v_eval, 'inputHash', v_hash);
  end if;
  return v_res;
end $$;

-- Staff: evaluate and persist a pinned snapshot for a child in their clinic.
create function public.evaluate_child(p_clinic_id uuid, p_child_id uuid, p_as_of date default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_canon uuid; v_res jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'child.read_clinical');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then
    perform private.audit(v_org, 'child.read_clinical', 'schedule.evaluate', 'child', p_child_id, null, null, null, 'denied');
    return null;
  end if;
  v_res := private.compute_child_schedule(v_canon, coalesce(p_as_of, private.local_today(p_clinic_id)), true);
  perform private.audit(v_org, 'child.read_clinical', 'schedule.evaluate', 'child', v_canon, null,
                        jsonb_build_object('status', v_res ->> 'status', 'evaluationId', v_res ->> 'evaluationId'), null);
  return v_res;
end $$;

-- Guardian with verified full access: computed for today, not persisted, limited projection (no internal reasons).
create function public.guardian_get_schedule(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid; v_res jsonb; v_clinic uuid; v_today date;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then return null; end if;
  select clinic_id into v_clinic from public.child_clinic_enrollments where child_id = v_canon and status in ('pending','active') order by is_primary desc, created_at limit 1;
  v_today := private.local_today(v_clinic);
  v_res := private.compute_child_schedule(v_canon, v_today, false);
  if v_res ->> 'status' <> 'evaluated' then return v_res; end if;
  return jsonb_build_object('status', 'evaluated', 'asOf', v_today, 'versionLabel', v_res ->> 'versionLabel', 'isDemo', (v_res ->> 'isDemo')::boolean,
    'pendingEvidence', v_res -> 'pendingEvidence',
    'requirements', (select coalesce(jsonb_agg(jsonb_build_object(
        'requirement', x ->> 'requirement', 'status', x ->> 'status', 'targetOn', x -> 'targetOn', 'recommendedOn', x -> 'recommendedOn',
        'windowStart', x -> 'windowStart', 'windowEnd', x -> 'windowEnd', 'creditedOn', x -> 'creditedOn') order by (x ->> 'ordinal')::int), '[]'::jsonb)
       from jsonb_array_elements(v_res -> 'requirements') x));
end $$;

revoke all on function public.evaluate_child(uuid, uuid, date) from public, anon, authenticated;
revoke all on function public.guardian_get_schedule(uuid) from public, anon, authenticated;
grant execute on function public.evaluate_child(uuid, uuid, date) to authenticated;
grant execute on function public.guardian_get_schedule(uuid) to authenticated;
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function private.has_capability(uuid, text), private.clinics_with(text), private.session_ok(),
  private.my_guardian_ids(), private.guardian_can_read_child(uuid) to authenticated;
-- END 0007_schedule_engine.sql

-- =====================================================================================================================
-- BEGIN 0008_schedule_lifecycle.sql  sha256=a05dd505e9cc89d1b6b025baef4b648eec010900725dcc476a52c97f908a4620
-- =====================================================================================================================
-- 0008 Clinical master data + schedule lifecycle: import -> review -> approve -> activate -> retire.
-- Blueprint refs: BP16 (rule lifecycle), BP38 P35/P36, F35, T31 (partly).
-- Separation of duties: a technical admin can import/stage master data; clinical activation requires rules.approve held by a
-- DIFFERENT person than the proposer. Demo versions can only exist while private.settings.demo_mode is true.

create function private.require_any(p_clinic uuid, p_caps text[]) returns void language plpgsql stable security definer set search_path = '' as $$
declare c text;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  foreach c in array p_caps loop
    if private.has_capability(p_clinic, c) then return; end if;
  end loop;
  raise exception 'forbidden' using errcode = 'CV403';
end $$;

-- ---------------------------------------------------------------------------------------------
-- Master data
-- ---------------------------------------------------------------------------------------------
create function public.create_antigen(p_operation_key uuid, p_clinic_id uuid, p_code text, p_name text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_id uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['admin.config','rules.propose']);
  v_prev := private.begin_command(v_org, p_operation_key, 'antigen.create', jsonb_build_object('c', p_clinic_id, 'code', p_code, 'name', p_name));
  if v_prev is not null then return v_prev; end if;
  insert into public.antigens (organization_id, code, name, created_by, updated_by) values (v_org, btrim(p_code), btrim(p_name), auth.uid(), auth.uid()) returning id into v_id;
  perform private.audit(v_org, 'master_data', 'antigen.created', 'antigen', v_id, null, jsonb_build_object('code', p_code), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('antigenId', v_id, 'status', 'draft'));
end $$;

create function public.create_vaccine_product(p_operation_key uuid, p_clinic_id uuid, p_product jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_id uuid; v_code text; v_a uuid; v_ac text; v_n int := 0;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['admin.config','rules.propose']);
  v_prev := private.begin_command(v_org, p_operation_key, 'product.create', jsonb_build_object('c', p_clinic_id, 'p', p_product));
  if v_prev is not null then return v_prev; end if;
  if p_product is null or jsonb_typeof(p_product) <> 'object' then raise exception 'product required' using errcode = 'CV400'; end if;
  if coalesce(jsonb_array_length(p_product -> 'antigenCodes'), 0) = 0 then raise exception 'a product must map to at least one antigen' using errcode = 'CV422'; end if;
  begin
    insert into public.vaccine_products (organization_id, code, name, manufacturer, presentation, stock_unit, doses_per_container, administration_unit, policy_reference, created_by, updated_by)
    values (v_org, btrim(p_product ->> 'code'), btrim(p_product ->> 'name'), nullif(btrim(coalesce(p_product ->> 'manufacturer', '')), ''), btrim(p_product ->> 'presentation'),
            btrim(p_product ->> 'stockUnit'), (p_product ->> 'dosesPerContainer')::numeric, btrim(p_product ->> 'administrationUnit'), coalesce(p_product ->> 'policyReference', ''), auth.uid(), auth.uid())
    returning id into v_id;
  exception when invalid_text_representation or not_null_violation then
    raise exception 'product details are incomplete or invalid' using errcode = 'CV422';
  end;
  for v_ac in select jsonb_array_elements_text(p_product -> 'antigenCodes') loop
    select id into v_a from public.antigens where organization_id = v_org and code = v_ac and status <> 'retired';
    if v_a is null then raise exception 'unknown antigen code %', v_ac using errcode = 'CV422'; end if;
    insert into public.product_antigens (organization_id, product_id, antigen_id, created_by) values (v_org, v_id, v_a, auth.uid());
    v_n := v_n + 1;
  end loop;
  perform private.audit(v_org, 'master_data', 'product.created', 'vaccine_product', v_id, null, jsonb_build_object('code', p_product ->> 'code', 'antigens', v_n), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('productId', v_id, 'status', 'draft'));
end $$;

-- Activation/retirement of master data is a clinical governance act: rules.approve, and not the creator.
create function public.set_master_status(p_operation_key uuid, p_clinic_id uuid, p_kind text, p_id uuid, p_status text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_creator uuid; v_cur text;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'rules.approve');
  if p_kind not in ('antigen','product') or p_status not in ('active','retired') then raise exception 'invalid request' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'master.set_status', jsonb_build_object('c', p_clinic_id, 'k', p_kind, 'id', p_id, 's', p_status));
  if v_prev is not null then return v_prev; end if;
  if p_kind = 'antigen' then
    select created_by, status into v_creator, v_cur from public.antigens where id = p_id and organization_id = v_org for update;
  else
    select created_by, status into v_creator, v_cur from public.vaccine_products where id = p_id and organization_id = v_org for update;
  end if;
  if v_cur is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if p_status = 'active' then
    if v_cur <> 'draft' then raise exception 'only draft items can be activated' using errcode = 'CV409'; end if;
    if v_creator = auth.uid() then raise exception 'activation requires a different person than the creator' using errcode = 'CV403'; end if;
    if p_kind = 'product' and exists (select 1 from public.product_antigens pa join public.antigens a on a.id = pa.antigen_id where pa.product_id = p_id and a.status <> 'active') then
      raise exception 'all mapped antigens must be active first' using errcode = 'CV409';
    end if;
  elsif v_cur = 'retired' then raise exception 'already retired' using errcode = 'CV409';
  end if;
  if p_kind = 'antigen' then update public.antigens set status = p_status, updated_by = auth.uid() where id = p_id;
  else update public.vaccine_products set status = p_status, updated_by = auth.uid() where id = p_id; end if;
  perform private.audit(v_org, 'rules.approve', 'master.' || p_kind || '.' || p_status, p_kind, p_id, jsonb_build_object('status', v_cur), jsonb_build_object('status', p_status), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('id', p_id, 'status', p_status));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Schedule import (draft)
-- ---------------------------------------------------------------------------------------------
create function public.import_schedule_draft(p_operation_key uuid, p_clinic_id uuid, p_payload jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_prev jsonb; v_ver uuid; v_demo boolean; v_program text; v_label text; v_src text;
  x jsonb; dep jsonb; fx jsonb; v_ant uuid; v_seq int; v_code text; v_ids jsonb := '{}'::jsonb; v_seqs jsonb := '{}'::jsonb;
  v_rid uuid; v_pid uuid; v_from date; v_to date; v_rules int := 0; v_deps int := 0; v_fx int := 0;
  allowed_status text[] := array['completed','not_yet_eligible','upcoming','due_today','due_now','overdue','past_recommended_date','staff_review_needed','not_applicable'];
  v_key text; v_val text; v_p text; v_d jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'rules.propose');
  v_prev := private.begin_command(v_org, p_operation_key, 'schedule.import', jsonb_build_object('c', p_clinic_id, 'p', p_payload));
  if v_prev is not null then return v_prev; end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then raise exception 'payload required' using errcode = 'CV400'; end if;

  v_demo := coalesce((p_payload ->> 'isDemo')::boolean, false);
  v_program := coalesce(nullif(btrim(p_payload ->> 'programCode'), ''), 'routine');
  v_label := nullif(btrim(coalesce(p_payload ->> 'versionLabel', '')), '');
  v_src := btrim(coalesce(p_payload ->> 'sourceReference', ''));
  if v_label is null then raise exception 'versionLabel is required' using errcode = 'CV422'; end if;
  if v_demo and not private.setting_bool('demo_mode') then raise exception 'demo schedules can only be imported while demo mode is on' using errcode = 'CV403'; end if;
  if not v_demo and v_src = '' then raise exception 'a real schedule must cite its authoritative source (sourceReference)' using errcode = 'CV422'; end if;
  if jsonb_typeof(p_payload -> 'rules') <> 'array' or jsonb_array_length(p_payload -> 'rules') not between 1 and 200 then raise exception 'rules must be an array of 1-200 items' using errcode = 'CV422'; end if;
  if jsonb_typeof(coalesce(p_payload -> 'fixtures', '[]'::jsonb)) <> 'array' then raise exception 'fixtures must be an array' using errcode = 'CV422'; end if;
  begin
    v_from := nullif(p_payload ->> 'effectiveFrom', '')::date; v_to := nullif(p_payload ->> 'effectiveTo', '')::date;
    perform (p_payload -> 'cohort' ->> 'dobFrom')::date, (p_payload -> 'cohort' ->> 'dobTo')::date;
  exception when others then raise exception 'invalid date in payload' using errcode = 'CV422';
  end;

  insert into public.schedule_versions (organization_id, program_code, version_label, status, is_demo, effective_from, effective_to, cohort_predicate, source_reference, source_hash, proposed_by, created_by, updated_by)
  values (v_org, v_program, v_label, 'draft', v_demo, v_from, v_to, coalesce(p_payload -> 'cohort', '{}'::jsonb), v_src, nullif(p_payload ->> 'sourceHash', ''), auth.uid(), auth.uid(), auth.uid())
  returning id into v_ver;

  for x in select * from jsonb_array_elements(p_payload -> 'rules') loop
    begin
      v_seq := (x ->> 'sequence')::int; v_code := btrim(x ->> 'requirement');
    exception when others then raise exception 'rule sequence must be an integer' using errcode = 'CV422';
    end;
    if v_seq is null or v_seq < 1 or v_code is null or v_code = '' then raise exception 'each rule needs a positive sequence and a requirement code' using errcode = 'CV422'; end if;
    if v_seqs ? v_code or exists (select 1 from jsonb_each_text(v_seqs) e where e.value = v_seq::text) then raise exception 'duplicate rule requirement or sequence: %', v_code using errcode = 'CV422'; end if;
    select id into v_ant from public.antigens where organization_id = v_org and code = x ->> 'antigen' and status <> 'retired';
    if v_ant is null then raise exception 'unknown antigen % in rule %', x ->> 'antigen', v_code using errcode = 'CV422'; end if;
    if not (private.valid_age(x -> 'targetOffset') and private.valid_age(x -> 'minimumAge') and private.valid_age(x -> 'maximumAge')
            and private.valid_age(x #> '{dueWindow,start}') and private.valid_age(x #> '{dueWindow,end}')) then
      raise exception 'invalid age/offset in rule % (value must be 0-9999 with unit days|weeks|months)', v_code using errcode = 'CV422';
    end if;
    if jsonb_typeof(coalesce(x -> 'acceptedProducts', '[]'::jsonb)) <> 'array' or jsonb_typeof(coalesce(x -> 'reviewConditions', '[]'::jsonb)) <> 'array' then
      raise exception 'acceptedProducts/reviewConditions must be arrays' using errcode = 'CV422';
    end if;
    for v_p in select jsonb_array_elements_text(coalesce(x -> 'acceptedProducts', '[]'::jsonb)) loop
      if not exists (select 1 from public.vaccine_products where organization_id = v_org and code = v_p and status <> 'retired') then
        raise exception 'unknown product code % in rule %', v_p, v_code using errcode = 'CV422';
      end if;
    end loop;
    if exists (select 1 from jsonb_array_elements_text(coalesce(x -> 'reviewConditions', '[]'::jsonb)) c where c <> 'clinician_review_required') then
      raise exception 'unsupported review condition in rule %', v_code using errcode = 'CV422';
    end if;
    insert into public.schedule_rules (organization_id, schedule_version_id, sequence_no, requirement_code, antigen_id, series_code, dose_ordinal, target_offset, minimum_age, maximum_age, due_window, review_conditions, accepted_products, created_by)
    values (v_org, v_ver, v_seq, v_code, v_ant, coalesce(nullif(btrim(x ->> 'series'), ''), v_code), coalesce((x ->> 'ordinal')::int, 1), x -> 'targetOffset', x -> 'minimumAge', x -> 'maximumAge', x -> 'dueWindow',
            coalesce(x -> 'reviewConditions', '[]'::jsonb), coalesce(x -> 'acceptedProducts', '[]'::jsonb), auth.uid())
    returning id into v_rid;
    v_ids := v_ids || jsonb_build_object(v_code, v_rid);
    v_seqs := v_seqs || jsonb_build_object(v_code, v_seq);
    v_rules := v_rules + 1;
  end loop;

  for dep in select * from jsonb_array_elements(coalesce(p_payload -> 'dependencies', '[]'::jsonb)) loop
    v_rid := (v_ids ->> (dep ->> 'rule'))::uuid; v_pid := (v_ids ->> (dep ->> 'predecessor'))::uuid;
    if v_rid is null or v_pid is null then raise exception 'dependency references an unknown requirement' using errcode = 'CV422'; end if;
    -- Predecessors must come earlier in sequence, which makes the dependency graph acyclic by construction.
    if (v_seqs ->> (dep ->> 'predecessor'))::int >= (v_seqs ->> (dep ->> 'rule'))::int then raise exception 'a predecessor must have a lower sequence than its dependent rule' using errcode = 'CV422'; end if;
    v_d := dep -> 'minimumInterval';
    if v_d is null or not private.valid_age(v_d) then raise exception 'invalid minimumInterval' using errcode = 'CV422'; end if;
    insert into public.schedule_rule_dependencies (organization_id, rule_id, predecessor_rule_id, minimum_interval_value, interval_unit, created_by)
    values (v_org, v_rid, v_pid, (v_d ->> 'value')::int, v_d ->> 'unit', auth.uid());
    v_deps := v_deps + 1;
  end loop;

  for fx in select * from jsonb_array_elements(coalesce(p_payload -> 'fixtures', '[]'::jsonb)) loop
    if nullif(btrim(fx ->> 'name'), '') is null or jsonb_typeof(fx -> 'expected') <> 'object' then raise exception 'each fixture needs a name and expected statuses' using errcode = 'CV422'; end if;
    for v_key, v_val in select key, value from jsonb_each_text(fx -> 'expected') loop
      if not (v_ids ? v_key) then raise exception 'fixture % expects unknown requirement %', fx ->> 'name', v_key using errcode = 'CV422'; end if;
      if v_val <> all (allowed_status) then raise exception 'fixture % uses unknown status %', fx ->> 'name', v_val using errcode = 'CV422'; end if;
    end loop;
    begin
      insert into public.schedule_fixtures (organization_id, schedule_version_id, name, dob, doses, as_of, expected, created_by)
      values (v_org, v_ver, btrim(fx ->> 'name'), (fx ->> 'dob')::date, coalesce(fx -> 'doses', '[]'::jsonb), (fx ->> 'asOf')::date, fx -> 'expected', auth.uid());
    exception when invalid_text_representation or datetime_field_overflow or not_null_violation then
      raise exception 'fixture % has an invalid or missing date', fx ->> 'name' using errcode = 'CV422';
    end;
    v_fx := v_fx + 1;
  end loop;

  perform private.audit(v_org, 'rules.propose', 'schedule.imported', 'schedule_version', v_ver, null,
                        jsonb_build_object('program', v_program, 'label', v_label, 'demo', v_demo, 'rules', v_rules, 'dependencies', v_deps, 'fixtures', v_fx), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', v_ver, 'status', 'draft', 'rules', v_rules, 'dependencies', v_deps, 'fixtures', v_fx));
end $$;

create function public.submit_schedule_for_review(p_operation_key uuid, p_clinic_id uuid, p_version_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; sv public.schedule_versions;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'rules.propose');
  v_prev := private.begin_command(v_org, p_operation_key, 'schedule.submit', jsonb_build_object('c', p_clinic_id, 'v', p_version_id));
  if v_prev is not null then return v_prev; end if;
  select * into sv from public.schedule_versions where id = p_version_id and organization_id = v_org for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if sv.status <> 'draft' then raise exception 'only drafts can be submitted' using errcode = 'CV409'; end if;
  if not exists (select 1 from public.schedule_fixtures where schedule_version_id = sv.id) then raise exception 'add at least one fixture case before review' using errcode = 'CV422'; end if;
  update public.schedule_versions set status = 'clinical_review', updated_by = auth.uid() where id = sv.id;
  perform private.audit(v_org, 'rules.propose', 'schedule.submitted', 'schedule_version', sv.id, jsonb_build_object('status', 'draft'), jsonb_build_object('status', 'clinical_review'), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', sv.id, 'status', 'clinical_review'));
end $$;

create function public.approve_schedule(p_operation_key uuid, p_clinic_id uuid, p_version_id uuid, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; sv public.schedule_versions; v_fx jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'rules.approve');
  v_prev := private.begin_command(v_org, p_operation_key, 'schedule.approve', jsonb_build_object('c', p_clinic_id, 'v', p_version_id, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  select * into sv from public.schedule_versions where id = p_version_id and organization_id = v_org for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if sv.status <> 'clinical_review' then raise exception 'version is not awaiting review' using errcode = 'CV409'; end if;
  if sv.proposed_by = auth.uid() then raise exception 'the proposer cannot approve their own schedule' using errcode = 'CV403'; end if;
  v_fx := private.run_fixtures(sv.id);
  if jsonb_array_length(v_fx) = 0 or exists (select 1 from jsonb_array_elements(v_fx) f where not (f ->> 'passed')::boolean) then
    raise exception 'fixture cases must all pass before approval' using errcode = 'CV422';
  end if;
  update public.schedule_versions set status = 'approved', approved_by = auth.uid(), reviewed_by = auth.uid(), approved_at = now(), updated_by = auth.uid() where id = sv.id;
  perform private.audit(v_org, 'rules.approve', 'schedule.approved', 'schedule_version', sv.id, jsonb_build_object('status', sv.status), jsonb_build_object('status', 'approved', 'fixtures', jsonb_array_length(v_fx)), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', sv.id, 'status', 'approved'));
end $$;

create function public.activate_schedule(p_operation_key uuid, p_clinic_id uuid, p_version_id uuid, p_effective_from date) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; sv public.schedule_versions; old public.schedule_versions; v_fx jsonb; v_today date; v_affected int;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'rules.approve');
  v_prev := private.begin_command(v_org, p_operation_key, 'schedule.activate', jsonb_build_object('c', p_clinic_id, 'v', p_version_id, 'from', p_effective_from));
  if v_prev is not null then return v_prev; end if;
  select * into sv from public.schedule_versions where id = p_version_id and organization_id = v_org for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if sv.status <> 'approved' then raise exception 'only approved versions can be activated' using errcode = 'CV409'; end if;
  if sv.is_demo and not private.setting_bool('demo_mode') then raise exception 'demo schedules cannot be activated outside demo mode' using errcode = 'CV403'; end if;
  v_today := private.local_today(p_clinic_id);
  if p_effective_from is null or p_effective_from < v_today then raise exception 'effective date must be today or later' using errcode = 'CV422'; end if;
  v_fx := private.run_fixtures(sv.id);
  if jsonb_array_length(v_fx) = 0 or exists (select 1 from jsonb_array_elements(v_fx) f where not (f ->> 'passed')::boolean) then
    raise exception 'fixture cases must all pass before activation' using errcode = 'CV422';
  end if;
  -- Lock the program row set, then retire the version in force so exactly one stays active (BP16).
  select * into old from public.schedule_versions where organization_id = v_org and program_code = sv.program_code and status = 'active' for update;
  if found then
    if p_effective_from <= old.effective_from then raise exception 'new version must take effect after the current one (%)', old.effective_from using errcode = 'CV422'; end if;
    update public.schedule_versions set status = 'retired', effective_to = p_effective_from - 1, updated_by = auth.uid() where id = old.id;
  end if;
  update public.schedule_versions set status = 'active', effective_from = p_effective_from, supersedes_id = old.id, updated_by = auth.uid() where id = sv.id;
  select count(*) into v_affected from public.child_programs where organization_id = v_org and program_code = sv.program_code and status = 'active';
  perform private.audit(v_org, 'rules.approve', 'schedule.activated', 'schedule_version', sv.id, jsonb_build_object('previous', old.id),
                        jsonb_build_object('effectiveFrom', p_effective_from, 'childrenToRecalculate', v_affected), null);
  -- Recalculation is lazy: the next evaluation of each child pins the new version; old evaluations keep their own reference.
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', sv.id, 'status', 'active', 'effectiveFrom', p_effective_from, 'childrenToRecalculate', v_affected));
end $$;

create function public.retire_schedule(p_operation_key uuid, p_clinic_id uuid, p_version_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; sv public.schedule_versions;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'rules.approve');
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'schedule.retire', jsonb_build_object('c', p_clinic_id, 'v', p_version_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into sv from public.schedule_versions where id = p_version_id and organization_id = v_org for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if sv.status not in ('active','approved') then raise exception 'only approved or active versions can be retired' using errcode = 'CV409'; end if;
  -- Manual retirement stops use immediately: the effective window ends yesterday (clinic-local).
  update public.schedule_versions set status = 'retired', effective_to = private.local_today(p_clinic_id) - 1, updated_by = auth.uid() where id = sv.id;
  perform private.audit(v_org, 'rules.approve', 'schedule.retired', 'schedule_version', sv.id, jsonb_build_object('status', sv.status), jsonb_build_object('status', 'retired'), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', sv.id, 'status', 'retired'));
end $$;

create function public.discard_schedule_draft(p_operation_key uuid, p_clinic_id uuid, p_version_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; sv public.schedule_versions;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['rules.propose','rules.approve']);
  v_prev := private.begin_command(v_org, p_operation_key, 'schedule.discard', jsonb_build_object('c', p_clinic_id, 'v', p_version_id));
  if v_prev is not null then return v_prev; end if;
  select * into sv from public.schedule_versions where id = p_version_id and organization_id = v_org for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if sv.status <> 'draft' then raise exception 'only drafts can be discarded' using errcode = 'CV409'; end if;
  delete from public.schedule_rule_dependencies where rule_id in (select id from public.schedule_rules where schedule_version_id = sv.id);
  delete from public.schedule_fixtures where schedule_version_id = sv.id;
  delete from public.schedule_rules where schedule_version_id = sv.id;
  delete from public.schedule_versions where id = sv.id;
  perform private.audit(v_org, 'rules.propose', 'schedule.discarded', 'schedule_version', sv.id, jsonb_build_object('label', sv.version_label), null, null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', sv.id, 'discarded', true));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Reads for the configuration pages
-- ---------------------------------------------------------------------------------------------
create function public.list_clinical_master(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['admin.config','rules.propose','rules.approve']);
  return jsonb_build_object(
    'demoMode', private.setting_bool('demo_mode'),
    'antigens', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'code', a.code, 'name', a.name, 'status', a.status, 'createdBy', a.created_by) order by a.code) from public.antigens a where a.organization_id = v_org), '[]'::jsonb),
    'products', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'code', p.code, 'name', p.name, 'presentation', p.presentation, 'status', p.status, 'createdBy', p.created_by,
        'antigens', coalesce((select jsonb_agg(a.code order by a.code) from public.product_antigens pa join public.antigens a on a.id = pa.antigen_id where pa.product_id = p.id), '[]'::jsonb)) order by p.code)
        from public.vaccine_products p where p.organization_id = v_org), '[]'::jsonb),
    'schedules', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'program', s.program_code, 'label', s.version_label, 'status', s.status, 'isDemo', s.is_demo,
        'effectiveFrom', s.effective_from, 'effectiveTo', s.effective_to, 'proposedBy', s.proposed_by, 'approvedBy', s.approved_by,
        'rules', (select count(*) from public.schedule_rules r where r.schedule_version_id = s.id),
        'fixtures', (select count(*) from public.schedule_fixtures f where f.schedule_version_id = s.id)) order by s.created_at desc)
        from public.schedule_versions s where s.organization_id = v_org), '[]'::jsonb));
end $$;

create function public.get_schedule_version(p_clinic_id uuid, p_version_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; sv public.schedule_versions;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['admin.config','rules.propose','rules.approve']);
  select * into sv from public.schedule_versions where id = p_version_id and organization_id = v_org;
  if not found then return null; end if;
  return jsonb_build_object(
    'id', sv.id, 'program', sv.program_code, 'label', sv.version_label, 'status', sv.status, 'isDemo', sv.is_demo, 'source', sv.source_reference,
    'effectiveFrom', sv.effective_from, 'effectiveTo', sv.effective_to, 'cohort', sv.cohort_predicate, 'proposedBy', sv.proposed_by, 'approvedBy', sv.approved_by, 'version', sv.version,
    'rules', coalesce((select jsonb_agg(jsonb_build_object('sequence', r.sequence_no, 'requirement', r.requirement_code, 'antigen', a.code, 'series', r.series_code, 'ordinal', r.dose_ordinal,
        'targetOffset', r.target_offset, 'minimumAge', r.minimum_age, 'maximumAge', r.maximum_age, 'dueWindow', r.due_window, 'acceptedProducts', r.accepted_products,
        'dependsOn', coalesce((select jsonb_agg(jsonb_build_object('predecessor', pr.requirement_code, 'interval', jsonb_build_object('value', d.minimum_interval_value, 'unit', d.interval_unit)))
                                 from public.schedule_rule_dependencies d join public.schedule_rules pr on pr.id = d.predecessor_rule_id where d.rule_id = r.id), '[]'::jsonb)) order by r.sequence_no)
        from public.schedule_rules r join public.antigens a on a.id = r.antigen_id where r.schedule_version_id = sv.id), '[]'::jsonb),
    'fixtures', private.run_fixtures(sv.id));
end $$;

create function public.preview_schedule_impact(p_clinic_id uuid, p_version_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; sv public.schedule_versions; v_match int; v_moving int;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['rules.propose','rules.approve']);
  select * into sv from public.schedule_versions where id = p_version_id and organization_id = v_org;
  if not found then return null; end if;
  select count(*) into v_match from public.children c
   where c.organization_id = v_org and c.record_status in ('provisional','active') and c.dob is not null
     and (sv.cohort_predicate ->> 'dobFrom' is null or c.dob >= (sv.cohort_predicate ->> 'dobFrom')::date)
     and (sv.cohort_predicate ->> 'dobTo' is null or c.dob <= (sv.cohort_predicate ->> 'dobTo')::date);
  select count(*) into v_moving from public.child_programs cp where cp.organization_id = v_org and cp.program_code = sv.program_code and cp.status = 'active' and cp.schedule_version_id <> sv.id;
  return jsonb_build_object('cohortChildren', v_match, 'childrenOnAnotherVersion', v_moving);
end $$;

do $$
declare f text;
begin
  foreach f in array array[
    'create_antigen(uuid,uuid,text,text)', 'create_vaccine_product(uuid,uuid,jsonb)', 'set_master_status(uuid,uuid,text,uuid,text)',
    'import_schedule_draft(uuid,uuid,jsonb)', 'submit_schedule_for_review(uuid,uuid,uuid)', 'approve_schedule(uuid,uuid,uuid,text)',
    'activate_schedule(uuid,uuid,uuid,date)', 'retire_schedule(uuid,uuid,uuid,text)', 'discard_schedule_draft(uuid,uuid,uuid)',
    'list_clinical_master(uuid)', 'get_schedule_version(uuid,uuid)', 'preview_schedule_impact(uuid,uuid)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function private.has_capability(uuid, text), private.clinics_with(text), private.session_ok(),
  private.my_guardian_ids(), private.guardian_can_read_child(uuid) to authenticated;
-- END 0008_schedule_lifecycle.sql

-- =====================================================================================================================
-- BEGIN 0009_evidence_history.sql  sha256=5b7b1139dfa4567a39aec346e81e9490cabc892d55c8da0636d11cd58dfea349
-- =====================================================================================================================
-- 0009 Outside-vaccination evidence, verification (as an immutable revision), and history reads.
-- Blueprint refs: BP15.C, BP18 (provenance), F04, T09. A parent/BHW report NEVER becomes a credited dose until a
-- clinician with evidence.verify maps it to an approved product and confirms the date; that confirmation is a new revision.

alter table public.record_review_cases add column vaccination_event_id uuid;
alter table public.record_review_cases add foreign key (organization_id, vaccination_event_id) references public.vaccination_events (organization_id, id);

-- Product presentation/conversion may not change once history references the product (BP28.3).
create function private.product_immutable_when_used() returns trigger language plpgsql set search_path = '' as $$
begin
  if (new.code, new.presentation, new.stock_unit, new.doses_per_container, new.administration_unit)
     is distinct from (old.code, old.presentation, old.stock_unit, old.doses_per_container, old.administration_unit)
     and exists (select 1 from public.vaccination_revisions r where r.product_id = old.id) then
    raise exception 'product presentation is immutable once used; create a new product record' using errcode = 'CV409';
  end if;
  return new;
end $$;
create trigger vaccine_products_immutable_when_used before update on public.vaccine_products for each row execute function private.product_immutable_when_used();

create function private.clean_outside_dose(p jsonb) returns jsonb language plpgsql stable set search_path = '' as $$
declare v_on date; v_prec text; v_text text := nullif(left(btrim(coalesce(p ->> 'productText', '')), 200), '');
begin
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'dose details required' using errcode = 'CV400'; end if;
  if v_text is null then raise exception 'describe the vaccine that was given' using errcode = 'CV422'; end if;
  begin v_on := nullif(p ->> 'administeredOn', '')::date; exception when others then raise exception 'invalid date' using errcode = 'CV422'; end;
  v_prec := coalesce(nullif(p ->> 'precision', ''), case when v_on is null then 'unknown' else 'exact' end);
  if v_prec not in ('exact','month','year','unknown') then raise exception 'invalid date precision' using errcode = 'CV422'; end if;
  if v_prec = 'exact' and v_on is null then raise exception 'an exact date is required (or choose a less precise option)' using errcode = 'CV422'; end if;
  if v_prec = 'unknown' then v_on := null; end if;
  if v_on is not null and v_on > current_date + 1 then raise exception 'an administration date cannot be in the future' using errcode = 'CV422'; end if;
  return jsonb_build_object('productText', v_text, 'administeredOn', v_on, 'precision', v_prec,
    'provider', nullif(left(btrim(coalesce(p ->> 'provider', '')), 200), ''), 'lotText', nullif(left(btrim(coalesce(p ->> 'lotText', '')), 100), ''),
    'reference', nullif(left(btrim(coalesce(p ->> 'reference', '')), 200), ''));
end $$;

-- Guardian (verified, full access) reports a dose given elsewhere. Pending evidence only; no credit, no stock effect.
create function public.report_outside_dose(p_operation_key uuid, p_child_id uuid, p_dose jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_canon uuid; v_prev jsonb; v_clean jsonb; v_ev uuid; v_clinic uuid; v_g uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then raise exception 'not found' using errcode = 'CV404'; end if;
  select organization_id into v_org from public.children where id = v_canon;
  v_prev := private.begin_command(v_org, p_operation_key, 'evidence.report', jsonb_build_object('child', p_child_id, 'dose', p_dose));
  if v_prev is not null then return v_prev; end if;
  v_clean := private.clean_outside_dose(p_dose);
  select clinic_id into v_clinic from public.child_clinic_enrollments where child_id = v_canon and status in ('pending','active') order by is_primary desc, created_at limit 1;
  select id into v_g from public.guardians where organization_id = v_org and profile_id = auth.uid();
  insert into public.vaccination_events (organization_id, original_child_id, origin, external_provider, external_reference, source_operation_id, created_by)
  values (v_org, v_canon, 'parent_reported', v_clean ->> 'provider', v_clean ->> 'reference', p_operation_key, auth.uid()) returning id into v_ev;
  insert into public.vaccination_revisions (organization_id, event_id, revision_no, child_id, reported_product_text, administered_on, date_precision, reported_lot,
                                             external_vaccinator, clinic_id, source, verification_status, created_by)
  values (v_org, v_ev, 1, v_canon, v_clean ->> 'productText', (v_clean ->> 'administeredOn')::date, v_clean ->> 'precision', v_clean ->> 'lotText',
          v_clean ->> 'provider', v_clinic, 'parent_reported', 'pending_verification', auth.uid());
  insert into public.record_review_cases (organization_id, clinic_id, kind, child_id, guardian_id, vaccination_event_id, reason, evidence, created_by, updated_by)
  values (v_org, v_clinic, 'clinical', v_canon, v_g, v_ev, 'outside vaccination evidence awaiting clinician verification',
          jsonb_build_object('reportedProduct', v_clean ->> 'productText', 'reportedDate', v_clean ->> 'administeredOn'), auth.uid(), auth.uid());
  perform private.audit(v_org, 'guardian', 'evidence.reported', 'vaccination_event', v_ev, null, jsonb_build_object('status', 'pending_verification'), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('eventId', v_ev, 'verificationStatus', 'pending_verification'));
end $$;

-- Staff enters an outside/historical dose, optionally verified on the spot against a document they have seen.
create function public.record_outside_dose_staff(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_dose jsonb, p_product_id uuid default null, p_verified boolean default false)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_canon uuid; v_prev jsonb; v_clean jsonb; v_ev uuid; v_status text;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'evidence.verify');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'evidence.record_staff',
                                  jsonb_build_object('c', p_clinic_id, 'child', p_child_id, 'dose', p_dose, 'p', p_product_id, 'v', p_verified));
  if v_prev is not null then return v_prev; end if;
  v_clean := private.clean_outside_dose(p_dose);
  if p_verified then
    if p_product_id is null or not exists (select 1 from public.vaccine_products where id = p_product_id and organization_id = v_org and status = 'active') then
      raise exception 'verification needs an active approved product' using errcode = 'CV422';
    end if;
    if v_clean ->> 'precision' <> 'exact' then raise exception 'verification needs an exact date' using errcode = 'CV422'; end if;
  end if;
  v_status := case when p_verified then 'verified' else 'pending_verification' end;
  insert into public.vaccination_events (organization_id, original_child_id, origin, external_provider, external_reference, source_operation_id, created_by)
  values (v_org, v_canon, 'external', v_clean ->> 'provider', v_clean ->> 'reference', p_operation_key, auth.uid()) returning id into v_ev;
  insert into public.vaccination_revisions (organization_id, event_id, revision_no, child_id, product_id, reported_product_text, administered_on, date_precision, reported_lot,
                                             external_vaccinator, clinic_id, source, verification_status, approved_by, signed_at, created_by)
  values (v_org, v_ev, 1, v_canon, case when p_verified then p_product_id end, v_clean ->> 'productText', (v_clean ->> 'administeredOn')::date, v_clean ->> 'precision',
          v_clean ->> 'lotText', v_clean ->> 'provider', p_clinic_id, 'external_documented', v_status, case when p_verified then auth.uid() end, case when p_verified then now() end, auth.uid());
  perform private.audit(v_org, 'evidence.verify', 'evidence.recorded_by_staff', 'vaccination_event', v_ev, null, jsonb_build_object('status', v_status), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('eventId', v_ev, 'verificationStatus', v_status));
end $$;

-- Verification/rejection = a NEW immutable revision, attributed to the verifier. The original report stays recoverable.
create function public.verify_outside_dose(p_operation_key uuid, p_clinic_id uuid, p_event_id uuid, p_decision text, p_product_id uuid default null,
                                           p_administered_on date default null, p_note text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; cur public.vaccination_revisions; v_on date; v_status text;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'evidence.verify');
  if p_decision not in ('verify','reject') then raise exception 'invalid decision' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'evidence.verify', jsonb_build_object('c', p_clinic_id, 'e', p_event_id, 'd', p_decision, 'p', p_product_id, 'on', p_administered_on, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  perform 1 from public.vaccination_events where id = p_event_id and organization_id = v_org for update;
  select * into cur from private.current_revisions where event_id = p_event_id;
  if cur.id is null or not private.child_in_clinic(private.canonical_child(cur.child_id), p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if cur.verification_status <> 'pending_verification' then raise exception 'evidence is not awaiting verification' using errcode = 'CV409'; end if;
  if p_decision = 'reject' then
    if p_note is null or length(btrim(p_note)) < 3 then raise exception 'a reason is required to reject evidence' using errcode = 'CV422'; end if;
    v_status := 'rejected';
  else
    if p_product_id is null or not exists (select 1 from public.vaccine_products where id = p_product_id and organization_id = v_org and status = 'active') then
      raise exception 'map the report to an active approved product' using errcode = 'CV422';
    end if;
    v_on := coalesce(p_administered_on, case when cur.date_precision = 'exact' then cur.administered_on end);
    if v_on is null then raise exception 'confirm an exact administration date' using errcode = 'CV422'; end if;
    if v_on > current_date + 1 then raise exception 'an administration date cannot be in the future' using errcode = 'CV422'; end if;
    v_status := 'verified';
  end if;
  insert into public.vaccination_revisions (organization_id, event_id, revision_no, child_id, product_id, reported_product_text, administered_on, date_precision, reported_lot,
                                             external_vaccinator, clinic_id, source, verification_status, approved_by, signed_at, reason, created_by)
  values (v_org, cur.event_id, cur.revision_no + 1, cur.child_id, case when v_status = 'verified' then p_product_id else cur.product_id end, cur.reported_product_text,
          case when v_status = 'verified' then v_on else cur.administered_on end, case when v_status = 'verified' then 'exact' else cur.date_precision end,
          cur.reported_lot, cur.external_vaccinator, coalesce(cur.clinic_id, p_clinic_id), cur.source, v_status, auth.uid(), now(), p_note, auth.uid());
  update public.record_review_cases set status = case when v_status = 'verified' then 'resolved' else 'rejected' end, resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', p_decision, 'note', p_note)
   where vaccination_event_id = cur.event_id and status in ('open','in_review');
  perform private.audit(v_org, 'evidence.verify', 'evidence.' || p_decision, 'vaccination_event', cur.event_id,
                        jsonb_build_object('status', cur.verification_status, 'revision', cur.revision_no), jsonb_build_object('status', v_status, 'revision', cur.revision_no + 1), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('eventId', cur.event_id, 'verificationStatus', v_status, 'revisionNo', cur.revision_no + 1));
end $$;

create function public.list_child_history(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_canon uuid; v_res jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'child.read_clinical');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then
    perform private.audit(v_org, 'child.read_clinical', 'history.view', 'child', p_child_id, null, null, null, 'denied');
    return null;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'eventId', cr.event_id, 'revisionNo', cr.revision_no, 'origin', e.origin, 'source', cr.source, 'verificationStatus', cr.verification_status,
    'eventStatus', cr.event_status, 'administeredOn', cr.administered_on, 'datePrecision', cr.date_precision,
    'product', p.name, 'productCode', p.code, 'reportedProduct', cr.reported_product_text, 'reportedLot', cr.reported_lot, 'provider', cr.external_vaccinator,
    'amended', cr.revision_no > 1) order by cr.administered_on desc nulls last, cr.created_at desc), '[]'::jsonb) into v_res
    from private.current_revisions cr join public.vaccination_events e on e.id = cr.event_id left join public.vaccine_products p on p.id = cr.product_id
   where cr.child_id in (select private.child_ids_with_aliases(v_canon));
  perform private.audit(v_org, 'child.read_clinical', 'history.view', 'child', v_canon, null, null, null);
  return v_res;
end $$;

create function public.guardian_child_history(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then return null; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
    'eventId', cr.event_id, 'administeredOn', cr.administered_on, 'datePrecision', cr.date_precision, 'product', coalesce(p.name, cr.reported_product_text),
    -- Provenance stays visible: reported-elsewhere is never presented as a clinic-verified dose.
    'status', case when cr.verification_status = 'verified' then 'verified' when cr.verification_status = 'pending_verification' then 'pending_verification' else 'not_accepted' end,
    'source', case when cr.source = 'clinic_administered' then 'clinic' else 'recorded_elsewhere' end)
    order by cr.administered_on desc nulls last), '[]'::jsonb)
    from private.current_revisions cr left join public.vaccine_products p on p.id = cr.product_id
   where cr.child_id in (select private.child_ids_with_aliases(v_canon)) and cr.event_status = 'active');
end $$;

do $$
declare f text;
begin
  foreach f in array array[
    'report_outside_dose(uuid,uuid,jsonb)', 'record_outside_dose_staff(uuid,uuid,uuid,jsonb,uuid,boolean)',
    'verify_outside_dose(uuid,uuid,uuid,text,uuid,date,text)', 'list_child_history(uuid,uuid)', 'guardian_child_history(uuid)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function private.has_capability(uuid, text), private.clinics_with(text), private.session_ok(),
  private.my_guardian_ids(), private.guardian_can_read_child(uuid) to authenticated;
-- END 0009_evidence_history.sql

-- =====================================================================================================================
-- BEGIN 0010_active_products.sql  sha256=5d185dae9454de4a3503708ef1adec6b5fd8fa26461f007e3eb85a7943c42f7f
-- =====================================================================================================================
-- 0010 Product picker for clinical recording forms (active products only, no configuration data).

create function public.list_active_products(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['evidence.verify','vaccination.record','inventory.manage','rules.propose','rules.approve']);
  return coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'code', p.code, 'name', p.name,
      'antigens', coalesce((select jsonb_agg(a.code order by a.code) from public.product_antigens pa join public.antigens a on a.id = pa.antigen_id where pa.product_id = p.id), '[]'::jsonb)) order by p.name)
    from public.vaccine_products p where p.organization_id = v_org and p.status = 'active'), '[]'::jsonb);
end $$;
revoke all on function public.list_active_products(uuid) from public, anon, authenticated;
grant execute on function public.list_active_products(uuid) to authenticated;
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function private.has_capability(uuid, text), private.clinics_with(text), private.session_ok(),
  private.my_guardian_ids(), private.guardian_can_read_child(uuid) to authenticated;
-- END 0010_active_products.sql

-- =====================================================================================================================
-- BEGIN 0011_inventory.sql  sha256=ecaf7bba57b66ad250d7da12abe9d3c3b0684e48154daeef8daae3b4b6698fd3
-- =====================================================================================================================
-- 0011 Vaccine inventory: lots, locations, immutable signed ledger, rebuildable balance projection.
-- Blueprint refs: BP19, BP28.4, F12, F15 (basic), T13, T14 (normal path), T15 (posting side), T16 (movement side).
--
-- Rules
--  * The ledger (stock_movements) is the truth. stock_balances is a projection maintained in the same transaction and can be
--    rebuilt and reconciled. Nobody edits a counter.
--  * physical on-hand, usable stock, quarantine and expired are different numbers.
--  * Single-dose presentations only for issue. Multi-dose products (doses_per_container <> 1) are blocked from issue until the
--    vial-session workflow exists (BP19 / MVP checklist).
--  * Expiry interpretation (is the printed date still usable?) is a cold-chain policy question: private.settings key
--    'expiry_last_day_usable' (default true) -- Requires external validation.

insert into private.settings(key, value) values
  ('expiry_last_day_usable', 'true'::jsonb),          -- policy: lot usable through its expiry date (needs validation)
  ('adjustment_auto_approve_units', '0'::jsonb)       -- |delta| above this needs inventory.approve (0 = every adjustment)
  on conflict (key) do nothing;

create table public.vaccine_lots (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  product_id uuid not null,
  manufacturer_lot text not null check (length(btrim(manufacturer_lot)) between 1 and 60),
  expires_on date not null,
  manufacturer text,
  global_disposition text not null default 'usable' check (global_disposition in ('usable','quarantined','recalled')),
  policy_version text not null default '',
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, product_id) references public.vaccine_products (organization_id, id),
  unique (organization_id, id), unique (organization_id, product_id, manufacturer_lot)
);
create index vaccine_lots_expiry_idx on public.vaccine_lots (expires_on, global_disposition);
create trigger vaccine_lots_touch before update on public.vaccine_lots for each row execute function private.touch_row();

-- Lot identity is immutable; only disposition may change, and only through commands (no direct grants exist anyway).
create function private.lot_identity_guard() returns trigger language plpgsql set search_path = '' as $$
begin
  if (new.product_id, new.manufacturer_lot, new.expires_on, new.manufacturer) is distinct from (old.product_id, old.manufacturer_lot, old.expires_on, old.manufacturer) then
    raise exception 'lot identity is immutable; use a reviewed correction' using errcode = 'CV409';
  end if;
  return new;
end $$;
create trigger vaccine_lots_identity before update on public.vaccine_lots for each row execute function private.lot_identity_guard();

create table public.stock_locations (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  name text not null check (length(btrim(name)) between 1 and 80),
  kind text not null check (kind in ('usable','quarantine','in_transit')),
  status text not null default 'active' check (status in ('active','closed')),
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  unique (organization_id, id), unique (clinic_id, name)
);
create trigger stock_locations_touch before update on public.stock_locations for each row execute function private.touch_row();

create table public.stock_transactions (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  type text not null check (type in ('receipt','issue_administration','wastage','adjustment','transfer_out','transfer_in','reversal')),
  source_reference text not null default '',
  event_id uuid,                     -- links an administration issue to its vaccination event (M06)
  reason text,
  approved_by uuid references public.profiles (id),
  operation_id uuid not null,        -- the client Idempotency-Key that caused this posting
  reverses_id uuid,
  occurred_at timestamptz not null default now(),
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, event_id) references public.vaccination_events (organization_id, id),
  foreign key (reverses_id) references public.stock_transactions (id),
  unique (organization_id, id), unique (organization_id, operation_id, type)
);
create index stock_tx_clinic_idx on public.stock_transactions (clinic_id, occurred_at desc);

create table public.stock_movements (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  transaction_id uuid not null,
  location_id uuid not null,
  lot_id uuid not null,
  quantity_delta numeric not null check (quantity_delta <> 0),
  unit text not null,
  movement_key text not null,
  occurred_at timestamptz not null default now(),
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  foreign key (organization_id, transaction_id) references public.stock_transactions (organization_id, id),
  foreign key (organization_id, location_id) references public.stock_locations (organization_id, id),
  foreign key (organization_id, lot_id) references public.vaccine_lots (organization_id, id),
  unique (organization_id, movement_key)
);
create index stock_movements_lot_idx on public.stock_movements (lot_id, location_id, occurred_at);
create index stock_movements_tx_idx on public.stock_movements (transaction_id);

create table public.stock_balances (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  location_id uuid not null, lot_id uuid not null,
  on_hand numeric not null default 0 check (on_hand >= 0),
  allocated numeric not null default 0 check (allocated >= 0 and allocated <= on_hand),
  reconciled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (organization_id, location_id) references public.stock_locations (organization_id, id),
  foreign key (organization_id, lot_id) references public.vaccine_lots (organization_id, id),
  unique (location_id, lot_id)
);

create trigger stock_transactions_immutable before update or delete on public.stock_transactions for each row execute function private.forbid_change();
create trigger stock_movements_immutable before update or delete on public.stock_movements for each row execute function private.forbid_change();

-- TRUNCATE bypasses row triggers, so append-only tables need statement-level guards too (found by test: the ledger could be wiped).
do $$
declare t text;
begin
  foreach t in array array['public.stock_transactions','public.stock_movements','public.vaccination_events','public.vaccination_revisions','public.schedule_evaluations','public.dose_credits','public.privacy_records','private.command_receipts'] loop
    execute format('create trigger %I before truncate on %s for each statement execute function private.forbid_change()', replace(t, '.', '_') || '_no_truncate', t);
  end loop;
end $$;

-- Projection maintained in the SAME transaction as the ledger insert; row lock serialises concurrent postings.
create function private.apply_movement() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  -- UPDATE first: an INSERT ... ON CONFLICT checks the proposed row's CHECK constraints before conflict resolution, so a
  -- negative delta would be rejected even though the resulting balance is valid.
  update public.stock_balances set on_hand = on_hand + new.quantity_delta, updated_at = now()
   where location_id = new.location_id and lot_id = new.lot_id;
  if not found then
    begin
      insert into public.stock_balances (organization_id, location_id, lot_id, on_hand) values (new.organization_id, new.location_id, new.lot_id, new.quantity_delta);
    exception when unique_violation then
      -- a concurrent first posting created the row between our UPDATE and INSERT
      update public.stock_balances set on_hand = on_hand + new.quantity_delta, updated_at = now() where location_id = new.location_id and lot_id = new.lot_id;
    end;
  end if;
  return new;
end $$;
create trigger stock_movements_apply after insert on public.stock_movements for each row execute function private.apply_movement();

-- Deferred FK from history to lots (the column existed since 0006).
alter table public.vaccination_revisions add foreign key (organization_id, lot_id) references public.vaccine_lots (organization_id, id);

-- Ledger ordering guarantee: a transaction's movements must net to zero only for transfers; everything else is single-leg.
alter table public.record_review_cases drop constraint if exists record_review_cases_kind_check;
alter table public.record_review_cases add constraint record_review_cases_kind_check check (kind in ('duplicate','link','identity_edit','correction','clinical','stock','sync'));

alter table public.vaccine_lots enable row level security;
alter table public.stock_locations enable row level security;
alter table public.stock_transactions enable row level security;
alter table public.stock_movements enable row level security;
alter table public.stock_balances enable row level security;
revoke all on public.vaccine_lots, public.stock_locations, public.stock_transactions, public.stock_movements, public.stock_balances from anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------------------------
create function private.lot_is_expired(p_expires date, p_as_of date) returns boolean language sql stable set search_path = '' as $$
  select case when private.setting_bool('expiry_last_day_usable') then p_expires < p_as_of else p_expires <= p_as_of end
$$;

-- Exact unit conversion (numeric, never floating point): doses -> stock units (containers).
create function private.doses_to_stock_units(p_product uuid, p_doses numeric) returns numeric language sql stable security definer set search_path = '' as $$
  select p_doses / doses_per_container from public.vaccine_products where id = p_product
$$;

-- Usable = physical on-hand, in a usable location, of a lot that is usable and unexpired, minus allocations.
create function private.usable_on_hand(p_location uuid, p_lot uuid, p_as_of date) returns numeric language sql stable security definer set search_path = '' as $$
  select coalesce((
    select case when l.global_disposition = 'usable' and loc.kind = 'usable' and loc.status = 'active' and not private.lot_is_expired(l.expires_on, p_as_of)
                then b.on_hand - b.allocated else 0 end
      from public.stock_balances b join public.vaccine_lots l on l.id = b.lot_id join public.stock_locations loc on loc.id = b.location_id
     where b.location_id = p_location and b.lot_id = p_lot), 0)
$$;

-- Internal posting primitive. Locks the balance row, refuses to go below zero, appends one immutable movement.
create function private.post_movement(p_org uuid, p_tx uuid, p_location uuid, p_lot uuid, p_delta numeric, p_key text) returns void
language plpgsql security definer set search_path = '' as $$
declare v_unit text; v_on numeric;
begin
  if p_delta = 0 then raise exception 'quantity must not be zero' using errcode = 'CV422'; end if;
  select p.stock_unit into v_unit from public.vaccine_lots l join public.vaccine_products p on p.id = l.product_id where l.id = p_lot and l.organization_id = p_org;
  if v_unit is null then raise exception 'unknown lot' using errcode = 'CV404'; end if;
  if p_delta < 0 then
    select on_hand into v_on from public.stock_balances where location_id = p_location and lot_id = p_lot for update;
    if coalesce(v_on, 0) + p_delta < 0 then raise exception 'insufficient stock' using errcode = 'CV409'; end if;
  end if;
  insert into public.stock_movements (organization_id, transaction_id, location_id, lot_id, quantity_delta, unit, movement_key, created_by)
  values (p_org, p_tx, p_location, p_lot, p_delta, v_unit, p_key, auth.uid());
end $$;

-- Used by the administration command (M06): one physical single-dose administration = one issue movement from a usable location.
create function private.issue_for_administration(p_org uuid, p_clinic uuid, p_location uuid, p_lot uuid, p_doses numeric, p_event uuid, p_operation uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_prod public.vaccine_products; v_lot public.vaccine_lots; v_loc public.stock_locations; v_tx uuid; v_today date; v_qty numeric;
begin
  select * into v_lot from public.vaccine_lots where id = p_lot and organization_id = p_org;
  select * into v_loc from public.stock_locations where id = p_location and organization_id = p_org and clinic_id = p_clinic;
  if v_lot.id is null or v_loc.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  select * into v_prod from public.vaccine_products where id = v_lot.product_id;
  if v_prod.doses_per_container <> 1 then raise exception 'multi-dose products need the vial workflow, which is not enabled' using errcode = 'CV422'; end if;
  if v_prod.status <> 'active' then raise exception 'product is not active' using errcode = 'CV409'; end if;
  v_today := private.local_today(p_clinic);
  if v_lot.global_disposition <> 'usable' then raise exception 'lot is % and cannot be used', v_lot.global_disposition using errcode = 'CV409'; end if;
  if private.lot_is_expired(v_lot.expires_on, v_today) then raise exception 'lot is expired' using errcode = 'CV409'; end if;
  if v_loc.kind <> 'usable' or v_loc.status <> 'active' then raise exception 'location is not a usable stock location' using errcode = 'CV409'; end if;
  v_qty := private.doses_to_stock_units(v_prod.id, p_doses);
  insert into public.stock_transactions (organization_id, clinic_id, type, event_id, operation_id, created_by)
  values (p_org, p_clinic, 'issue_administration', p_event, p_operation, auth.uid()) returning id into v_tx;
  perform private.post_movement(p_org, v_tx, p_location, p_lot, -v_qty, 'issue:' || p_operation);
  return v_tx;
end $$;

create function private.inventory_org(p_clinic uuid, p_cap text default 'inventory.manage') returns uuid language plpgsql stable security definer set search_path = '' as $$
declare v_org uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic, p_cap);
  return v_org;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Commands
-- ---------------------------------------------------------------------------------------------
create function public.create_stock_location(p_operation_key uuid, p_clinic_id uuid, p_name text, p_kind text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id); v_prev jsonb; v_id uuid;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.create_location', jsonb_build_object('c', p_clinic_id, 'n', p_name, 'k', p_kind));
  if v_prev is not null then return v_prev; end if;
  insert into public.stock_locations (organization_id, clinic_id, name, kind, created_by, updated_by) values (v_org, p_clinic_id, btrim(p_name), p_kind, auth.uid(), auth.uid()) returning id into v_id;
  perform private.audit(v_org, 'inventory.manage', 'stock.location_created', 'stock_location', v_id, null, jsonb_build_object('kind', p_kind), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('locationId', v_id));
end $$;

create function public.register_lot(p_operation_key uuid, p_clinic_id uuid, p_product_id uuid, p_manufacturer_lot text, p_expires_on date, p_manufacturer text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id); v_prev jsonb; v_id uuid;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.register_lot', jsonb_build_object('c', p_clinic_id, 'p', p_product_id, 'l', p_manufacturer_lot, 'e', p_expires_on, 'm', p_manufacturer));
  if v_prev is not null then return v_prev; end if;
  if not exists (select 1 from public.vaccine_products where id = p_product_id and organization_id = v_org and status = 'active') then raise exception 'product is not active' using errcode = 'CV422'; end if;
  if p_expires_on is null then raise exception 'expiry date is required' using errcode = 'CV422'; end if;
  if private.lot_is_expired(p_expires_on, private.local_today(p_clinic_id)) then raise exception 'a lot that is already expired cannot be registered for use' using errcode = 'CV422'; end if;
  insert into public.vaccine_lots (organization_id, product_id, manufacturer_lot, expires_on, manufacturer, created_by, updated_by)
  values (v_org, p_product_id, btrim(p_manufacturer_lot), p_expires_on, nullif(btrim(coalesce(p_manufacturer, '')), ''), auth.uid(), auth.uid()) returning id into v_id;
  perform private.audit(v_org, 'inventory.manage', 'stock.lot_registered', 'vaccine_lot', v_id, null, jsonb_build_object('lot', p_manufacturer_lot, 'expires', p_expires_on), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('lotId', v_id));
end $$;

-- Receiving: positive quantity, delivery reference required. Not accepted (damaged/suspect) stock is booked into quarantine, never usable.
create function public.receive_stock(p_operation_key uuid, p_clinic_id uuid, p_location_id uuid, p_lot_id uuid, p_quantity numeric, p_delivery_reference text, p_accepted boolean default true) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id); v_prev jsonb; v_lot public.vaccine_lots; v_loc public.stock_locations; v_q uuid; v_tx uuid; v_dest uuid;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.receive', jsonb_build_object('c', p_clinic_id, 'loc', p_location_id, 'lot', p_lot_id, 'q', p_quantity, 'ref', p_delivery_reference, 'a', p_accepted));
  if v_prev is not null then return v_prev; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'quantity must be positive' using errcode = 'CV422'; end if;
  if p_delivery_reference is null or length(btrim(p_delivery_reference)) = 0 then raise exception 'delivery reference is required' using errcode = 'CV422'; end if;
  select * into v_lot from public.vaccine_lots where id = p_lot_id and organization_id = v_org;
  select * into v_loc from public.stock_locations where id = p_location_id and organization_id = v_org and clinic_id = p_clinic_id and status = 'active';
  if v_lot.id is null or v_loc.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if v_loc.kind <> 'usable' then raise exception 'receive into a usable location' using errcode = 'CV422'; end if;
  if v_lot.global_disposition = 'recalled' then raise exception 'lot is recalled' using errcode = 'CV409'; end if;
  v_dest := p_location_id;
  if not p_accepted then
    select id into v_q from public.stock_locations where clinic_id = p_clinic_id and kind = 'quarantine' and status = 'active' order by created_at limit 1;
    if v_q is null then raise exception 'create a quarantine location before receiving unaccepted stock' using errcode = 'CV422'; end if;
    v_dest := v_q;
  end if;
  insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, operation_id, created_by)
  values (v_org, p_clinic_id, 'receipt', btrim(p_delivery_reference), p_operation_key, auth.uid()) returning id into v_tx;
  perform private.post_movement(v_org, v_tx, v_dest, p_lot_id, p_quantity, 'receipt:' || p_operation_key);
  perform private.audit(v_org, 'inventory.manage', 'stock.received', 'vaccine_lot', p_lot_id, null, jsonb_build_object('qty', p_quantity, 'accepted', p_accepted, 'ref', p_delivery_reference), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transactionId', v_tx, 'locationId', v_dest, 'accepted', p_accepted));
end $$;

create function public.record_wastage(p_operation_key uuid, p_clinic_id uuid, p_location_id uuid, p_lot_id uuid, p_quantity numeric, p_reason text, p_incident_reference text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id); v_prev jsonb; v_tx uuid; v_loc public.stock_locations;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.wastage', jsonb_build_object('c', p_clinic_id, 'loc', p_location_id, 'lot', p_lot_id, 'q', p_quantity, 'r', p_reason, 'i', p_incident_reference));
  if v_prev is not null then return v_prev; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'quantity must be positive' using errcode = 'CV422'; end if;
  if p_reason not in ('expired','damaged','spoiled','breakage','open_vial_discard','temperature_excursion','other') then raise exception 'invalid wastage reason' using errcode = 'CV422'; end if;
  select * into v_loc from public.stock_locations where id = p_location_id and organization_id = v_org and clinic_id = p_clinic_id;
  if v_loc.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, operation_id, created_by)
  values (v_org, p_clinic_id, 'wastage', coalesce(p_incident_reference, ''), p_reason, p_operation_key, auth.uid()) returning id into v_tx;
  perform private.post_movement(v_org, v_tx, p_location_id, p_lot_id, -p_quantity, 'wastage:' || p_operation_key);
  perform private.audit(v_org, 'inventory.manage', 'stock.wastage', 'vaccine_lot', p_lot_id, null, jsonb_build_object('qty', p_quantity, 'reason', p_reason), p_incident_reference);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transactionId', v_tx));
end $$;

-- Physical count reconciliation. Differences above the threshold need a second person with inventory.approve.
create function public.propose_stock_adjustment(p_operation_key uuid, p_clinic_id uuid, p_location_id uuid, p_lot_id uuid, p_observed numeric, p_count_reference text, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid := private.inventory_org(p_clinic_id); v_prev jsonb; v_book numeric; v_delta numeric; v_thr numeric; v_case uuid; v_tx uuid; v_can_approve boolean;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.adjust', jsonb_build_object('c', p_clinic_id, 'loc', p_location_id, 'lot', p_lot_id, 'obs', p_observed, 'ref', p_count_reference, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if p_observed is null or p_observed < 0 then raise exception 'observed count must be zero or more' using errcode = 'CV422'; end if;
  if p_count_reference is null or length(btrim(p_count_reference)) = 0 or p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'count reference and reason are required' using errcode = 'CV422'; end if;
  if not exists (select 1 from public.stock_locations where id = p_location_id and organization_id = v_org and clinic_id = p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  select coalesce(on_hand, 0) into v_book from public.stock_balances where location_id = p_location_id and lot_id = p_lot_id;
  v_book := coalesce(v_book, 0);
  v_delta := p_observed - v_book;
  if v_delta = 0 then return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'no_difference', 'book', v_book)); end if;
  v_thr := coalesce((select (value)::text::numeric from private.settings where key = 'adjustment_auto_approve_units'), 0);
  v_can_approve := private.has_capability(p_clinic_id, 'inventory.approve');
  if abs(v_delta) <= v_thr or v_can_approve then
    -- Even an approver's own proposal is posted by that approver: the actor is recorded as both requester and approver.
    insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, approved_by, operation_id, created_by)
    values (v_org, p_clinic_id, 'adjustment', p_count_reference, p_reason, case when v_can_approve then auth.uid() end, p_operation_key, auth.uid()) returning id into v_tx;
    perform private.post_movement(v_org, v_tx, p_location_id, p_lot_id, v_delta, 'adjust:' || p_operation_key);
    perform private.audit(v_org, 'inventory.manage', 'stock.adjusted', 'vaccine_lot', p_lot_id, jsonb_build_object('book', v_book), jsonb_build_object('observed', p_observed, 'delta', v_delta), p_reason);
    return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'posted', 'delta', v_delta, 'transactionId', v_tx));
  end if;
  -- Above threshold and no approval authority: park as a review case; nothing is posted yet.
  insert into public.record_review_cases (organization_id, clinic_id, kind, reason, evidence, created_by, updated_by)
  values (v_org, p_clinic_id, 'stock', 'stock count difference awaiting approval',
          jsonb_build_object('locationId', p_location_id, 'lotId', p_lot_id, 'book', v_book, 'observed', p_observed, 'delta', v_delta, 'countReference', p_count_reference, 'reason', p_reason, 'operationKey', p_operation_key),
          auth.uid(), auth.uid()) returning id into v_case;
  perform private.audit(v_org, 'inventory.manage', 'stock.adjustment_proposed', 'review_case', v_case, jsonb_build_object('book', v_book), jsonb_build_object('observed', p_observed), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'pending_approval', 'caseId', v_case, 'delta', v_delta));
end $$;

create function public.approve_stock_adjustment(p_operation_key uuid, p_clinic_id uuid, p_case_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id, 'inventory.approve'); v_prev jsonb; k public.record_review_cases; v_book numeric; v_tx uuid; v_delta numeric; v_loc uuid; v_lot uuid;
begin
  select * into k from public.record_review_cases where id = p_case_id and organization_id = v_org and clinic_id = p_clinic_id and kind = 'stock' for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.approve_adjustment', jsonb_build_object('c', p_clinic_id, 'case', p_case_id));
  if v_prev is not null then return v_prev; end if;
  if k.status not in ('open','in_review') then raise exception 'case already decided' using errcode = 'CV409'; end if;
  if k.created_by = auth.uid() then raise exception 'the proposer cannot approve their own adjustment' using errcode = 'CV403'; end if;
  v_loc := (k.evidence ->> 'locationId')::uuid; v_lot := (k.evidence ->> 'lotId')::uuid;
  -- Re-derive the delta from the observed count against the CURRENT book balance (stock may have moved since the proposal).
  select coalesce(on_hand, 0) into v_book from public.stock_balances where location_id = v_loc and lot_id = v_lot for update;
  v_book := coalesce(v_book, 0);
  v_delta := (k.evidence ->> 'observed')::numeric - v_book;
  if v_delta <> 0 then
    insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, approved_by, operation_id, created_by)
    values (v_org, p_clinic_id, 'adjustment', k.evidence ->> 'countReference', k.evidence ->> 'reason', auth.uid(), p_operation_key, k.created_by) returning id into v_tx;
    perform private.post_movement(v_org, v_tx, v_loc, v_lot, v_delta, 'adjust:' || p_operation_key);
  end if;
  update public.record_review_cases set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', 'approved', 'postedDelta', v_delta, 'transactionId', v_tx) where id = k.id;
  perform private.audit(v_org, 'inventory.approve', 'stock.adjustment_approved', 'review_case', k.id, null, jsonb_build_object('delta', v_delta), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'posted', 'delta', v_delta, 'transactionId', v_tx));
end $$;

-- Lot disposition. Quarantine can be applied by inventory staff; recall and release need inventory.approve. Physical stock is untouched.
create function public.set_lot_disposition(p_operation_key uuid, p_clinic_id uuid, p_lot_id uuid, p_disposition text, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; l public.vaccine_lots; v_cap text;
begin
  if p_disposition not in ('quarantined','recalled','usable') then raise exception 'invalid disposition' using errcode = 'CV422'; end if;
  v_cap := case when p_disposition = 'quarantined' then 'inventory.manage' else 'inventory.approve' end;
  v_org := private.inventory_org(p_clinic_id, v_cap);
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.disposition', jsonb_build_object('c', p_clinic_id, 'lot', p_lot_id, 'd', p_disposition, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into l from public.vaccine_lots where id = p_lot_id and organization_id = v_org for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if l.global_disposition = p_disposition then raise exception 'lot is already %', p_disposition using errcode = 'CV409'; end if;
  if l.global_disposition = 'recalled' and p_disposition = 'usable' then
    -- Releasing a recall is a deliberate governance act: only inventory.approve, recorded, and never silently.
    null;
  end if;
  update public.vaccine_lots set global_disposition = p_disposition, updated_by = auth.uid() where id = l.id;
  perform private.audit(v_org, v_cap, 'stock.lot_' || p_disposition, 'vaccine_lot', l.id, jsonb_build_object('disposition', l.global_disposition), jsonb_build_object('disposition', p_disposition), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('lotId', l.id, 'disposition', p_disposition));
end $$;

-- Read models ---------------------------------------------------------------------------------
create function public.list_stock(p_clinic_id uuid) returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_today date; v_res jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['inventory.manage','inventory.approve','vaccination.record']);
  v_today := private.local_today(p_clinic_id);
  select jsonb_build_object(
    'asOf', v_today,
    'locations', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'kind', s.kind, 'status', s.status) order by s.name) from public.stock_locations s where s.clinic_id = p_clinic_id), '[]'::jsonb),
    'lots', coalesce((select jsonb_agg(jsonb_build_object(
        'lotId', l.id, 'lot', l.manufacturer_lot, 'product', p.name, 'productCode', p.code, 'stockUnit', p.stock_unit, 'expiresOn', l.expires_on, 'disposition', l.global_disposition,
        'expired', private.lot_is_expired(l.expires_on, v_today),
        'physicalOnHand', coalesce((select sum(b.on_hand) from public.stock_balances b join public.stock_locations s on s.id = b.location_id where b.lot_id = l.id and s.clinic_id = p_clinic_id), 0),
        'usable', coalesce((select sum(private.usable_on_hand(b.location_id, b.lot_id, v_today)) from public.stock_balances b join public.stock_locations s on s.id = b.location_id where b.lot_id = l.id and s.clinic_id = p_clinic_id), 0),
        'locations', coalesce((select jsonb_agg(jsonb_build_object('locationId', b.location_id, 'onHand', b.on_hand)) from public.stock_balances b join public.stock_locations s on s.id = b.location_id where b.lot_id = l.id and s.clinic_id = p_clinic_id), '[]'::jsonb))
      order by l.expires_on, l.manufacturer_lot)
      from public.vaccine_lots l join public.vaccine_products p on p.id = l.product_id where l.organization_id = v_org), '[]'::jsonb)) into v_res;
  return v_res;
end $$;

create function public.list_lot_ledger(p_clinic_id uuid, p_lot_id uuid) returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id, 'inventory.manage');
begin
  return coalesce((select jsonb_agg(jsonb_build_object('movementId', m.id, 'at', m.occurred_at, 'type', t.type, 'delta', m.quantity_delta, 'unit', m.unit, 'location', s.name,
      'reference', t.source_reference, 'reason', t.reason, 'approvedBy', t.approved_by) order by m.occurred_at, m.id)
    from public.stock_movements m join public.stock_transactions t on t.id = m.transaction_id join public.stock_locations s on s.id = m.location_id
   where m.lot_id = p_lot_id and s.clinic_id = p_clinic_id and m.organization_id = v_org), '[]'::jsonb);
end $$;

-- Projection vs ledger reconciliation; optionally repairs the PROJECTION (never the ledger).
create function public.reconcile_stock(p_operation_key uuid, p_clinic_id uuid, p_repair boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id, 'inventory.approve'); v_prev jsonb; v_diff jsonb;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.reconcile', jsonb_build_object('c', p_clinic_id, 'repair', p_repair));
  if v_prev is not null then return v_prev; end if;
  select coalesce(jsonb_agg(jsonb_build_object('locationId', x.location_id, 'lotId', x.lot_id, 'ledger', x.ledger, 'projection', x.projection)), '[]'::jsonb) into v_diff from (
    select coalesce(l.location_id, b.location_id) location_id, coalesce(l.lot_id, b.lot_id) lot_id, coalesce(l.q, 0) ledger, coalesce(b.on_hand, 0) projection
      from (select m.location_id, m.lot_id, sum(m.quantity_delta) q from public.stock_movements m join public.stock_locations s on s.id = m.location_id where s.clinic_id = p_clinic_id group by 1, 2) l
      full join (select b2.location_id, b2.lot_id, b2.on_hand from public.stock_balances b2 join public.stock_locations s on s.id = b2.location_id where s.clinic_id = p_clinic_id) b
        on b.location_id = l.location_id and b.lot_id = l.lot_id
     where coalesce(l.q, 0) <> coalesce(b.on_hand, 0)) x;
  if p_repair and jsonb_array_length(v_diff) > 0 then
    -- Rebuild projection rows from the ledger. allocated is preserved but capped so the projection stays valid.
    insert into public.stock_balances (organization_id, location_id, lot_id, on_hand)
    select v_org, (d ->> 'locationId')::uuid, (d ->> 'lotId')::uuid, (d ->> 'ledger')::numeric from jsonb_array_elements(v_diff) d
    on conflict (location_id, lot_id) do update set on_hand = excluded.on_hand, allocated = least(public.stock_balances.allocated, excluded.on_hand), updated_at = now();
  end if;
  update public.stock_balances b set reconciled_at = now() from public.stock_locations s where s.id = b.location_id and s.clinic_id = p_clinic_id and (p_repair or jsonb_array_length(v_diff) = 0);
  perform private.audit(v_org, 'inventory.approve', 'stock.reconciled', 'clinic', p_clinic_id, null, jsonb_build_object('mismatches', jsonb_array_length(v_diff), 'repaired', p_repair and jsonb_array_length(v_diff) > 0), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('mismatches', v_diff, 'repaired', p_repair and jsonb_array_length(v_diff) > 0));
end $$;

do $$
declare f text;
begin
  foreach f in array array[
    'create_stock_location(uuid,uuid,text,text)', 'register_lot(uuid,uuid,uuid,text,date,text)', 'receive_stock(uuid,uuid,uuid,uuid,numeric,text,boolean)',
    'record_wastage(uuid,uuid,uuid,uuid,numeric,text,text)', 'propose_stock_adjustment(uuid,uuid,uuid,uuid,numeric,text,text)', 'approve_stock_adjustment(uuid,uuid,uuid)',
    'set_lot_disposition(uuid,uuid,uuid,text,text)', 'list_stock(uuid)', 'list_lot_ledger(uuid,uuid)', 'reconcile_stock(uuid,uuid,boolean)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function private.has_capability(uuid, text), private.clinics_with(text), private.session_ok(),
  private.my_guardian_ids(), private.guardian_can_read_child(uuid) to authenticated;
-- END 0011_inventory.sql

-- =====================================================================================================================
-- BEGIN 0012_visits.sql  sha256=07029178e78be971540d610a06ac48bbd932ee39f908bd7dc0a499d16406a22c
-- =====================================================================================================================
-- 0012 Sessions, appointments, arrival queue, encounters, and the durable outbox.
-- Blueprint refs: BP17, BP28.4, F07, F08, T02, T26 (partly). Booking, arrival and clinical completion are DIFFERENT facts:
--  * an appointment reserves capacity; it never proves eligibility or vaccination;
--  * a queue entry is an arrival; numbers are allocated per clinic per local day and never reused;
--  * an encounter is the clinical visit; it starts when service starts.

-- ---------------------------------------------------------------------------------------------
-- Durable outbox (private): business transactions enqueue; a bounded worker (M07) delivers. No external calls here.
-- ---------------------------------------------------------------------------------------------
create table private.outbox_jobs (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  job_type text not null,
  aggregate_type text not null,
  aggregate_id uuid not null,
  dedupe_key text not null,
  payload jsonb not null default '{}'::jsonb,
  status text not null default 'queued' check (status in ('queued','processing','done','failed','cancelled')),
  available_at timestamptz not null default now(),
  attempt_count integer not null default 0,
  locked_until timestamptz,
  last_error_code text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, dedupe_key)
);
create index outbox_ready_idx on private.outbox_jobs (status, available_at);

create function private.enqueue(p_org uuid, p_type text, p_agg_type text, p_agg uuid, p_dedupe text, p_payload jsonb, p_available timestamptz default now()) returns void
language sql security definer set search_path = '' as $$
  insert into private.outbox_jobs (organization_id, job_type, aggregate_type, aggregate_id, dedupe_key, payload, available_at)
  values (p_org, p_type, p_agg_type, p_agg, p_dedupe, coalesce(p_payload, '{}'::jsonb), p_available)
  on conflict (organization_id, dedupe_key) do nothing
$$;

-- ---------------------------------------------------------------------------------------------
-- Sessions
-- ---------------------------------------------------------------------------------------------
create table public.clinic_sessions (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  service_date date not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  service_code text not null default 'immunization' check (length(btrim(service_code)) between 1 and 40),
  total_capacity integer not null check (total_capacity >= 0),
  online_capacity integer not null check (online_capacity >= 0),
  walkin_capacity integer not null check (walkin_capacity >= 0),
  status text not null default 'open' check (status in ('open','closed','cancelled')),
  cancel_reason text,
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  unique (organization_id, id),
  check (ends_at > starts_at),
  check (online_capacity + walkin_capacity <= total_capacity)
);
create index clinic_sessions_lookup_idx on public.clinic_sessions (clinic_id, service_date, status);
create trigger clinic_sessions_touch before update on public.clinic_sessions for each row execute function private.touch_row();

create table public.appointments (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  child_id uuid not null, session_id uuid not null,
  booked_by uuid not null references public.profiles (id),
  channel text not null check (channel in ('online','assisted')),
  status text not null default 'confirmed' check (status in ('confirmed','checked_in','fulfilled','cancelled','no_show','rescheduled')),
  reason text,
  replaces_id uuid references public.appointments (id),
  checked_in_at timestamptz,
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, session_id) references public.clinic_sessions (organization_id, id),
  unique (organization_id, id)
);
create unique index appointments_one_active_uq on public.appointments (child_id, session_id) where status in ('confirmed','checked_in','fulfilled');
create index appointments_session_idx on public.appointments (session_id, status);
create index appointments_child_idx on public.appointments (child_id, status);
create trigger appointments_touch before update on public.appointments for each row execute function private.touch_row();

create table public.appointment_items (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  appointment_id uuid not null, rule_id uuid,
  purpose text not null default 'care',
  created_at timestamptz not null default now(),
  foreign key (organization_id, appointment_id) references public.appointments (organization_id, id),
  foreign key (organization_id, rule_id) references public.schedule_rules (organization_id, id)
);
create unique index appointment_items_uq on public.appointment_items (appointment_id, rule_id) where rule_id is not null;

-- ---------------------------------------------------------------------------------------------
-- Encounters and queue
-- ---------------------------------------------------------------------------------------------
create table public.encounters (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  child_id uuid not null, clinic_id uuid not null, appointment_id uuid,
  service_date date not null,
  started_at timestamptz, ended_at timestamptz,
  status text not null default 'open' check (status in ('open','completed','cancelled')),
  outcome text check (outcome in ('vaccinated','deferred','referred','no_service','left')),
  assessment_reference text, consent_reference text,
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, appointment_id) references public.appointments (organization_id, id),
  unique (organization_id, id),
  check (status <> 'completed' or outcome is not null)
);
create index encounters_clinic_idx on public.encounters (clinic_id, service_date, status);
create trigger encounters_touch before update on public.encounters for each row execute function private.touch_row();
alter table public.vaccination_events add foreign key (organization_id, encounter_id) references public.encounters (organization_id, id);

create table private.queue_counters (clinic_id uuid not null, service_date date not null, next_no integer not null default 1, primary key (clinic_id, service_date));

create table public.queue_entries (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  child_id uuid not null, clinic_id uuid not null, service_date date not null,
  appointment_id uuid, encounter_id uuid,
  ticket_no integer not null check (ticket_no > 0),
  station text,
  status text not null default 'waiting' check (status in ('waiting','called','in_service','completed','held','left','cancelled','deferred')),
  walk_in boolean not null default false,
  priority_code text not null default 'routine' check (priority_code in ('routine','priority')),
  priority_reason text,
  queued_at timestamptz not null default now(),
  arrived_at timestamptz not null default now(),
  called_at timestamptz, service_started_at timestamptz, completed_at timestamptz,
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, appointment_id) references public.appointments (organization_id, id),
  foreign key (organization_id, encounter_id) references public.encounters (organization_id, id),
  unique (organization_id, id),
  unique (clinic_id, service_date, ticket_no),
  check (priority_code = 'routine' or (priority_reason is not null and length(btrim(priority_reason)) >= 3))
);
create unique index queue_one_active_uq on public.queue_entries (clinic_id, service_date, child_id) where status in ('waiting','called','in_service','held');
create index queue_order_idx on public.queue_entries (clinic_id, service_date, status, priority_code, queued_at);
create trigger queue_entries_touch before update on public.queue_entries for each row execute function private.touch_row();

create table public.queue_events (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  queue_entry_id uuid not null,
  from_status text, to_status text not null,
  station text, reason text,
  occurred_at timestamptz not null default now(),
  created_at timestamptz not null default now(), created_by uuid references public.profiles (id),
  foreign key (organization_id, queue_entry_id) references public.queue_entries (organization_id, id)
);
create index queue_events_entry_idx on public.queue_events (queue_entry_id, occurred_at);
create trigger queue_events_immutable before update or delete on public.queue_events for each row execute function private.forbid_change();
create trigger queue_events_no_truncate before truncate on public.queue_events for each statement execute function private.forbid_change();

-- Follow-up work for closures/needs-recheck (BP17: closure never silently cancels bookings).
alter table public.record_review_cases drop constraint record_review_cases_kind_check;
alter table public.record_review_cases add constraint record_review_cases_kind_check check (kind in ('duplicate','link','identity_edit','correction','clinical','stock','sync','appointment'));

alter table public.clinic_sessions enable row level security;
alter table public.appointments enable row level security;
alter table public.appointment_items enable row level security;
alter table public.encounters enable row level security;
alter table public.queue_entries enable row level security;
alter table public.queue_events enable row level security;
revoke all on public.clinic_sessions, public.appointments, public.appointment_items, public.encounters, public.queue_entries, public.queue_events from anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------------------------
create function private.session_booked(p_session uuid) returns integer language sql stable security definer set search_path = '' as $$
  select count(*)::int from public.appointments where session_id = p_session and status in ('confirmed','checked_in','fulfilled')
$$;

create function private.allocate_ticket(p_clinic uuid, p_date date) returns integer language plpgsql security definer set search_path = '' as $$
declare v int;
begin
  -- The upsert takes the counter row's lock, so concurrent check-ins are serialised and numbers are unique and gapless.
  insert into private.queue_counters (clinic_id, service_date, next_no) values (p_clinic, p_date, 2)
  on conflict (clinic_id, service_date) do update set next_no = private.queue_counters.next_no + 1
  returning next_no - 1 into v;
  return v;
end $$;

create function private.ticket_label(p_date date, p_no int) returns text language sql immutable set search_path = '' as $$
  select to_char(p_date, 'MMDD') || '-' || lpad(p_no::text, 3, '0')
$$;

create function private.appointment_json(a public.appointments, s public.clinic_sessions) returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('appointmentId', a.id, 'childId', a.child_id, 'sessionId', a.session_id, 'status', a.status, 'channel', a.channel,
    'serviceDate', s.service_date, 'startsAt', s.starts_at, 'endsAt', s.ends_at, 'serviceCode', s.service_code, 'reason', a.reason, 'version', a.version)
$$;

-- Guardian (verified) or clinic staff acting on a child
create function private.can_book_for(p_child uuid, p_clinic uuid) returns text language plpgsql stable security definer set search_path = '' as $$
begin
  if private.guardian_has_full_access(p_child) then return 'online'; end if;
  if private.has_capability(p_clinic, 'appointment.manage') and private.child_in_clinic(p_child, p_clinic) then return 'assisted'; end if;
  return null;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Session commands
-- ---------------------------------------------------------------------------------------------
create function public.create_session(p_operation_key uuid, p_clinic_id uuid, p_session jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_tz text; v_prev jsonb; v_id uuid; v_date date; v_start timestamptz; v_end timestamptz; v_total int; v_online int; v_walk int; v_code text;
begin
  select organization_id, timezone into v_org, v_tz from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'appointment.manage');
  v_prev := private.begin_command(v_org, p_operation_key, 'session.create', jsonb_build_object('c', p_clinic_id, 's', p_session));
  if v_prev is not null then return v_prev; end if;
  begin
    v_date := (p_session ->> 'serviceDate')::date;
    v_start := ((p_session ->> 'serviceDate') || ' ' || (p_session ->> 'startTime'))::timestamp at time zone v_tz;
    v_end := ((p_session ->> 'serviceDate') || ' ' || (p_session ->> 'endTime'))::timestamp at time zone v_tz;
    v_total := (p_session ->> 'totalCapacity')::int; v_online := (p_session ->> 'onlineCapacity')::int; v_walk := (p_session ->> 'walkinCapacity')::int;
  exception when others then raise exception 'invalid session details' using errcode = 'CV422';
  end;
  v_code := coalesce(nullif(btrim(p_session ->> 'serviceCode'), ''), 'immunization');
  if v_end <= v_start then raise exception 'the session must end after it starts' using errcode = 'CV422'; end if;
  if v_total < 0 or v_online < 0 or v_walk < 0 or v_online + v_walk > v_total then raise exception 'online plus walk-in capacity cannot exceed total capacity' using errcode = 'CV422'; end if;
  insert into public.clinic_sessions (organization_id, clinic_id, service_date, starts_at, ends_at, service_code, total_capacity, online_capacity, walkin_capacity, created_by, updated_by)
  values (v_org, p_clinic_id, v_date, v_start, v_end, v_code, v_total, v_online, v_walk, auth.uid(), auth.uid()) returning id into v_id;
  perform private.audit(v_org, 'appointment.manage', 'session.created', 'clinic_session', v_id, null, jsonb_build_object('date', v_date, 'online', v_online, 'walkin', v_walk, 'total', v_total), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('sessionId', v_id));
end $$;
-- END 0012_visits.sql

-- =====================================================================================================================
-- BEGIN 0013_visit_commands.sql  sha256=ddc15f77cee10316c295aa205f19a5d7844d69bb0ec34d662598b75bf3c8399b
-- =====================================================================================================================
-- 0013 Booking, check-in and queue commands + read models. See 0012 for the model and invariants.
-- Concurrency: the session row lock serialises bookings (T02); the counter row lock serialises ticket allocation;
-- FOR UPDATE SKIP LOCKED lets two stations call "next" without receiving the same patient.

-- ---------------------------------------------------------------------------------------------
-- Session reads and closure
-- ---------------------------------------------------------------------------------------------
create function public.list_sessions(p_clinic_id uuid, p_from date default null, p_to date default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_from date; v_to date; v_res jsonb;
begin
  perform private.require_any(p_clinic_id, array['appointment.manage','queue.manage','child.search']);
  v_from := coalesce(p_from, private.local_today(p_clinic_id)); v_to := coalesce(p_to, v_from + 14);
  if v_to < v_from or v_to - v_from > 92 then raise exception 'date range must be 0-92 days' using errcode = 'CV422'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'sessionId', s.id, 'serviceDate', s.service_date, 'startsAt', s.starts_at, 'endsAt', s.ends_at, 'serviceCode', s.service_code, 'status', s.status,
      'totalCapacity', s.total_capacity, 'onlineCapacity', s.online_capacity, 'walkinCapacity', s.walkin_capacity,
      'booked', private.session_booked(s.id), 'remainingOnline', greatest(s.online_capacity - private.session_booked(s.id), 0)) order by s.starts_at), '[]'::jsonb)
    into v_res from public.clinic_sessions s where s.clinic_id = p_clinic_id and s.service_date between v_from and v_to;
  return v_res;
end $$;

-- Guardians (signed in, any verified child) see open sessions with room. No child or booking details are exposed.
create function public.guardian_list_sessions(p_clinic_id uuid, p_from date default null, p_to date default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_from date; v_to date;
begin
  if auth.uid() is null or not private.session_ok() then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not exists (select 1 from public.clinics where id = p_clinic_id and status = 'active') then raise exception 'not found' using errcode = 'CV404'; end if;
  v_from := coalesce(p_from, private.local_today(p_clinic_id)); v_to := coalesce(p_to, v_from + 30);
  if v_to < v_from or v_to - v_from > 92 then raise exception 'date range must be 0-92 days' using errcode = 'CV422'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('sessionId', s.id, 'serviceDate', s.service_date, 'startsAt', s.starts_at, 'endsAt', s.ends_at, 'serviceCode', s.service_code,
        'hasRoom', private.session_booked(s.id) < s.online_capacity) order by s.starts_at)
      from public.clinic_sessions s where s.clinic_id = p_clinic_id and s.status = 'open' and s.ends_at > now() and s.service_date between v_from and v_to), '[]'::jsonb);
end $$;

-- Closing a session never silently cancels bookings: each confirmed appointment gets a follow-up case and an outbox notice.
create function public.cancel_session(p_operation_key uuid, p_clinic_id uuid, p_session_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; s public.clinic_sessions; a record; v_n int := 0;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'appointment.manage');
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'session.cancel', jsonb_build_object('c', p_clinic_id, 's', p_session_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into s from public.clinic_sessions where id = p_session_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if s.status <> 'open' then raise exception 'session is not open' using errcode = 'CV409'; end if;
  update public.clinic_sessions set status = 'cancelled', cancel_reason = p_reason, updated_by = auth.uid() where id = s.id;
  for a in select * from public.appointments where session_id = s.id and status = 'confirmed' loop
    insert into public.record_review_cases (organization_id, clinic_id, kind, child_id, reason, evidence, created_by, updated_by)
    values (v_org, p_clinic_id, 'appointment', a.child_id, 'session cancelled: contact family to rebook', jsonb_build_object('appointmentId', a.id, 'sessionId', s.id, 'serviceDate', s.service_date), auth.uid(), auth.uid());
    perform private.enqueue(v_org, 'appointment.session_cancelled', 'appointment', a.id, 'appt-session-cancelled:' || a.id, jsonb_build_object('sessionId', s.id));
    v_n := v_n + 1;
  end loop;
  perform private.audit(v_org, 'appointment.manage', 'session.cancelled', 'clinic_session', s.id, jsonb_build_object('status', s.status), jsonb_build_object('status', 'cancelled', 'affectedBookings', v_n), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('sessionId', s.id, 'affectedBookings', v_n));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Appointments
-- ---------------------------------------------------------------------------------------------
create function public.book_appointment(p_operation_key uuid, p_child_id uuid, p_session_id uuid, p_reason text default null, p_rule_codes text[] default '{}') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_canon uuid; s public.clinic_sessions; v_channel text; v_prev jsonb; v_id uuid; c public.children; v_ver uuid; v_code text; v_rule uuid; a public.appointments;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  -- Lock the session row first: this serialises every booking, cancellation and move touching this session.
  select * into s from public.clinic_sessions where id = p_session_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_channel := private.can_book_for(v_canon, s.clinic_id);
  if v_channel is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(s.organization_id, p_operation_key, 'appointment.book', jsonb_build_object('child', p_child_id, 'session', p_session_id, 'reason', p_reason, 'rules', to_jsonb(coalesce(p_rule_codes, '{}'))));
  if v_prev is not null then return v_prev; end if;
  select * into c from public.children where id = v_canon;
  if c.record_status not in ('provisional','active') then raise exception 'record is not open for booking' using errcode = 'CV409'; end if;
  if s.status <> 'open' or s.ends_at <= now() then raise exception 'this session is not open for booking' using errcode = 'CV409'; end if;
  if exists (select 1 from public.appointments where child_id = v_canon and session_id = s.id and status in ('confirmed','checked_in','fulfilled')) then
    raise exception 'this child already has an appointment in this session' using errcode = 'CV409';
  end if;
  if private.session_booked(s.id) >= s.online_capacity then raise exception 'this session is full' using errcode = 'CV409'; end if;

  insert into public.appointments (organization_id, child_id, session_id, booked_by, channel, reason, created_by, updated_by)
  values (s.organization_id, v_canon, s.id, auth.uid(), v_channel, left(p_reason, 300), auth.uid(), auth.uid()) returning id into v_id;

  -- Optional: which schedule requirements this visit is for. Must exist in the version in force; never implies clearance.
  if coalesce(array_length(p_rule_codes, 1), 0) > 0 then
    v_ver := private.active_schedule_for(s.organization_id, 'routine', c.dob, s.service_date);
    if v_ver is null then raise exception 'no approved schedule is in force for those requirements' using errcode = 'CV422'; end if;
    foreach v_code in array p_rule_codes loop
      select id into v_rule from public.schedule_rules where schedule_version_id = v_ver and requirement_code = v_code;
      if v_rule is null then raise exception 'unknown requirement %', v_code using errcode = 'CV422'; end if;
      insert into public.appointment_items (organization_id, appointment_id, rule_id) values (s.organization_id, v_id, v_rule) on conflict do nothing;
    end loop;
  end if;
  perform private.enqueue(s.organization_id, 'appointment.confirmation', 'appointment', v_id, 'appt-confirm:' || v_id, jsonb_build_object('sessionId', s.id));
  perform private.audit(s.organization_id, case when v_channel = 'online' then 'guardian' else 'appointment.manage' end, 'appointment.booked', 'appointment', v_id, null,
                        jsonb_build_object('session', s.id, 'channel', v_channel), p_reason);
  select * into a from public.appointments where id = v_id;
  return private.finish_command(s.organization_id, p_operation_key, private.appointment_json(a, s));
end $$;

create function public.cancel_appointment(p_operation_key uuid, p_appointment_id uuid, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare a public.appointments; s public.clinic_sessions; v_prev jsonb; v_channel text;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select a0.* into a from public.appointments a0 where a0.id = p_appointment_id;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  select * into s from public.clinic_sessions where id = a.session_id for update;   -- session lock first (consistent ordering)
  select * into a from public.appointments where id = p_appointment_id for update;
  v_channel := private.can_book_for(a.child_id, s.clinic_id);
  if v_channel is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(a.organization_id, p_operation_key, 'appointment.cancel', jsonb_build_object('a', p_appointment_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if a.status <> 'confirmed' then raise exception 'only a confirmed appointment can be cancelled' using errcode = 'CV409'; end if;
  update public.appointments set status = 'cancelled', reason = coalesce(left(p_reason, 300), reason), updated_by = auth.uid() where id = a.id;
  -- obsolete unsent messages for this booking are withdrawn (BP22)
  update private.outbox_jobs set status = 'cancelled', updated_at = now() where organization_id = a.organization_id and status = 'queued' and (dedupe_key like 'appt-remind:' || a.id || '%' or dedupe_key = 'appt-confirm:' || a.id);
  perform private.enqueue(a.organization_id, 'appointment.cancellation', 'appointment', a.id, 'appt-cancel:' || a.id, '{}'::jsonb);
  perform private.audit(a.organization_id, case when v_channel = 'online' then 'guardian' else 'appointment.manage' end, 'appointment.cancelled', 'appointment', a.id, jsonb_build_object('status', 'confirmed'), jsonb_build_object('status', 'cancelled'), p_reason);
  return private.finish_command(a.organization_id, p_operation_key, jsonb_build_object('appointmentId', a.id, 'status', 'cancelled'));
end $$;

-- Atomic move: if the new session cannot take the child, the original booking is untouched (BP17).
create function public.reschedule_appointment(p_operation_key uuid, p_appointment_id uuid, p_new_session_id uuid, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare a public.appointments; so public.clinic_sessions; sn public.clinic_sessions; v_prev jsonb; v_channel text; v_new uuid; a2 public.appointments;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select a0.* into a from public.appointments a0 where a0.id = p_appointment_id;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  -- lock both sessions in a stable id order to avoid deadlocks between opposite moves
  perform 1 from public.clinic_sessions where id in (a.session_id, p_new_session_id) order by id for update;
  select * into so from public.clinic_sessions where id = a.session_id;
  select * into sn from public.clinic_sessions where id = p_new_session_id;
  if sn.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  select * into a from public.appointments where id = p_appointment_id for update;
  v_channel := private.can_book_for(a.child_id, so.clinic_id);
  if v_channel is null or sn.clinic_id <> so.clinic_id then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(a.organization_id, p_operation_key, 'appointment.reschedule', jsonb_build_object('a', p_appointment_id, 'n', p_new_session_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if a.status <> 'confirmed' then raise exception 'only a confirmed appointment can be moved' using errcode = 'CV409'; end if;
  if sn.id = so.id then raise exception 'choose a different session' using errcode = 'CV422'; end if;
  if sn.status <> 'open' or sn.ends_at <= now() then raise exception 'that session is not open for booking' using errcode = 'CV409'; end if;
  if exists (select 1 from public.appointments where child_id = a.child_id and session_id = sn.id and status in ('confirmed','checked_in','fulfilled')) then raise exception 'this child already has an appointment in that session' using errcode = 'CV409'; end if;
  if private.session_booked(sn.id) >= sn.online_capacity then raise exception 'that session is full' using errcode = 'CV409'; end if;
  update public.appointments set status = 'rescheduled', updated_by = auth.uid() where id = a.id;
  insert into public.appointments (organization_id, child_id, session_id, booked_by, channel, reason, replaces_id, created_by, updated_by)
  values (a.organization_id, a.child_id, sn.id, auth.uid(), v_channel, coalesce(left(p_reason, 300), a.reason), a.id, auth.uid(), auth.uid()) returning id into v_new;
  insert into public.appointment_items (organization_id, appointment_id, rule_id, purpose) select organization_id, v_new, rule_id, purpose from public.appointment_items where appointment_id = a.id;
  update private.outbox_jobs set status = 'cancelled', updated_at = now() where organization_id = a.organization_id and status = 'queued' and (dedupe_key like 'appt-remind:' || a.id || '%' or dedupe_key = 'appt-confirm:' || a.id);
  perform private.enqueue(a.organization_id, 'appointment.confirmation', 'appointment', v_new, 'appt-confirm:' || v_new, jsonb_build_object('sessionId', sn.id, 'rescheduledFrom', a.id));
  perform private.audit(a.organization_id, case when v_channel = 'online' then 'guardian' else 'appointment.manage' end, 'appointment.rescheduled', 'appointment', v_new,
                        jsonb_build_object('from', a.id, 'session', so.id), jsonb_build_object('session', sn.id), p_reason);
  select * into a2 from public.appointments where id = v_new;
  return private.finish_command(a.organization_id, p_operation_key, private.appointment_json(a2, sn) || jsonb_build_object('replaces', a.id));
end $$;

create function public.list_appointments(p_clinic_id uuid, p_date date default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_date date; v_org uuid;
begin
  perform private.require_any(p_clinic_id, array['appointment.manage','queue.manage']);
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  v_date := coalesce(p_date, private.local_today(p_clinic_id));
  perform private.audit(v_org, 'appointment.manage', 'appointments.view', 'clinic', p_clinic_id, null, jsonb_build_object('date', v_date), null);
  return coalesce((select jsonb_agg(jsonb_build_object('appointmentId', a.id, 'status', a.status, 'channel', a.channel, 'childId', c.id, 'childName', c.display_name, 'recordNo', c.local_record_no,
        'sessionId', s.id, 'startsAt', s.starts_at, 'endsAt', s.ends_at, 'serviceCode', s.service_code, 'reason', a.reason, 'version', a.version) order by s.starts_at, c.display_name)
      from public.appointments a join public.clinic_sessions s on s.id = a.session_id join public.children c on c.id = a.child_id
     where s.clinic_id = p_clinic_id and s.service_date = v_date), '[]'::jsonb);
end $$;

-- Guardian: appointments for children they hold verified access to.
create function public.my_appointments() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('appointmentId', a.id, 'status', a.status, 'childId', c.id, 'childName', c.display_name, 'sessionId', s.id,
      'serviceDate', s.service_date, 'startsAt', s.starts_at, 'endsAt', s.ends_at, 'clinicId', s.clinic_id, 'clinicName', cl.name, 'serviceCode', s.service_code, 'version', a.version)
      order by s.starts_at desc), '[]'::jsonb)
    from public.appointments a join public.clinic_sessions s on s.id = a.session_id join public.children c on c.id = a.child_id join public.clinics cl on cl.id = s.clinic_id
   where private.guardian_has_full_access(a.child_id) and a.status in ('confirmed','checked_in','fulfilled','no_show','cancelled','rescheduled') and s.service_date >= current_date - 60
$$;

-- ---------------------------------------------------------------------------------------------
-- Arrival queue
-- ---------------------------------------------------------------------------------------------
create function private.queue_event(p_entry public.queue_entries, p_from text, p_to text, p_station text, p_reason text) returns void
language sql security definer set search_path = '' as $$
  insert into public.queue_events (organization_id, queue_entry_id, from_status, to_status, station, reason, created_by)
  values (p_entry.organization_id, p_entry.id, p_from, p_to, p_station, p_reason, auth.uid())
$$;

create function public.check_in(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_appointment_id uuid default null, p_overflow_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_prev jsonb; v_canon uuid; v_today date; a public.appointments; s public.clinic_sessions; c public.children; e public.queue_entries;
  v_no int; v_walkin boolean := p_appointment_id is null; v_cap int; v_used int;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'queue.manage');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'queue.check_in', jsonb_build_object('c', p_clinic_id, 'child', p_child_id, 'a', p_appointment_id, 'o', p_overflow_reason));
  if v_prev is not null then return v_prev; end if;
  select * into c from public.children where id = v_canon;
  if c.record_status not in ('provisional','active') then raise exception 'record is not open for service' using errcode = 'CV409'; end if;
  v_today := private.local_today(p_clinic_id);
  if exists (select 1 from public.queue_entries where clinic_id = p_clinic_id and service_date = v_today and child_id = v_canon and status in ('waiting','called','in_service','held')) then
    raise exception 'this child is already in today''s queue' using errcode = 'CV409';
  end if;

  if not v_walkin then
    select a0.* into a from public.appointments a0 where a0.id = p_appointment_id and a0.child_id = v_canon;
    if not found then raise exception 'not found' using errcode = 'CV404'; end if;
    select * into s from public.clinic_sessions where id = a.session_id;
    if s.clinic_id <> p_clinic_id then raise exception 'not found' using errcode = 'CV404'; end if;
    select * into a from public.appointments where id = p_appointment_id for update;
    if a.status <> 'confirmed' then raise exception 'appointment is %', a.status using errcode = 'CV409'; end if;
    if s.service_date <> v_today then raise exception 'this appointment is not for today; reschedule it or check the child in as a walk-in' using errcode = 'CV409'; end if;
  else
    -- Walk-ins draw on the reserved allocation of today's open sessions. Overflow is a recorded staff decision, never silent.
    select coalesce(sum(walkin_capacity), 0) into v_cap from public.clinic_sessions where clinic_id = p_clinic_id and service_date = v_today and status = 'open';
    select count(*) into v_used from public.queue_entries where clinic_id = p_clinic_id and service_date = v_today and walk_in and status <> 'cancelled';
    if v_used >= v_cap and (p_overflow_reason is null or length(btrim(p_overflow_reason)) < 3) then
      raise exception 'the walk-in allocation for today is used up (or no session is open); record an overflow reason to continue' using errcode = 'CV409';
    end if;
  end if;

  v_no := private.allocate_ticket(p_clinic_id, v_today);
  insert into public.queue_entries (organization_id, child_id, clinic_id, service_date, appointment_id, ticket_no, walk_in, created_by, updated_by)
  values (v_org, v_canon, p_clinic_id, v_today, p_appointment_id, v_no, v_walkin, auth.uid(), auth.uid()) returning * into e;
  perform private.queue_event(e, null, 'waiting', null, case when v_walkin and p_overflow_reason is not null then 'overflow: ' || p_overflow_reason end);
  if not v_walkin then update public.appointments set status = 'checked_in', checked_in_at = now(), updated_by = auth.uid() where id = a.id; end if;
  perform private.audit(v_org, 'queue.manage', 'queue.checked_in', 'queue_entry', e.id, null, jsonb_build_object('ticket', v_no, 'walkIn', v_walkin, 'overflow', p_overflow_reason is not null), p_overflow_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('queueEntryId', e.id, 'ticketNo', v_no, 'ticket', private.ticket_label(v_today, v_no), 'walkIn', v_walkin, 'status', 'waiting', 'version', e.version));
end $$;

create function private.queue_next_allowed(p_from text, p_to text) returns boolean language sql immutable set search_path = '' as $$
  select (p_from, p_to) in (
    ('waiting','called'), ('waiting','left'), ('waiting','cancelled'),
    ('called','called'), ('called','in_service'), ('called','held'), ('called','left'), ('called','cancelled'),
    ('held','waiting'), ('held','left'), ('held','cancelled'),
    ('in_service','completed'), ('in_service','deferred'))
$$;

create function public.queue_transition(p_operation_key uuid, p_clinic_id uuid, p_entry_id uuid, p_to text, p_expected_version integer, p_station text default null, p_reason text default null, p_outcome text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_prev jsonb; e public.queue_entries; v_from text; v_enc uuid; v_now timestamptz := now(); v_today date;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'queue.manage');
  select * into e from public.queue_entries where id = p_entry_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'queue.transition', jsonb_build_object('c', p_clinic_id, 'e', p_entry_id, 'to', p_to, 'v', p_expected_version, 'st', p_station, 'r', p_reason, 'o', p_outcome));
  if v_prev is not null then return v_prev; end if;
  if e.version <> p_expected_version then raise exception 'stale version' using errcode = 'CV409'; end if;
  v_from := e.status;
  if not private.queue_next_allowed(v_from, p_to) then raise exception 'cannot move a ticket from % to %', v_from, p_to using errcode = 'CV409'; end if;
  if p_to in ('left','cancelled','held') and (p_reason is null or length(btrim(p_reason)) < 3) then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  v_today := e.service_date;

  if p_to = 'called' then
    update public.queue_entries set status = 'called', called_at = v_now, station = coalesce(p_station, station), updated_by = auth.uid() where id = e.id;
  elsif p_to = 'in_service' then
    if e.encounter_id is null then
      insert into public.encounters (organization_id, child_id, clinic_id, appointment_id, service_date, started_at, created_by, updated_by)
      values (v_org, e.child_id, p_clinic_id, e.appointment_id, e.service_date, v_now, auth.uid(), auth.uid()) returning id into v_enc;
    else v_enc := e.encounter_id; end if;
    update public.queue_entries set status = 'in_service', service_started_at = coalesce(service_started_at, v_now), station = coalesce(p_station, station), encounter_id = v_enc, updated_by = auth.uid() where id = e.id;
  elsif p_to = 'held' then
    update public.queue_entries set status = 'held', updated_by = auth.uid() where id = e.id;
  elsif p_to = 'waiting' then
    -- A returning patient keeps their ticket but re-joins the line behind those already waiting (published clinic policy).
    update public.queue_entries set status = 'waiting', queued_at = v_now, updated_by = auth.uid() where id = e.id;
  elsif p_to in ('left','cancelled') then
    update public.queue_entries set status = p_to, completed_at = v_now, updated_by = auth.uid() where id = e.id;
    -- the booking is not consumed: the family can be checked in again
    if e.appointment_id is not null then update public.appointments set status = 'confirmed', checked_in_at = null, updated_by = auth.uid() where id = e.appointment_id and status = 'checked_in'; end if;
  elsif p_to in ('completed','deferred') then
    p_outcome := coalesce(p_outcome, case when p_to = 'deferred' then 'deferred' end);
    if p_outcome is null or p_outcome not in ('vaccinated','deferred','referred','no_service') then raise exception 'record the visit outcome' using errcode = 'CV422'; end if;
    if p_to = 'deferred' and p_outcome not in ('deferred','referred') then raise exception 'a deferred visit ends as deferred or referred' using errcode = 'CV422'; end if;
    update public.queue_entries set status = p_to, completed_at = v_now, updated_by = auth.uid() where id = e.id;
    update public.encounters set status = 'completed', outcome = p_outcome, ended_at = v_now, updated_by = auth.uid() where id = e.encounter_id;
    -- Fulfilled = the planned encounter happened and has an outcome (it may be a deferral). It does not imply every planned dose was given.
    if e.appointment_id is not null then update public.appointments set status = 'fulfilled', updated_by = auth.uid() where id = e.appointment_id; end if;
  end if;
  select * into e from public.queue_entries where id = e.id;
  perform private.queue_event(e, v_from, p_to, coalesce(p_station, e.station), p_reason);
  perform private.audit(v_org, 'queue.manage', 'queue.' || p_to, 'queue_entry', e.id, jsonb_build_object('status', v_from), jsonb_build_object('status', p_to, 'outcome', p_outcome), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('queueEntryId', e.id, 'status', e.status, 'version', e.version, 'encounterId', e.encounter_id, 'ticket', private.ticket_label(e.service_date, e.ticket_no)));
end $$;

-- "Call next": priority first, then longest waiting. SKIP LOCKED means two stations never receive the same patient.
create function public.call_next(p_operation_key uuid, p_clinic_id uuid, p_station text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; e public.queue_entries; v_today date;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'queue.manage');
  v_prev := private.begin_command(v_org, p_operation_key, 'queue.call_next', jsonb_build_object('c', p_clinic_id, 's', p_station));
  if v_prev is not null then return v_prev; end if;
  v_today := private.local_today(p_clinic_id);
  select * into e from public.queue_entries
   where clinic_id = p_clinic_id and service_date = v_today and status = 'waiting'
   order by (priority_code = 'priority') desc, queued_at, ticket_no
   for update skip locked limit 1;
  if not found then return private.finish_command(v_org, p_operation_key, jsonb_build_object('called', false)); end if;
  update public.queue_entries set status = 'called', called_at = now(), station = left(p_station, 40), updated_by = auth.uid() where id = e.id;
  select * into e from public.queue_entries where id = e.id;
  perform private.queue_event(e, 'waiting', 'called', e.station, null);
  perform private.audit(v_org, 'queue.manage', 'queue.called', 'queue_entry', e.id, jsonb_build_object('status', 'waiting'), jsonb_build_object('status', 'called', 'station', e.station), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('called', true, 'queueEntryId', e.id, 'ticket', private.ticket_label(e.service_date, e.ticket_no), 'station', e.station, 'version', e.version));
end $$;

create function public.set_queue_priority(p_operation_key uuid, p_clinic_id uuid, p_entry_id uuid, p_priority text, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; e public.queue_entries;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'queue.manage');
  if p_priority not in ('routine','priority') then raise exception 'invalid priority' using errcode = 'CV422'; end if;
  if p_priority = 'priority' and (p_reason is null or length(btrim(p_reason)) < 3) then raise exception 'a reason is required to prioritise a patient' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'queue.priority', jsonb_build_object('c', p_clinic_id, 'e', p_entry_id, 'p', p_priority, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into e from public.queue_entries where id = p_entry_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if e.status not in ('waiting','held') then raise exception 'only waiting tickets can be re-prioritised' using errcode = 'CV409'; end if;
  update public.queue_entries set priority_code = p_priority, priority_reason = case when p_priority = 'priority' then p_reason end, updated_by = auth.uid() where id = e.id;
  perform private.audit(v_org, 'queue.manage', 'queue.priority_changed', 'queue_entry', e.id, jsonb_build_object('priority', e.priority_code), jsonb_build_object('priority', p_priority), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('queueEntryId', e.id, 'priority', p_priority));
end $$;

create function public.list_queue(p_clinic_id uuid, p_date date default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_date date; v_org uuid;
begin
  perform private.require_any(p_clinic_id, array['queue.manage','appointment.manage','child.search']);
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  v_date := coalesce(p_date, private.local_today(p_clinic_id));
  perform private.audit(v_org, 'queue.manage', 'queue.view', 'clinic', p_clinic_id, null, jsonb_build_object('date', v_date), null);
  return coalesce((select jsonb_agg(jsonb_build_object(
      'queueEntryId', q.id, 'ticket', private.ticket_label(q.service_date, q.ticket_no), 'ticketNo', q.ticket_no, 'status', q.status, 'station', q.station, 'priority', q.priority_code,
      'priorityReason', q.priority_reason, 'walkIn', q.walk_in, 'childId', c.id, 'childName', c.display_name, 'recordNo', c.local_record_no,
      'arrivedAt', q.arrived_at, 'queuedAt', q.queued_at, 'calledAt', q.called_at, 'serviceStartedAt', q.service_started_at, 'encounterId', q.encounter_id, 'appointmentId', q.appointment_id, 'version', q.version)
      order by case q.status when 'in_service' then 0 when 'called' then 1 when 'waiting' then 2 when 'held' then 3 else 4 end, (q.priority_code = 'priority') desc, q.queued_at, q.ticket_no)
    from public.queue_entries q join public.children c on c.id = q.child_id where q.clinic_id = p_clinic_id and q.service_date = v_date), '[]'::jsonb);
end $$;

-- Waiting-room display: ticket numbers and stations only. No names, birth dates or vaccine information (BP17).
create function public.public_queue_display(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_today date;
begin
  if not exists (select 1 from public.clinics where id = p_clinic_id and status = 'active') then return null; end if;
  v_today := private.local_today(p_clinic_id);
  return jsonb_build_object(
    'asOf', now(),
    'nowCalling', coalesce((select jsonb_agg(jsonb_build_object('ticket', private.ticket_label(q.service_date, q.ticket_no), 'station', q.station) order by q.called_at) from public.queue_entries q
                             where q.clinic_id = p_clinic_id and q.service_date = v_today and q.status in ('called','in_service')), '[]'::jsonb),
    'waiting', coalesce((select jsonb_agg(private.ticket_label(q.service_date, q.ticket_no) order by (q.priority_code = 'priority') desc, q.queued_at, q.ticket_no) from public.queue_entries q
                          where q.clinic_id = p_clinic_id and q.service_date = v_today and q.status = 'waiting'), '[]'::jsonb));
end $$;

-- Guardian: private status for their own child only. Shows people ahead; no time estimate without measured data (BP17).
create function public.guardian_queue_status(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid; e public.queue_entries; v_ahead int;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then return null; end if;
  select q.* into e from public.queue_entries q
   where q.child_id = v_canon and q.status in ('waiting','called','in_service','held') and q.service_date = private.local_today(q.clinic_id) order by q.created_at desc limit 1;
  if not found then return null; end if;
  select count(*) into v_ahead from public.queue_entries o
   where o.clinic_id = e.clinic_id and o.service_date = e.service_date and o.status = 'waiting' and o.id <> e.id
     and ((o.priority_code = 'priority' and e.priority_code <> 'priority') or (o.priority_code = e.priority_code and (o.queued_at, o.ticket_no) < (e.queued_at, e.ticket_no)));
  return jsonb_build_object('ticket', private.ticket_label(e.service_date, e.ticket_no), 'status', e.status, 'station', e.station, 'peopleAhead', case when e.status = 'waiting' then v_ahead end, 'updatedAt', e.updated_at);
end $$;

do $$
declare f text;
begin
  foreach f in array array[
    'create_session(uuid,uuid,jsonb)', 'list_sessions(uuid,date,date)', 'guardian_list_sessions(uuid,date,date)', 'cancel_session(uuid,uuid,uuid,text)',
    'book_appointment(uuid,uuid,uuid,text,text[])', 'cancel_appointment(uuid,uuid,text)', 'reschedule_appointment(uuid,uuid,uuid,text)',
    'list_appointments(uuid,date)', 'my_appointments()', 'check_in(uuid,uuid,uuid,uuid,text)',
    'queue_transition(uuid,uuid,uuid,text,integer,text,text,text)', 'call_next(uuid,uuid,text)', 'set_queue_priority(uuid,uuid,uuid,text,text)',
    'list_queue(uuid,date)', 'guardian_queue_status(uuid)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
revoke all on function public.public_queue_display(uuid) from public, anon, authenticated;
grant execute on function public.public_queue_display(uuid) to anon, authenticated;
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function private.has_capability(uuid, text), private.clinics_with(text), private.session_ok(),
  private.my_guardian_ids(), private.guardian_can_read_child(uuid) to authenticated;
-- END 0013_visit_commands.sql

-- =====================================================================================================================
-- BEGIN 0014_my_children_clinic.sql  sha256=1d5ad24eb8e026d10149e289b32e3701cbeb3a8442ede4019cbaa84e60acf49f
-- =====================================================================================================================
-- 0014 Guardian child list also returns the child's clinic id (needed to offer that clinic's sessions).
create or replace function public.my_children() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'childId', c.id, 'displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob, 'dobPrecision', c.birth_date_precision,
    'recordStatus', c.record_status, 'relationshipStatus', r.status, 'accessScope', r.access_scope, 'relationship', r.relationship,
    'clinicId', (select e.clinic_id from public.child_clinic_enrollments e where e.child_id = c.id and e.status in ('pending','active') order by e.is_primary desc, e.created_at limit 1),
    'clinicName', (select cl.name from public.child_clinic_enrollments e join public.clinics cl on cl.id = e.clinic_id
                    where e.child_id = c.id and e.status in ('pending','active') order by e.is_primary desc, e.created_at limit 1)
  ) order by c.display_name), '[]'::jsonb)
  from public.guardian_child_relationships r
  join public.children c on c.id = r.child_id
  where r.guardian_id in (select private.my_guardian_ids()) and r.status in ('provisional','active') and c.record_status <> 'merged'
$$;
revoke all on function public.my_children() from public, anon, authenticated;
grant execute on function public.my_children() to authenticated;
-- END 0014_my_children_clinic.sql

-- =====================================================================================================================
-- BEGIN 0015_administration.sql  sha256=c92931347a3d7fc4b698eb92b35044554010b0cfbf1c431e7f290827048dfbbe
-- =====================================================================================================================
-- 0015 Atomic administration recording, exception intake for already-given care, corrections and lot tracing.
-- Blueprint refs: BP18, BP19 (corrections vs physical stock), BP15.E, F09, F05, F15, T03-T08, T13-T16.
--
-- One normal recording = ONE transaction: identity + encounter + lot/stock + timing checks -> event + signed revision ->
-- stock issue -> encounter refs -> pinned schedule evaluation -> outbox -> audit -> receipt. Any failure rolls all of it back
-- (no partial clinical save). Actual care that fails the normal checks is never lost: it goes through the exception path.

alter table public.vaccination_revisions drop constraint vaccination_revisions_source_check;
alter table public.vaccination_revisions add constraint vaccination_revisions_source_check
  check (source in ('clinic_administered','clinic_exception','paper_reconciliation','external_documented','parent_reported','bhw_reported','historical_import'));

-- Capability check for ANOTHER profile (e.g. "vaccinated by" someone other than the signed-in recorder).
create function private.profile_has_cap(p_profile uuid, p_clinic uuid, p_cap text) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.staff_memberships m
      join public.clinics c on c.id = m.clinic_id and c.organization_id = m.organization_id
      join public.profiles p on p.id = m.profile_id and p.status = 'active'
     where m.profile_id = p_profile and m.clinic_id = p_clinic and m.status = 'active' and c.status = 'active'
       and m.valid_from <= now() and (m.valid_until is null or m.valid_until > now())
       and (p_cap = any (private.role_preset(m.role_code)) or p_cap = any (m.capabilities)))
$$;

-- Would this dose, given on p_on, satisfy the approved schedule? Never an override: blocks are explained, exceptions use another path.
create function private.check_planned_dose(p_child uuid, p_product uuid, p_on date) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  c public.children; v_ver uuid; v_in jsonb; v_codes jsonb; v_pcode text; v_res jsonb; v_credited jsonb; v_flagged jsonb; v_blocking jsonb := '[]'::jsonb;
begin
  select * into c from public.children where id = p_child;
  v_ver := private.active_schedule_for(c.organization_id, 'routine', c.dob, p_on);
  if v_ver is null then return jsonb_build_object('evaluated', false, 'blocked', false, 'credited', '[]'::jsonb, 'reasons', '[]'::jsonb); end if;
  v_in := private.child_eval_inputs(p_child);
  if exists (select 1 from jsonb_array_elements(v_in -> 'holds') h) then
    return jsonb_build_object('evaluated', true, 'blocked', true, 'credited', '[]'::jsonb, 'reasons', jsonb_build_array('clinical_hold'));
  end if;
  if not (v_in ->> 'dobExact')::boolean then
    return jsonb_build_object('evaluated', true, 'blocked', true, 'credited', '[]'::jsonb, 'reasons', jsonb_build_array('birth_date_not_exact'));
  end if;
  select coalesce(jsonb_agg(a.code order by a.code), '[]'::jsonb), max(p.code) into v_codes, v_pcode
    from public.vaccine_products p left join public.product_antigens pa on pa.product_id = p.id left join public.antigens a on a.id = pa.antigen_id where p.id = p_product;
  v_res := private.evaluate_rules(v_ver, c.dob, true, (v_in -> 'doses') || jsonb_build_array(jsonb_build_object('id', 'new', 'antigens', v_codes, 'product', v_pcode, 'on', p_on, 'unresolved', false)), v_in -> 'holds', p_on);
  select coalesce(jsonb_agg(x ->> 'requirement'), '[]'::jsonb) into v_credited from jsonb_array_elements(v_res -> 'requirements') x where x ->> 'creditedDoseId' = 'new';
  select coalesce(jsonb_agg(jsonb_build_object('requirement', x ->> 'requirement', 'reason', d ->> 'reason')), '[]'::jsonb) into v_flagged
    from jsonb_array_elements(v_res -> 'requirements') x, jsonb_array_elements(coalesce(x -> 'reasons' -> 0 -> 'doses', '[]'::jsonb)) d where d ->> 'doseId' = 'new';
  return jsonb_build_object('evaluated', true, 'blocked', jsonb_array_length(v_flagged) > 0, 'credited', v_credited, 'reasons', v_flagged);
end $$;

create function private.reasons_text(p jsonb) returns text language sql immutable set search_path = '' as $$
  select coalesce(string_agg(case when jsonb_typeof(r) = 'string' then trim(both '"' from r::text) else (r ->> 'requirement') || ': ' || (r ->> 'reason') end, '; '), '')
    from jsonb_array_elements(p) r
$$;

create function public.get_open_encounter(p_clinic_id uuid, p_child_id uuid) returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_canon uuid; e public.encounters;
begin
  perform private.require_any(p_clinic_id, array['vaccination.record','queue.manage','child.read_clinical']);
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  select * into e from public.encounters where child_id = v_canon and clinic_id = p_clinic_id and status = 'open' order by started_at desc nulls last limit 1;
  if not found then return null; end if;
  return jsonb_build_object('encounterId', e.id, 'serviceDate', e.service_date, 'startedAt', e.started_at, 'assessmentReference', e.assessment_reference, 'consentReference', e.consent_reference,
                            'administrations', (select count(*) from public.vaccination_events v where v.encounter_id = e.id));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Normal (planned) administration
-- ---------------------------------------------------------------------------------------------
create function public.record_administration(p_operation_key uuid, p_clinic_id uuid, p_encounter_id uuid, p_admin jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_tz text; v_prev jsonb; enc public.encounters; v_child uuid; c public.children; v_by uuid; v_at timestamptz; v_on date;
  v_lot public.vaccine_lots; v_prod public.vaccine_products; v_loc uuid; v_doses numeric; v_check jsonb; v_event uuid; v_rev uuid; v_tx uuid;
  v_route text; v_site text; v_res jsonb; v_credited jsonb; v_eval uuid; v_confirm boolean;
begin
  select organization_id, timezone into v_org, v_tz from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  -- Lock the encounter first (consistent order: encounter -> stock row), serialising concurrent recording for one visit.
  select * into enc from public.encounters where id = p_encounter_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_child := private.canonical_child(enc.child_id);
  if not private.child_in_clinic(v_child, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'vaccination.record', jsonb_build_object('c', p_clinic_id, 'enc', p_encounter_id, 'a', p_admin));
  if v_prev is not null then return v_prev; end if;
  if enc.status <> 'open' then raise exception 'the visit is not open' using errcode = 'CV409'; end if;
  select * into c from public.children where id = v_child;
  if c.record_status <> 'active' then raise exception 'confirm the child''s identity before recording care' using errcode = 'CV409'; end if;
  if p_admin is null or jsonb_typeof(p_admin) <> 'object' then raise exception 'administration details required' using errcode = 'CV400'; end if;

  begin
    v_by := coalesce(nullif(p_admin ->> 'administeredBy', '')::uuid, auth.uid());
    v_at := coalesce(nullif(p_admin ->> 'administeredAt', '')::timestamptz, now());
    v_loc := (p_admin ->> 'locationId')::uuid;
    v_doses := coalesce(nullif(p_admin ->> 'doses', '')::numeric, 1);
    v_confirm := coalesce((p_admin ->> 'confirmRepeat')::boolean, false);
    select * into v_lot from public.vaccine_lots where id = (p_admin ->> 'lotId')::uuid and organization_id = v_org;
  exception when others then raise exception 'administration details are invalid' using errcode = 'CV422';
  end;
  if v_lot.id is null or v_loc is null then raise exception 'choose the lot and stock location used' using errcode = 'CV422'; end if;
  select * into v_prod from public.vaccine_products where id = v_lot.product_id;
  if nullif(p_admin ->> 'productId', '') is not null and (p_admin ->> 'productId')::uuid <> v_prod.id then raise exception 'the lot belongs to a different product' using errcode = 'CV422'; end if;
  if v_by <> auth.uid() and not private.profile_has_cap(v_by, p_clinic_id, 'vaccination.record') then raise exception 'the named vaccinator is not authorised to vaccinate at this clinic' using errcode = 'CV422'; end if;
  if v_doses <> 1 then raise exception 'record one administration at a time (single-dose presentations)' using errcode = 'CV422'; end if;
  if v_at > now() + interval '5 minutes' then raise exception 'the administration time cannot be in the future' using errcode = 'CV422'; end if;
  v_on := (v_at at time zone v_tz)::date;
  v_route := nullif(left(btrim(coalesce(p_admin ->> 'route', '')), 40), '');
  v_site := nullif(left(btrim(coalesce(p_admin ->> 'site', '')), 40), '');

  -- Possible duplicate: same child + product + local date. A genuine repeat is allowed only when explicitly confirmed (BP39);
  -- it must then still satisfy the schedule below, otherwise it goes through the exception path (facts preserved, no credit).
  if not v_confirm and exists (
      select 1 from private.current_revisions cr where cr.child_id in (select private.child_ids_with_aliases(v_child)) and cr.product_id = v_prod.id
         and cr.event_status = 'active' and cr.verification_status <> 'rejected' and cr.administered_on = v_on) then
    raise exception 'a similar administration already exists for this child today; confirm only if this is a genuine repeat' using errcode = 'CV409';
  end if;
  -- Timing/eligibility per the APPROVED schedule (planned path). Explained, never silently overridden.
  v_check := private.check_planned_dose(v_child, v_prod.id, v_on);
  if (v_check ->> 'blocked')::boolean then
    raise exception 'not allowed by the approved schedule (%). If the vaccine was already given, use "record care already given".', private.reasons_text(v_check -> 'reasons') using errcode = 'CV422';
  end if;

  insert into public.vaccination_events (organization_id, original_child_id, encounter_id, origin, source_operation_id, created_by)
  values (v_org, v_child, enc.id, 'clinic_administered', p_operation_key, auth.uid()) returning id into v_event;
  insert into public.vaccination_revisions (organization_id, event_id, revision_no, child_id, product_id, administered_on, administered_at, date_precision, lot_id, expiry_snapshot,
                                             quantity, unit, route, site, administered_by, clinic_id, source, verification_status, signed_at, created_by)
  values (v_org, v_event, 1, v_child, v_prod.id, v_on, v_at, 'exact', v_lot.id, v_lot.expires_on, 1, 'dose', v_route, v_site, v_by, p_clinic_id, 'clinic_administered', 'verified', now(), auth.uid())
  returning id into v_rev;

  -- Stock in the SAME transaction: exactly one physical issue. Failure here rolls the clinical record back too (T04).
  v_tx := private.issue_for_administration(v_org, p_clinic_id, v_loc, v_lot.id, v_doses, v_event, p_operation_key);

  update public.encounters set assessment_reference = coalesce(nullif(left(btrim(coalesce(p_admin ->> 'assessmentReference', '')), 200), ''), assessment_reference),
         consent_reference = coalesce(nullif(left(btrim(coalesce(p_admin ->> 'consentReference', '')), 200), ''), consent_reference), updated_by = auth.uid() where id = enc.id;

  v_res := private.compute_child_schedule(v_child, private.local_today(p_clinic_id), true);
  v_eval := nullif(v_res ->> 'evaluationId', '')::uuid;
  select coalesce(jsonb_agg(x ->> 'requirement'), '[]'::jsonb) into v_credited from jsonb_array_elements(coalesce(v_res -> 'requirements', '[]'::jsonb)) x where x ->> 'creditedDoseId' = v_rev::text;

  perform private.enqueue(v_org, 'vaccination.recorded', 'vaccination_event', v_event, 'vax-recorded:' || v_event, jsonb_build_object('childId', v_child, 'clinicId', p_clinic_id));
  perform private.audit(v_org, 'vaccination.record', 'vaccination.recorded', 'vaccination_event', v_event, null,
                        jsonb_build_object('child', v_child, 'product', v_prod.code, 'lot', v_lot.manufacturer_lot, 'on', v_on, 'credited', v_credited, 'stockTransaction', v_tx), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('eventId', v_event, 'revisionId', v_rev, 'stockTransactionId', v_tx, 'evaluationId', v_eval,
      'creditedRequirements', v_credited, 'scheduleEvaluated', coalesce((v_check ->> 'evaluated')::boolean, false), 'administeredOn', v_on));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Exception intake: care ALREADY GIVEN that fails the normal checks. Facts preserved, credit withheld, stock never invented.
-- ---------------------------------------------------------------------------------------------
create function public.record_administration_exception(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_encounter_id uuid, p_admin jsonb, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_tz text; v_prev jsonb; v_child uuid; v_by uuid; v_at timestamptz; v_on date; v_lot public.vaccine_lots; v_prod public.vaccine_products; v_loc uuid;
  v_event uuid; v_rev uuid; v_case uuid; v_tx uuid; v_problems text[] := '{}'; v_check jsonb; v_stock_case uuid; v_text text; v_product_id uuid;
begin
  select organization_id, timezone into v_org, v_tz from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  v_child := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_child, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'explain why this could not be recorded normally' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'vaccination.exception', jsonb_build_object('c', p_clinic_id, 'child', p_child_id, 'enc', p_encounter_id, 'a', p_admin, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if p_encounter_id is not null and not exists (select 1 from public.encounters where id = p_encounter_id and clinic_id = p_clinic_id and child_id = v_child) then raise exception 'not found' using errcode = 'CV404'; end if;
  begin
    v_by := coalesce(nullif(p_admin ->> 'administeredBy', '')::uuid, auth.uid());
    v_at := (p_admin ->> 'administeredAt')::timestamptz;
    v_loc := nullif(p_admin ->> 'locationId', '')::uuid;
    v_product_id := nullif(p_admin ->> 'productId', '')::uuid;
    if nullif(p_admin ->> 'lotId', '') is not null then select * into v_lot from public.vaccine_lots where id = (p_admin ->> 'lotId')::uuid and organization_id = v_org; end if;
  exception when others then raise exception 'details are invalid' using errcode = 'CV422';
  end;
  v_text := nullif(left(btrim(coalesce(p_admin ->> 'productText', '')), 200), '');
  if v_at is null then raise exception 'the actual administration time is required' using errcode = 'CV422'; end if;
  if v_at > now() + interval '5 minutes' then raise exception 'the administration time cannot be in the future' using errcode = 'CV422'; end if;
  if v_lot.id is not null then v_product_id := v_lot.product_id; end if;
  if v_product_id is null and v_text is null then raise exception 'identify the vaccine (product or a description)' using errcode = 'CV422'; end if;
  if v_product_id is not null then select * into v_prod from public.vaccine_products where id = v_product_id and organization_id = v_org; if v_prod.id is null then raise exception 'unknown product' using errcode = 'CV422'; end if; end if;
  v_on := (v_at at time zone v_tz)::date;

  -- Why would the normal path have refused? (for the reviewer; none of these blocks the record)
  if v_prod.id is null then v_problems := array_append(v_problems, 'product_not_mapped'); end if;
  if v_lot.id is null then v_problems := array_append(v_problems, 'lot_unknown');
  elsif v_lot.global_disposition <> 'usable' then v_problems := array_append(v_problems, 'lot_' || v_lot.global_disposition);
  elsif private.lot_is_expired(v_lot.expires_on, v_on) then v_problems := array_append(v_problems, 'lot_expired'); end if;
  if v_prod.id is not null then
    v_check := private.check_planned_dose(v_child, v_prod.id, v_on);
    if (v_check ->> 'blocked')::boolean then v_problems := array_append(v_problems, 'timing_or_eligibility: ' || private.reasons_text(v_check -> 'reasons')); end if;
  end if;

  insert into public.vaccination_events (organization_id, original_child_id, encounter_id, origin, source_operation_id, created_by)
  values (v_org, v_child, p_encounter_id, 'clinic_administered', p_operation_key, auth.uid()) returning id into v_event;
  -- Pending verification: the engine credits only verified revisions, so no credit is possible until a reviewer accepts it.
  insert into public.vaccination_revisions (organization_id, event_id, revision_no, child_id, product_id, reported_product_text, administered_on, administered_at, date_precision, lot_id, reported_lot, expiry_snapshot,
                                             quantity, unit, route, site, administered_by, clinic_id, source, verification_status, reason, created_by)
  values (v_org, v_event, 1, v_child, v_prod.id, coalesce(v_text, v_prod.name), v_on, v_at, 'exact', v_lot.id, nullif(left(btrim(coalesce(p_admin ->> 'lotText', '')), 100), ''), v_lot.expires_on,
          1, 'dose', nullif(left(btrim(coalesce(p_admin ->> 'route', '')), 40), ''), nullif(left(btrim(coalesce(p_admin ->> 'site', '')), 40), ''), v_by, p_clinic_id, 'clinic_exception', 'pending_verification', p_reason, auth.uid())
  returning id into v_rev;

  -- Stock: post the issue ONLY if the lot is known, usable and stocked. Otherwise open a reconciliation item; never fake a lot or go negative.
  if v_lot.id is not null and v_loc is not null and v_prod.doses_per_container = 1 and not exists (select 1 from unnest(v_problems) pr where pr like 'lot_%' or pr = 'product_not_mapped') then
    begin
      v_tx := private.issue_for_administration(v_org, p_clinic_id, v_loc, v_lot.id, 1, v_event, p_operation_key);
    exception when others then
      v_problems := array_append(v_problems, 'stock_unavailable');
    end;
  else
    v_problems := array_append(v_problems, 'stock_not_posted');
  end if;
  if v_tx is null then
    insert into public.record_review_cases (organization_id, clinic_id, kind, child_id, vaccination_event_id, reason, evidence, created_by, updated_by)
    values (v_org, p_clinic_id, 'stock', v_child, v_event, 'care was given but no stock issue could be posted; reconcile the lot and quantity',
            jsonb_build_object('eventId', v_event, 'lotId', v_lot.id, 'reportedLot', p_admin ->> 'lotText', 'problems', to_jsonb(v_problems)), auth.uid(), auth.uid()) returning id into v_stock_case;
  end if;
  insert into public.record_review_cases (organization_id, clinic_id, kind, child_id, vaccination_event_id, reason, evidence, created_by, updated_by)
  values (v_org, p_clinic_id, 'clinical', v_child, v_event, left('administration recorded as an exception: ' || p_reason, 500),
          jsonb_build_object('problems', to_jsonb(v_problems), 'exception', true, 'stockPosted', v_tx is not null, 'stockCaseId', v_stock_case), auth.uid(), auth.uid()) returning id into v_case;
  perform private.audit(v_org, 'vaccination.record', 'vaccination.exception_recorded', 'vaccination_event', v_event, null,
                        jsonb_build_object('child', v_child, 'problems', to_jsonb(v_problems), 'stockPosted', v_tx is not null), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('eventId', v_event, 'revisionId', v_rev, 'reviewCaseId', v_case, 'stockPosted', v_tx is not null, 'problems', to_jsonb(v_problems),
                                'verificationStatus', 'pending_verification', 'credited', false));
end $$;

-- A clinical lead accepts or rejects an exception. Acceptance creates revision N+1 (verified); credit still follows the engine's rules.
create function public.resolve_administration_exception(p_operation_key uuid, p_clinic_id uuid, p_event_id uuid, p_decision text, p_note text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; cur public.vaccination_revisions; v_status text; v_eval jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'correction.approve');
  if p_decision not in ('accept','reject') or p_note is null or length(btrim(p_note)) < 3 then raise exception 'decision and note are required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'vaccination.exception_resolve', jsonb_build_object('c', p_clinic_id, 'e', p_event_id, 'd', p_decision, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  perform 1 from public.vaccination_events where id = p_event_id and organization_id = v_org for update;
  select * into cur from private.current_revisions where event_id = p_event_id;
  if cur.id is null or cur.source <> 'clinic_exception' or not private.child_in_clinic(private.canonical_child(cur.child_id), p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if cur.verification_status <> 'pending_verification' then raise exception 'already decided' using errcode = 'CV409'; end if;
  if cur.created_by = auth.uid() then raise exception 'the recorder cannot approve their own exception' using errcode = 'CV403'; end if;
  v_status := case when p_decision = 'accept' then 'verified' else 'rejected' end;
  if v_status = 'verified' and cur.product_id is null then raise exception 'map the exception to an approved product before accepting (edit via correction)' using errcode = 'CV422'; end if;
  insert into public.vaccination_revisions (organization_id, event_id, revision_no, child_id, product_id, reported_product_text, administered_on, administered_at, date_precision, lot_id, reported_lot, expiry_snapshot,
                                             quantity, unit, route, site, administered_by, clinic_id, source, verification_status, event_status, approved_by, signed_at, reason, created_by)
  values (v_org, cur.event_id, cur.revision_no + 1, cur.child_id, cur.product_id, cur.reported_product_text, cur.administered_on, cur.administered_at, cur.date_precision, cur.lot_id, cur.reported_lot, cur.expiry_snapshot,
          cur.quantity, cur.unit, cur.route, cur.site, cur.administered_by, cur.clinic_id, 'clinic_exception', v_status, case when v_status = 'rejected' then 'voided' else 'active' end, auth.uid(), now(), p_note, auth.uid());
  update public.record_review_cases set status = case when v_status = 'verified' then 'resolved' else 'rejected' end, resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', p_decision, 'note', p_note) where vaccination_event_id = cur.event_id and kind = 'clinical' and status in ('open','in_review');
  v_eval := private.compute_child_schedule(private.canonical_child(cur.child_id), private.local_today(p_clinic_id), true);
  perform private.audit(v_org, 'correction.approve', 'vaccination.exception_' || p_decision, 'vaccination_event', cur.event_id, jsonb_build_object('status', cur.verification_status), jsonb_build_object('status', v_status), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('eventId', cur.event_id, 'verificationStatus', v_status, 'revisionNo', cur.revision_no + 1, 'evaluationId', v_eval ->> 'evaluationId'));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Corrections: propose (clinical staff) -> approve (different person with correction.approve)
-- ---------------------------------------------------------------------------------------------
create function public.request_correction(p_operation_key uuid, p_clinic_id uuid, p_event_id uuid, p_kind text, p_proposal jsonb, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; cur public.vaccination_revisions; v_case uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  if p_kind not in ('correct_details','reattribute_child','void_duplicate') then raise exception 'invalid correction type' using errcode = 'CV422'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'correction.request', jsonb_build_object('c', p_clinic_id, 'e', p_event_id, 'k', p_kind, 'p', p_proposal, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into cur from private.current_revisions where event_id = p_event_id and organization_id = v_org;
  if cur.id is null or not private.child_in_clinic(private.canonical_child(cur.child_id), p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if cur.event_status <> 'active' then raise exception 'this record is already voided' using errcode = 'CV409'; end if;
  if exists (select 1 from public.record_review_cases where vaccination_event_id = p_event_id and kind = 'correction' and status in ('open','in_review')) then raise exception 'a correction for this record is already waiting for review' using errcode = 'CV409'; end if;
  if p_kind = 'reattribute_child' and (nullif(p_proposal ->> 'toChildId', '') is null) then raise exception 'name the correct child' using errcode = 'CV422'; end if;
  if p_kind = 'void_duplicate' and coalesce(p_proposal ->> 'stockEffect', '') not in ('return_to_stock','wastage','none') then raise exception 'state what happened to the vaccine (return_to_stock, wastage or none)' using errcode = 'CV422'; end if;
  insert into public.record_review_cases (organization_id, clinic_id, kind, child_id, vaccination_event_id, reason, evidence, created_by, updated_by)
  values (v_org, p_clinic_id, 'correction', cur.child_id, p_event_id, left(p_reason, 500), jsonb_build_object('kind', p_kind, 'proposal', p_proposal, 'baseRevision', cur.revision_no), auth.uid(), auth.uid()) returning id into v_case;
  perform private.audit(v_org, 'vaccination.record', 'correction.requested', 'vaccination_event', p_event_id, null, jsonb_build_object('kind', p_kind, 'caseId', v_case), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('caseId', v_case, 'status', 'open'));
end $$;

create function public.approve_correction(p_operation_key uuid, p_clinic_id uuid, p_case_id uuid, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_prev jsonb; k public.record_review_cases; cur public.vaccination_revisions; v_kind text; v_prop jsonb; v_new_lot uuid; v_new_loc uuid; v_old_tx public.stock_transactions; v_old_mv public.stock_movements;
  v_lot public.vaccine_lots; v_child uuid := null; v_tx uuid; v_rev uuid; v_on date; v_at timestamptz; v_route text; v_site text; v_status text; v_stock jsonb := '[]'::jsonb; v_tz text; v_eval1 jsonb; v_eval2 jsonb;
  v_prod uuid; v_effect text; v_new_child uuid; v_ev_status text;
begin
  select organization_id, timezone into v_org, v_tz from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'correction.approve');
  select * into k from public.record_review_cases where id = p_case_id and organization_id = v_org and clinic_id = p_clinic_id and kind = 'correction' for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'correction.approve', jsonb_build_object('c', p_clinic_id, 'case', p_case_id, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  if k.status not in ('open','in_review') then raise exception 'already decided' using errcode = 'CV409'; end if;
  if k.created_by = auth.uid() then raise exception 'the proposer cannot approve their own correction' using errcode = 'CV403'; end if;
  perform 1 from public.vaccination_events where id = k.vaccination_event_id for update;
  select * into cur from private.current_revisions where event_id = k.vaccination_event_id;
  if cur.revision_no <> (k.evidence ->> 'baseRevision')::int then raise exception 'the record changed since this correction was requested; request it again' using errcode = 'CV409'; end if;
  v_kind := k.evidence ->> 'kind'; v_prop := k.evidence -> 'proposal';
  v_on := cur.administered_on; v_at := cur.administered_at; v_route := cur.route; v_site := cur.site; v_prod := cur.product_id; v_new_lot := cur.lot_id; v_status := cur.verification_status; v_ev_status := cur.event_status;
  v_new_child := cur.child_id;

  if v_kind = 'correct_details' then
    if nullif(v_prop ->> 'administeredAt', '') is not null then v_at := (v_prop ->> 'administeredAt')::timestamptz; v_on := (v_at at time zone v_tz)::date; end if;
    if v_at > now() + interval '5 minutes' then raise exception 'the administration time cannot be in the future' using errcode = 'CV422'; end if;
    if v_prop ? 'route' then v_route := nullif(left(btrim(v_prop ->> 'route'), 40), ''); end if;
    if v_prop ? 'site' then v_site := nullif(left(btrim(v_prop ->> 'site'), 40), ''); end if;
    if nullif(v_prop ->> 'lotId', '') is not null and (v_prop ->> 'lotId')::uuid <> cur.lot_id then
      -- The physical fact changed (a different vial was used): compensate the ledger, do not rewrite it (BP19).
      select * into v_lot from public.vaccine_lots where id = (v_prop ->> 'lotId')::uuid and organization_id = v_org;
      if v_lot.id is null then raise exception 'unknown lot' using errcode = 'CV422'; end if;
      v_new_loc := nullif(v_prop ->> 'locationId', '')::uuid;
      if v_new_loc is null then raise exception 'name the stock location of the correct lot' using errcode = 'CV422'; end if;
      select t.* into v_old_tx from public.stock_transactions t where t.event_id = cur.event_id and t.type = 'issue_administration' order by t.created_at limit 1;
      if v_old_tx.id is not null then
        select m.* into v_old_mv from public.stock_movements m where m.transaction_id = v_old_tx.id limit 1;
        insert into public.stock_transactions (organization_id, clinic_id, type, event_id, reason, approved_by, operation_id, reverses_id, created_by)
        values (v_org, p_clinic_id, 'reversal', cur.event_id, 'correction: wrong lot recorded', auth.uid(), p_operation_key, v_old_tx.id, auth.uid()) returning id into v_tx;
        perform private.post_movement(v_org, v_tx, v_old_mv.location_id, v_old_mv.lot_id, -v_old_mv.quantity_delta, 'corr-rev:' || p_operation_key);
        v_stock := v_stock || jsonb_build_object('reversed', v_old_tx.id);
      end if;
      v_tx := private.issue_for_administration(v_org, p_clinic_id, v_new_loc, v_lot.id, 1, cur.event_id, p_operation_key); -- refuses if the correct lot cannot supply it
      v_stock := v_stock || jsonb_build_object('issued', v_tx);
      v_new_lot := v_lot.id; v_prod := v_lot.product_id;
    end if;
  elsif v_kind = 'reattribute_child' then
    v_new_child := private.canonical_child((v_prop ->> 'toChildId')::uuid);
    if not private.child_in_clinic(v_new_child, p_clinic_id) or v_new_child = cur.child_id then raise exception 'the correct child must be a different child enrolled at this clinic' using errcode = 'CV422'; end if;
  else -- void_duplicate
    v_effect := v_prop ->> 'stockEffect';
    v_ev_status := 'voided';
    select t.* into v_old_tx from public.stock_transactions t where t.event_id = cur.event_id and t.type = 'issue_administration' order by t.created_at limit 1;
    if v_old_tx.id is not null and v_effect in ('return_to_stock','wastage') then
      select m.* into v_old_mv from public.stock_movements m where m.transaction_id = v_old_tx.id limit 1;
      insert into public.stock_transactions (organization_id, clinic_id, type, event_id, reason, approved_by, operation_id, reverses_id, created_by)
      values (v_org, p_clinic_id, 'reversal', cur.event_id, 'correction: duplicate record voided', auth.uid(), p_operation_key, v_old_tx.id, auth.uid()) returning id into v_tx;
      perform private.post_movement(v_org, v_tx, v_old_mv.location_id, v_old_mv.lot_id, -v_old_mv.quantity_delta, 'void-rev:' || p_operation_key);
      v_stock := v_stock || jsonb_build_object('reversed', v_old_tx.id);
      if v_effect = 'wastage' then
        -- The vial was physically used or spoiled: it is NOT returned to usable stock, it is reclassified as wastage.
        insert into public.stock_transactions (organization_id, clinic_id, type, event_id, reason, approved_by, operation_id, created_by)
        values (v_org, p_clinic_id, 'wastage', cur.event_id, 'duplicate record: dose physically lost', auth.uid(), p_operation_key, auth.uid()) returning id into v_tx;
        perform private.post_movement(v_org, v_tx, v_old_mv.location_id, v_old_mv.lot_id, v_old_mv.quantity_delta, 'void-waste:' || p_operation_key);
        v_stock := v_stock || jsonb_build_object('wastage', v_tx);
      end if;
    end if;
  end if;

  insert into public.vaccination_revisions (organization_id, event_id, revision_no, child_id, product_id, reported_product_text, administered_on, administered_at, date_precision, lot_id, reported_lot, expiry_snapshot,
                                             quantity, unit, route, site, administered_by, external_vaccinator, clinic_id, source, verification_status, event_status, approved_by, signed_at, reason, created_by)
  values (v_org, cur.event_id, cur.revision_no + 1, v_new_child, v_prod, cur.reported_product_text, v_on, v_at, cur.date_precision, v_new_lot,
          cur.reported_lot, coalesce((select expires_on from public.vaccine_lots where id = v_new_lot), cur.expiry_snapshot), cur.quantity, cur.unit, v_route, v_site, cur.administered_by, cur.external_vaccinator, cur.clinic_id,
          cur.source, cur.verification_status, v_ev_status, auth.uid(), now(), coalesce(p_note, k.reason), auth.uid()) returning id into v_rev;

  update public.record_review_cases set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', 'approved', 'newRevision', cur.revision_no + 1, 'stock', v_stock, 'note', p_note) where id = k.id;
  -- Recalculate downstream credit for every child whose facts changed (T16); certificates are reviewed in the certificate module.
  v_eval1 := private.compute_child_schedule(private.canonical_child(cur.child_id), private.local_today(p_clinic_id), true);
  if v_new_child <> cur.child_id then v_eval2 := private.compute_child_schedule(v_new_child, private.local_today(p_clinic_id), true); end if;
  perform private.enqueue(v_org, 'certificate.review', 'vaccination_event', cur.event_id, 'cert-review:' || v_rev::text, jsonb_build_object('event', cur.event_id, 'revision', cur.revision_no + 1));
  perform private.audit(v_org, 'correction.approve', 'correction.approved', 'vaccination_event', cur.event_id,
                        jsonb_build_object('revision', cur.revision_no, 'lot', cur.lot_id, 'child', cur.child_id), jsonb_build_object('revision', cur.revision_no + 1, 'lot', v_new_lot, 'child', v_new_child, 'kind', v_kind, 'stock', v_stock), coalesce(p_note, k.reason));
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('eventId', cur.event_id, 'revisionNo', cur.revision_no + 1, 'kind', v_kind, 'stock', v_stock));
end $$;


create function public.reject_correction(p_operation_key uuid, p_clinic_id uuid, p_case_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; k public.record_review_cases;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'correction.approve');
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  select * into k from public.record_review_cases where id = p_case_id and organization_id = v_org and clinic_id = p_clinic_id and kind = 'correction' for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'correction.reject', jsonb_build_object('c', p_clinic_id, 'case', p_case_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if k.status not in ('open','in_review') then raise exception 'already decided' using errcode = 'CV409'; end if;
  update public.record_review_cases set status = 'rejected', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(), resolution = jsonb_build_object('decision', 'rejected', 'reason', p_reason) where id = k.id;
  perform private.audit(v_org, 'correction.approve', 'correction.rejected', 'vaccination_event', k.vaccination_event_id, null, null, p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('caseId', k.id, 'status', 'rejected'));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Lot tracing (F15): which children received doses from a lot. Restricted, identifiable, audited.
-- ---------------------------------------------------------------------------------------------
create function public.trace_lot_use(p_clinic_id uuid, p_lot_id uuid) returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_res jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'inventory.approve');
  perform private.require_capability(p_clinic_id, 'child.read_clinical');
  select coalesce(jsonb_agg(jsonb_build_object('eventId', cr.event_id, 'childId', c.id, 'childName', c.display_name, 'recordNo', c.local_record_no, 'administeredOn', cr.administered_on,
      'status', cr.verification_status, 'eventStatus', cr.event_status, 'source', cr.source, 'revisionNo', cr.revision_no, 'clinicId', cr.clinic_id) order by cr.administered_on, c.display_name), '[]'::jsonb) into v_res
    from private.current_revisions cr join public.children c on c.id = private.canonical_child(cr.child_id)
   where cr.lot_id = p_lot_id and cr.organization_id = v_org;
  perform private.audit(v_org, 'inventory.approve', 'lot.traced', 'vaccine_lot', p_lot_id, null, jsonb_build_object('records', jsonb_array_length(v_res)), null);
  return v_res;
end $$;

do $$
declare f text;
begin
  foreach f in array array[
    'get_open_encounter(uuid,uuid)', 'record_administration(uuid,uuid,uuid,jsonb)', 'record_administration_exception(uuid,uuid,uuid,uuid,jsonb,text)',
    'resolve_administration_exception(uuid,uuid,uuid,text,text)', 'request_correction(uuid,uuid,uuid,text,jsonb,text)', 'approve_correction(uuid,uuid,uuid,text)',
    'reject_correction(uuid,uuid,uuid,text)', 'trace_lot_use(uuid,uuid)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function private.has_capability(uuid, text), private.clinics_with(text), private.session_ok(),
  private.my_guardian_ids(), private.guardian_can_read_child(uuid) to authenticated;
-- END 0015_administration.sql

-- =====================================================================================================================
-- BEGIN 0016_review_case_event.sql  sha256=6a74af68fa62c4e3aa831762a4ea461393d1c3edb71a5b509f8047a391937224
-- =====================================================================================================================
-- 0016 Review cases also expose the linked vaccination event (needed to decide corrections and exceptions from the queue).
create or replace function public.list_review_cases(p_clinic_id uuid, p_status text default 'open', p_limit integer default 50)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_res jsonb;
begin
  if not (private.has_capability(p_clinic_id, 'guardian.verify') or private.has_capability(p_clinic_id, 'review.resolve') or private.has_capability(p_clinic_id, 'correction.approve')
          or private.has_capability(p_clinic_id, 'inventory.approve')) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
  select coalesce(jsonb_agg(x order by x ->> 'createdAt'), '[]'::jsonb) into v_res from (
    select jsonb_build_object('caseId', k.id, 'kind', k.kind, 'status', k.status, 'reason', k.reason, 'createdAt', k.created_at, 'version', k.version,
             'evidence', k.evidence, 'childId', k.child_id, 'candidateChildId', k.candidate_child_id, 'eventId', k.vaccination_event_id, 'createdBy', k.created_by,
             'child', (select jsonb_build_object('displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob) from public.children c where c.id = k.child_id),
             'candidate', (select jsonb_build_object('displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob) from public.children c where c.id = k.candidate_child_id
                             and private.child_in_clinic(c.id, p_clinic_id)),
             'guardianName', (select g.full_name from public.guardians g where g.id = k.guardian_id)) x
      from public.record_review_cases k
     where k.clinic_id = p_clinic_id and k.status = p_status
     order by k.created_at limit least(greatest(coalesce(p_limit, 50), 1), 100)) s;
  return v_res;
end $$;
revoke all on function public.list_review_cases(uuid, text, integer) from public, anon, authenticated;
grant execute on function public.list_review_cases(uuid, text, integer) to authenticated;
-- END 0016_review_case_event.sql

-- =====================================================================================================================
-- BEGIN 0017_certificates_messages.sql  sha256=0a96272a905feb61bee4ba4a5ed5e71b43642e196fb507b5c12d90b5e53ab72f
-- =====================================================================================================================
-- 0017 Guardian certificates, in-app messages and the bounded outbox worker. Blueprint refs: BP20, BP22, F16, T23, T24.
--  * A certificate freezes an immutable snapshot of VERIFIED, ACTIVE clinical revisions; it is a separate lifecycle from the vaccination history.
--  * The document (PDF) is stored privately in the database (private.certificate_documents); reprints return the same bytes.
--  * The public verification token is random, only its hash is stored, and the public answer contains no name, birth date or dose list.
--  * A later correction of a fact the certificate shows flags it "under review"; the old snapshot is never rewritten.
--  * The outbox worker delivers in-app messages only. No SMS/e-mail provider is called anywhere (M09).

-- ---------------------------------------------------------------------------------------------
-- Certificates
-- ---------------------------------------------------------------------------------------------
create table private.certificate_counters (organization_id uuid primary key, next_value bigint not null default 1);

create function private.next_certificate_no(p_org uuid) returns text language plpgsql security definer set search_path = '' as $$
declare v bigint;
begin
  insert into private.certificate_counters (organization_id) values (p_org) on conflict (organization_id) do nothing;
  update private.certificate_counters set next_value = next_value + 1 where organization_id = p_org returning next_value - 1 into v;
  return 'CERT-' || lpad(v::text, 6, '0');
end $$;

create table public.certificates (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  child_id uuid not null,
  certificate_no text not null,
  snapshot jsonb not null,
  content_hash text not null,
  verification_token_hash text,
  status text not null default 'pending' check (status in ('pending','issued','revoked')),
  review_needed boolean not null default false,
  issued_at timestamptz,
  issuer_id uuid not null references public.profiles (id),
  replaces_id uuid references public.certificates (id),
  revoked_at timestamptz,
  revoked_by uuid references public.profiles (id),
  revocation_reason text,
  created_at timestamptz not null default now(),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  unique (organization_id, certificate_no),
  unique (verification_token_hash),
  unique (organization_id, id),
  check (status <> 'issued' or (issued_at is not null and verification_token_hash is not null)),
  check (status <> 'revoked' or (revoked_at is not null and revocation_reason is not null))
);
create index certificates_child_idx on public.certificates (child_id, status);
create unique index certificates_one_replacement_uq on public.certificates (replaces_id) where replaces_id is not null and status <> 'revoked';

create table public.certificate_items (
  certificate_id uuid not null references public.certificates (id),
  vaccination_revision_id uuid not null references public.vaccination_revisions (id),
  primary key (certificate_id, vaccination_revision_id)
);
create index certificate_items_revision_idx on public.certificate_items (vaccination_revision_id);

create table private.certificate_documents (
  certificate_id uuid primary key references public.certificates (id),
  pdf bytea not null check (length(pdf) between 100 and 2097152),
  sha256 text not null,
  stored_at timestamptz not null default now()
);

create function private.certificates_guard() returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_op = 'DELETE' then raise exception 'certificates cannot be deleted' using errcode = 'CV403'; end if;
  if new.snapshot is distinct from old.snapshot or new.content_hash is distinct from old.content_hash or new.child_id is distinct from old.child_id
     or new.clinic_id is distinct from old.clinic_id or new.certificate_no is distinct from old.certificate_no or new.issuer_id is distinct from old.issuer_id
     or new.replaces_id is distinct from old.replaces_id then
    raise exception 'an issued certificate snapshot is immutable' using errcode = 'CV403';
  end if;
  if old.status = 'revoked' and new.status <> 'revoked' then raise exception 'a revoked certificate stays revoked' using errcode = 'CV403'; end if;
  if old.status = 'issued' and new.status = 'pending' then raise exception 'an issued certificate cannot return to pending' using errcode = 'CV403'; end if;
  if old.status <> 'pending' and new.verification_token_hash is distinct from old.verification_token_hash then raise exception 'the verification token cannot change after issue' using errcode = 'CV403'; end if;
  return new;
end $$;
create trigger certificates_guard before update or delete on public.certificates for each row execute function private.certificates_guard();
create trigger certificates_no_truncate before truncate on public.certificates for each statement execute function private.forbid_change();
create trigger certificate_items_immutable before update or delete on public.certificate_items for each row execute function private.forbid_change();
create trigger certificate_items_no_truncate before truncate on public.certificate_items for each statement execute function private.forbid_change();
create trigger certificate_documents_immutable before update or delete on private.certificate_documents for each row execute function private.forbid_change();
create trigger certificate_documents_no_truncate before truncate on private.certificate_documents for each statement execute function private.forbid_change();

alter table public.certificates enable row level security;
alter table public.certificate_items enable row level security;
revoke all on public.certificates, public.certificate_items from anon, authenticated;

-- A correction to a fact the certificate shows (date, product, lot, child, voided) flags it for review; the snapshot is preserved (T23).
create function private.flag_certificates_for_review() returns trigger language plpgsql security definer set search_path = '' as $$
declare prev public.vaccination_revisions;
begin
  if new.revision_no < 2 then return new; end if;
  select * into prev from public.vaccination_revisions where event_id = new.event_id and revision_no = new.revision_no - 1;
  if prev.id is null then return new; end if;
  if prev.administered_on is distinct from new.administered_on or prev.product_id is distinct from new.product_id or prev.lot_id is distinct from new.lot_id
     or prev.child_id is distinct from new.child_id or prev.event_status is distinct from new.event_status or prev.verification_status is distinct from new.verification_status then
    update public.certificates c set review_needed = true
     where c.status = 'issued' and c.id in (select ci.certificate_id from public.certificate_items ci join public.vaccination_revisions r on r.id = ci.vaccination_revision_id where r.event_id = new.event_id);
  end if;
  return new;
end $$;
create trigger vaccination_revisions_flag_certificates after insert on public.vaccination_revisions for each row execute function private.flag_certificates_for_review();

create function private.certificate_json(c public.certificates, p_staff boolean) returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('id', c.id, 'certificateNo', c.certificate_no, 'status', c.status, 'reviewNeeded', c.review_needed, 'issuedAt', c.issued_at,
           'replacesNo', (select r.certificate_no from public.certificates r where r.id = c.replaces_id),
           'entryCount', jsonb_array_length(c.snapshot -> 'entries'),
           'hasDocument', exists (select 1 from private.certificate_documents d where d.certificate_id = c.id))
         || case when p_staff then jsonb_build_object('revokedAt', c.revoked_at, 'revocationReason', c.revocation_reason, 'childId', c.child_id) else '{}'::jsonb end
$$;

-- ---------------------------------------------------------------------------------------------
-- Commands
-- ---------------------------------------------------------------------------------------------
create function public.issue_certificate(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_replaces_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_prev jsonb; v_canon uuid; v_child public.children; v_clinic public.clinics; v_entries jsonb; v_snap jsonb; v_id uuid := gen_random_uuid(); v_no text; v_issuer text; old public.certificates;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'certificate.issue');
  v_prev := private.begin_command(v_org, p_operation_key, 'certificate.issue', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 'rp', p_replaces_id));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then
    perform private.audit(v_org, 'certificate.issue', 'certificate.issue', 'child', p_child_id, null, null, null, 'denied');
    return null;
  end if;
  if p_replaces_id is not null then
    select * into old from public.certificates where id = p_replaces_id and organization_id = v_org and child_id in (select private.child_ids_with_aliases(v_canon)) for update;
    if old.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
    if old.status = 'pending' then raise exception 'a certificate that is still pending cannot be replaced' using errcode = 'CV409'; end if;
    if exists (select 1 from public.certificates x where x.replaces_id = old.id and x.status <> 'revoked') then raise exception 'a replacement for this certificate is already in progress' using errcode = 'CV409'; end if;
  end if;
  select * into v_child from public.children where id = v_canon;
  select * into v_clinic from public.clinics where id = p_clinic_id;
  select coalesce(jsonb_agg(jsonb_build_object(
           'eventId', cr.event_id, 'revisionId', cr.id, 'revisionNo', cr.revision_no, 'administeredOn', cr.administered_on, 'datePrecision', cr.date_precision,
           'product', coalesce(p.name, cr.reported_product_text),
           'source', case when cr.source = 'clinic_administered' then 'clinic' else 'recorded_elsewhere' end,
           'lot', case when cr.source = 'clinic_administered' then coalesce(l.manufacturer_lot, cr.reported_lot) else null end,
           'provider', case when cr.source = 'clinic_administered' then null else cr.external_vaccinator end)
         order by cr.administered_on, cr.created_at), '[]'::jsonb) into v_entries
    from private.current_revisions cr left join public.vaccine_products p on p.id = cr.product_id left join public.vaccine_lots l on l.id = cr.lot_id
   where cr.child_id in (select private.child_ids_with_aliases(v_canon)) and cr.event_status = 'active' and cr.verification_status = 'verified' and cr.administered_on is not null;
  if jsonb_array_length(v_entries) = 0 then raise exception 'there are no verified vaccinations to certify yet' using errcode = 'CV422'; end if;
  select display_name into v_issuer from public.profiles where id = auth.uid();
  v_no := private.next_certificate_no(v_org);
  v_snap := jsonb_build_object('version', 1, 'certificateNo', v_no,
    'clinic', jsonb_build_object('name', v_clinic.name, 'address', v_clinic.address, 'contact', v_clinic.contact_text, 'timezone', v_clinic.timezone),
    'child', jsonb_build_object('displayName', v_child.display_name, 'dob', v_child.dob, 'datePrecision', v_child.birth_date_precision, 'recordNo', v_child.local_record_no),
    'entries', v_entries, 'issuedBy', coalesce(nullif(v_issuer, ''), 'Clinic staff'), 'preparedAt', now());
  insert into public.certificates (id, organization_id, clinic_id, child_id, certificate_no, snapshot, content_hash, issuer_id, replaces_id)
  values (v_id, v_org, p_clinic_id, v_canon, v_no, v_snap, encode(sha256(convert_to(v_snap::text, 'UTF8')), 'hex'), auth.uid(), p_replaces_id);
  insert into public.certificate_items (certificate_id, vaccination_revision_id)
  select v_id, (e ->> 'revisionId')::uuid from jsonb_array_elements(v_entries) e;
  perform private.audit(v_org, 'certificate.issue', 'certificate.prepared', 'certificate', v_id, null, jsonb_build_object('no', v_no, 'entries', jsonb_array_length(v_entries), 'replaces', p_replaces_id), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('certificateId', v_id, 'certificateNo', v_no, 'status', 'pending'));
end $$;

-- Rotates the verification token of a PENDING certificate and returns it once, with the frozen snapshot, so the app can render the document.
-- The token is never written anywhere in clear text (not in the receipt either), which is why this is a separate, non-idempotent call.
create function public.begin_certificate_render(p_certificate_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.certificates; v_token text;
begin
  select * into c from public.certificates where id = p_certificate_id;
  if c.id is null or not private.has_capability(c.clinic_id, 'certificate.issue') then return null; end if;
  if c.status <> 'pending' then raise exception 'this certificate has already been issued' using errcode = 'CV409'; end if;
  v_token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  update public.certificates set verification_token_hash = encode(sha256(convert_to(v_token, 'UTF8')), 'hex') where id = c.id;
  return jsonb_build_object('certificateId', c.id, 'certificateNo', c.certificate_no, 'token', v_token, 'snapshot', c.snapshot, 'contentHash', c.content_hash);
end $$;

create function public.store_certificate_pdf(p_operation_key uuid, p_certificate_id uuid, p_pdf_base64 text, p_sha256 text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.certificates; v_prev jsonb; v_bytes bytea; old public.certificates; v_guardian record;
begin
  select * into c from public.certificates where id = p_certificate_id for update;
  if c.id is null or not private.has_capability(c.clinic_id, 'certificate.issue') then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(c.organization_id, p_operation_key, 'certificate.store', jsonb_build_object('c', p_certificate_id, 'h', p_sha256));
  if v_prev is not null then return v_prev; end if;
  if c.status <> 'pending' then raise exception 'this certificate has already been issued' using errcode = 'CV409'; end if;
  if c.verification_token_hash is null then raise exception 'start rendering first' using errcode = 'CV409'; end if;
  if p_pdf_base64 is null or length(p_pdf_base64) > 2800000 then raise exception 'the document is too large' using errcode = 'CV422'; end if;
  begin v_bytes := decode(p_pdf_base64, 'base64'); exception when others then raise exception 'the document is not valid' using errcode = 'CV422'; end;
  if convert_from(substring(v_bytes from 1 for 5), 'SQL_ASCII') <> '%PDF-' then raise exception 'the document is not a PDF' using errcode = 'CV422'; end if;
  if encode(sha256(v_bytes), 'hex') <> lower(coalesce(p_sha256, '')) then raise exception 'the document did not match its checksum' using errcode = 'CV422'; end if;
  insert into private.certificate_documents (certificate_id, pdf, sha256) values (c.id, v_bytes, lower(p_sha256));
  update public.certificates set status = 'issued', issued_at = now() where id = c.id;
  if c.replaces_id is not null then
    select * into old from public.certificates where id = c.replaces_id for update;
    if old.status <> 'revoked' then
      update public.certificates set status = 'revoked', revoked_at = now(), revoked_by = auth.uid(), revocation_reason = 'Replaced by ' || c.certificate_no, review_needed = false where id = old.id;
      perform private.enqueue(c.organization_id, 'certificate.revoked', 'certificate', old.id, 'cert-revoked:' || old.id, jsonb_build_object('replacedBy', c.certificate_no));
    end if;
  end if;
  perform private.enqueue(c.organization_id, 'certificate.issued', 'certificate', c.id, 'cert-issued:' || c.id, '{}'::jsonb);
  perform private.audit(c.organization_id, 'certificate.issue', 'certificate.issued', 'certificate', c.id, jsonb_build_object('status', 'pending'), jsonb_build_object('status', 'issued', 'sha256', lower(p_sha256)), null);
  return private.finish_command(c.organization_id, p_operation_key, jsonb_build_object('certificateId', c.id, 'certificateNo', c.certificate_no, 'status', 'issued'));
end $$;

create function public.revoke_certificate(p_operation_key uuid, p_clinic_id uuid, p_certificate_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; c public.certificates;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'certificate.issue');
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'certificate.revoke', jsonb_build_object('c', p_clinic_id, 'cert', p_certificate_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into c from public.certificates where id = p_certificate_id and organization_id = v_org and clinic_id = p_clinic_id for update;
  if c.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if c.status = 'revoked' then raise exception 'already revoked' using errcode = 'CV409'; end if;
  if c.status = 'pending' then raise exception 'a pending certificate has nothing to revoke yet' using errcode = 'CV409'; end if;
  update public.certificates set status = 'revoked', revoked_at = now(), revoked_by = auth.uid(), revocation_reason = left(btrim(p_reason), 300), review_needed = false where id = c.id;
  perform private.enqueue(v_org, 'certificate.revoked', 'certificate', c.id, 'cert-revoked:' || c.id, '{}'::jsonb);
  perform private.audit(v_org, 'certificate.issue', 'certificate.revoked', 'certificate', c.id, jsonb_build_object('status', c.status), jsonb_build_object('status', 'revoked'), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('certificateId', c.id, 'status', 'revoked'));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Reads
-- ---------------------------------------------------------------------------------------------
create function public.list_child_certificates(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  perform private.require_capability(p_clinic_id, 'certificate.issue');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  return (select coalesce(jsonb_agg(private.certificate_json(c, true) order by c.created_at desc), '[]'::jsonb) from public.certificates c where c.child_id in (select private.child_ids_with_aliases(v_canon)) and c.clinic_id = p_clinic_id);
end $$;

create function public.guardian_list_certificates(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then return null; end if;
  return (select coalesce(jsonb_agg(private.certificate_json(c, false) order by c.created_at desc), '[]'::jsonb) from public.certificates c where c.child_id in (select private.child_ids_with_aliases(v_canon)) and c.status in ('issued','revoked'));
end $$;

-- Same stored bytes every time (BP20 "reprints download the same issued document"). Guardians get only certificates that are currently issued.
create function public.get_certificate_pdf(p_certificate_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.certificates; d private.certificate_documents; v_staff boolean; v_guardian boolean;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select * into c from public.certificates where id = p_certificate_id;
  if c.id is null then return null; end if;
  v_staff := private.has_capability(c.clinic_id, 'certificate.issue');
  v_guardian := private.guardian_has_full_access(private.canonical_child(c.child_id)) and c.status = 'issued';
  if not (v_staff or v_guardian) then return null; end if;
  select * into d from private.certificate_documents where certificate_id = c.id;
  if d.certificate_id is null then return null; end if;
  perform private.audit(c.organization_id, case when v_staff then 'certificate.issue' else 'guardian' end, 'certificate.downloaded', 'certificate', c.id, null, null, null);
  return jsonb_build_object('certificateNo', c.certificate_no, 'status', c.status, 'sha256', d.sha256, 'pdfBase64', encode(d.pdf, 'base64'));
end $$;

-- Public: minimal authenticity result. Unknown, malformed and still-pending tokens all look the same (NULL -> not found).
create function public.verify_certificate(p_token text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.certificates; v_clinic text;
begin
  if p_token is null or p_token !~ '^[0-9a-f]{64}$' then return null; end if;
  select * into c from public.certificates where verification_token_hash = encode(sha256(convert_to(p_token, 'UTF8')), 'hex') and status in ('issued','revoked');
  if c.id is null then return null; end if;
  select name into v_clinic from public.clinics where id = c.clinic_id;
  return jsonb_build_object('status', case when c.status = 'revoked' then 'revoked' when c.review_needed then 'under_review' else 'valid' end,
                            'certificateNo', c.certificate_no, 'clinicName', v_clinic, 'issuedOn', (c.issued_at at time zone (select timezone from public.clinics where id = c.clinic_id))::date);
end $$;

-- ---------------------------------------------------------------------------------------------
-- In-app messages
-- ---------------------------------------------------------------------------------------------
create table public.messages (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  recipient_profile_id uuid not null references public.profiles (id),
  child_id uuid,
  kind text not null check (length(kind) between 1 and 60),
  title text not null check (length(title) between 1 and 120),
  body text not null check (length(body) between 1 and 600),
  dedupe_key text not null,
  created_at timestamptz not null default now(),
  read_at timestamptz,
  unique (recipient_profile_id, dedupe_key)
);
create index messages_inbox_idx on public.messages (recipient_profile_id, created_at desc);
alter table public.messages enable row level security;
revoke all on public.messages from anon, authenticated;

create function public.my_messages(p_limit integer default 50) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.session_ok() then return null; end if;
  return jsonb_build_object(
    'unread', (select count(*) from public.messages where recipient_profile_id = auth.uid() and read_at is null),
    'items', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'kind', x.kind, 'title', x.title, 'body', x.body, 'childId', x.child_id, 'createdAt', x.created_at, 'read', x.read_at is not null) order by x.created_at desc), '[]'::jsonb)
                from (select * from public.messages where recipient_profile_id = auth.uid() order by created_at desc limit least(greatest(coalesce(p_limit, 50), 1), 100)) x));
end $$;

create function public.mark_messages_read(p_ids uuid[] default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.session_ok() then return null; end if;
  update public.messages set read_at = now() where recipient_profile_id = auth.uid() and read_at is null and (p_ids is null or id = any (p_ids));
  get diagnostics v_n = row_count;
  return jsonb_build_object('marked', v_n);
end $$;

-- ---------------------------------------------------------------------------------------------
-- Outbox worker (private). Bounded, retrying, safe to run from several workers at once (SKIP LOCKED).
-- ---------------------------------------------------------------------------------------------
create function private.notify_guardians(p_org uuid, p_child uuid, p_kind text, p_title text, p_body text, p_dedupe text) returns integer
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  insert into public.messages (organization_id, recipient_profile_id, child_id, kind, title, body, dedupe_key)
  select distinct p_org, g.profile_id, private.canonical_child(p_child), p_kind, p_title, p_body, p_dedupe
    from public.guardian_child_relationships r join public.guardians g on g.id = r.guardian_id
   where r.child_id = private.canonical_child(p_child) and r.status = 'active' and r.access_scope = 'full' and (r.ends_at is null or r.ends_at > now())
     and g.profile_id is not null and g.deleted_at is null
  on conflict (recipient_profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- Returns 'done' or 'cancelled'; raising means "retry later". Message wording is fixed here and contains no clinical guidance.
create function private.handle_outbox_job(j private.outbox_jobs) returns text
language plpgsql security definer set search_path = '' as $$
declare a public.appointments; s public.clinic_sessions; c public.certificates; v_child public.children; v_clinic public.clinics; v_when text; v_key text;
begin
  if j.job_type in ('appointment.confirmation','appointment.cancellation','appointment.session_cancelled') then
    select * into a from public.appointments where id = j.aggregate_id;
    if a.id is null then return 'cancelled'; end if;
    select * into s from public.clinic_sessions where id = a.session_id;
    select * into v_clinic from public.clinics where id = s.clinic_id;
    select * into v_child from public.children where id = a.child_id;
    v_when := to_char(s.starts_at at time zone v_clinic.timezone, 'FMDay, FMDD FMMonth YYYY "at" FMHH12:MI AM');
    if j.job_type = 'appointment.confirmation' then
      if a.status not in ('confirmed','checked_in','fulfilled') then return 'cancelled'; end if;
      perform private.notify_guardians(j.organization_id, a.child_id, 'appointment', case when j.payload ? 'rescheduledFrom' then 'Visit rescheduled' else 'Visit booked' end,
        format('%s: %s at %s.', v_child.display_name, v_when, v_clinic.name), j.dedupe_key);
    elsif j.job_type = 'appointment.cancellation' then
      perform private.notify_guardians(j.organization_id, a.child_id, 'appointment', 'Visit cancelled', format('The visit for %s on %s was cancelled.', v_child.display_name, v_when), j.dedupe_key);
    else
      perform private.notify_guardians(j.organization_id, a.child_id, 'appointment', 'Clinic session cancelled',
        format('The clinic session on %s was cancelled, so the visit for %s will not take place. Please book another time.', v_when, v_child.display_name), j.dedupe_key);
    end if;
    return 'done';
  elsif j.job_type = 'vaccination.recorded' then
    select * into v_child from public.children where id = (j.payload ->> 'childId')::uuid;
    if v_child.id is null then return 'cancelled'; end if;
    perform private.notify_guardians(j.organization_id, v_child.id, 'record', 'Vaccination recorded', format('A vaccination was recorded for %s. Open the record to see what was given.', v_child.display_name), j.dedupe_key);
    return 'done';
  elsif j.job_type in ('certificate.issued','certificate.revoked') then
    select * into c from public.certificates where id = j.aggregate_id;
    if c.id is null then return 'cancelled'; end if;
    select * into v_child from public.children where id = c.child_id;
    if j.job_type = 'certificate.issued' then
      perform private.notify_guardians(j.organization_id, c.child_id, 'certificate', 'Certificate ready', format('Certificate %s for %s is ready to download.', c.certificate_no, v_child.display_name), j.dedupe_key);
    else
      perform private.notify_guardians(j.organization_id, c.child_id, 'certificate', 'Certificate no longer valid',
        format('Certificate %s for %s is no longer valid.%s Please ask the clinic about a new one.', c.certificate_no, v_child.display_name, case when j.payload ? 'replacedBy' then ' It was replaced by ' || (j.payload ->> 'replacedBy') || '.' else '' end), j.dedupe_key);
    end if;
    return 'done';
  elsif j.job_type = 'certificate.review' then
    -- Notify only when a certificate that shows the corrected record has actually been flagged.
    for c in select x.* from public.certificates x where x.status = 'issued' and x.review_needed and x.id in
             (select ci.certificate_id from public.certificate_items ci join public.vaccination_revisions r on r.id = ci.vaccination_revision_id where r.event_id = j.aggregate_id) loop
      select * into v_child from public.children where id = c.child_id;
      perform private.notify_guardians(j.organization_id, c.child_id, 'certificate', 'Certificate under review',
        format('A record shown on certificate %s for %s was corrected. The clinic is reviewing the certificate.', c.certificate_no, v_child.display_name), 'cert-review:' || c.id || ':' || j.dedupe_key);
    end loop;
    return 'done';
  end if;
  raise exception 'no handler for job type' using errcode = 'CV422';
end $$;

create function private.process_outbox(p_limit integer default 20) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare j private.outbox_jobs; v_res text; v_done integer := 0; v_cancelled integer := 0; v_retry integer := 0; v_failed integer := 0; v_code text;
begin
  for j in select * from private.outbox_jobs
            where (status = 'queued' and available_at <= now()) or (status = 'processing' and locked_until < now())
            order by available_at, created_at limit least(greatest(coalesce(p_limit, 20), 1), 200) for update skip locked loop
    begin
      v_res := private.handle_outbox_job(j);
      update private.outbox_jobs set status = case when v_res = 'cancelled' then 'cancelled' else 'done' end, attempt_count = attempt_count + 1, locked_until = null, last_error_code = null, updated_at = now() where id = j.id;
      if v_res = 'cancelled' then v_cancelled := v_cancelled + 1; else v_done := v_done + 1; end if;
    exception when others then
      get stacked diagnostics v_code = returned_sqlstate;
      if j.attempt_count + 1 >= 5 or v_code = 'CV422' then
        update private.outbox_jobs set status = 'failed', attempt_count = attempt_count + 1, last_error_code = v_code, locked_until = null, updated_at = now() where id = j.id;
        v_failed := v_failed + 1;
      else
        update private.outbox_jobs set status = 'queued', attempt_count = attempt_count + 1, last_error_code = v_code, locked_until = null,
               available_at = now() + make_interval(mins => power(2, j.attempt_count)::int), updated_at = now() where id = j.id;
        v_retry := v_retry + 1;
      end if;
    end;
  end loop;
  return jsonb_build_object('done', v_done, 'cancelled', v_cancelled, 'retry', v_retry, 'failed', v_failed);
end $$;

-- ---------------------------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------------------------
revoke all on function private.next_certificate_no(uuid), private.certificates_guard(), private.flag_certificates_for_review(), private.certificate_json(public.certificates, boolean),
  private.notify_guardians(uuid, uuid, text, text, text, text), private.handle_outbox_job(private.outbox_jobs), private.process_outbox(integer) from public, anon, authenticated;
do $$
declare f text;
begin
  foreach f in array array[
    'issue_certificate(uuid,uuid,uuid,uuid)', 'begin_certificate_render(uuid)', 'store_certificate_pdf(uuid,uuid,text,text)', 'revoke_certificate(uuid,uuid,uuid,text)',
    'list_child_certificates(uuid,uuid)', 'guardian_list_certificates(uuid)', 'get_certificate_pdf(uuid)', 'my_messages(integer)', 'mark_messages_read(uuid[])'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  revoke all on function public.verify_certificate(text) from public, anon, authenticated;
  grant execute on function public.verify_certificate(text) to anon, authenticated;
end $$;
-- END 0017_certificates_messages.sql

-- =====================================================================================================================
-- BEGIN 0018_reports.sql  sha256=d37e55f7d0d5c5edd5f8a5d53e98102127bac376d6bb12480c69714ebf807717
-- =====================================================================================================================
-- 0018 Operational reports and paper reconciliation. Blueprint refs: F33, BP27 (exports), BP31, M08.
--  * Reports are clinic-scoped aggregates computed from the same facts the care screens use (current revisions, ledger, queue).
--    They never take numbers from a cache and never include names or other identifiers.
--  * Every report returns its metric definitions and a definitions version so a printed figure can be interpreted later.
--  * Exports (CSV, produced by the app) apply small-cell suppression using a privacy-owner threshold setting
--    (default 0 = off; the right value Requires external validation) and are audited.
--  * Paper reconciliation compares paper-log tallies entered later with what the system holds; it never edits either side.

insert into private.settings(key, value) values ('report_small_cell_threshold', '0'::jsonb) on conflict (key) do nothing;

create table public.paper_tallies (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  service_date date not null,
  product_id uuid not null,
  paper_count integer not null check (paper_count between 0 and 10000),
  note text,
  entered_by uuid not null references public.profiles (id),
  entered_at timestamptz not null default now(),
  operation_id uuid not null unique,
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, product_id) references public.vaccine_products (organization_id, id)
);
create index paper_tallies_lookup_idx on public.paper_tallies (clinic_id, service_date, product_id, entered_at desc);
create trigger paper_tallies_immutable before update or delete on public.paper_tallies for each row execute function private.forbid_change();
create trigger paper_tallies_no_truncate before truncate on public.paper_tallies for each statement execute function private.forbid_change();
alter table public.paper_tallies enable row level security;
revoke all on public.paper_tallies from anon, authenticated;

create function private.report_definitions() returns jsonb language sql immutable set search_path = '' as $$
  select jsonb_build_object('version', 'r1', 'terms', jsonb_build_object(
    'booked', 'Appointments in a session on that date that are confirmed, checked in or fulfilled.',
    'cancelled', 'Appointments in a session on that date that were cancelled.',
    'noShow', 'Appointments in a session on that date marked no-show by staff.',
    'arrivals', 'Queue tickets issued that date, excluding tickets cancelled at the desk.',
    'walkIns', 'Arrivals without an appointment.',
    'completed', 'Arrivals whose visit ended with service completed.',
    'deferred', 'Arrivals whose visit ended deferred by a clinician.',
    'left', 'Arrivals marked as having left before service.',
    'vaccinationsGiven', 'Vaccinations given at this clinic on that date, counted once per event using its latest revision; voided events are excluded. One dose = one event.',
    'certificatesIssued', 'Certificates that reached the issued state on that date (local clinic date).',
    'received', 'Units received into stock in the period (ledger receipts).',
    'issued', 'Units issued for administration in the period, net of reversals.',
    'wastage', 'Units recorded as wastage in the period.',
    'adjustments', 'Net units from approved count adjustments in the period.',
    'onHand', 'Units on hand now according to the stock projection.',
    'ledgerTotal', 'Sum of every ledger movement for the lot at this clinic. It must equal onHand.',
    'paperCount', 'Doses written in the paper log for that date and product, as entered later by staff (latest entry counts).',
    'systemCount', 'Vaccinations given in the system for that date and product (see vaccinationsGiven).',
    'difference', 'systemCount minus paperCount. Zero means the two agree; any other value needs a staff explanation, not an edit.'))
$$;

create function private.report_range(p_clinic uuid, p_from date, p_to date) returns void language plpgsql stable security definer set search_path = '' as $$
begin
  if p_from is null or p_to is null or p_to < p_from then raise exception 'choose a start date that is not after the end date' using errcode = 'CV422'; end if;
  if p_to - p_from > 365 then raise exception 'a report can cover at most 366 days' using errcode = 'CV422'; end if;
end $$;

-- Small-cell rule for exports: counts between 1 and threshold-1 are withheld.
create function private.export_cell(p_n bigint, p_export boolean) returns bigint language sql stable security definer set search_path = '' as $$
  select case when p_export and p_n > 0 and p_n < coalesce((select (value)::text::int from private.settings where key = 'report_small_cell_threshold'), 0) then null else p_n end
$$;

create function private.report_org(p_clinic uuid, p_cap text default 'report.run') returns uuid language plpgsql stable security definer set search_path = '' as $$
declare v_org uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic, p_cap);
  return v_org;
end $$;

create function public.report_daily_activity(p_clinic_id uuid, p_from date, p_to date, p_export boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id); v_tz text; v_rows jsonb; v_supp boolean;
begin
  perform private.report_range(p_clinic_id, p_from, p_to);
  select timezone into v_tz from public.clinics where id = p_clinic_id;
  with days as (select d::date d from generate_series(p_from, p_to, interval '1 day') d),
  appt as (select s.service_date d,
             count(*) filter (where a.status in ('confirmed','checked_in','fulfilled')) booked,
             count(*) filter (where a.status = 'cancelled') cancelled,
             count(*) filter (where a.status = 'no_show') no_show
             from public.appointments a join public.clinic_sessions s on s.id = a.session_id
            where s.clinic_id = p_clinic_id and s.service_date between p_from and p_to group by 1),
  q as (select service_date d,
          count(*) filter (where status <> 'cancelled') arrivals,
          count(*) filter (where walk_in and status <> 'cancelled') walk_ins,
          count(*) filter (where status = 'completed') completed,
          count(*) filter (where status = 'deferred') deferred,
          count(*) filter (where status = 'left') left_n
          from public.queue_entries where clinic_id = p_clinic_id and service_date between p_from and p_to group by 1),
  v as (select cr.administered_on d, count(*) n from private.current_revisions cr
         where cr.clinic_id = p_clinic_id and cr.source = 'clinic_administered' and cr.event_status = 'active' and cr.administered_on between p_from and p_to group by 1),
  c as (select (ce.issued_at at time zone v_tz)::date d, count(*) n from public.certificates ce
         where ce.clinic_id = p_clinic_id and ce.issued_at is not null and (ce.issued_at at time zone v_tz)::date between p_from and p_to group by 1)
  select jsonb_agg(jsonb_build_object('date', days.d, 'booked', coalesce(appt.booked, 0), 'cancelled', coalesce(appt.cancelled, 0), 'noShow', coalesce(appt.no_show, 0),
           'arrivals', coalesce(q.arrivals, 0), 'walkIns', coalesce(q.walk_ins, 0), 'completed', coalesce(q.completed, 0), 'deferred', coalesce(q.deferred, 0), 'left', coalesce(q.left_n, 0),
           'vaccinationsGiven', private.export_cell(coalesce(v.n, 0), p_export), 'certificatesIssued', coalesce(c.n, 0)) order by days.d)
    into v_rows from days left join appt on appt.d = days.d left join q on q.d = days.d left join v on v.d = days.d left join c on c.d = days.d;
  v_supp := exists (select 1 from jsonb_array_elements(v_rows) r where r -> 'vaccinationsGiven' = 'null'::jsonb);
  if not p_export then perform private.audit(v_org, 'report.run', 'report.viewed', 'clinic', p_clinic_id, null, jsonb_build_object('report', 'daily_activity', 'from', p_from, 'to', p_to), null); end if;
  return jsonb_build_object('report', 'daily_activity', 'from', p_from, 'to', p_to, 'asOf', now(), 'suppressed', v_supp, 'definitions', private.report_definitions(), 'rows', coalesce(v_rows, '[]'::jsonb),
    'totals', case when v_supp then null else (select jsonb_build_object(
       'booked', sum((r ->> 'booked')::int), 'cancelled', sum((r ->> 'cancelled')::int), 'noShow', sum((r ->> 'noShow')::int), 'arrivals', sum((r ->> 'arrivals')::int), 'walkIns', sum((r ->> 'walkIns')::int),
       'completed', sum((r ->> 'completed')::int), 'deferred', sum((r ->> 'deferred')::int), 'left', sum((r ->> 'left')::int),
       'vaccinationsGiven', sum((r ->> 'vaccinationsGiven')::int), 'certificatesIssued', sum((r ->> 'certificatesIssued')::int)) from jsonb_array_elements(v_rows) r) end);
end $$;

create function public.report_vaccinations_by_product(p_clinic_id uuid, p_from date, p_to date, p_export boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id); v_rows jsonb; v_supp boolean;
begin
  perform private.report_range(p_clinic_id, p_from, p_to);
  select coalesce(jsonb_agg(jsonb_build_object('productCode', x.code, 'product', x.name, 'count', private.export_cell(x.n, p_export)) order by x.name), '[]'::jsonb) into v_rows from (
    select p.code, p.name, count(*) n from private.current_revisions cr join public.vaccine_products p on p.id = cr.product_id
     where cr.clinic_id = p_clinic_id and cr.source = 'clinic_administered' and cr.event_status = 'active' and cr.administered_on between p_from and p_to group by p.code, p.name) x;
  v_supp := exists (select 1 from jsonb_array_elements(v_rows) r where r -> 'count' = 'null'::jsonb);
  if not p_export then perform private.audit(v_org, 'report.run', 'report.viewed', 'clinic', p_clinic_id, null, jsonb_build_object('report', 'vaccinations_by_product', 'from', p_from, 'to', p_to), null); end if;
  return jsonb_build_object('report', 'vaccinations_by_product', 'from', p_from, 'to', p_to, 'asOf', now(), 'suppressed', v_supp, 'definitions', private.report_definitions(), 'rows', v_rows,
    'total', case when v_supp then null else (select coalesce(sum((r ->> 'count')::int), 0) from jsonb_array_elements(v_rows) r) end);
end $$;

create function public.report_stock_summary(p_clinic_id uuid, p_from date, p_to date, p_export boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id); v_tz text; v_rows jsonb;
begin
  perform private.report_range(p_clinic_id, p_from, p_to);
  select timezone into v_tz from public.clinics where id = p_clinic_id;
  select coalesce(jsonb_agg(jsonb_build_object('productCode', p.code, 'product', p.name, 'lot', l.manufacturer_lot, 'expiresOn', l.expires_on, 'disposition', l.global_disposition,
           'received', x.received, 'issued', x.issued, 'wastage', x.wastage, 'adjustments', x.adjustments, 'onHand', x.on_hand, 'ledgerTotal', x.ledger_total,
           'reconciles', x.on_hand = x.ledger_total) order by p.name, l.expires_on, l.manufacturer_lot), '[]'::jsonb) into v_rows
    from (select m.lot_id,
            coalesce(sum(m.quantity_delta) filter (where t.type = 'receipt' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) received,
            -coalesce(sum(m.quantity_delta) filter (where t.type in ('issue_administration') and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0)
              - coalesce(sum(m.quantity_delta) filter (where t.type = 'reversal' and t.reason like 'correction:%' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) issued,
            -coalesce(sum(m.quantity_delta) filter (where t.type = 'wastage' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) wastage,
            coalesce(sum(m.quantity_delta) filter (where t.type = 'adjustment' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) adjustments,
            coalesce((select sum(b.on_hand) from public.stock_balances b join public.stock_locations s on s.id = b.location_id where b.lot_id = m.lot_id and s.clinic_id = p_clinic_id), 0) on_hand,
            sum(m.quantity_delta) ledger_total
            from public.stock_movements m join public.stock_transactions t on t.id = m.transaction_id
           where t.clinic_id = p_clinic_id group by m.lot_id) x
    join public.vaccine_lots l on l.id = x.lot_id join public.vaccine_products p on p.id = l.product_id;
  if not p_export then perform private.audit(v_org, 'report.run', 'report.viewed', 'clinic', p_clinic_id, null, jsonb_build_object('report', 'stock_summary', 'from', p_from, 'to', p_to), null); end if;
  return jsonb_build_object('report', 'stock_summary', 'from', p_from, 'to', p_to, 'asOf', now(), 'suppressed', false, 'definitions', private.report_definitions(), 'rows', v_rows);
end $$;

create function public.report_backlog(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id);
begin
  perform private.audit(v_org, 'report.run', 'report.viewed', 'clinic', p_clinic_id, null, jsonb_build_object('report', 'backlog'), null);
  return jsonb_build_object('report', 'backlog', 'asOf', now(), 'definitions', jsonb_build_object('version', 'r1', 'terms', jsonb_build_object(
      'openReviewCases', 'Review cases still open or in review, by type.', 'pendingOutsideDoses', 'Doses reported as given elsewhere that staff have not yet verified or rejected.',
      'provisionalChildren', 'Children enrolled here whose identity has not been confirmed.', 'pendingGuardianLinks', 'Guardian links waiting for in-person verification.',
      'pendingCertificates', 'Certificates prepared but not yet issued (document not stored).', 'failedMessages', 'Notification jobs that failed permanently.')),
    'openReviewCases', (select coalesce(jsonb_object_agg(kind, n), '{}'::jsonb) from (select kind, count(*) n from public.record_review_cases where clinic_id = p_clinic_id and status in ('open','in_review') group by kind) k),
    'pendingOutsideDoses', (select count(*) from private.current_revisions cr where cr.verification_status = 'pending_verification' and cr.event_status = 'active'
                              and private.child_in_clinic(private.canonical_child(cr.child_id), p_clinic_id)),
    'provisionalChildren', (select count(*) from public.children c join public.child_clinic_enrollments e on e.child_id = c.id and e.clinic_id = p_clinic_id and e.status in ('pending','active') where c.record_status = 'provisional' and c.merged_into_id is null),
    'pendingGuardianLinks', (select count(*) from public.guardian_child_relationships r join public.child_clinic_enrollments e on e.child_id = r.child_id and e.clinic_id = p_clinic_id and e.status in ('pending','active') where r.status = 'provisional'),
    'pendingCertificates', (select count(*) from public.certificates where clinic_id = p_clinic_id and status = 'pending'),
    'failedMessages', (select count(*) from private.outbox_jobs where organization_id = v_org and status = 'failed'));
end $$;

-- Paper reconciliation ---------------------------------------------------------------------------------------------
create function public.record_paper_tally(p_operation_key uuid, p_clinic_id uuid, p_service_date date, p_product_id uuid, p_paper_count integer, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not (private.has_capability(p_clinic_id, 'report.run') or private.has_capability(p_clinic_id, 'vaccination.record')) then raise exception 'forbidden' using errcode = 'CV403'; end if;
  if p_service_date is null or p_service_date > private.local_today(p_clinic_id) then raise exception 'the paper log date cannot be in the future' using errcode = 'CV422'; end if;
  if p_paper_count is null or p_paper_count < 0 or p_paper_count > 10000 then raise exception 'enter the number of doses written on the paper log' using errcode = 'CV422'; end if;
  if not exists (select 1 from public.vaccine_products where id = p_product_id and organization_id = v_org) then raise exception 'unknown product' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'paper.tally', jsonb_build_object('c', p_clinic_id, 'd', p_service_date, 'p', p_product_id, 'n', p_paper_count, 'note', p_note));
  if v_prev is not null then return v_prev; end if;
  insert into public.paper_tallies (organization_id, clinic_id, service_date, product_id, paper_count, note, entered_by, operation_id)
  values (v_org, p_clinic_id, p_service_date, p_product_id, p_paper_count, left(nullif(btrim(p_note), ''), 300), auth.uid(), p_operation_key);
  perform private.audit(v_org, 'report.run', 'paper.tally', 'clinic', p_clinic_id, null, jsonb_build_object('date', p_service_date, 'product', p_product_id, 'count', p_paper_count), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('recorded', true));
end $$;

create function public.report_paper_reconciliation(p_clinic_id uuid, p_from date, p_to date, p_export boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_rows jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not (private.has_capability(p_clinic_id, 'report.run') or private.has_capability(p_clinic_id, 'vaccination.record')) then raise exception 'forbidden' using errcode = 'CV403'; end if;
  perform private.report_range(p_clinic_id, p_from, p_to);
  select coalesce(jsonb_agg(jsonb_build_object('date', k.d, 'productCode', p.code, 'product', p.name, 'paperCount', k.paper, 'systemCount', k.sys, 'difference', k.sys - coalesce(k.paper, 0), 'note', k.note,
           'status', case when k.paper is null then 'no_paper_tally' when k.sys = k.paper then 'matches' when k.sys > k.paper then 'system_higher' else 'paper_higher' end) order by k.d, p.name), '[]'::jsonb) into v_rows
  from (
    select coalesce(s.d, t.d) d, coalesce(s.product_id, t.product_id) product_id, coalesce(s.n, 0) sys, t.paper_count paper, t.note
      from (select cr.administered_on d, cr.product_id, count(*) n from private.current_revisions cr
             where cr.clinic_id = p_clinic_id and cr.source = 'clinic_administered' and cr.event_status = 'active' and cr.administered_on between p_from and p_to group by 1, 2) s
      full join (select distinct on (service_date, product_id) service_date d, product_id, paper_count, note from public.paper_tallies
                  where clinic_id = p_clinic_id and service_date between p_from and p_to order by service_date, product_id, entered_at desc) t
        on t.d = s.d and t.product_id = s.product_id) k
  join public.vaccine_products p on p.id = k.product_id;
  if not p_export then perform private.audit(v_org, 'report.run', 'report.viewed', 'clinic', p_clinic_id, null, jsonb_build_object('report', 'paper_reconciliation', 'from', p_from, 'to', p_to), null); end if;
  return jsonb_build_object('report', 'paper_reconciliation', 'from', p_from, 'to', p_to, 'asOf', now(), 'suppressed', false, 'definitions', private.report_definitions(), 'rows', v_rows,
    'unresolved', (select count(*) from jsonb_array_elements(v_rows) r where r ->> 'status' <> 'matches'));
end $$;

-- Exports leave the system, so each one is audited (who, which report, which period) and uses the small-cell rule.
create function public.record_report_export(p_operation_key uuid, p_clinic_id uuid, p_report text, p_from date, p_to date) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id); v_prev jsonb;
begin
  if p_report not in ('daily_activity','vaccinations_by_product','stock_summary','paper_reconciliation') then raise exception 'unknown report' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'report.export', jsonb_build_object('c', p_clinic_id, 'r', p_report, 'f', p_from, 't', p_to));
  if v_prev is not null then return v_prev; end if;
  perform private.audit(v_org, 'report.run', 'report.exported', 'clinic', p_clinic_id, null, jsonb_build_object('report', p_report, 'from', p_from, 'to', p_to, 'smallCellThreshold', (select value from private.settings where key = 'report_small_cell_threshold')), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('exported', true));
end $$;

revoke all on function private.report_definitions(), private.report_range(uuid, date, date), private.export_cell(bigint, boolean), private.report_org(uuid, text) from public, anon, authenticated;
do $$
declare f text;
begin
  foreach f in array array[
    'report_daily_activity(uuid,date,date,boolean)', 'report_vaccinations_by_product(uuid,date,date,boolean)', 'report_stock_summary(uuid,date,date,boolean)', 'report_backlog(uuid)',
    'record_paper_tally(uuid,uuid,date,uuid,integer,text)', 'report_paper_reconciliation(uuid,date,date,boolean)', 'record_report_export(uuid,uuid,text,date,date)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
-- END 0018_reports.sql

-- =====================================================================================================================
-- BEGIN 0019_transfers_temperature.sql  sha256=99eb6624207d0b00dbe609039a5f9f0ca185aaba28ca0fe363b947b9132dd632
-- =====================================================================================================================
-- 0019 Stock transfers with in-transit custody, and temperature logs. Blueprint refs: F13, F14, BP19, M09 (inventory intelligence).
--  * A transfer is two ledger transactions: SEND moves stock from a usable location into the sender's "In transit" location
--    (nothing disappears from the books while it travels); RECEIVE moves it from transit into the receiver's location.
--  * A short delivery leaves the missing units visibly in transit and opens a review case; a person then decides "write off" or "return".
--  * Cold-chain limits are POLICY: none exist until an approver records them with a policy reference. Readings are always kept; they are
--    only judged against limits that someone approved. Nothing is quarantined automatically: an excursion is flagged for a person to decide.

-- ---------------------------------------------------------------------------------------------
-- Report correction: a transfer spans two clinics, so the ledger for a clinic is what moved in ITS locations.
-- ---------------------------------------------------------------------------------------------
create or replace function public.report_stock_summary(p_clinic_id uuid, p_from date, p_to date, p_export boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id); v_tz text; v_rows jsonb;
begin
  perform private.report_range(p_clinic_id, p_from, p_to);
  select timezone into v_tz from public.clinics where id = p_clinic_id;
  select coalesce(jsonb_agg(jsonb_build_object('productCode', p.code, 'product', p.name, 'lot', l.manufacturer_lot, 'expiresOn', l.expires_on, 'disposition', l.global_disposition,
           'received', x.received, 'issued', x.issued, 'wastage', x.wastage, 'adjustments', x.adjustments, 'onHand', x.on_hand, 'ledgerTotal', x.ledger_total,
           'reconciles', x.on_hand = x.ledger_total) order by p.name, l.expires_on, l.manufacturer_lot), '[]'::jsonb) into v_rows
    from (select m.lot_id,
            coalesce(sum(m.quantity_delta) filter (where t.type = 'receipt' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) received,
            -coalesce(sum(m.quantity_delta) filter (where t.type in ('issue_administration') and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0)
              - coalesce(sum(m.quantity_delta) filter (where t.type = 'reversal' and t.reason like 'correction:%' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) issued,
            -coalesce(sum(m.quantity_delta) filter (where t.type = 'wastage' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) wastage,
            coalesce(sum(m.quantity_delta) filter (where t.type = 'adjustment' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) adjustments,
            coalesce((select sum(b.on_hand) from public.stock_balances b join public.stock_locations s2 on s2.id = b.location_id where b.lot_id = m.lot_id and s2.clinic_id = p_clinic_id), 0) on_hand,
            sum(m.quantity_delta) ledger_total
            from public.stock_movements m join public.stock_transactions t on t.id = m.transaction_id join public.stock_locations s on s.id = m.location_id
           where s.clinic_id = p_clinic_id group by m.lot_id) x
    join public.vaccine_lots l on l.id = x.lot_id join public.vaccine_products p on p.id = l.product_id;
  if not p_export then perform private.audit(v_org, 'report.run', 'report.viewed', 'clinic', p_clinic_id, null, jsonb_build_object('report', 'stock_summary', 'from', p_from, 'to', p_to), null); end if;
  return jsonb_build_object('report', 'stock_summary', 'from', p_from, 'to', p_to, 'asOf', now(), 'suppressed', false, 'definitions', private.report_definitions(), 'rows', v_rows);
end $$;

-- ---------------------------------------------------------------------------------------------
-- Transfers
-- ---------------------------------------------------------------------------------------------
create table public.stock_transfers (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  from_clinic_id uuid not null,
  to_clinic_id uuid not null,
  lot_id uuid not null,
  from_location_id uuid not null references public.stock_locations (id),
  transit_location_id uuid not null references public.stock_locations (id),
  to_location_id uuid references public.stock_locations (id),
  quantity_sent numeric not null check (quantity_sent > 0),
  quantity_received numeric check (quantity_received > 0),
  status text not null default 'in_transit' check (status in ('in_transit','received','received_short','cancelled','closed_written_off','closed_returned')),
  reference text not null,
  note text,
  sent_by uuid not null references public.profiles (id),
  sent_at timestamptz not null default now(),
  received_by uuid references public.profiles (id),
  received_at timestamptz,
  resolution_note text,
  resolved_by uuid references public.profiles (id),
  resolved_at timestamptz,
  review_case_id uuid,
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, from_clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, to_clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, lot_id) references public.vaccine_lots (organization_id, id),
  check (from_clinic_id <> to_clinic_id),
  check (quantity_received is null or quantity_received <= quantity_sent),
  unique (organization_id, reference)
);
create index stock_transfers_from_idx on public.stock_transfers (from_clinic_id, status);
create index stock_transfers_to_idx on public.stock_transfers (to_clinic_id, status);
create trigger stock_transfers_no_delete before delete on public.stock_transfers for each row execute function private.forbid_change();
create trigger stock_transfers_no_truncate before truncate on public.stock_transfers for each statement execute function private.forbid_change();
alter table public.stock_transfers enable row level security;
revoke all on public.stock_transfers from anon, authenticated;

create function private.transit_location(p_org uuid, p_clinic uuid) returns uuid language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  select id into v_id from public.stock_locations where clinic_id = p_clinic and kind = 'in_transit' and status = 'active' order by created_at limit 1;
  if v_id is null then
    insert into public.stock_locations (organization_id, clinic_id, name, kind, created_by, updated_by) values (p_org, p_clinic, 'In transit', 'in_transit', auth.uid(), auth.uid())
    on conflict (clinic_id, name) do nothing;
    select id into v_id from public.stock_locations where clinic_id = p_clinic and kind = 'in_transit' order by created_at limit 1;
  end if;
  return v_id;
end $$;

create function private.transfer_json(t public.stock_transfers) returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('id', t.id, 'reference', t.reference, 'status', t.status, 'fromClinicId', t.from_clinic_id, 'toClinicId', t.to_clinic_id,
    'fromClinic', (select name from public.clinics where id = t.from_clinic_id), 'toClinic', (select name from public.clinics where id = t.to_clinic_id),
    'lotId', t.lot_id, 'lot', l.manufacturer_lot, 'product', p.name, 'productCode', p.code, 'expiresOn', l.expires_on, 'stockUnit', p.stock_unit,
    'quantitySent', t.quantity_sent, 'quantityReceived', t.quantity_received, 'shortfall', case when t.status = 'received_short' then t.quantity_sent - t.quantity_received else null end,
    'sentAt', t.sent_at, 'receivedAt', t.received_at, 'note', t.note, 'resolutionNote', t.resolution_note)
    from public.vaccine_lots l join public.vaccine_products p on p.id = l.product_id where l.id = t.lot_id
$$;

create function public.send_stock_transfer(p_operation_key uuid, p_from_clinic_id uuid, p_to_clinic_id uuid, p_from_location_id uuid, p_lot_id uuid, p_quantity numeric, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_from_clinic_id); v_prev jsonb; v_lot public.vaccine_lots; v_loc public.stock_locations; v_prod public.vaccine_products; v_transit uuid; v_tx uuid; v_id uuid := gen_random_uuid(); v_ref text; v_today date;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.transfer.send', jsonb_build_object('f', p_from_clinic_id, 't', p_to_clinic_id, 'loc', p_from_location_id, 'lot', p_lot_id, 'q', p_quantity, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'quantity must be positive' using errcode = 'CV422'; end if;
  if p_to_clinic_id = p_from_clinic_id or not exists (select 1 from public.clinics where id = p_to_clinic_id and organization_id = v_org and status = 'active') then raise exception 'choose another active clinic in this organization' using errcode = 'CV422'; end if;
  select * into v_lot from public.vaccine_lots where id = p_lot_id and organization_id = v_org;
  select * into v_loc from public.stock_locations where id = p_from_location_id and organization_id = v_org and clinic_id = p_from_clinic_id and status = 'active';
  if v_lot.id is null or v_loc.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  select * into v_prod from public.vaccine_products where id = v_lot.product_id;
  v_today := private.local_today(p_from_clinic_id);
  if v_loc.kind <> 'usable' then raise exception 'send from a usable location' using errcode = 'CV422'; end if;
  if v_lot.global_disposition <> 'usable' then raise exception 'lot is % and cannot be transferred', v_lot.global_disposition using errcode = 'CV409'; end if;
  if private.lot_is_expired(v_lot.expires_on, v_today) then raise exception 'lot is expired' using errcode = 'CV409'; end if;
  v_transit := private.transit_location(v_org, p_from_clinic_id);
  v_ref := 'TR-' || to_char(now(), 'YYMMDD') || '-' || upper(substr(replace(v_id::text, '-', ''), 1, 6));
  insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, operation_id, created_by)
  values (v_org, p_from_clinic_id, 'transfer_out', v_ref, left(p_note, 300), p_operation_key, auth.uid()) returning id into v_tx;
  perform private.post_movement(v_org, v_tx, p_from_location_id, p_lot_id, -p_quantity, 'tr-out:' || p_operation_key);
  perform private.post_movement(v_org, v_tx, v_transit, p_lot_id, p_quantity, 'tr-transit:' || p_operation_key);
  insert into public.stock_transfers (id, organization_id, from_clinic_id, to_clinic_id, lot_id, from_location_id, transit_location_id, quantity_sent, reference, note, sent_by)
  values (v_id, v_org, p_from_clinic_id, p_to_clinic_id, p_lot_id, p_from_location_id, v_transit, p_quantity, v_ref, left(nullif(btrim(p_note), ''), 300), auth.uid());
  perform private.audit(v_org, 'inventory.manage', 'transfer.sent', 'stock_transfer', v_id, null, jsonb_build_object('ref', v_ref, 'to', p_to_clinic_id, 'lot', p_lot_id, 'qty', p_quantity), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transferId', v_id, 'reference', v_ref, 'status', 'in_transit'));
end $$;

create function public.receive_stock_transfer(p_operation_key uuid, p_clinic_id uuid, p_transfer_id uuid, p_location_id uuid, p_received_quantity numeric, p_accepted boolean default true, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id); v_prev jsonb; t public.stock_transfers; v_loc public.stock_locations; v_dest uuid; v_q uuid; v_tx uuid; v_status text; v_case uuid;
begin
  select * into t from public.stock_transfers where id = p_transfer_id and organization_id = v_org and to_clinic_id = p_clinic_id for update;
  if t.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.transfer.receive', jsonb_build_object('c', p_clinic_id, 't', p_transfer_id, 'loc', p_location_id, 'q', p_received_quantity, 'a', p_accepted, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  if t.status <> 'in_transit' then raise exception 'this transfer is not waiting to be received' using errcode = 'CV409'; end if;
  if p_received_quantity is null or p_received_quantity <= 0 or p_received_quantity > t.quantity_sent then raise exception 'received quantity must be more than zero and at most what was sent' using errcode = 'CV422'; end if;
  select * into v_loc from public.stock_locations where id = p_location_id and organization_id = v_org and clinic_id = p_clinic_id and status = 'active';
  if v_loc.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if v_loc.kind <> 'usable' then raise exception 'receive into a usable location' using errcode = 'CV422'; end if;
  v_dest := p_location_id;
  if not p_accepted then
    select id into v_q from public.stock_locations where clinic_id = p_clinic_id and kind = 'quarantine' and status = 'active' order by created_at limit 1;
    if v_q is null then raise exception 'create a quarantine location before receiving unaccepted stock' using errcode = 'CV422'; end if;
    v_dest := v_q;
  end if;
  insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, operation_id, created_by)
  values (v_org, p_clinic_id, 'transfer_in', t.reference, left(p_note, 300), p_operation_key, auth.uid()) returning id into v_tx;
  perform private.post_movement(v_org, v_tx, t.transit_location_id, t.lot_id, -p_received_quantity, 'tr-take:' || p_operation_key);
  perform private.post_movement(v_org, v_tx, v_dest, t.lot_id, p_received_quantity, 'tr-in:' || p_operation_key);
  v_status := case when p_received_quantity < t.quantity_sent then 'received_short' else 'received' end;
  if v_status = 'received_short' then
    insert into public.record_review_cases (organization_id, clinic_id, kind, reason, evidence, created_by, updated_by)
    values (v_org, t.from_clinic_id, 'stock', 'Transfer ' || t.reference || ' arrived short', jsonb_build_object('transferId', t.id, 'sent', t.quantity_sent, 'received', p_received_quantity), auth.uid(), auth.uid()) returning id into v_case;
  end if;
  update public.stock_transfers set status = v_status, to_location_id = v_dest, quantity_received = p_received_quantity, received_by = auth.uid(), received_at = now(), review_case_id = v_case, version = version + 1 where id = t.id;
  perform private.audit(v_org, 'inventory.manage', 'transfer.received', 'stock_transfer', t.id, jsonb_build_object('status', 'in_transit'), jsonb_build_object('status', v_status, 'qty', p_received_quantity, 'accepted', p_accepted), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transferId', t.id, 'status', v_status, 'locationId', v_dest, 'shortfall', t.quantity_sent - p_received_quantity));
end $$;

create function public.cancel_stock_transfer(p_operation_key uuid, p_clinic_id uuid, p_transfer_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id); v_prev jsonb; t public.stock_transfers; v_tx uuid; v_loc public.stock_locations;
begin
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  select * into t from public.stock_transfers where id = p_transfer_id and organization_id = v_org and from_clinic_id = p_clinic_id for update;
  if t.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.transfer.cancel', jsonb_build_object('c', p_clinic_id, 't', p_transfer_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if t.status <> 'in_transit' then raise exception 'only a transfer that has not been received can be cancelled' using errcode = 'CV409'; end if;
  select * into v_loc from public.stock_locations where id = t.from_location_id and status = 'active';
  if v_loc.id is null then raise exception 'the original location is closed; return the stock through a count adjustment' using errcode = 'CV409'; end if;
  insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, operation_id, created_by)
  values (v_org, p_clinic_id, 'transfer_in', t.reference, 'cancelled: ' || left(btrim(p_reason), 250), p_operation_key, auth.uid()) returning id into v_tx;
  perform private.post_movement(v_org, v_tx, t.transit_location_id, t.lot_id, -t.quantity_sent, 'tr-cancel-out:' || p_operation_key);
  perform private.post_movement(v_org, v_tx, t.from_location_id, t.lot_id, t.quantity_sent, 'tr-cancel-back:' || p_operation_key);
  update public.stock_transfers set status = 'cancelled', resolution_note = left(btrim(p_reason), 300), resolved_by = auth.uid(), resolved_at = now(), version = version + 1 where id = t.id;
  perform private.audit(v_org, 'inventory.manage', 'transfer.cancelled', 'stock_transfer', t.id, jsonb_build_object('status', 'in_transit'), jsonb_build_object('status', 'cancelled'), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transferId', t.id, 'status', 'cancelled'));
end $$;

-- A short delivery is resolved by a person who did not send it: write the missing units off as wastage, or take them back into stock.
create function public.resolve_transfer_shortfall(p_operation_key uuid, p_clinic_id uuid, p_transfer_id uuid, p_decision text, p_note text, p_return_location_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id, 'inventory.approve'); v_prev jsonb; t public.stock_transfers; v_tx uuid; v_short numeric; v_loc public.stock_locations; v_status text;
begin
  if p_decision not in ('write_off','return') then raise exception 'choose write_off or return' using errcode = 'CV422'; end if;
  if p_note is null or length(btrim(p_note)) < 3 then raise exception 'a note is required' using errcode = 'CV422'; end if;
  select * into t from public.stock_transfers where id = p_transfer_id and organization_id = v_org and from_clinic_id = p_clinic_id for update;
  if t.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.transfer.resolve', jsonb_build_object('c', p_clinic_id, 't', p_transfer_id, 'd', p_decision, 'n', p_note, 'l', p_return_location_id));
  if v_prev is not null then return v_prev; end if;
  if t.status <> 'received_short' then raise exception 'this transfer has no shortfall to resolve' using errcode = 'CV409'; end if;
  if t.sent_by = auth.uid() then raise exception 'the person who sent the transfer cannot resolve its shortfall' using errcode = 'CV403'; end if;
  v_short := t.quantity_sent - t.quantity_received;
  if p_decision = 'write_off' then
    insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, approved_by, operation_id, created_by)
    values (v_org, p_clinic_id, 'wastage', t.reference, 'transfer shortfall written off: ' || left(btrim(p_note), 200), auth.uid(), p_operation_key, auth.uid()) returning id into v_tx;
    perform private.post_movement(v_org, v_tx, t.transit_location_id, t.lot_id, -v_short, 'tr-writeoff:' || p_operation_key);
    v_status := 'closed_written_off';
  else
    select * into v_loc from public.stock_locations where id = coalesce(p_return_location_id, t.from_location_id) and organization_id = v_org and clinic_id = p_clinic_id and status = 'active' and kind = 'usable';
    if v_loc.id is null then raise exception 'choose an active usable location to return the stock to' using errcode = 'CV422'; end if;
    insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, approved_by, operation_id, created_by)
    values (v_org, p_clinic_id, 'transfer_in', t.reference, 'shortfall returned: ' || left(btrim(p_note), 200), auth.uid(), p_operation_key, auth.uid()) returning id into v_tx;
    perform private.post_movement(v_org, v_tx, t.transit_location_id, t.lot_id, -v_short, 'tr-ret-out:' || p_operation_key);
    perform private.post_movement(v_org, v_tx, v_loc.id, t.lot_id, v_short, 'tr-ret-in:' || p_operation_key);
    v_status := 'closed_returned';
  end if;
  update public.stock_transfers set status = v_status, resolution_note = left(btrim(p_note), 300), resolved_by = auth.uid(), resolved_at = now(), version = version + 1 where id = t.id;
  if t.review_case_id is not null then
    update public.record_review_cases set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(), resolution = jsonb_build_object('decision', p_decision, 'note', p_note) where id = t.review_case_id and status in ('open','in_review');
  end if;
  perform private.audit(v_org, 'inventory.approve', 'transfer.shortfall_resolved', 'stock_transfer', t.id, jsonb_build_object('status', 'received_short'), jsonb_build_object('status', v_status, 'units', v_short), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transferId', t.id, 'status', v_status, 'units', v_short));
end $$;

create function public.list_stock_transfers(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['inventory.manage','inventory.approve']);
  return jsonb_build_object(
    'outgoing', coalesce((select jsonb_agg(private.transfer_json(t) order by t.sent_at desc) from (select * from public.stock_transfers where from_clinic_id = p_clinic_id order by sent_at desc limit 50) t), '[]'::jsonb),
    'incoming', coalesce((select jsonb_agg(private.transfer_json(t) order by t.sent_at desc) from (select * from public.stock_transfers where to_clinic_id = p_clinic_id order by sent_at desc limit 50) t), '[]'::jsonb),
    'clinics', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name) order by c.name) from public.clinics c where c.organization_id = v_org and c.status = 'active' and c.id <> p_clinic_id), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Temperature logs
-- ---------------------------------------------------------------------------------------------
create table public.cold_chain_limits (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  min_c numeric not null check (min_c between -80 and 60),
  max_c numeric not null check (max_c between -80 and 60),
  policy_reference text not null check (length(btrim(policy_reference)) >= 3),
  set_by uuid not null references public.profiles (id),
  set_at timestamptz not null default now(),
  operation_id uuid not null unique,
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  check (min_c < max_c)
);
create index cold_chain_limits_idx on public.cold_chain_limits (clinic_id, set_at desc);

create table public.temperature_readings (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  location_id uuid not null references public.stock_locations (id),
  observed_at timestamptz not null,
  min_c numeric not null check (min_c between -80 and 60),
  max_c numeric not null check (max_c between -80 and 60),
  limit_min_c numeric,
  limit_max_c numeric,
  limits_id uuid references public.cold_chain_limits (id),
  status text not null check (status in ('no_limits','within_limits','excursion')),
  note text,
  recorded_by uuid not null references public.profiles (id),
  recorded_at timestamptz not null default now(),
  operation_id uuid not null unique,
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  check (min_c <= max_c)
);
create index temperature_readings_idx on public.temperature_readings (clinic_id, location_id, observed_at desc);

create table public.temperature_reviews (
  reading_id uuid primary key references public.temperature_readings (id),
  organization_id uuid not null references public.organizations (id),
  action text not null check (action in ('no_action','lots_quarantined','stock_discarded','other')),
  note text not null check (length(btrim(note)) >= 3),
  reviewed_by uuid not null references public.profiles (id),
  reviewed_at timestamptz not null default now()
);

do $$
declare t text;
begin
  foreach t in array array['public.cold_chain_limits','public.temperature_readings','public.temperature_reviews'] loop
    execute format('create trigger %I before update or delete on %s for each row execute function private.forbid_change()', replace(t, '.', '_') || '_immutable', t);
    execute format('create trigger %I before truncate on %s for each statement execute function private.forbid_change()', replace(t, '.', '_') || '_no_truncate', t);
    execute format('alter table %s enable row level security', t);
    execute format('revoke all on %s from anon, authenticated', t);
  end loop;
end $$;

create function public.set_cold_chain_limits(p_operation_key uuid, p_clinic_id uuid, p_min_c numeric, p_max_c numeric, p_policy_reference text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id, 'inventory.approve'); v_prev jsonb; v_id uuid;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'coldchain.limits', jsonb_build_object('c', p_clinic_id, 'a', p_min_c, 'b', p_max_c, 'p', p_policy_reference));
  if v_prev is not null then return v_prev; end if;
  if p_min_c is null or p_max_c is null or p_min_c >= p_max_c then raise exception 'the lower limit must be below the upper limit' using errcode = 'CV422'; end if;
  if p_policy_reference is null or length(btrim(p_policy_reference)) < 3 then raise exception 'name the cold-chain policy these limits come from' using errcode = 'CV422'; end if;
  insert into public.cold_chain_limits (organization_id, clinic_id, min_c, max_c, policy_reference, set_by, operation_id) values (v_org, p_clinic_id, p_min_c, p_max_c, btrim(p_policy_reference), auth.uid(), p_operation_key) returning id into v_id;
  perform private.audit(v_org, 'inventory.approve', 'coldchain.limits_set', 'clinic', p_clinic_id, null, jsonb_build_object('min', p_min_c, 'max', p_max_c, 'policy', p_policy_reference), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('limitsId', v_id));
end $$;

create function public.record_temperature(p_operation_key uuid, p_clinic_id uuid, p_location_id uuid, p_observed_at timestamptz, p_min_c numeric, p_max_c numeric, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id); v_prev jsonb; v_lim public.cold_chain_limits; v_status text; v_id uuid; v_loc public.stock_locations;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'coldchain.reading', jsonb_build_object('c', p_clinic_id, 'l', p_location_id, 'o', p_observed_at, 'a', p_min_c, 'b', p_max_c, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  select * into v_loc from public.stock_locations where id = p_location_id and organization_id = v_org and clinic_id = p_clinic_id and status = 'active';
  if v_loc.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if v_loc.kind = 'in_transit' then raise exception 'readings are logged for storage locations' using errcode = 'CV422'; end if;
  if p_min_c is null or p_max_c is null or p_min_c > p_max_c or p_min_c < -80 or p_max_c > 60 then raise exception 'check the temperatures: lowest cannot be above highest, and both must be realistic' using errcode = 'CV422'; end if;
  if p_observed_at is null or p_observed_at > now() + interval '5 minutes' then raise exception 'the reading time cannot be in the future' using errcode = 'CV422'; end if;
  if p_observed_at < now() - interval '14 days' then raise exception 'readings older than 14 days cannot be entered here' using errcode = 'CV422'; end if;
  select * into v_lim from public.cold_chain_limits where clinic_id = p_clinic_id order by set_at desc limit 1;
  v_status := case when v_lim.id is null then 'no_limits' when p_min_c < v_lim.min_c or p_max_c > v_lim.max_c then 'excursion' else 'within_limits' end;
  insert into public.temperature_readings (organization_id, clinic_id, location_id, observed_at, min_c, max_c, limit_min_c, limit_max_c, limits_id, status, note, recorded_by, operation_id)
  values (v_org, p_clinic_id, p_location_id, p_observed_at, p_min_c, p_max_c, v_lim.min_c, v_lim.max_c, v_lim.id, v_status, left(nullif(btrim(p_note), ''), 300), auth.uid(), p_operation_key) returning id into v_id;
  perform private.audit(v_org, 'inventory.manage', case when v_status = 'excursion' then 'coldchain.excursion' else 'coldchain.reading' end, 'stock_location', p_location_id, null, jsonb_build_object('min', p_min_c, 'max', p_max_c, 'status', v_status), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('readingId', v_id, 'status', v_status));
end $$;

create function public.review_temperature_excursion(p_operation_key uuid, p_clinic_id uuid, p_reading_id uuid, p_action text, p_note text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id, 'inventory.approve'); v_prev jsonb; r public.temperature_readings;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'coldchain.review', jsonb_build_object('c', p_clinic_id, 'r', p_reading_id, 'a', p_action, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  if p_action not in ('no_action','lots_quarantined','stock_discarded','other') then raise exception 'choose what was done' using errcode = 'CV422'; end if;
  if p_note is null or length(btrim(p_note)) < 3 then raise exception 'a note is required' using errcode = 'CV422'; end if;
  select * into r from public.temperature_readings where id = p_reading_id and organization_id = v_org and clinic_id = p_clinic_id;
  if r.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if r.status <> 'excursion' then raise exception 'only an excursion needs review' using errcode = 'CV409'; end if;
  if exists (select 1 from public.temperature_reviews where reading_id = r.id) then raise exception 'already reviewed' using errcode = 'CV409'; end if;
  if r.recorded_by = auth.uid() then raise exception 'the person who logged the reading cannot review it' using errcode = 'CV403'; end if;
  insert into public.temperature_reviews (reading_id, organization_id, action, note, reviewed_by) values (r.id, v_org, p_action, btrim(p_note), auth.uid());
  perform private.audit(v_org, 'inventory.approve', 'coldchain.excursion_reviewed', 'stock_location', r.location_id, null, jsonb_build_object('action', p_action), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('readingId', r.id, 'action', p_action));
end $$;

create function public.list_temperature(p_clinic_id uuid, p_days integer default 14) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_days int := least(greatest(coalesce(p_days, 14), 1), 90);
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['inventory.manage','inventory.approve']);
  return jsonb_build_object(
    'limits', (select jsonb_build_object('minC', l.min_c, 'maxC', l.max_c, 'policyReference', l.policy_reference, 'setAt', l.set_at) from public.cold_chain_limits l where l.clinic_id = p_clinic_id order by l.set_at desc limit 1),
    'readings', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'location', s.name, 'locationId', r.location_id, 'observedAt', r.observed_at, 'minC', r.min_c, 'maxC', r.max_c, 'status', r.status, 'note', r.note,
          'limitMinC', r.limit_min_c, 'limitMaxC', r.limit_max_c, 'reviewed', rv.reading_id is not null, 'reviewAction', rv.action, 'reviewNote', rv.note) order by r.observed_at desc)
        from public.temperature_readings r join public.stock_locations s on s.id = r.location_id left join public.temperature_reviews rv on rv.reading_id = r.id
       where r.clinic_id = p_clinic_id and r.observed_at >= now() - make_interval(days => v_days)), '[]'::jsonb),
    'openExcursions', (select count(*) from public.temperature_readings r where r.clinic_id = p_clinic_id and r.status = 'excursion' and not exists (select 1 from public.temperature_reviews rv where rv.reading_id = r.id)));
end $$;

revoke all on function private.transit_location(uuid, uuid), private.transfer_json(public.stock_transfers) from public, anon, authenticated;
do $$
declare f text;
begin
  foreach f in array array[
    'send_stock_transfer(uuid,uuid,uuid,uuid,uuid,numeric,text)', 'receive_stock_transfer(uuid,uuid,uuid,uuid,numeric,boolean,text)', 'cancel_stock_transfer(uuid,uuid,uuid,text)',
    'resolve_transfer_shortfall(uuid,uuid,uuid,text,text,uuid)', 'list_stock_transfers(uuid)', 'set_cold_chain_limits(uuid,uuid,numeric,numeric,text)',
    'record_temperature(uuid,uuid,uuid,timestamptz,numeric,numeric,text)', 'review_temperature_excursion(uuid,uuid,uuid,text,text)', 'list_temperature(uuid,integer)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- Backlog now also shows cold-chain and transfer work waiting for a person.
create or replace function public.report_backlog(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id);
begin
  perform private.audit(v_org, 'report.run', 'report.viewed', 'clinic', p_clinic_id, null, jsonb_build_object('report', 'backlog'), null);
  return jsonb_build_object('report', 'backlog', 'asOf', now(), 'definitions', jsonb_build_object('version', 'r1', 'terms', jsonb_build_object(
      'openReviewCases', 'Review cases still open or in review, by type.', 'pendingOutsideDoses', 'Doses reported as given elsewhere that staff have not yet verified or rejected.',
      'provisionalChildren', 'Children enrolled here whose identity has not been confirmed.', 'pendingGuardianLinks', 'Guardian links waiting for in-person verification.',
      'pendingCertificates', 'Certificates prepared but not yet issued (document not stored).', 'failedMessages', 'Notification jobs that failed permanently.',
      'openTemperatureExcursions', 'Fridge readings outside the approved limits that nobody has reviewed.', 'transfersNeedingDecision', 'Stock transfers that arrived short and still need a decision.',
      'transfersInTransit', 'Stock sent to or from this clinic that has not been received yet.')),
    'openReviewCases', (select coalesce(jsonb_object_agg(kind, n), '{}'::jsonb) from (select kind, count(*) n from public.record_review_cases where clinic_id = p_clinic_id and status in ('open','in_review') group by kind) k),
    'pendingOutsideDoses', (select count(*) from private.current_revisions cr where cr.verification_status = 'pending_verification' and cr.event_status = 'active'
                              and private.child_in_clinic(private.canonical_child(cr.child_id), p_clinic_id)),
    'provisionalChildren', (select count(*) from public.children c join public.child_clinic_enrollments e on e.child_id = c.id and e.clinic_id = p_clinic_id and e.status in ('pending','active') where c.record_status = 'provisional' and c.merged_into_id is null),
    'pendingGuardianLinks', (select count(*) from public.guardian_child_relationships r join public.child_clinic_enrollments e on e.child_id = r.child_id and e.clinic_id = p_clinic_id and e.status in ('pending','active') where r.status = 'provisional'),
    'pendingCertificates', (select count(*) from public.certificates where clinic_id = p_clinic_id and status = 'pending'),
    'failedMessages', (select count(*) from private.outbox_jobs where organization_id = v_org and status = 'failed'),
    'openTemperatureExcursions', (select count(*) from public.temperature_readings r where r.clinic_id = p_clinic_id and r.status = 'excursion' and not exists (select 1 from public.temperature_reviews rv where rv.reading_id = r.id)),
    'transfersNeedingDecision', (select count(*) from public.stock_transfers where from_clinic_id = p_clinic_id and status = 'received_short'),
    'transfersInTransit', (select count(*) from public.stock_transfers where (from_clinic_id = p_clinic_id or to_clinic_id = p_clinic_id) and status = 'in_transit'));
end $$;
-- END 0019_transfers_temperature.sql

-- =====================================================================================================================
-- BEGIN 0020_sms_preferences.sql  sha256=f326d76c7834047b2d588329610a4a83dbbc1e0c95c5b39535d08f19ffd24928
-- =====================================================================================================================
-- 0020 Contact preferences, SMS consent and the SMS delivery pipeline (provider-neutral). Blueprint refs: F18, BP22, BP31, M09.
--  * A child can receive full service without a phone or working SMS: SMS is an optional extra, never the only channel.
--  * A phone number is only used after clinic staff have checked it in person AND the guardian has opted in; changing the number resets both.
--  * SMS text is fixed and minimal: no child name, no vaccine, no clinical guidance. Details stay in the app.
--  * The database owns the message state machine (queued -> sending -> sent -> delivered | failed | undeliverable). A provider adapter only
--    claims messages, sends them and reports back; provider webhooks are idempotent and can arrive out of order.
--  * No provider is called from a SQL function or a business transaction.

alter table public.guardians add column sms_opt_in boolean not null default false;
alter table public.guardians add column contact_verified_by uuid references public.profiles (id);

-- Changing the phone number invalidates the in-person check and the opt-in.
create function private.guardian_phone_changed() returns trigger language plpgsql set search_path = '' as $$
begin
  if new.contact_phone is distinct from old.contact_phone then
    new.contact_verified_at := null;
    new.contact_verified_by := null;
    new.contact_status := 'unverified';
    new.sms_opt_in := false;
  end if;
  return new;
end $$;
create trigger guardians_phone_changed before update of contact_phone on public.guardians for each row execute function private.guardian_phone_changed();

create table public.sms_consents (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  guardian_id uuid not null,
  action text not null check (action in ('granted','withdrawn')),
  source text not null check (source in ('app','provider_reply','phone_changed')),
  recorded_by uuid references public.profiles (id),
  recorded_at timestamptz not null default now(),
  foreign key (organization_id, guardian_id) references public.guardians (organization_id, id)
);
create index sms_consents_guardian_idx on public.sms_consents (guardian_id, recorded_at desc);

create table public.sms_messages (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  guardian_id uuid not null,
  kind text not null,
  body text not null check (length(body) between 1 and 320),
  dedupe_key text not null,
  status text not null default 'queued' check (status in ('queued','sending','sent','delivered','failed','undeliverable','opted_out')),
  attempt_count integer not null default 0,
  available_at timestamptz not null default now(),
  locked_until timestamptz,
  provider text,
  provider_message_id text,
  last_error_code text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (organization_id, guardian_id) references public.guardians (organization_id, id),
  unique (guardian_id, dedupe_key)
);
create index sms_messages_ready_idx on public.sms_messages (status, available_at);
create unique index sms_messages_provider_idx on public.sms_messages (provider, provider_message_id) where provider_message_id is not null;

create table public.sms_events (
  id uuid primary key default gen_random_uuid(),
  provider text not null,
  provider_event_id text not null,
  provider_message_id text,
  status text not null,
  occurred_at timestamptz not null,
  applied boolean not null default false,
  received_at timestamptz not null default now(),
  unique (provider, provider_event_id)
);

create trigger sms_consents_immutable before update or delete on public.sms_consents for each row execute function private.forbid_change();
create trigger sms_consents_no_truncate before truncate on public.sms_consents for each statement execute function private.forbid_change();
create trigger sms_events_immutable before delete on public.sms_events for each row execute function private.forbid_change();
create trigger sms_events_no_truncate before truncate on public.sms_events for each statement execute function private.forbid_change();
alter table public.sms_consents enable row level security;
alter table public.sms_messages enable row level security;
alter table public.sms_events enable row level security;
revoke all on public.sms_consents, public.sms_messages, public.sms_events from anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- Guardian preferences
-- ---------------------------------------------------------------------------------------------
create function private.mask_phone(p text) returns text language sql immutable set search_path = '' as $$
  select case when p is null or length(p) < 4 then null else repeat('•', greatest(length(regexp_replace(p, '\D', '', 'g')) - 3, 0)) || right(regexp_replace(p, '\D', '', 'g'), 3) end
$$;

create function public.get_contact_preferences() returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.session_ok() then return null; end if;
  return (select jsonb_build_object('guardianId', g.id, 'language', g.preferred_language, 'phoneMasked', private.mask_phone(g.contact_phone), 'hasPhone', g.contact_phone is not null,
            'phoneChecked', g.contact_verified_at is not null and g.contact_phone is not null, 'smsOptIn', g.sms_opt_in)
            from public.guardians g where g.profile_id = auth.uid() and g.deleted_at is null order by g.created_at limit 1);
end $$;

create function public.set_contact_preferences(p_operation_key uuid, p_language text default null, p_phone text default null, p_sms_opt_in boolean default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare g public.guardians; v_prev jsonb; v_phone text;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.session_ok() then raise exception 'forbidden' using errcode = 'CV403'; end if;
  select * into g from public.guardians where profile_id = auth.uid() and deleted_at is null order by created_at limit 1 for update;
  if g.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(g.organization_id, p_operation_key, 'contact.preferences', jsonb_build_object('l', p_language, 'p', p_phone, 'o', p_sms_opt_in));
  if v_prev is not null then return v_prev; end if;
  if p_language is not null then
    if p_language not in ('en','fil') then raise exception 'unsupported language' using errcode = 'CV422'; end if;
    update public.guardians set preferred_language = p_language, updated_by = auth.uid() where id = g.id;
  end if;
  if p_phone is not null then
    v_phone := nullif(regexp_replace(btrim(p_phone), '[\s\-()]', '', 'g'), '');
    if v_phone is not null and v_phone !~ '^\+?[0-9]{7,15}$' then raise exception 'enter a phone number using digits only (for example 0917 123 4567)' using errcode = 'CV422'; end if;
    if v_phone is distinct from g.contact_phone then
      update public.guardians set contact_phone = v_phone, updated_by = auth.uid() where id = g.id;   -- trigger resets the check and the opt-in
      if g.sms_opt_in then
        insert into public.sms_consents (organization_id, guardian_id, action, source, recorded_by) values (g.organization_id, g.id, 'withdrawn', 'phone_changed', auth.uid());
      end if;
    end if;
  end if;
  select * into g from public.guardians where id = g.id;
  if p_sms_opt_in is not null and p_sms_opt_in is distinct from g.sms_opt_in then
    if p_sms_opt_in then
      if g.contact_phone is null or g.contact_verified_at is null then raise exception 'the clinic must check your phone number in person before text messages can be turned on' using errcode = 'CV422'; end if;
    end if;
    update public.guardians set sms_opt_in = p_sms_opt_in, updated_by = auth.uid() where id = g.id;
    insert into public.sms_consents (organization_id, guardian_id, action, source, recorded_by) values (g.organization_id, g.id, case when p_sms_opt_in then 'granted' else 'withdrawn' end, 'app', auth.uid());
    if not p_sms_opt_in then
      update public.sms_messages set status = 'undeliverable', last_error_code = 'opted_out', updated_at = now() where guardian_id = g.id and status = 'queued';
    end if;
  end if;
  perform private.audit(g.organization_id, 'guardian', 'contact.preferences_changed', 'guardian', g.id, null, jsonb_build_object('language', p_language, 'phoneChanged', p_phone is not null, 'smsOptIn', p_sms_opt_in), null);
  return private.finish_command(g.organization_id, p_operation_key, public.get_contact_preferences());
end $$;

-- Staff confirm, in person, that the number on file belongs to this guardian.
create function public.verify_guardian_contact(p_operation_key uuid, p_clinic_id uuid, p_guardian_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; g public.guardians;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'guardian.verify');
  v_prev := private.begin_command(v_org, p_operation_key, 'contact.verify', jsonb_build_object('c', p_clinic_id, 'g', p_guardian_id));
  if v_prev is not null then return v_prev; end if;
  select * into g from public.guardians where id = p_guardian_id and organization_id = v_org and deleted_at is null for update;
  if g.id is null or not exists (select 1 from public.guardian_child_relationships r join public.child_clinic_enrollments e on e.child_id = r.child_id and e.clinic_id = p_clinic_id and e.status in ('pending','active')
                                   where r.guardian_id = g.id and r.status in ('provisional','active')) then
    raise exception 'not found' using errcode = 'CV404';
  end if;
  if g.contact_phone is null then raise exception 'there is no phone number on file to check' using errcode = 'CV422'; end if;
  update public.guardians set contact_verified_at = now(), contact_verified_by = auth.uid(), contact_status = 'verified', updated_by = auth.uid() where id = g.id;
  perform private.audit(v_org, 'guardian.verify', 'contact.verified', 'guardian', g.id, null, jsonb_build_object('phone', private.mask_phone(g.contact_phone)), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('guardianId', g.id, 'phoneChecked', true));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Queueing: an SMS is created next to the in-app message, only for guardians who opted in on a checked number.
-- ---------------------------------------------------------------------------------------------
drop function private.notify_guardians(uuid, uuid, text, text, text, text);
create function private.notify_guardians(p_org uuid, p_child uuid, p_kind text, p_title text, p_body text, p_dedupe text, p_sms text default null) returns integer
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  insert into public.messages (organization_id, recipient_profile_id, child_id, kind, title, body, dedupe_key)
  select distinct p_org, g.profile_id, private.canonical_child(p_child), p_kind, p_title, p_body, p_dedupe
    from public.guardian_child_relationships r join public.guardians g on g.id = r.guardian_id
   where r.child_id = private.canonical_child(p_child) and r.status = 'active' and r.access_scope = 'full' and (r.ends_at is null or r.ends_at > now())
     and g.profile_id is not null and g.deleted_at is null
  on conflict (recipient_profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count;
  if p_sms is not null then
    insert into public.sms_messages (organization_id, guardian_id, kind, body, dedupe_key)
    select distinct p_org, g.id, p_kind, p_sms, p_dedupe
      from public.guardian_child_relationships r join public.guardians g on g.id = r.guardian_id
     where r.child_id = private.canonical_child(p_child) and r.status = 'active' and r.access_scope = 'full' and (r.ends_at is null or r.ends_at > now())
       and g.deleted_at is null and g.sms_opt_in and g.contact_phone is not null and g.contact_verified_at is not null
    on conflict (guardian_id, dedupe_key) do nothing;
  end if;
  return v_n;
end $$;
revoke all on function private.notify_guardians(uuid, uuid, text, text, text, text, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- Delivery pipeline (called by the worker connection, never by API roles)
-- ---------------------------------------------------------------------------------------------
create function private.claim_sms(p_limit integer default 20) returns table (id uuid, phone text, body text, attempt integer)
language plpgsql security definer set search_path = '' as $$
begin
  -- a message stuck in "sending" (worker died) becomes claimable again; providers must treat the message id as an idempotency key
  update public.sms_messages set status = 'queued', updated_at = now() where status = 'sending' and locked_until < now();
  return query
  with c as (
    select m.id from public.sms_messages m join public.guardians g on g.id = m.guardian_id
     where m.status = 'queued' and m.available_at <= now() and g.sms_opt_in and g.contact_phone is not null and g.contact_verified_at is not null
     order by m.available_at, m.created_at limit least(greatest(coalesce(p_limit, 20), 1), 100) for update of m skip locked)
  update public.sms_messages m set status = 'sending', attempt_count = m.attempt_count + 1, locked_until = now() + interval '2 minutes', updated_at = now()
    from c join public.guardians g2 on true where m.id = c.id and g2.id = m.guardian_id
  returning m.id, g2.contact_phone, m.body, m.attempt_count;
end $$;

create function private.mark_sms(p_id uuid, p_outcome text, p_provider text default null, p_provider_message_id text default null, p_error text default null) returns void
language plpgsql security definer set search_path = '' as $$
declare m public.sms_messages;
begin
  select * into m from public.sms_messages where id = p_id for update;
  if m.id is null or m.status <> 'sending' then return; end if;
  if p_outcome = 'sent' then
    update public.sms_messages set status = 'sent', provider = p_provider, provider_message_id = p_provider_message_id, locked_until = null, last_error_code = null, updated_at = now() where id = m.id;
  elsif p_outcome = 'retry' and m.attempt_count < 5 then
    update public.sms_messages set status = 'queued', locked_until = null, last_error_code = left(p_error, 60), available_at = now() + make_interval(mins => power(2, m.attempt_count)::int), updated_at = now() where id = m.id;
  else
    update public.sms_messages set status = 'failed', locked_until = null, last_error_code = left(coalesce(p_error, 'failed'), 60), updated_at = now() where id = m.id;
  end if;
end $$;

-- Provider status callbacks: idempotent per (provider, event id), tolerant of out-of-order delivery (status only moves forward).
create function private.record_sms_event(p_provider text, p_event_id text, p_provider_message_id text, p_status text, p_at timestamptz) returns boolean
language plpgsql security definer set search_path = '' as $$
declare v_new uuid; m public.sms_messages; v_rank_old int; v_rank_new int;
begin
  if p_status not in ('sent','delivered','failed','undeliverable','opted_out') then raise exception 'unknown status' using errcode = 'CV422'; end if;
  insert into public.sms_events (provider, provider_event_id, provider_message_id, status, occurred_at) values (p_provider, p_event_id, p_provider_message_id, p_status, coalesce(p_at, now()))
  on conflict (provider, provider_event_id) do nothing returning id into v_new;
  if v_new is null then return false; end if;       -- duplicate callback
  select * into m from public.sms_messages where provider = p_provider and provider_message_id = p_provider_message_id for update;
  if m.id is null then return false; end if;
  v_rank_old := case m.status when 'queued' then 0 when 'sending' then 1 when 'sent' then 2 when 'delivered' then 3 else 4 end;
  v_rank_new := case p_status when 'sent' then 2 when 'delivered' then 3 else 4 end;
  if p_status = 'opted_out' then
    update public.sms_messages set status = 'opted_out', updated_at = now() where id = m.id;
    update public.guardians set sms_opt_in = false where id = m.guardian_id and sms_opt_in;
    insert into public.sms_consents (organization_id, guardian_id, action, source) select m.organization_id, m.guardian_id, 'withdrawn', 'provider_reply' where not exists
      (select 1 from public.sms_consents c where c.guardian_id = m.guardian_id and c.action = 'withdrawn' and c.source = 'provider_reply' and c.recorded_at > now() - interval '1 minute');
    update public.sms_messages set status = 'undeliverable', last_error_code = 'opted_out', updated_at = now() where guardian_id = m.guardian_id and status = 'queued';
  elsif v_rank_new > v_rank_old and not (m.status = 'delivered' and p_status in ('failed','undeliverable')) then
    update public.sms_messages set status = p_status, last_error_code = case when p_status in ('failed','undeliverable') then p_status else last_error_code end, updated_at = now() where id = m.id;
  else
    return false;    -- late or stale event: recorded, not applied
  end if;
  update public.sms_events set applied = true where id = v_new;
  return true;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Message wording: the SMS never carries a child's name, a vaccine or clinical guidance.
-- ---------------------------------------------------------------------------------------------
create or replace function private.handle_outbox_job(j private.outbox_jobs) returns text
language plpgsql security definer set search_path = '' as $$
declare a public.appointments; s public.clinic_sessions; c public.certificates; v_child public.children; v_clinic public.clinics; v_when text;
begin
  if j.job_type in ('appointment.confirmation','appointment.cancellation','appointment.session_cancelled') then
    select * into a from public.appointments where id = j.aggregate_id;
    if a.id is null then return 'cancelled'; end if;
    select * into s from public.clinic_sessions where id = a.session_id;
    select * into v_clinic from public.clinics where id = s.clinic_id;
    select * into v_child from public.children where id = a.child_id;
    v_when := to_char(s.starts_at at time zone v_clinic.timezone, 'FMDay, FMDD FMMonth YYYY "at" FMHH12:MI AM');
    if j.job_type = 'appointment.confirmation' then
      if a.status not in ('confirmed','checked_in','fulfilled') then return 'cancelled'; end if;
      perform private.notify_guardians(j.organization_id, a.child_id, 'appointment', case when j.payload ? 'rescheduledFrom' then 'Visit rescheduled' else 'Visit booked' end,
        format('%s: %s at %s.', v_child.display_name, v_when, v_clinic.name), j.dedupe_key,
        format('%s: a visit is booked for %s. Details are in the app.', v_clinic.name, v_when));
    elsif j.job_type = 'appointment.cancellation' then
      perform private.notify_guardians(j.organization_id, a.child_id, 'appointment', 'Visit cancelled', format('The visit for %s on %s was cancelled.', v_child.display_name, v_when), j.dedupe_key,
        format('%s: a visit on %s was cancelled. Open the app to book another time.', v_clinic.name, v_when));
    else
      perform private.notify_guardians(j.organization_id, a.child_id, 'appointment', 'Clinic session cancelled',
        format('The clinic session on %s was cancelled, so the visit for %s will not take place. Please book another time.', v_when, v_child.display_name), j.dedupe_key,
        format('%s: the session on %s was cancelled. Open the app to book another time.', v_clinic.name, v_when));
    end if;
    return 'done';
  elsif j.job_type = 'vaccination.recorded' then
    select * into v_child from public.children where id = (j.payload ->> 'childId')::uuid;
    if v_child.id is null then return 'cancelled'; end if;
    perform private.notify_guardians(j.organization_id, v_child.id, 'record', 'Vaccination recorded', format('A vaccination was recorded for %s. Open the record to see what was given.', v_child.display_name), j.dedupe_key);
    return 'done';
  elsif j.job_type in ('certificate.issued','certificate.revoked') then
    select * into c from public.certificates where id = j.aggregate_id;
    if c.id is null then return 'cancelled'; end if;
    select * into v_child from public.children where id = c.child_id;
    select * into v_clinic from public.clinics where id = c.clinic_id;
    if j.job_type = 'certificate.issued' then
      perform private.notify_guardians(j.organization_id, c.child_id, 'certificate', 'Certificate ready', format('Certificate %s for %s is ready to download.', c.certificate_no, v_child.display_name), j.dedupe_key,
        format('%s: a certificate is ready in the app.', v_clinic.name));
    else
      perform private.notify_guardians(j.organization_id, c.child_id, 'certificate', 'Certificate no longer valid',
        format('Certificate %s for %s is no longer valid.%s Please ask the clinic about a new one.', c.certificate_no, v_child.display_name, case when j.payload ? 'replacedBy' then ' It was replaced by ' || (j.payload ->> 'replacedBy') || '.' else '' end), j.dedupe_key);
    end if;
    return 'done';
  elsif j.job_type = 'certificate.review' then
    for c in select x.* from public.certificates x where x.status = 'issued' and x.review_needed and x.id in
             (select ci.certificate_id from public.certificate_items ci join public.vaccination_revisions r on r.id = ci.vaccination_revision_id where r.event_id = j.aggregate_id) loop
      select * into v_child from public.children where id = c.child_id;
      perform private.notify_guardians(j.organization_id, c.child_id, 'certificate', 'Certificate under review',
        format('A record shown on certificate %s for %s was corrected. The clinic is reviewing the certificate.', c.certificate_no, v_child.display_name), 'cert-review:' || c.id || ':' || j.dedupe_key);
    end loop;
    return 'done';
  end if;
  raise exception 'no handler for job type' using errcode = 'CV422';
end $$;

-- Waiting-for-a-person view for reports.
create or replace function private.sms_backlog(p_org uuid) returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('queued', count(*) filter (where status in ('queued','sending')), 'failed', count(*) filter (where status = 'failed'))
    from public.sms_messages where organization_id = p_org and created_at > now() - interval '30 days'
$$;

revoke all on function private.guardian_phone_changed(), private.mask_phone(text), private.claim_sms(integer), private.mark_sms(uuid, text, text, text, text),
  private.record_sms_event(text, text, text, text, timestamptz), private.handle_outbox_job(private.outbox_jobs), private.sms_backlog(uuid) from public, anon, authenticated;
do $$
declare f text;
begin
  foreach f in array array['get_contact_preferences()', 'set_contact_preferences(uuid,text,text,boolean)', 'verify_guardian_contact(uuid,uuid,uuid)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- Staff view of guardians' contact status for one child (masked number; no message content).
create function public.list_child_guardian_contacts(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  perform private.require_capability(p_clinic_id, 'guardian.verify');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('relationshipId', r.id, 'guardianId', g.id, 'phoneMasked', private.mask_phone(g.contact_phone), 'hasPhone', g.contact_phone is not null,
            'phoneChecked', g.contact_verified_at is not null and g.contact_phone is not null, 'smsOptIn', g.sms_opt_in) order by g.full_name), '[]'::jsonb)
            from public.guardian_child_relationships r join public.guardians g on g.id = r.guardian_id where r.child_id = v_canon and r.status in ('provisional','active') and g.deleted_at is null);
end $$;
revoke all on function public.list_child_guardian_contacts(uuid, uuid) from public, anon, authenticated;
grant execute on function public.list_child_guardian_contacts(uuid, uuid) to authenticated;
-- END 0020_sms_preferences.sql

-- =====================================================================================================================
-- BEGIN 0021_catchup_checkins.sql  sha256=968d112b9e534ffa207b3bb6075339e3f313458782cf82a2eccf78d7abfb3d28
-- =====================================================================================================================
-- 0021 Staff-authored catch-up plans (two-person reviewed) and staffed check-ins. Blueprint refs: F11, F20, BP17, M09.
--  * The system contains NO catch-up rules. A catch-up plan is written by clinical staff (what, when, why, which policy) and must be
--    approved by a different person with rules.approve. It never changes the schedule engine, never credits doses, never books visits.
--  * A check-in is a guardian's question to the clinic. Nothing answers it automatically and nothing is triaged by software: staff read
--    and reply. The feature stays OFF for a clinic until its clinical lead records the safety notice families will see; there is no default text.

-- ---------------------------------------------------------------------------------------------
-- Catch-up plans
-- ---------------------------------------------------------------------------------------------
create table public.catchup_plans (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  child_id uuid not null,
  status text not null default 'draft' check (status in ('draft','submitted','approved','rejected','superseded','cancelled')),
  rationale text not null check (length(btrim(rationale)) >= 10),
  policy_reference text not null check (length(btrim(policy_reference)) >= 3),
  authored_by uuid not null references public.profiles (id),
  submitted_at timestamptz,
  reviewed_by uuid references public.profiles (id),
  reviewed_at timestamptz,
  review_note text,
  version integer not null default 1 check (version > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  unique (organization_id, id),
  check (reviewed_by is null or reviewed_by <> authored_by)
);
create unique index catchup_one_approved_uq on public.catchup_plans (child_id) where status = 'approved';
create index catchup_plans_child_idx on public.catchup_plans (child_id, status);

create table public.catchup_plan_items (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  plan_id uuid not null,
  seq integer not null check (seq > 0),
  label text not null check (length(btrim(label)) between 1 and 200),
  product_id uuid,
  target_date date,
  note text check (note is null or length(note) <= 300),
  status text not null default 'planned' check (status in ('planned','done','dropped')),
  status_note text,
  status_by uuid references public.profiles (id),
  status_at timestamptz,
  foreign key (organization_id, plan_id) references public.catchup_plans (organization_id, id),
  foreign key (organization_id, product_id) references public.vaccine_products (organization_id, id),
  unique (plan_id, seq)
);

-- Items are frozen once a plan leaves draft: only their status may change, and only while the plan is approved.
create function private.catchup_item_guard() returns trigger language plpgsql set search_path = '' as $$
declare v_status text;
begin
  select status into v_status from public.catchup_plans where id = coalesce(old.plan_id, new.plan_id);
  if tg_op = 'DELETE' then
    if v_status <> 'draft' then raise exception 'plan items cannot be removed after submission' using errcode = 'CV403'; end if;
    return old;
  end if;
  if tg_op = 'INSERT' then
    if v_status <> 'draft' then raise exception 'plan items cannot be added after submission' using errcode = 'CV403'; end if;
    return new;
  end if;
  if (new.plan_id, new.seq, new.label, new.product_id, new.target_date, new.note) is distinct from (old.plan_id, old.seq, old.label, old.product_id, old.target_date, old.note) then
    if v_status <> 'draft' then raise exception 'plan items cannot be edited after submission' using errcode = 'CV403'; end if;
  elsif v_status <> 'approved' and (new.status is distinct from old.status) then
    raise exception 'only items of an approved plan can be marked' using errcode = 'CV403';
  end if;
  return new;
end $$;
create trigger catchup_items_guard before insert or update or delete on public.catchup_plan_items for each row execute function private.catchup_item_guard();
create trigger catchup_items_no_truncate before truncate on public.catchup_plan_items for each statement execute function private.forbid_change();
create trigger catchup_plans_no_delete before delete on public.catchup_plans for each row execute function private.forbid_change();
create trigger catchup_plans_no_truncate before truncate on public.catchup_plans for each statement execute function private.forbid_change();
create trigger catchup_plans_touch before update on public.catchup_plans for each row execute function private.touch_row();
alter table public.catchup_plans enable row level security;
alter table public.catchup_plan_items enable row level security;
revoke all on public.catchup_plans, public.catchup_plan_items from anon, authenticated;

create function private.catchup_json(p public.catchup_plans, p_staff boolean) returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('id', p.id, 'status', p.status, 'childId', p.child_id, 'version', p.version, 'reviewedAt', p.reviewed_at,
      'items', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'seq', i.seq, 'label', i.label, 'productId', i.product_id, 'targetDate', i.target_date, 'note', i.note, 'status', i.status)
                  || case when p_staff then jsonb_build_object('statusNote', i.status_note) else '{}'::jsonb end order by i.seq) from public.catchup_plan_items i where i.plan_id = p.id), '[]'::jsonb))
    || case when p_staff then jsonb_build_object('rationale', p.rationale, 'policyReference', p.policy_reference, 'authoredBy', (select display_name from public.profiles where id = p.authored_by),
         'authoredById', p.authored_by, 'submittedAt', p.submitted_at, 'reviewNote', p.review_note, 'reviewedBy', (select display_name from public.profiles where id = p.reviewed_by), 'createdAt', p.created_at) else '{}'::jsonb end
$$;

create function private.catchup_items_insert(p_org uuid, p_plan uuid, p_items jsonb) returns void language plpgsql security definer set search_path = '' as $$
declare i jsonb; n int := 0; v_prod uuid;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'add at least one planned item' using errcode = 'CV422'; end if;
  if jsonb_array_length(p_items) > 30 then raise exception 'a plan can have at most 30 items' using errcode = 'CV422'; end if;
  for i in select * from jsonb_array_elements(p_items) loop
    n := n + 1;
    if length(btrim(coalesce(i ->> 'label', ''))) = 0 then raise exception 'every item needs a description' using errcode = 'CV422'; end if;
    v_prod := nullif(i ->> 'productId', '')::uuid;
    if v_prod is not null and not exists (select 1 from public.vaccine_products where id = v_prod and organization_id = p_org) then raise exception 'unknown product' using errcode = 'CV422'; end if;
    insert into public.catchup_plan_items (organization_id, plan_id, seq, label, product_id, target_date, note)
    values (p_org, p_plan, n, left(btrim(i ->> 'label'), 200), v_prod, nullif(i ->> 'targetDate', '')::date, left(nullif(btrim(coalesce(i ->> 'note', '')), ''), 300));
  end loop;
end $$;

create function public.save_catchup_draft(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_plan_id uuid, p_rationale text, p_policy_reference text, p_items jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_canon uuid; p public.catchup_plans;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  v_prev := private.begin_command(v_org, p_operation_key, 'catchup.save', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 'p', p_plan_id, 'r', p_rationale, 'pr', p_policy_reference, 'i', p_items));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  if p_rationale is null or length(btrim(p_rationale)) < 10 then raise exception 'explain why this plan is needed (at least a sentence)' using errcode = 'CV422'; end if;
  if p_policy_reference is null or length(btrim(p_policy_reference)) < 3 then raise exception 'name the clinical policy or advice this plan follows' using errcode = 'CV422'; end if;
  if p_plan_id is null then
    if exists (select 1 from public.catchup_plans where child_id = v_canon and status in ('draft','submitted')) then raise exception 'this child already has a plan being prepared' using errcode = 'CV409'; end if;
    insert into public.catchup_plans (organization_id, clinic_id, child_id, rationale, policy_reference, authored_by) values (v_org, p_clinic_id, v_canon, btrim(p_rationale), btrim(p_policy_reference), auth.uid()) returning * into p;
  else
    select * into p from public.catchup_plans where id = p_plan_id and organization_id = v_org and clinic_id = p_clinic_id and child_id = v_canon for update;
    if p.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
    if p.status <> 'draft' then raise exception 'only a draft can be edited' using errcode = 'CV409'; end if;
    if p.authored_by <> auth.uid() then raise exception 'only the author can edit a draft' using errcode = 'CV403'; end if;
    update public.catchup_plans set rationale = btrim(p_rationale), policy_reference = btrim(p_policy_reference) where id = p.id;
    delete from public.catchup_plan_items where plan_id = p.id;
  end if;
  perform private.catchup_items_insert(v_org, p.id, p_items);
  perform private.audit(v_org, 'vaccination.record', 'catchup.drafted', 'catchup_plan', p.id, null, jsonb_build_object('child', v_canon, 'items', jsonb_array_length(p_items)), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('planId', p.id, 'status', 'draft'));
end $$;

create function public.submit_catchup_plan(p_operation_key uuid, p_clinic_id uuid, p_plan_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; p public.catchup_plans;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  v_prev := private.begin_command(v_org, p_operation_key, 'catchup.submit', jsonb_build_object('c', p_clinic_id, 'p', p_plan_id));
  if v_prev is not null then return v_prev; end if;
  select * into p from public.catchup_plans where id = p_plan_id and organization_id = v_org and clinic_id = p_clinic_id for update;
  if p.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if p.authored_by <> auth.uid() then raise exception 'only the author can submit a plan' using errcode = 'CV403'; end if;
  if p.status <> 'draft' then raise exception 'only a draft can be submitted' using errcode = 'CV409'; end if;
  if not exists (select 1 from public.catchup_plan_items where plan_id = p.id) then raise exception 'add at least one planned item' using errcode = 'CV422'; end if;
  update public.catchup_plans set status = 'submitted', submitted_at = now() where id = p.id;
  perform private.audit(v_org, 'vaccination.record', 'catchup.submitted', 'catchup_plan', p.id, jsonb_build_object('status', 'draft'), jsonb_build_object('status', 'submitted'), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('planId', p.id, 'status', 'submitted'));
end $$;

create function public.review_catchup_plan(p_operation_key uuid, p_clinic_id uuid, p_plan_id uuid, p_decision text, p_note text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; p public.catchup_plans; v_status text; v_old uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'rules.approve');
  v_prev := private.begin_command(v_org, p_operation_key, 'catchup.review', jsonb_build_object('c', p_clinic_id, 'p', p_plan_id, 'd', p_decision, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  if p_decision not in ('approve','reject') then raise exception 'choose approve or reject' using errcode = 'CV422'; end if;
  if p_decision = 'reject' and (p_note is null or length(btrim(p_note)) < 3) then raise exception 'say why the plan is rejected' using errcode = 'CV422'; end if;
  select * into p from public.catchup_plans where id = p_plan_id and organization_id = v_org and clinic_id = p_clinic_id for update;
  if p.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if p.status <> 'submitted' then raise exception 'only a submitted plan can be reviewed' using errcode = 'CV409'; end if;
  if p.authored_by = auth.uid() then raise exception 'the author cannot review their own plan' using errcode = 'CV403'; end if;
  v_status := case when p_decision = 'approve' then 'approved' else 'rejected' end;
  if v_status = 'approved' then
    for v_old in select id from public.catchup_plans where child_id = p.child_id and status = 'approved' and id <> p.id loop
      update public.catchup_plans set status = 'superseded' where id = v_old;
    end loop;
  end if;
  update public.catchup_plans set status = v_status, reviewed_by = auth.uid(), reviewed_at = now(), review_note = left(nullif(btrim(coalesce(p_note, '')), ''), 300) where id = p.id;
  if v_status = 'approved' then
    perform private.enqueue(v_org, 'catchup.approved', 'catchup_plan', p.id, 'catchup-approved:' || p.id, jsonb_build_object('childId', p.child_id));
  end if;
  perform private.audit(v_org, 'rules.approve', 'catchup.' || v_status, 'catchup_plan', p.id, jsonb_build_object('status', 'submitted'), jsonb_build_object('status', v_status), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('planId', p.id, 'status', v_status));
end $$;

create function public.set_catchup_item_status(p_operation_key uuid, p_clinic_id uuid, p_item_id uuid, p_status text, p_note text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; i public.catchup_plan_items; p public.catchup_plans;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  v_prev := private.begin_command(v_org, p_operation_key, 'catchup.item', jsonb_build_object('c', p_clinic_id, 'i', p_item_id, 's', p_status, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  if p_status not in ('done','dropped') then raise exception 'choose done or dropped' using errcode = 'CV422'; end if;
  if p_note is null or length(btrim(p_note)) < 3 then raise exception 'a note is required' using errcode = 'CV422'; end if;
  select * into i from public.catchup_plan_items where id = p_item_id and organization_id = v_org for update;
  select * into p from public.catchup_plans where id = i.plan_id and clinic_id = p_clinic_id;
  if i.id is null or p.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if p.status <> 'approved' then raise exception 'only items of the approved plan can be marked' using errcode = 'CV409'; end if;
  if i.status <> 'planned' then raise exception 'this item was already marked' using errcode = 'CV409'; end if;
  update public.catchup_plan_items set status = p_status, status_note = left(btrim(p_note), 300), status_by = auth.uid(), status_at = now() where id = i.id;
  perform private.audit(v_org, 'vaccination.record', 'catchup.item_' || p_status, 'catchup_plan', p.id, null, jsonb_build_object('item', i.id, 'label', i.label), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('itemId', i.id, 'status', p_status));
end $$;

create function public.cancel_catchup_plan(p_operation_key uuid, p_clinic_id uuid, p_plan_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; p public.catchup_plans;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  v_prev := private.begin_command(v_org, p_operation_key, 'catchup.cancel', jsonb_build_object('c', p_clinic_id, 'p', p_plan_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  select * into p from public.catchup_plans where id = p_plan_id and organization_id = v_org and clinic_id = p_clinic_id for update;
  if p.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if p.status not in ('draft','submitted','approved') then raise exception 'this plan is already closed' using errcode = 'CV409'; end if;
  if p.authored_by <> auth.uid() and not private.has_capability(p_clinic_id, 'rules.approve') then raise exception 'only the author or a plan approver can cancel it' using errcode = 'CV403'; end if;
  update public.catchup_plans set status = 'cancelled', review_note = coalesce(review_note, left(btrim(p_reason), 300)) where id = p.id;
  perform private.audit(v_org, 'vaccination.record', 'catchup.cancelled', 'catchup_plan', p.id, jsonb_build_object('status', p.status), jsonb_build_object('status', 'cancelled'), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('planId', p.id, 'status', 'cancelled'));
end $$;

create function public.list_catchup_plans(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  perform private.require_capability(p_clinic_id, 'child.read_clinical');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  return (select coalesce(jsonb_agg(private.catchup_json(p, true) order by p.created_at desc), '[]'::jsonb) from public.catchup_plans p where p.child_id = v_canon and p.clinic_id = p_clinic_id);
end $$;

-- Guardians see only the APPROVED plan: what is planned and its state. Not the rationale, policy reference or staff notes.
create function public.guardian_get_catchup_plan(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then return null; end if;
  return (select private.catchup_json(p, false) from public.catchup_plans p where p.child_id = v_canon and p.status = 'approved');
end $$;

-- Plans awaiting review, clinic-wide.
create function public.list_catchup_reviews(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform private.require_capability(p_clinic_id, 'rules.approve');
  return (select coalesce(jsonb_agg(jsonb_build_object('planId', p.id, 'childId', p.child_id, 'childName', c.display_name, 'recordNo', c.local_record_no, 'submittedAt', p.submitted_at,
            'authoredBy', (select display_name from public.profiles where id = p.authored_by), 'authoredById', p.authored_by, 'itemCount', (select count(*) from public.catchup_plan_items i where i.plan_id = p.id)) order by p.submitted_at), '[]'::jsonb)
            from public.catchup_plans p join public.children c on c.id = p.child_id where p.clinic_id = p_clinic_id and p.status = 'submitted');
end $$;

-- ---------------------------------------------------------------------------------------------
-- Check-ins
-- ---------------------------------------------------------------------------------------------
create function public.set_checkin_policy(p_operation_key uuid, p_clinic_id uuid, p_enabled boolean, p_safety_notice text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_pol jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'grant.approve.clinical');
  v_prev := private.begin_command(v_org, p_operation_key, 'checkin.policy', jsonb_build_object('c', p_clinic_id, 'e', p_enabled, 'n', p_safety_notice));
  if v_prev is not null then return v_prev; end if;
  if p_enabled and (p_safety_notice is null or length(btrim(p_safety_notice)) < 20) then raise exception 'write the safety notice families will see (at least a sentence) before turning check-ins on' using errcode = 'CV422'; end if;
  v_pol := (select operational_policy from public.clinics where id = p_clinic_id) || jsonb_build_object('checkinEnabled', coalesce(p_enabled, false), 'checkinSafetyNotice', left(btrim(coalesce(p_safety_notice, '')), 600));
  update public.clinics set operational_policy = v_pol where id = p_clinic_id;
  perform private.audit(v_org, 'grant.approve.clinical', 'checkin.policy_set', 'clinic', p_clinic_id, null, jsonb_build_object('enabled', coalesce(p_enabled, false)), p_safety_notice);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('enabled', coalesce(p_enabled, false)));
end $$;

create function public.get_checkin_policy(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform private.require_any(p_clinic_id, array['grant.approve.clinical','child.read_clinical']);
  return (select jsonb_build_object('enabled', coalesce((operational_policy ->> 'checkinEnabled')::boolean, false), 'safetyNotice', coalesce(operational_policy ->> 'checkinSafetyNotice', '')) from public.clinics where id = p_clinic_id);
end $$;

create table public.checkins (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  child_id uuid not null,
  guardian_profile_id uuid not null references public.profiles (id),
  category text not null check (category in ('question','after_vaccination','other')),
  message text not null check (length(btrim(message)) between 3 and 1000),
  status text not null default 'open' check (status in ('open','answered','closed')),
  answer text check (answer is null or length(answer) between 1 and 500),
  answered_by uuid references public.profiles (id),
  answered_at timestamptz,
  created_at timestamptz not null default now(),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, child_id) references public.children (organization_id, id)
);
create index checkins_clinic_idx on public.checkins (clinic_id, status, created_at);
create trigger checkins_no_delete before delete on public.checkins for each row execute function private.forbid_change();
create trigger checkins_no_truncate before truncate on public.checkins for each statement execute function private.forbid_change();
alter table public.checkins enable row level security;
revoke all on public.checkins from anon, authenticated;

-- Returns the clinic's own safety notice with the acknowledgement so the guardian always sees it at the moment of sending.
create function public.create_checkin(p_operation_key uuid, p_child_id uuid, p_category text, p_message text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid; v_clinic uuid; v_org uuid; v_prev jsonb; v_pol jsonb; v_id uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then raise exception 'not found' using errcode = 'CV404'; end if;
  select e.clinic_id, c.organization_id, c.operational_policy into v_clinic, v_org, v_pol from public.child_clinic_enrollments e join public.clinics c on c.id = e.clinic_id
   where e.child_id = v_canon and e.status in ('pending','active') order by e.is_primary desc, e.created_at limit 1;
  if v_clinic is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if not coalesce((v_pol ->> 'checkinEnabled')::boolean, false) or length(coalesce(v_pol ->> 'checkinSafetyNotice', '')) < 20 then
    raise exception 'this clinic has not turned on check-ins; please call or visit the clinic' using errcode = 'CV409';
  end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'checkin.create', jsonb_build_object('ch', v_canon, 'c', p_category, 'm', p_message));
  if v_prev is not null then return v_prev; end if;
  if p_category not in ('question','after_vaccination','other') then raise exception 'choose what this is about' using errcode = 'CV422'; end if;
  if p_message is null or length(btrim(p_message)) < 3 then raise exception 'write your question' using errcode = 'CV422'; end if;
  if (select count(*) from public.checkins where child_id = v_canon and status = 'open') >= 3 then raise exception 'you already have several questions waiting; the clinic will reply to those first' using errcode = 'CV409'; end if;
  insert into public.checkins (organization_id, clinic_id, child_id, guardian_profile_id, category, message) values (v_org, v_clinic, v_canon, auth.uid(), p_category, left(btrim(p_message), 1000)) returning id into v_id;
  perform private.audit(v_org, 'guardian', 'checkin.created', 'checkin', v_id, null, jsonb_build_object('category', p_category), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('checkinId', v_id, 'safetyNotice', v_pol ->> 'checkinSafetyNotice'));
end $$;

create function public.my_checkins(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid; v_pol jsonb;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then return null; end if;
  select c.operational_policy into v_pol from public.child_clinic_enrollments e join public.clinics c on c.id = e.clinic_id where e.child_id = v_canon and e.status in ('pending','active') order by e.is_primary desc limit 1;
  return jsonb_build_object('enabled', coalesce((v_pol ->> 'checkinEnabled')::boolean, false) and length(coalesce(v_pol ->> 'checkinSafetyNotice', '')) >= 20, 'safetyNotice', coalesce(v_pol ->> 'checkinSafetyNotice', ''),
    'items', coalesce((select jsonb_agg(jsonb_build_object('id', k.id, 'category', k.category, 'message', k.message, 'status', k.status, 'answer', k.answer, 'createdAt', k.created_at, 'answeredAt', k.answered_at) order by k.created_at desc)
                        from public.checkins k where k.child_id = v_canon and k.guardian_profile_id = auth.uid()), '[]'::jsonb));
end $$;

create function public.list_checkins(p_clinic_id uuid, p_status text default 'open') returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform private.require_capability(p_clinic_id, 'child.read_clinical');
  if p_status not in ('open','answered','closed') then raise exception 'unknown status' using errcode = 'CV422'; end if;
  perform private.audit((select organization_id from public.clinics where id = p_clinic_id), 'child.read_clinical', 'checkin.list', 'clinic', p_clinic_id, null, jsonb_build_object('status', p_status), null);
  return (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'childId', k.child_id, 'childName', c.display_name, 'recordNo', c.local_record_no, 'category', k.category, 'message', k.message, 'status', k.status, 'answer', k.answer,
            'createdAt', k.created_at, 'answeredAt', k.answered_at) order by (k.category = 'after_vaccination') desc, k.created_at), '[]'::jsonb)
            from public.checkins k join public.children c on c.id = k.child_id where k.clinic_id = p_clinic_id and k.status = p_status);
end $$;

create function public.answer_checkin(p_operation_key uuid, p_clinic_id uuid, p_checkin_id uuid, p_answer text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; k public.checkins; v_name text;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'child.read_clinical');
  v_prev := private.begin_command(v_org, p_operation_key, 'checkin.answer', jsonb_build_object('c', p_clinic_id, 'k', p_checkin_id, 'a', p_answer));
  if v_prev is not null then return v_prev; end if;
  if p_answer is null or length(btrim(p_answer)) < 1 or length(p_answer) > 500 then raise exception 'write a reply of up to 500 characters' using errcode = 'CV422'; end if;
  select * into k from public.checkins where id = p_checkin_id and organization_id = v_org and clinic_id = p_clinic_id for update;
  if k.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if k.status <> 'open' then raise exception 'this question was already answered' using errcode = 'CV409'; end if;
  update public.checkins set status = 'answered', answer = btrim(p_answer), answered_by = auth.uid(), answered_at = now() where id = k.id;
  select display_name into v_name from public.children where id = k.child_id;
  insert into public.messages (organization_id, recipient_profile_id, child_id, kind, title, body, dedupe_key)
  values (v_org, k.guardian_profile_id, k.child_id, 'checkin', 'The clinic replied', left('Reply about ' || v_name || ': ' || btrim(p_answer), 600), 'checkin:' || k.id) on conflict (recipient_profile_id, dedupe_key) do nothing;
  perform private.audit(v_org, 'child.read_clinical', 'checkin.answered', 'checkin', k.id, jsonb_build_object('status', 'open'), jsonb_build_object('status', 'answered'), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('checkinId', k.id, 'status', 'answered'));
end $$;

-- ---------------------------------------------------------------------------------------------
-- Outbox: notify the family when a plan is approved (wrapper keeps the earlier handler intact)
-- ---------------------------------------------------------------------------------------------
alter function private.handle_outbox_job(private.outbox_jobs) rename to handle_outbox_job_base;
create function private.handle_outbox_job(j private.outbox_jobs) returns text
language plpgsql security definer set search_path = '' as $$
declare v_child public.children;
begin
  if j.job_type = 'catchup.approved' then
    select * into v_child from public.children where id = (j.payload ->> 'childId')::uuid;
    if v_child.id is null then return 'cancelled'; end if;
    perform private.notify_guardians(j.organization_id, v_child.id, 'record', 'Care plan from the clinic', format('The clinic added a care plan for %s. Open the record to see it.', v_child.display_name), j.dedupe_key);
    return 'done';
  end if;
  return private.handle_outbox_job_base(j);
end $$;

-- Backlog now also shows plans and questions waiting for a person.
create or replace function public.report_backlog(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id);
begin
  perform private.audit(v_org, 'report.run', 'report.viewed', 'clinic', p_clinic_id, null, jsonb_build_object('report', 'backlog'), null);
  return jsonb_build_object('report', 'backlog', 'asOf', now(), 'definitions', jsonb_build_object('version', 'r1', 'terms', jsonb_build_object(
      'openReviewCases', 'Review cases still open or in review, by type.', 'pendingOutsideDoses', 'Doses reported as given elsewhere that staff have not yet verified or rejected.',
      'provisionalChildren', 'Children enrolled here whose identity has not been confirmed.', 'pendingGuardianLinks', 'Guardian links waiting for in-person verification.',
      'pendingCertificates', 'Certificates prepared but not yet issued (document not stored).', 'failedMessages', 'Notification jobs that failed permanently.',
      'openTemperatureExcursions', 'Fridge readings outside the approved limits that nobody has reviewed.', 'transfersNeedingDecision', 'Stock transfers that arrived short and still need a decision.',
      'transfersInTransit', 'Stock sent to or from this clinic that has not been received yet.',
      'plansAwaitingReview', 'Catch-up plans submitted and waiting for a second person.', 'openCheckins', 'Questions from families that no one has answered yet.')),
    'openReviewCases', (select coalesce(jsonb_object_agg(kind, n), '{}'::jsonb) from (select kind, count(*) n from public.record_review_cases where clinic_id = p_clinic_id and status in ('open','in_review') group by kind) k),
    'pendingOutsideDoses', (select count(*) from private.current_revisions cr where cr.verification_status = 'pending_verification' and cr.event_status = 'active'
                              and private.child_in_clinic(private.canonical_child(cr.child_id), p_clinic_id)),
    'provisionalChildren', (select count(*) from public.children c join public.child_clinic_enrollments e on e.child_id = c.id and e.clinic_id = p_clinic_id and e.status in ('pending','active') where c.record_status = 'provisional' and c.merged_into_id is null),
    'pendingGuardianLinks', (select count(*) from public.guardian_child_relationships r join public.child_clinic_enrollments e on e.child_id = r.child_id and e.clinic_id = p_clinic_id and e.status in ('pending','active') where r.status = 'provisional'),
    'pendingCertificates', (select count(*) from public.certificates where clinic_id = p_clinic_id and status = 'pending'),
    'failedMessages', (select count(*) from private.outbox_jobs where organization_id = v_org and status = 'failed'),
    'openTemperatureExcursions', (select count(*) from public.temperature_readings r where r.clinic_id = p_clinic_id and r.status = 'excursion' and not exists (select 1 from public.temperature_reviews rv where rv.reading_id = r.id)),
    'transfersNeedingDecision', (select count(*) from public.stock_transfers where from_clinic_id = p_clinic_id and status = 'received_short'),
    'transfersInTransit', (select count(*) from public.stock_transfers where (from_clinic_id = p_clinic_id or to_clinic_id = p_clinic_id) and status = 'in_transit'),
    'plansAwaitingReview', (select count(*) from public.catchup_plans where clinic_id = p_clinic_id and status = 'submitted'),
    'openCheckins', (select count(*) from public.checkins where clinic_id = p_clinic_id and status = 'open'));
end $$;

revoke all on function private.catchup_item_guard(), private.catchup_json(public.catchup_plans, boolean), private.catchup_items_insert(uuid, uuid, jsonb), private.handle_outbox_job(private.outbox_jobs),
  private.handle_outbox_job_base(private.outbox_jobs) from public, anon, authenticated;
do $$
declare f text;
begin
  foreach f in array array[
    'save_catchup_draft(uuid,uuid,uuid,uuid,text,text,jsonb)', 'submit_catchup_plan(uuid,uuid,uuid)', 'review_catchup_plan(uuid,uuid,uuid,text,text)', 'set_catchup_item_status(uuid,uuid,uuid,text,text)',
    'cancel_catchup_plan(uuid,uuid,uuid,text)', 'list_catchup_plans(uuid,uuid)', 'guardian_get_catchup_plan(uuid)', 'list_catchup_reviews(uuid)', 'set_checkin_policy(uuid,uuid,boolean,text)',
    'get_checkin_policy(uuid)', 'create_checkin(uuid,uuid,text,text)', 'my_checkins(uuid)', 'list_checkins(uuid,text)', 'answer_checkin(uuid,uuid,uuid,text)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
-- END 0021_catchup_checkins.sql

-- =====================================================================================================================
-- BEGIN 0022_followup_holds_privacy.sql  sha256=32a746031ff0477ea1391686c95f8dda8ab71b75d88b87bd5c3666a4ecc495e1
-- =====================================================================================================================
-- 0022 Follow-up worklist with outreach log, clinical hold commands, clinic privacy notice with acknowledgement gate.
-- Blueprint refs: F10, F04 (privacy), F09 (holds), BP17, BP33, M02/M03 leftovers.
--  * The worklist is DERIVED from the schedule engine's results for the clinic's own approved schedule. It never invents due dates;
--    with no active schedule it says so and lists nothing.
--  * Outreach attempts are an append-only log. Contact numbers are shown only to staff who follow families up.
--  * A clinical hold is placed by clinical staff and released only by a clinical lead; the engine already refuses planned doses under a hold.
--  * The privacy notice text and version belong to the clinic's privacy owner. There is no default text. When a notice is configured,
--    a guardian must acknowledge the current version before adding a child or asking to link one.

-- ---------------------------------------------------------------------------------------------
-- Clinical holds
-- ---------------------------------------------------------------------------------------------
alter table public.clinical_holds add column resolution_note text;
alter table public.clinical_holds add column resolved_at timestamptz;
alter table public.clinical_holds add column placed_clinic_id uuid;

create function public.place_clinical_hold(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_reason_code text, p_restricted_note text default null, p_review_on date default null, p_rule_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_canon uuid; v_id uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  v_prev := private.begin_command(v_org, p_operation_key, 'hold.place', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 'r', p_reason_code, 'n', p_restricted_note, 'd', p_review_on, 'rule', p_rule_id));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  if p_reason_code is null or length(btrim(p_reason_code)) < 3 or length(p_reason_code) > 80 then raise exception 'name the reason for the hold (3 to 80 characters)' using errcode = 'CV422'; end if;
  if p_review_on is not null and p_review_on < private.local_today(p_clinic_id) then raise exception 'the review date cannot be in the past' using errcode = 'CV422'; end if;
  if p_rule_id is not null and not exists (select 1 from public.schedule_rules where id = p_rule_id and organization_id = v_org) then raise exception 'unknown schedule item' using errcode = 'CV422'; end if;
  if exists (select 1 from public.clinical_holds where child_id = v_canon and status = 'active' and coalesce(rule_id, '00000000-0000-0000-0000-000000000000') = coalesce(p_rule_id, '00000000-0000-0000-0000-000000000000')) then
    raise exception 'this hold already exists' using errcode = 'CV409';
  end if;
  insert into public.clinical_holds (organization_id, child_id, rule_id, reason_code, restricted_note, review_on, placed_clinic_id, created_by, updated_by)
  values (v_org, v_canon, p_rule_id, btrim(p_reason_code), left(nullif(btrim(coalesce(p_restricted_note, '')), ''), 500), p_review_on, p_clinic_id, auth.uid(), auth.uid()) returning id into v_id;
  perform private.audit(v_org, 'vaccination.record', 'hold.placed', 'child', v_canon, null, jsonb_build_object('holdId', v_id, 'rule', p_rule_id, 'reviewOn', p_review_on), p_reason_code);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('holdId', v_id, 'status', 'active'));
end $$;

create function public.release_clinical_hold(p_operation_key uuid, p_clinic_id uuid, p_hold_id uuid, p_note text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; h public.clinical_holds;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'review.resolve');
  v_prev := private.begin_command(v_org, p_operation_key, 'hold.release', jsonb_build_object('c', p_clinic_id, 'h', p_hold_id, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  if p_note is null or length(btrim(p_note)) < 3 then raise exception 'say why the hold is released' using errcode = 'CV422'; end if;
  select * into h from public.clinical_holds where id = p_hold_id and organization_id = v_org for update;
  if h.id is null or not private.child_in_clinic(private.canonical_child(h.child_id), p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if h.status <> 'active' then raise exception 'this hold is already released' using errcode = 'CV409'; end if;
  update public.clinical_holds set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), resolution_note = left(btrim(p_note), 500), updated_by = auth.uid() where id = h.id;
  perform private.audit(v_org, 'review.resolve', 'hold.released', 'child', h.child_id, jsonb_build_object('status', 'active'), jsonb_build_object('status', 'resolved'), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('holdId', h.id, 'status', 'resolved'));
end $$;

create function public.list_clinical_holds(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  perform private.require_capability(p_clinic_id, 'child.read_clinical');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'status', h.status, 'reason', h.reason_code, 'note', h.restricted_note, 'reviewOn', h.review_on, 'startsAt', h.starts_at,
            'ruleRequirement', (select r.requirement_code from public.schedule_rules r where r.id = h.rule_id), 'resolvedAt', h.resolved_at, 'resolutionNote', h.resolution_note,
            'placedBy', (select display_name from public.profiles where id = h.created_by)) order by h.starts_at desc), '[]'::jsonb)
            from public.clinical_holds h where h.child_id = v_canon);
end $$;

-- ---------------------------------------------------------------------------------------------
-- Clinic privacy notice and the acknowledgement gate
-- ---------------------------------------------------------------------------------------------
create function public.set_privacy_notice(p_operation_key uuid, p_clinic_id uuid, p_version text, p_text text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'admin.config');
  v_prev := private.begin_command(v_org, p_operation_key, 'privacy.notice', jsonb_build_object('c', p_clinic_id, 'v', p_version, 't', p_text));
  if v_prev is not null then return v_prev; end if;
  if p_version is null or length(btrim(p_version)) = 0 or length(p_version) > 50 then raise exception 'give the notice a version (for example "2026-10")' using errcode = 'CV422'; end if;
  if p_text is null or length(btrim(p_text)) < 50 or length(p_text) > 8000 then raise exception 'paste the privacy notice text approved by your privacy owner (at least 50 characters)' using errcode = 'CV422'; end if;
  if (select operational_policy -> 'privacyNotice' ->> 'version' from public.clinics where id = p_clinic_id) = btrim(p_version) then raise exception 'use a new version when the text changes' using errcode = 'CV409'; end if;
  update public.clinics set operational_policy = operational_policy || jsonb_build_object('privacyNotice', jsonb_build_object('version', btrim(p_version), 'text', btrim(p_text), 'setAt', now())) where id = p_clinic_id;
  perform private.audit(v_org, 'admin.config', 'privacy.notice_set', 'clinic', p_clinic_id, null, jsonb_build_object('version', btrim(p_version)), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('version', btrim(p_version)));
end $$;

create function private.guardian_ack_version(p_org uuid, p_version text) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.privacy_records pr join public.guardians g on g.id = pr.guardian_id
                  where g.profile_id = auth.uid() and g.organization_id = p_org and pr.record_type = 'notice_acknowledgement' and pr.notice_version = p_version and pr.decision = 'acknowledged')
$$;

create function public.get_privacy_notice(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.clinics; v_n jsonb;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select * into c from public.clinics where id = p_clinic_id and status = 'active';
  if c.id is null then return null; end if;
  v_n := c.operational_policy -> 'privacyNotice';
  if v_n is null then return jsonb_build_object('configured', false, 'acknowledged', true); end if;
  return jsonb_build_object('configured', true, 'version', v_n ->> 'version', 'text', v_n ->> 'text', 'acknowledged', private.guardian_ack_version(c.organization_id, v_n ->> 'version'));
end $$;

create function public.acknowledge_clinic_privacy_notice(p_operation_key uuid, p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.clinics; v_prev jsonb; v_ver text; v_g uuid; v_id uuid;
begin
  if auth.uid() is null or not private.session_ok() then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select * into c from public.clinics where id = p_clinic_id and status = 'active';
  if c.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_ver := c.operational_policy -> 'privacyNotice' ->> 'version';
  if v_ver is null then raise exception 'this clinic has no privacy notice to accept' using errcode = 'CV409'; end if;
  v_prev := private.begin_command(c.organization_id, p_operation_key, 'privacy.acknowledge_clinic', jsonb_build_object('c', p_clinic_id, 'v', v_ver));
  if v_prev is not null then return v_prev; end if;
  if not private.guardian_ack_version(c.organization_id, v_ver) then
    v_g := private.ensure_guardian(c.organization_id);
    insert into public.privacy_records (organization_id, guardian_id, purpose, record_type, notice_version, decision, created_by)
    values (c.organization_id, v_g, 'care_records', 'notice_acknowledgement', v_ver, 'acknowledged', auth.uid()) returning id into v_id;
    perform private.audit(c.organization_id, 'guardian', 'privacy.acknowledged', 'clinic', p_clinic_id, null, jsonb_build_object('version', v_ver), null);
  end if;
  return private.finish_command(c.organization_id, p_operation_key, jsonb_build_object('version', v_ver, 'acknowledged', true));
end $$;

create function private.require_privacy_ack(p_clinic uuid) returns void language plpgsql stable security definer set search_path = '' as $$
declare c public.clinics; v_ver text;
begin
  select * into c from public.clinics where id = p_clinic;
  if c.id is null then return; end if;
  v_ver := c.operational_policy -> 'privacyNotice' ->> 'version';
  if v_ver is not null and auth.uid() is not null and not private.guardian_ack_version(c.organization_id, v_ver) then
    raise exception 'please read and accept the clinic''s privacy notice first' using errcode = 'CV409';
  end if;
end $$;

-- The two guardian self-service entry points check the acknowledgement first, then run the original commands unchanged.
alter function public.create_child_provisional(uuid, uuid, jsonb, text) rename to create_child_provisional_base;
alter function public.request_guardian_link(uuid, uuid, jsonb, text) rename to request_guardian_link_base;
revoke all on function public.create_child_provisional_base(uuid, uuid, jsonb, text), public.request_guardian_link_base(uuid, uuid, jsonb, text) from public, anon, authenticated;

create function public.create_child_provisional(p_operation_key uuid, p_clinic_id uuid, p_child jsonb, p_relationship text default 'mother') returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform private.require_privacy_ack(p_clinic_id);
  return public.create_child_provisional_base(p_operation_key, p_clinic_id, p_child, p_relationship);
end $$;

create function public.request_guardian_link(p_operation_key uuid, p_clinic_id uuid, p_descriptor jsonb, p_relationship text default 'other') returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform private.require_privacy_ack(p_clinic_id);
  return public.request_guardian_link_base(p_operation_key, p_clinic_id, p_descriptor, p_relationship);
end $$;

-- ---------------------------------------------------------------------------------------------
-- Follow-up worklist
-- ---------------------------------------------------------------------------------------------
create table public.followup_snapshots (
  child_id uuid primary key references public.children (id),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  computed_at timestamptz not null default now(),
  as_of date not null,
  schedule_version_id uuid,
  status text not null check (status in ('evaluated','no_active_schedule')),
  behind integer not null default 0,
  due integer not null default 0,
  review integer not null default 0,
  needs jsonb not null default '[]'::jsonb,
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id)
);
create index followup_snapshots_clinic_idx on public.followup_snapshots (clinic_id, behind desc, due desc);

create table public.followup_attempts (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  child_id uuid not null,
  outcome text not null check (outcome in ('reached','no_answer','wrong_number','refused','will_visit','moved_away','other')),
  note text check (note is null or length(note) <= 300),
  next_try_on date,
  recorded_by uuid not null references public.profiles (id),
  recorded_at timestamptz not null default now(),
  operation_id uuid not null unique,
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, child_id) references public.children (organization_id, id)
);
create index followup_attempts_idx on public.followup_attempts (child_id, recorded_at desc);
create trigger followup_attempts_immutable before update or delete on public.followup_attempts for each row execute function private.forbid_change();
create trigger followup_attempts_no_truncate before truncate on public.followup_attempts for each statement execute function private.forbid_change();
alter table public.followup_snapshots enable row level security;
alter table public.followup_attempts enable row level security;
revoke all on public.followup_snapshots, public.followup_attempts from anon, authenticated;

create function private.followup_is_stale(p_org uuid, p_dob date, p_today date, p_computed timestamptz, p_version uuid, p_has boolean) returns boolean
language sql stable security definer set search_path = '' as $$
  select not p_has or p_computed < now() - interval '24 hours' or p_version is distinct from private.active_schedule_for(p_org, 'routine', p_dob, p_today)
$$;

-- Recomputes snapshots for the children whose snapshot is missing or older than 24 hours (oldest first). Bounded per call.
create function public.refresh_followup(p_operation_key uuid, p_clinic_id uuid, p_batch integer default 100) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_today date; r record; v_res jsonb; v_n int := 0; v_needs jsonb; v_behind int; v_due int; v_review int; v_batch int := least(greatest(coalesce(p_batch, 100), 1), 200); v_left int; v_ver uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['bhw.followup','child.read_clinical']);
  v_prev := private.begin_command(v_org, p_operation_key, 'followup.refresh', jsonb_build_object('c', p_clinic_id, 'b', v_batch));
  if v_prev is not null then return v_prev; end if;
  v_today := private.local_today(p_clinic_id);
  for r in
    select c.id from public.children c join public.child_clinic_enrollments e on e.child_id = c.id and e.clinic_id = p_clinic_id and e.status = 'active'
      left join public.followup_snapshots s on s.child_id = c.id
     where c.merged_into_id is null and c.record_status = 'active' and c.deleted_at is null and private.followup_is_stale(c.organization_id, c.dob, v_today, s.computed_at, s.schedule_version_id, s.child_id is not null)
     order by s.computed_at nulls first, c.created_at limit v_batch
  loop
    v_res := private.compute_child_schedule(r.id, v_today, false);
    v_ver := private.active_schedule_for(v_org, 'routine', (select dob from public.children where id = r.id), v_today);
    if v_res ->> 'status' <> 'evaluated' then
      insert into public.followup_snapshots (child_id, organization_id, clinic_id, as_of, status, schedule_version_id) values (r.id, v_org, p_clinic_id, v_today, 'no_active_schedule', v_ver)
      on conflict (child_id) do update set computed_at = now(), as_of = v_today, status = 'no_active_schedule', behind = 0, due = 0, review = 0, needs = '[]'::jsonb, clinic_id = p_clinic_id, schedule_version_id = v_ver;
    else
      select coalesce(jsonb_agg(jsonb_build_object('requirement', x ->> 'requirement', 'status', x ->> 'status') order by (x ->> 'requirement')), '[]'::jsonb),
             count(*) filter (where x ->> 'status' in ('overdue','past_recommended_date')), count(*) filter (where x ->> 'status' in ('due_now','due_today')), count(*) filter (where x ->> 'status' = 'staff_review_needed')
        into v_needs, v_behind, v_due, v_review
        from jsonb_array_elements(v_res -> 'requirements') x where x ->> 'status' in ('overdue','past_recommended_date','due_now','due_today','staff_review_needed');
      insert into public.followup_snapshots (child_id, organization_id, clinic_id, as_of, status, behind, due, review, needs, schedule_version_id) values (r.id, v_org, p_clinic_id, v_today, 'evaluated', v_behind, v_due, v_review, v_needs, v_ver)
      on conflict (child_id) do update set computed_at = now(), as_of = v_today, status = 'evaluated', behind = v_behind, due = v_due, review = v_review, needs = v_needs, clinic_id = p_clinic_id, schedule_version_id = v_ver;
    end if;
    v_n := v_n + 1;
  end loop;
  select count(*) into v_left from public.children c join public.child_clinic_enrollments e on e.child_id = c.id and e.clinic_id = p_clinic_id and e.status = 'active'
    left join public.followup_snapshots s on s.child_id = c.id where c.merged_into_id is null and c.record_status = 'active' and private.followup_is_stale(c.organization_id, c.dob, v_today, s.computed_at, s.schedule_version_id, s.child_id is not null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('refreshed', v_n, 'remaining', v_left));
end $$;

create function public.list_followup_worklist(p_clinic_id uuid, p_filter text default 'behind', p_limit integer default 50) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_res jsonb; v_lim int := least(greatest(coalesce(p_limit, 50), 1), 100); v_today date; v_contact boolean;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['bhw.followup','child.read_clinical']);
  if p_filter not in ('behind','due','review','all') then raise exception 'unknown filter' using errcode = 'CV422'; end if;
  v_today := private.local_today(p_clinic_id);
  v_contact := private.has_capability(p_clinic_id, 'bhw.followup');
  select jsonb_build_object(
    'asOf', now(),
    'schedule', case when exists (select 1 from public.followup_snapshots where clinic_id = p_clinic_id and status = 'evaluated') then 'active' when exists (select 1 from public.followup_snapshots where clinic_id = p_clinic_id) then 'none' else 'unknown' end,
    'staleChildren', (select count(*) from public.children c join public.child_clinic_enrollments e on e.child_id = c.id and e.clinic_id = p_clinic_id and e.status = 'active'
                        left join public.followup_snapshots s on s.child_id = c.id where c.merged_into_id is null and c.record_status = 'active' and private.followup_is_stale(c.organization_id, c.dob, v_today, s.computed_at, s.schedule_version_id, s.child_id is not null)),
    'items', coalesce((select jsonb_agg(x.item order by x.ord1 desc, x.ord2 desc, x.ord3) from (
        select jsonb_build_object('childId', c.id, 'childName', c.display_name, 'recordNo', c.local_record_no, 'dob', c.dob, 'behind', s.behind, 'due', s.due, 'review', s.review, 'needs', s.needs, 'computedAt', s.computed_at,
                 'lastAttempt', (select jsonb_build_object('outcome', a.outcome, 'at', a.recorded_at, 'note', a.note, 'nextTryOn', a.next_try_on) from public.followup_attempts a where a.child_id = c.id order by a.recorded_at desc limit 1),
                 'attempts', (select count(*) from public.followup_attempts a where a.child_id = c.id),
                 'guardian', (select jsonb_build_object('name', g.full_name, 'phone', case when v_contact then g.contact_phone end, 'phoneChecked', g.contact_verified_at is not null)
                                from public.guardian_child_relationships r join public.guardians g on g.id = r.guardian_id where r.child_id = c.id and r.status = 'active' and g.deleted_at is null order by r.created_at limit 1)) item,
               s.behind ord1, s.due ord2, c.display_name ord3
          from public.followup_snapshots s join public.children c on c.id = s.child_id
         where s.clinic_id = p_clinic_id and s.status = 'evaluated'
           and ((p_filter = 'behind' and s.behind > 0) or (p_filter = 'due' and s.due > 0) or (p_filter = 'review' and s.review > 0) or (p_filter = 'all' and (s.behind + s.due + s.review) > 0))
           and not exists (select 1 from public.followup_attempts a where a.child_id = c.id and a.next_try_on > v_today and a.recorded_at = (select max(a2.recorded_at) from public.followup_attempts a2 where a2.child_id = c.id))
         order by s.behind desc, s.due desc, c.display_name limit v_lim) x), '[]'::jsonb)) into v_res;
  perform private.audit(v_org, case when v_contact then 'bhw.followup' else 'child.read_clinical' end, 'followup.listed', 'clinic', p_clinic_id, null, jsonb_build_object('filter', p_filter, 'shown', jsonb_array_length(v_res -> 'items')), null);
  return v_res;
end $$;

create function public.log_followup_attempt(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_outcome text, p_note text default null, p_next_try_on date default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_canon uuid; v_id uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['bhw.followup','child.read_clinical']);
  v_prev := private.begin_command(v_org, p_operation_key, 'followup.attempt', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 'o', p_outcome, 'n', p_note, 'd', p_next_try_on));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  if p_outcome not in ('reached','no_answer','wrong_number','refused','will_visit','moved_away','other') then raise exception 'choose what happened' using errcode = 'CV422'; end if;
  if p_next_try_on is not null and (p_next_try_on <= private.local_today(p_clinic_id) or p_next_try_on > private.local_today(p_clinic_id) + 180) then raise exception 'choose a date within the next 6 months' using errcode = 'CV422'; end if;
  insert into public.followup_attempts (organization_id, clinic_id, child_id, outcome, note, next_try_on, recorded_by, operation_id)
  values (v_org, p_clinic_id, v_canon, p_outcome, left(nullif(btrim(coalesce(p_note, '')), ''), 300), p_next_try_on, auth.uid(), p_operation_key) returning id into v_id;
  perform private.audit(v_org, 'bhw.followup', 'followup.attempt', 'child', v_canon, null, jsonb_build_object('outcome', p_outcome), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('attemptId', v_id));
end $$;

revoke all on function private.guardian_ack_version(uuid, text), private.require_privacy_ack(uuid), private.followup_is_stale(uuid, date, date, timestamptz, uuid, boolean) from public, anon, authenticated;
do $$
declare f text;
begin
  foreach f in array array[
    'place_clinical_hold(uuid,uuid,uuid,text,text,date,uuid)', 'release_clinical_hold(uuid,uuid,uuid,text)', 'list_clinical_holds(uuid,uuid)',
    'set_privacy_notice(uuid,uuid,text,text)', 'get_privacy_notice(uuid)', 'acknowledge_clinic_privacy_notice(uuid,uuid)',
    'create_child_provisional(uuid,uuid,jsonb,text)', 'request_guardian_link(uuid,uuid,jsonb,text)',
    'refresh_followup(uuid,uuid,integer)', 'list_followup_worklist(uuid,text,integer)', 'log_followup_attempt(uuid,uuid,uuid,text,text,date)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- A change to a child's history or holds makes the stored follow-up result untrustworthy: mark it stale so the next refresh recomputes it.
create function private.followup_invalidate() returns trigger language plpgsql security definer set search_path = '' as $$
declare v_child uuid := new.child_id;
begin
  update public.followup_snapshots set computed_at = now() - interval '1000 days' where child_id in (select private.child_ids_with_aliases(private.canonical_child(v_child)));
  return new;
end $$;
create trigger vaccination_revisions_followup after insert on public.vaccination_revisions for each row execute function private.followup_invalidate();
create trigger clinical_holds_followup after insert or update on public.clinical_holds for each row execute function private.followup_invalidate();
revoke all on function private.followup_invalidate() from public, anon, authenticated;
-- END 0022_followup_holds_privacy.sql

-- =====================================================================================================================
-- BEGIN 0023_record_transfer.sql  sha256=aec82a3f8294fcfcc74c1e84599bd6d82a01eb09921b41a940ea89e232efe3b5
-- =====================================================================================================================
-- 0023 Record transfer between clinics of the same organization. Blueprint refs: F26, BP17, BP33.
--  * A family that moves can have the child's record (enrollment) moved from one clinic to another. It needs three things, in order:
--    the guardian's consent (in the app, or recorded by staff who checked them in person), release by a clinical lead of the current
--    clinic, and acceptance by staff of the receiving clinic. Nothing moves before the last step.
--  * Nothing is copied or deleted: the record is one child in one organization. Access follows the enrollment, so the old clinic
--    loses access and the new clinic gains it at the moment of acceptance. History, certificates and audit stay as they are.
--  * Transfers between different organizations need a data-exchange agreement and are NOT supported (see external-validation.md).

create table public.record_transfers (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  child_id uuid not null,
  from_clinic_id uuid not null,
  to_clinic_id uuid not null,
  status text not null default 'requested' check (status in ('requested','ready','completed','declined','cancelled')),
  initiated_by uuid not null references public.profiles (id),
  consent_method text not null check (consent_method in ('app','in_person')),
  consent_at timestamptz not null default now(),
  consent_guardian_id uuid,
  reason text check (reason is null or length(reason) <= 300),
  release_by uuid references public.profiles (id),
  release_at timestamptz,
  decided_by uuid references public.profiles (id),
  decided_at timestamptz,
  decision_note text,
  completed_by uuid references public.profiles (id),
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  foreign key (organization_id, child_id) references public.children (organization_id, id),
  foreign key (organization_id, from_clinic_id) references public.clinics (organization_id, id),
  foreign key (organization_id, to_clinic_id) references public.clinics (organization_id, id),
  check (from_clinic_id <> to_clinic_id)
);
create unique index record_transfers_one_open_uq on public.record_transfers (child_id) where status in ('requested','ready');
create index record_transfers_from_idx on public.record_transfers (from_clinic_id, status);
create index record_transfers_to_idx on public.record_transfers (to_clinic_id, status);
create trigger record_transfers_no_delete before delete on public.record_transfers for each row execute function private.forbid_change();
create trigger record_transfers_no_truncate before truncate on public.record_transfers for each statement execute function private.forbid_change();
alter table public.record_transfers enable row level security;
revoke all on public.record_transfers from anon, authenticated;

create function private.transfer_target_ok(p_org uuid, p_from uuid, p_to uuid) returns void language plpgsql stable security definer set search_path = '' as $$
begin
  if p_to is null or p_to = p_from or not exists (select 1 from public.clinics where id = p_to and organization_id = p_org and status = 'active') then
    raise exception 'choose another active clinic in this organization' using errcode = 'CV422';
  end if;
end $$;

-- Guardian asks for their child's record to move (their request is their consent).
create function public.request_record_transfer_guardian(p_operation_key uuid, p_child_id uuid, p_to_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid; v_org uuid; v_from uuid; v_prev jsonb; v_id uuid; v_g uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then raise exception 'not found' using errcode = 'CV404'; end if;
  select organization_id into v_org from public.children where id = v_canon;
  select clinic_id into v_from from public.child_clinic_enrollments where child_id = v_canon and status = 'active' order by is_primary desc, created_at limit 1;
  if v_from is null then raise exception 'this child is not enrolled at a clinic yet' using errcode = 'CV409'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'transfer.request_guardian', jsonb_build_object('ch', v_canon, 'to', p_to_clinic_id));
  if v_prev is not null then return v_prev; end if;
  perform private.transfer_target_ok(v_org, v_from, p_to_clinic_id);
  if exists (select 1 from public.record_transfers where child_id = v_canon and status in ('requested','ready')) then raise exception 'a transfer for this child is already in progress' using errcode = 'CV409'; end if;
  select id into v_g from public.guardians where profile_id = auth.uid() and organization_id = v_org and deleted_at is null order by created_at limit 1;
  insert into public.record_transfers (organization_id, child_id, from_clinic_id, to_clinic_id, initiated_by, consent_method, consent_guardian_id)
  values (v_org, v_canon, v_from, p_to_clinic_id, auth.uid(), 'app', v_g) returning id into v_id;
  perform private.audit(v_org, 'guardian', 'transfer.requested', 'child', v_canon, null, jsonb_build_object('transferId', v_id, 'from', v_from, 'to', p_to_clinic_id), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transferId', v_id, 'status', 'requested'));
end $$;

-- Staff of the CURRENT clinic record that the guardian, checked in person, asked to move the record.
create function public.initiate_record_transfer_out(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_to_clinic_id uuid, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_canon uuid; v_id uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'guardian.verify');
  v_prev := private.begin_command(v_org, p_operation_key, 'transfer.initiate_out', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 'to', p_to_clinic_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not exists (select 1 from public.child_clinic_enrollments where child_id = v_canon and clinic_id = p_clinic_id and status = 'active') then return null; end if;
  perform private.transfer_target_ok(v_org, p_clinic_id, p_to_clinic_id);
  if not exists (select 1 from public.guardian_child_relationships where child_id = v_canon and status = 'active' and access_scope = 'full') then raise exception 'a verified guardian must ask for the transfer' using errcode = 'CV409'; end if;
  if exists (select 1 from public.record_transfers where child_id = v_canon and status in ('requested','ready')) then raise exception 'a transfer for this child is already in progress' using errcode = 'CV409'; end if;
  insert into public.record_transfers (organization_id, child_id, from_clinic_id, to_clinic_id, initiated_by, consent_method, reason)
  values (v_org, v_canon, p_clinic_id, p_to_clinic_id, auth.uid(), 'in_person', left(nullif(btrim(coalesce(p_reason, '')), ''), 300)) returning id into v_id;
  perform private.audit(v_org, 'guardian.verify', 'transfer.initiated', 'child', v_canon, null, jsonb_build_object('transferId', v_id, 'to', p_to_clinic_id), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transferId', v_id, 'status', 'requested'));
end $$;

-- A clinical lead of the current clinic releases the record.
create function public.approve_record_transfer_release(p_operation_key uuid, p_clinic_id uuid, p_transfer_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; t public.record_transfers;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'review.resolve');
  select * into t from public.record_transfers where id = p_transfer_id and organization_id = v_org and from_clinic_id = p_clinic_id for update;
  if t.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'transfer.release', jsonb_build_object('c', p_clinic_id, 't', p_transfer_id));
  if v_prev is not null then return v_prev; end if;
  if t.status <> 'requested' then raise exception 'this transfer is not waiting for release' using errcode = 'CV409'; end if;
  update public.record_transfers set status = 'ready', release_by = auth.uid(), release_at = now() where id = t.id;
  perform private.audit(v_org, 'review.resolve', 'transfer.released', 'child', t.child_id, jsonb_build_object('status', 'requested'), jsonb_build_object('status', 'ready'), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transferId', t.id, 'status', 'ready'));
end $$;

-- Staff of the RECEIVING clinic accept a released transfer. This is the moment access moves.
create function public.accept_record_transfer(p_operation_key uuid, p_clinic_id uuid, p_transfer_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; t public.record_transfers; v_cancelled int; a record;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'child.register');
  select * into t from public.record_transfers where id = p_transfer_id and organization_id = v_org and to_clinic_id = p_clinic_id for update;
  if t.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'transfer.accept', jsonb_build_object('c', p_clinic_id, 't', p_transfer_id));
  if v_prev is not null then return v_prev; end if;
  if t.status <> 'ready' then raise exception 'this transfer has not been released by the current clinic' using errcode = 'CV409'; end if;
  if exists (select 1 from public.encounters where child_id = t.child_id and clinic_id = t.from_clinic_id and status = 'open') then raise exception 'a visit is in progress at the current clinic; finish it first' using errcode = 'CV409'; end if;
  update public.child_clinic_enrollments set status = 'closed', ends_at = now(), is_primary = false, updated_by = auth.uid() where child_id = t.child_id and clinic_id = t.from_clinic_id and status in ('pending','active');
  update public.child_clinic_enrollments set is_primary = false, updated_by = auth.uid() where child_id = t.child_id and status = 'active';
  insert into public.child_clinic_enrollments (organization_id, child_id, clinic_id, status, is_primary, basis, created_by, updated_by)
  values (v_org, t.child_id, t.to_clinic_id, 'active', true, 'transfer', auth.uid(), auth.uid());
  -- Future bookings at the old clinic no longer apply; the family is told through the normal cancellation message.
  for a in select ap.id, ap.organization_id from public.appointments ap join public.clinic_sessions s on s.id = ap.session_id where ap.child_id = t.child_id and s.clinic_id = t.from_clinic_id and ap.status = 'confirmed' loop
    update public.appointments set status = 'cancelled', reason = 'record transferred to another clinic', updated_by = auth.uid() where id = a.id;
    update private.outbox_jobs set status = 'cancelled', updated_at = now() where organization_id = a.organization_id and status = 'queued' and dedupe_key = 'appt-confirm:' || a.id;
    perform private.enqueue(a.organization_id, 'appointment.cancellation', 'appointment', a.id, 'appt-cancel:' || a.id, '{}'::jsonb);
  end loop;
  get diagnostics v_cancelled = row_count;
  update public.record_transfers set status = 'completed', completed_by = auth.uid(), completed_at = now() where id = t.id;
  perform private.enqueue(v_org, 'record.transferred', 'record_transfer', t.id, 'record-transferred:' || t.id, jsonb_build_object('childId', t.child_id, 'toClinicId', t.to_clinic_id));
  perform private.audit(v_org, 'child.register', 'transfer.completed', 'child', t.child_id, jsonb_build_object('clinic', t.from_clinic_id), jsonb_build_object('clinic', t.to_clinic_id), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transferId', t.id, 'status', 'completed', 'childId', t.child_id));
end $$;

-- Either clinic (before completion) or the guardian may stop it.
create function public.decline_record_transfer(p_operation_key uuid, p_clinic_id uuid, p_transfer_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; t public.record_transfers;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  select * into t from public.record_transfers where id = p_transfer_id and organization_id = v_org and p_clinic_id in (from_clinic_id, to_clinic_id) for update;
  if t.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if p_clinic_id = t.from_clinic_id then perform private.require_capability(p_clinic_id, 'review.resolve'); else perform private.require_capability(p_clinic_id, 'child.register'); end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'transfer.decline', jsonb_build_object('c', p_clinic_id, 't', p_transfer_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  if t.status not in ('requested','ready') then raise exception 'this transfer is already closed' using errcode = 'CV409'; end if;
  update public.record_transfers set status = 'declined', decided_by = auth.uid(), decided_at = now(), decision_note = left(btrim(p_reason), 300) where id = t.id;
  perform private.audit(v_org, 'review.resolve', 'transfer.declined', 'child', t.child_id, jsonb_build_object('status', t.status), jsonb_build_object('status', 'declined'), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transferId', t.id, 'status', 'declined'));
end $$;

create function public.cancel_record_transfer_guardian(p_operation_key uuid, p_transfer_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_prev jsonb; t public.record_transfers;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select * into t from public.record_transfers where id = p_transfer_id for update;
  if t.id is null or not private.guardian_has_full_access(t.child_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(t.organization_id, p_operation_key, 'transfer.cancel', jsonb_build_object('t', p_transfer_id));
  if v_prev is not null then return v_prev; end if;
  if t.status not in ('requested','ready') then raise exception 'this transfer is already closed' using errcode = 'CV409'; end if;
  update public.record_transfers set status = 'cancelled', decided_by = auth.uid(), decided_at = now(), decision_note = 'cancelled by the guardian' where id = t.id;
  perform private.audit(t.organization_id, 'guardian', 'transfer.cancelled', 'child', t.child_id, jsonb_build_object('status', t.status), jsonb_build_object('status', 'cancelled'), null);
  return private.finish_command(t.organization_id, p_operation_key, jsonb_build_object('transferId', t.id, 'status', 'cancelled'));
end $$;

create function public.list_record_transfers(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['guardian.verify','review.resolve','child.register']);
  return jsonb_build_object(
    'outgoing', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'status', t.status, 'childId', t.child_id, 'childName', c.display_name, 'recordNo', c.local_record_no, 'toClinic', (select name from public.clinics where id = t.to_clinic_id),
                  'consent', t.consent_method, 'requestedAt', t.created_at, 'releasedAt', t.release_at, 'note', t.decision_note) order by t.created_at desc)
               from public.record_transfers t join public.children c on c.id = t.child_id where t.from_clinic_id = p_clinic_id and t.created_at > now() - interval '90 days'), '[]'::jsonb),
    'incoming', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'status', t.status, 'fromClinic', (select name from public.clinics where id = t.from_clinic_id), 'requestedAt', t.created_at, 'releasedAt', t.release_at, 'consent', t.consent_method,
                  'childName', case when t.status in ('ready','completed') then c.display_name end, 'recordNo', case when t.status in ('ready','completed') then c.local_record_no end,
                  'childId', case when t.status = 'completed' then t.child_id end) order by t.created_at desc)
               from public.record_transfers t join public.children c on c.id = t.child_id where t.to_clinic_id = p_clinic_id and t.created_at > now() - interval '90 days'), '[]'::jsonb),
    'clinics', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name) order by x.name) from public.clinics x where x.organization_id = v_org and x.status = 'active' and x.id <> p_clinic_id), '[]'::jsonb));
end $$;

create function public.my_record_transfers(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then return null; end if;
  return jsonb_build_object(
    'transfers', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'status', t.status, 'toClinic', (select name from public.clinics where id = t.to_clinic_id), 'fromClinic', (select name from public.clinics where id = t.from_clinic_id),
                  'requestedAt', t.created_at, 'completedAt', t.completed_at, 'note', t.decision_note) order by t.created_at desc) from public.record_transfers t where t.child_id = v_canon), '[]'::jsonb),
    'clinics', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name) order by x.name) from public.clinics x where x.organization_id = (select organization_id from public.children where id = v_canon) and x.status = 'active'
                          and x.id not in (select clinic_id from public.child_clinic_enrollments where child_id = v_canon and status in ('pending','active'))), '[]'::jsonb));
end $$;

-- Outbox: tell the family when the move is complete (wrapper keeps earlier handlers intact).
alter function private.handle_outbox_job(private.outbox_jobs) rename to handle_outbox_job_prev;
create function private.handle_outbox_job(j private.outbox_jobs) returns text
language plpgsql security definer set search_path = '' as $$
declare v_child public.children; v_clinic text;
begin
  if j.job_type = 'record.transferred' then
    select * into v_child from public.children where id = (j.payload ->> 'childId')::uuid;
    select name into v_clinic from public.clinics where id = (j.payload ->> 'toClinicId')::uuid;
    if v_child.id is null or v_clinic is null then return 'cancelled'; end if;
    perform private.notify_guardians(j.organization_id, v_child.id, 'record', 'Record moved to another clinic', format('%s''s record now belongs to %s. Book any new visits there.', v_child.display_name, v_clinic), j.dedupe_key,
      format('%s: your child''s record moved here. Details are in the app.', v_clinic));
    return 'done';
  end if;
  return private.handle_outbox_job_prev(j);
end $$;

revoke all on function private.transfer_target_ok(uuid, uuid, uuid), private.handle_outbox_job(private.outbox_jobs), private.handle_outbox_job_prev(private.outbox_jobs) from public, anon, authenticated;
do $$
declare f text;
begin
  foreach f in array array[
    'request_record_transfer_guardian(uuid,uuid,uuid)', 'initiate_record_transfer_out(uuid,uuid,uuid,uuid,text)', 'approve_record_transfer_release(uuid,uuid,uuid)', 'accept_record_transfer(uuid,uuid,uuid)',
    'decline_record_transfer(uuid,uuid,uuid,text)', 'cancel_record_transfer_guardian(uuid,uuid)', 'list_record_transfers(uuid)', 'my_record_transfers(uuid)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
-- END 0023_record_transfer.sql

-- =====================================================================================================================
-- BEGIN 0024_config_content_audit_ops.sql  sha256=b42e77d84c2139a8c2be738689171ff79d69eed48ea849704cc6975eaeb32b42
-- =====================================================================================================================
-- 0024 Clinic profile settings, reviewed care information, audit search and operations status.
-- Blueprint refs: P01, P13, P34, P37, P39, P40, F19, F23.
--  * Clinic contact details and opening hours are typed in by the clinic; the public pages show exactly that, or say nothing was configured.
--  * Care information is written by the clinic and approved by a second person before families can see it. The system ships none.
--  * The audit search is read-only and organization-wide for holders of audit.read; every search is itself audited.
--  * Operations status only reports facts that were recorded: an unknown health stays "unknown", never "ok".

-- ---------------------------------------------------------------------------------------------
-- Clinic profile
-- ---------------------------------------------------------------------------------------------
alter table public.clinics add column hours_text text check (hours_text is null or length(hours_text) <= 500);

create or replace function public.list_public_clinics() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'address', address, 'contact', contact_text, 'hours', hours_text) order by name), '[]'::jsonb)
    from public.clinics where status = 'active'
$$;

create function public.update_clinic_profile(p_operation_key uuid, p_clinic_id uuid, p_name text, p_address text, p_contact text, p_hours text, p_timezone text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; c public.clinics;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'admin.config');
  v_prev := private.begin_command(v_org, p_operation_key, 'clinic.profile', jsonb_build_object('c', p_clinic_id, 'n', p_name, 'a', p_address, 'ct', p_contact, 'h', p_hours, 'tz', p_timezone));
  if v_prev is not null then return v_prev; end if;
  if p_name is null or length(btrim(p_name)) = 0 or length(p_name) > 120 then raise exception 'enter the clinic name' using errcode = 'CV422'; end if;
  if p_timezone is null or not exists (select 1 from pg_timezone_names where name = p_timezone) then raise exception 'choose a valid time zone (for example Asia/Manila)' using errcode = 'CV422'; end if;
  if length(coalesce(p_address, '')) > 300 or length(coalesce(p_contact, '')) > 300 or length(coalesce(p_hours, '')) > 500 then raise exception 'one of the texts is too long' using errcode = 'CV422'; end if;
  select * into c from public.clinics where id = p_clinic_id for update;
  update public.clinics set name = btrim(p_name), address = btrim(coalesce(p_address, '')), contact_text = nullif(btrim(coalesce(p_contact, '')), ''), hours_text = nullif(btrim(coalesce(p_hours, '')), ''), timezone = p_timezone, updated_by = auth.uid()
   where id = p_clinic_id;
  perform private.audit(v_org, 'admin.config', 'clinic.profile_changed', 'clinic', p_clinic_id,
    jsonb_build_object('name', c.name, 'address', c.address, 'contact', c.contact_text, 'hours', c.hours_text, 'timezone', c.timezone),
    jsonb_build_object('name', btrim(p_name), 'address', btrim(coalesce(p_address, '')), 'contact', nullif(btrim(coalesce(p_contact, '')), ''), 'hours', nullif(btrim(coalesce(p_hours, '')), ''), 'timezone', p_timezone), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('clinicId', p_clinic_id));
end $$;

create function public.get_clinic_profile(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform private.require_capability(p_clinic_id, 'admin.config');
  return (select jsonb_build_object('name', name, 'address', address, 'contact', contact_text, 'hours', hours_text, 'timezone', timezone) from public.clinics where id = p_clinic_id);
end $$;

-- ---------------------------------------------------------------------------------------------
-- Reviewed care information (P13, P37)
-- ---------------------------------------------------------------------------------------------
create table public.content_items (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  clinic_id uuid not null,
  code text not null check (code ~ '^[a-z0-9][a-z0-9-]{1,58}$'),
  created_by uuid not null references public.profiles (id),
  created_at timestamptz not null default now(),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  unique (clinic_id, code),
  unique (organization_id, id)
);
create table public.content_versions (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  item_id uuid not null,
  language text not null check (language in ('en','fil')),
  title text not null check (length(btrim(title)) between 3 and 150),
  body text not null check (length(btrim(body)) between 20 and 4000),
  source_reference text not null check (length(btrim(source_reference)) >= 3),
  status text not null default 'draft' check (status in ('draft','submitted','active','rejected','retired')),
  authored_by uuid not null references public.profiles (id),
  reviewed_by uuid references public.profiles (id),
  review_note text,
  reviewed_on date,
  created_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, item_id) references public.content_items (organization_id, id),
  check (reviewed_by is null or reviewed_by <> authored_by)
);
create unique index content_one_active_uq on public.content_versions (item_id, language) where status = 'active';
create index content_versions_item_idx on public.content_versions (item_id, status);
create function private.content_guard() returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_op = 'DELETE' then raise exception 'care information cannot be deleted' using errcode = 'CV403'; end if;
  if old.status <> 'draft' and (new.title, new.body, new.source_reference, new.language) is distinct from (old.title, old.body, old.source_reference, old.language) then
    raise exception 'submitted or published wording cannot be edited' using errcode = 'CV403';
  end if;
  return new;
end $$;
create trigger content_versions_guard before update or delete on public.content_versions for each row execute function private.content_guard();
create trigger content_versions_no_truncate before truncate on public.content_versions for each statement execute function private.forbid_change();
create trigger content_items_no_truncate before truncate on public.content_items for each statement execute function private.forbid_change();
alter table public.content_items enable row level security;
alter table public.content_versions enable row level security;
revoke all on public.content_items, public.content_versions from anon, authenticated;

create function public.save_content_draft(p_operation_key uuid, p_clinic_id uuid, p_code text, p_language text, p_title text, p_body text, p_source text, p_version_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_item uuid; v_ver public.content_versions;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if not (private.has_capability(p_clinic_id, 'admin.config') or private.has_capability(p_clinic_id, 'rules.propose')) then perform private.require_capability(p_clinic_id, 'admin.config'); end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'content.save', jsonb_build_object('c', p_clinic_id, 'code', p_code, 'l', p_language, 't', p_title, 'b', p_body, 's', p_source, 'v', p_version_id));
  if v_prev is not null then return v_prev; end if;
  if p_language not in ('en','fil') then raise exception 'choose a language' using errcode = 'CV422'; end if;
  if p_title is null or length(btrim(p_title)) < 3 or p_body is null or length(btrim(p_body)) < 20 then raise exception 'write a title and the full text (at least 20 characters)' using errcode = 'CV422'; end if;
  if p_source is null or length(btrim(p_source)) < 3 then raise exception 'name where this information comes from' using errcode = 'CV422'; end if;
  if p_version_id is null then
    if p_code is null or p_code !~ '^[a-z0-9][a-z0-9-]{1,58}$' then raise exception 'use a short code of lowercase letters, numbers and dashes' using errcode = 'CV422'; end if;
    insert into public.content_items (organization_id, clinic_id, code, created_by) values (v_org, p_clinic_id, p_code, auth.uid()) on conflict (clinic_id, code) do nothing;
    select id into v_item from public.content_items where clinic_id = p_clinic_id and code = p_code;
    if exists (select 1 from public.content_versions where item_id = v_item and language = p_language and status in ('draft','submitted')) then raise exception 'a version in this language is already being prepared' using errcode = 'CV409'; end if;
    insert into public.content_versions (organization_id, item_id, language, title, body, source_reference, authored_by) values (v_org, v_item, p_language, btrim(p_title), btrim(p_body), btrim(p_source), auth.uid()) returning * into v_ver;
  else
    select v.* into v_ver from public.content_versions v join public.content_items i on i.id = v.item_id where v.id = p_version_id and i.clinic_id = p_clinic_id for update of v;
    if v_ver.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
    if v_ver.status <> 'draft' then raise exception 'only a draft can be edited' using errcode = 'CV409'; end if;
    if v_ver.authored_by <> auth.uid() then raise exception 'only the author can edit a draft' using errcode = 'CV403'; end if;
    update public.content_versions set language = p_language, title = btrim(p_title), body = btrim(p_body), source_reference = btrim(p_source) where id = v_ver.id returning * into v_ver;
  end if;
  perform private.audit(v_org, 'admin.config', 'content.drafted', 'content_version', v_ver.id, null, jsonb_build_object('language', p_language), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', v_ver.id, 'status', 'draft'));
end $$;

create function public.submit_content(p_operation_key uuid, p_clinic_id uuid, p_version_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v public.content_versions;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select cv.* into v from public.content_versions cv join public.content_items i on i.id = cv.item_id where cv.id = p_version_id and i.clinic_id = p_clinic_id for update of cv;
  if v.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if v.authored_by <> auth.uid() then raise exception 'only the author can submit' using errcode = 'CV403'; end if;
  perform private.require_any(p_clinic_id, array['admin.config','rules.propose']);
  v_prev := private.begin_command(v_org, p_operation_key, 'content.submit', jsonb_build_object('c', p_clinic_id, 'v', p_version_id));
  if v_prev is not null then return v_prev; end if;
  if v.status <> 'draft' then raise exception 'only a draft can be submitted' using errcode = 'CV409'; end if;
  update public.content_versions set status = 'submitted' where id = v.id;
  perform private.audit(v_org, 'admin.config', 'content.submitted', 'content_version', v.id, null, null, null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', v.id, 'status', 'submitted'));
end $$;

create function public.review_content(p_operation_key uuid, p_clinic_id uuid, p_version_id uuid, p_decision text, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v public.content_versions; v_status text;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'rules.approve');
  select cv.* into v from public.content_versions cv join public.content_items i on i.id = cv.item_id where cv.id = p_version_id and i.clinic_id = p_clinic_id for update of cv;
  if v.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'content.review', jsonb_build_object('c', p_clinic_id, 'v', p_version_id, 'd', p_decision, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  if p_decision not in ('approve','reject') then raise exception 'choose approve or reject' using errcode = 'CV422'; end if;
  if p_decision = 'reject' and (p_note is null or length(btrim(p_note)) < 3) then raise exception 'say why it is rejected' using errcode = 'CV422'; end if;
  if v.status <> 'submitted' then raise exception 'only a submitted version can be reviewed' using errcode = 'CV409'; end if;
  if v.authored_by = auth.uid() then raise exception 'the author cannot approve their own wording' using errcode = 'CV403'; end if;
  v_status := case when p_decision = 'approve' then 'active' else 'rejected' end;
  if v_status = 'active' then
    update public.content_versions set status = 'retired' where item_id = v.item_id and language = v.language and status = 'active' and id <> v.id;
  end if;
  update public.content_versions set status = v_status, reviewed_by = auth.uid(), reviewed_on = (now() at time zone (select timezone from public.clinics where id = p_clinic_id))::date, review_note = left(nullif(btrim(coalesce(p_note, '')), ''), 300) where id = v.id;
  perform private.audit(v_org, 'rules.approve', 'content.' || v_status, 'content_version', v.id, jsonb_build_object('status', 'submitted'), jsonb_build_object('status', v_status), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', v.id, 'status', v_status));
end $$;

create function public.retire_content(p_operation_key uuid, p_clinic_id uuid, p_version_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v public.content_versions;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'rules.approve');
  select cv.* into v from public.content_versions cv join public.content_items i on i.id = cv.item_id where cv.id = p_version_id and i.clinic_id = p_clinic_id for update of cv;
  if v.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'content.retire', jsonb_build_object('c', p_clinic_id, 'v', p_version_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  if v.status <> 'active' then raise exception 'only published information can be withdrawn' using errcode = 'CV409'; end if;
  update public.content_versions set status = 'retired', review_note = left(btrim(p_reason), 300) where id = v.id;
  perform private.audit(v_org, 'rules.approve', 'content.retired', 'content_version', v.id, null, null, p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', v.id, 'status', 'retired'));
end $$;

create function public.list_content(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform private.require_any(p_clinic_id, array['admin.config','rules.propose','rules.approve']);
  return (select coalesce(jsonb_agg(jsonb_build_object('versionId', v.id, 'code', i.code, 'language', v.language, 'title', v.title, 'body', v.body, 'source', v.source_reference, 'status', v.status,
            'authoredBy', (select display_name from public.profiles where id = v.authored_by), 'authoredById', v.authored_by, 'reviewedBy', (select display_name from public.profiles where id = v.reviewed_by), 'reviewedOn', v.reviewed_on, 'reviewNote', v.review_note)
            order by i.code, v.language, v.created_at desc), '[]'::jsonb)
            from public.content_versions v join public.content_items i on i.id = v.item_id where i.clinic_id = p_clinic_id);
end $$;

-- Families see only ACTIVE (approved) information of the clinics their children belong to, in their language, with the English version marked as a fallback.
create function public.guardian_care_content() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_lang text;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.session_ok() then return null; end if;
  select coalesce((select preferred_language from public.guardians where profile_id = auth.uid() and deleted_at is null order by created_at limit 1), 'en') into v_lang;
  return (select coalesce(jsonb_agg(jsonb_build_object('code', x.code, 'title', x.title, 'body', x.body, 'source', x.source_reference, 'reviewedOn', x.reviewed_on, 'clinic', x.clinic, 'language', x.language, 'fallback', x.language <> v_lang) order by x.clinic, x.code), '[]'::jsonb)
    from (select distinct on (i.id) i.code, v.title, v.body, v.source_reference, v.reviewed_on, v.language, c.name clinic
            from public.content_items i join public.clinics c on c.id = i.clinic_id join public.content_versions v on v.item_id = i.id and v.status = 'active'
           where i.clinic_id in (select e.clinic_id from public.child_clinic_enrollments e join public.guardian_child_relationships r on r.child_id = e.child_id join public.guardians g on g.id = r.guardian_id
                                  where g.profile_id = auth.uid() and e.status in ('pending','active') and r.status = 'active' and r.access_scope = 'full')
           order by i.id, (v.language = v_lang) desc, v.reviewed_on desc) x);
end $$;

-- ---------------------------------------------------------------------------------------------
-- Audit search (P39)
-- ---------------------------------------------------------------------------------------------
create function public.search_audit(p_clinic_id uuid, p_action text default null, p_actor uuid default null, p_from timestamptz default null, p_to timestamptz default null, p_before timestamptz default null, p_limit integer default 50) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_lim int := least(greatest(coalesce(p_limit, 50), 1), 100); v_rows jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'audit.read');
  if p_from is not null and p_to is not null and p_to < p_from then raise exception 'the end of the period is before its start' using errcode = 'CV422'; end if;
  select coalesce(jsonb_agg(x.j order by x.t desc), '[]'::jsonb) into v_rows from (
    select a.server_time t, jsonb_build_object('id', a.id, 'at', a.server_time, 'action', a.action, 'capability', a.actor_capability, 'entityType', a.entity_type, 'entityId', a.entity_id, 'outcome', a.outcome, 'reason', a.reason,
             'actor', (select display_name from public.profiles where id = a.actor_id), 'actorId', a.actor_id, 'system', a.system_job_id, 'before', a.before, 'after', a.after) j
      from private.audit_logs a
     where a.organization_id = v_org and (p_action is null or a.action like replace(replace(p_action, '%', ''), '_', '\_') || '%') and (p_actor is null or a.actor_id = p_actor)
       and (p_from is null or a.server_time >= p_from) and (p_to is null or a.server_time <= p_to) and (p_before is null or a.server_time < p_before)
     order by a.server_time desc limit v_lim) x;
  perform private.audit(v_org, 'audit.read', 'audit.searched', 'clinic', p_clinic_id, null, jsonb_build_object('action', p_action, 'actor', p_actor, 'from', p_from, 'to', p_to, 'returned', jsonb_array_length(v_rows)), null);
  return jsonb_build_object('rows', v_rows, 'nextBefore', case when jsonb_array_length(v_rows) = v_lim then (v_rows -> (v_lim - 1)) ->> 'at' end);
end $$;

-- ---------------------------------------------------------------------------------------------
-- Operations status (P40): only recorded facts
-- ---------------------------------------------------------------------------------------------
create table public.ops_checks (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  kind text not null check (kind in ('restore_drill','database_backup','file_backup')),
  result text not null check (result in ('passed','failed')),
  performed_on date not null check (performed_on <= current_date + 1),
  evidence text not null check (length(btrim(evidence)) >= 5),
  recorded_by uuid not null references public.profiles (id),
  recorded_at timestamptz not null default now()
);
create trigger ops_checks_immutable before update or delete on public.ops_checks for each row execute function private.forbid_change();
create trigger ops_checks_no_truncate before truncate on public.ops_checks for each statement execute function private.forbid_change();
alter table public.ops_checks enable row level security;
revoke all on public.ops_checks from anon, authenticated;

create function public.record_ops_check(p_operation_key uuid, p_clinic_id uuid, p_kind text, p_result text, p_performed_on date, p_evidence text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_id uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'admin.config');
  v_prev := private.begin_command(v_org, p_operation_key, 'ops.check', jsonb_build_object('c', p_clinic_id, 'k', p_kind, 'r', p_result, 'd', p_performed_on, 'e', p_evidence));
  if v_prev is not null then return v_prev; end if;
  if p_kind not in ('restore_drill','database_backup','file_backup') or p_result not in ('passed','failed') then raise exception 'choose what was checked and the result' using errcode = 'CV422'; end if;
  if p_performed_on is null or p_performed_on > private.local_today(p_clinic_id) then raise exception 'the date cannot be in the future' using errcode = 'CV422'; end if;
  if p_evidence is null or length(btrim(p_evidence)) < 5 then raise exception 'say where the evidence is (a ticket, log or document reference)' using errcode = 'CV422'; end if;
  insert into public.ops_checks (organization_id, kind, result, performed_on, evidence, recorded_by) values (v_org, p_kind, p_result, p_performed_on, left(btrim(p_evidence), 300), auth.uid()) returning id into v_id;
  perform private.audit(v_org, 'admin.config', 'ops.check_recorded', 'clinic', p_clinic_id, null, jsonb_build_object('kind', p_kind, 'result', p_result), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('checkId', v_id));
end $$;

create function public.get_ops_status(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; k text; v_checks jsonb := '{}'::jsonb; r public.ops_checks;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['admin.config','audit.read']);
  foreach k in array array['restore_drill','database_backup','file_backup'] loop
    select * into r from public.ops_checks where organization_id = v_org and kind = k order by performed_on desc, recorded_at desc limit 1;
    v_checks := v_checks || jsonb_build_object(k, case when r.id is null then null else jsonb_build_object('result', r.result, 'performedOn', r.performed_on, 'evidence', r.evidence, 'daysAgo', private.local_today(p_clinic_id) - r.performed_on) end);
  end loop;
  return jsonb_build_object('checks', v_checks,
    'jobs', jsonb_build_object('queued', (select count(*) from private.outbox_jobs where organization_id = v_org and status = 'queued'), 'processing', (select count(*) from private.outbox_jobs where organization_id = v_org and status = 'processing'),
      'failed', (select count(*) from private.outbox_jobs where organization_id = v_org and status = 'failed'), 'oldestQueuedMinutes', (select extract(epoch from (now() - min(available_at)))::int / 60 from private.outbox_jobs where organization_id = v_org and status = 'queued' and available_at <= now())),
    'sms', private.sms_backlog(v_org),
    'lastAudit', (select max(server_time) from private.audit_logs where organization_id = v_org));
end $$;

revoke all on function private.content_guard() from public, anon, authenticated;
do $$
declare f text;
begin
  foreach f in array array[
    'update_clinic_profile(uuid,uuid,text,text,text,text,text)', 'get_clinic_profile(uuid)', 'save_content_draft(uuid,uuid,text,text,text,text,text,uuid)', 'submit_content(uuid,uuid,uuid)', 'review_content(uuid,uuid,uuid,text,text)',
    'retire_content(uuid,uuid,uuid,text)', 'list_content(uuid)', 'guardian_care_content()', 'search_audit(uuid,text,uuid,timestamptz,timestamptz,timestamptz,integer)', 'record_ops_check(uuid,uuid,text,text,date,text)', 'get_ops_status(uuid)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
-- END 0024_config_content_audit_ops.sql

-- =====================================================================================================================
-- BEGIN 0025_scheduling_integrity.sql  sha256=a89d1b76b414fad4baba3ebbccb9dd2df11602f6c56cc284cf3023ae1a481a97
-- =====================================================================================================================
-- Serialize child scheduling with transfer/merge. Retain the original command bodies
-- as private-to-the-API implementation functions so existing receipts and audits stay intact.
alter function public.book_appointment(uuid,uuid,uuid,text,text[]) rename to book_appointment_prev;
alter function public.reschedule_appointment(uuid,uuid,uuid,text) rename to reschedule_appointment_prev;
alter function public.check_in(uuid,uuid,uuid,uuid,text) rename to check_in_prev;
alter function public.merge_children(uuid,uuid,uuid,uuid,text) rename to merge_children_prev;
alter function public.accept_record_transfer(uuid,uuid,uuid) rename to accept_record_transfer_prev;
alter function public.queue_transition(uuid,uuid,uuid,text,integer,text,text,text) rename to queue_transition_prev;

create function private.scheduling_replay(p_org uuid, p_key uuid, p_type text, p_payload jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r private.command_receipts; v_hash text;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select * into r from private.command_receipts where organization_id = p_org and operation_key = p_key;
  if r.id is null then return null; end if;
  v_hash := encode(sha256(convert_to(coalesce(p_payload, '{}'::jsonb)::text, 'UTF8')), 'hex');
  if r.actor_id <> auth.uid() or r.command_type <> p_type or r.payload_hash <> v_hash then
    raise exception 'operation key reused with different content' using errcode = 'CV409';
  end if;
  return r.result;
end $$;

create function public.book_appointment(p_operation_key uuid, p_child_id uuid, p_session_id uuid, p_reason text default null, p_rule_codes text[] default '{}') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_child uuid; v_clinic uuid; v_org uuid; v_replay jsonb;
begin
  select organization_id, clinic_id into v_org, v_clinic from public.clinic_sessions where id = p_session_id;
  v_child := private.canonical_child(p_child_id);
  if private.can_book_for(v_child, v_clinic) is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_replay := private.scheduling_replay(v_org, p_operation_key, 'appointment.book', jsonb_build_object('child', p_child_id, 'session', p_session_id, 'reason', p_reason, 'rules', to_jsonb(coalesce(p_rule_codes, '{}'))));
  if v_replay is not null then return v_replay; end if;
  perform 1 from public.children where id = v_child for update;
  if private.guardian_has_full_access(v_child) and not private.child_in_clinic(v_child, v_clinic) then
    raise exception 'not found' using errcode = 'CV404';
  end if;
  return public.book_appointment_prev(p_operation_key, p_child_id, p_session_id, p_reason, p_rule_codes);
end $$;

create function public.reschedule_appointment(p_operation_key uuid, p_appointment_id uuid, p_new_session_id uuid, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_child uuid; v_clinic uuid; v_org uuid; v_replay jsonb;
begin
  select a.child_id, a.organization_id, s.clinic_id into v_child, v_org, v_clinic from public.appointments a join public.clinic_sessions s on s.id = a.session_id where a.id = p_appointment_id;
  if private.can_book_for(v_child, v_clinic) is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_replay := private.scheduling_replay(v_org, p_operation_key, 'appointment.reschedule', jsonb_build_object('a', p_appointment_id, 'n', p_new_session_id, 'r', p_reason));
  if v_replay is not null then return v_replay; end if;
  perform 1 from public.children where id = v_child for update;
  if v_child is not null and not private.child_in_clinic(v_child, v_clinic) then raise exception 'not found' using errcode = 'CV404'; end if;
  return public.reschedule_appointment_prev(p_operation_key, p_appointment_id, p_new_session_id, p_reason);
end $$;

create function public.check_in(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_appointment_id uuid default null, p_overflow_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_child uuid; v_session uuid; v_status text; v_today date; v_org uuid; v_replay jsonb;
begin
  perform private.require_capability(p_clinic_id, 'queue.manage');
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  v_replay := private.scheduling_replay(v_org, p_operation_key, 'queue.check_in', jsonb_build_object('c', p_clinic_id, 'child', p_child_id, 'a', p_appointment_id, 'o', p_overflow_reason));
  if v_replay is not null then return v_replay; end if;
  v_child := private.canonical_child(p_child_id);
  perform 1 from public.children where id = v_child for update;
  if p_appointment_id is not null then
    select a.session_id into v_session from public.appointments a where a.id = p_appointment_id and a.child_id = v_child;
    if v_session is not null then
      select status into v_status from public.clinic_sessions where id = v_session for update;
      if v_status = 'cancelled' then raise exception 'this session was cancelled' using errcode = 'CV409'; end if;
    end if;
  else
    v_today := private.local_today(p_clinic_id);
    -- All stations at this clinic/date hold the same lock through capacity check and insertion.
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_clinic_id::text || ':' || v_today::text, 0));
  end if;
  return public.check_in_prev(p_operation_key, p_clinic_id, p_child_id, p_appointment_id, p_overflow_reason);
end $$;

create function public.queue_transition(p_operation_key uuid, p_clinic_id uuid, p_entry_id uuid, p_to text, p_expected_version integer, p_station text default null, p_reason text default null, p_outcome text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_child uuid;
begin
  perform private.require_capability(p_clinic_id, 'queue.manage');
  select child_id into v_child from public.queue_entries where id = p_entry_id and clinic_id = p_clinic_id;
  perform 1 from public.children where id = v_child for update;
  return public.queue_transition_prev(p_operation_key, p_clinic_id, p_entry_id, p_to, p_expected_version, p_station, p_reason, p_outcome);
end $$;

create function public.accept_record_transfer(p_operation_key uuid, p_clinic_id uuid, p_transfer_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_child uuid; v_org uuid; v_replay jsonb;
begin
  perform private.require_capability(p_clinic_id, 'child.register');
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  v_replay := private.scheduling_replay(v_org, p_operation_key, 'transfer.accept', jsonb_build_object('c', p_clinic_id, 't', p_transfer_id));
  if v_replay is not null then return v_replay; end if;
  select child_id into v_child from public.record_transfers where id = p_transfer_id and to_clinic_id = p_clinic_id;
  perform 1 from public.children where id = v_child for update;
  return public.accept_record_transfer_prev(p_operation_key, p_clinic_id, p_transfer_id);
end $$;

create function public.merge_children(p_operation_key uuid, p_clinic_id uuid, p_survivor uuid, p_duplicate uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_result jsonb; v_org uuid; v_replay jsonb; a record;
begin
  perform private.require_capability(p_clinic_id, 'review.resolve');
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  v_replay := private.scheduling_replay(v_org, p_operation_key, 'child.merge', jsonb_build_object('clinic', p_clinic_id, 's', p_survivor, 'd', p_duplicate, 'reason', p_reason));
  if v_replay is not null then return v_replay; end if;
  perform 1 from public.children where id in (p_survivor, p_duplicate) order by id for update;
  if exists (select 1 from public.encounters where child_id in (p_survivor, p_duplicate) and status = 'open') then
    raise exception 'finish active visits before merging records' using errcode = 'CV409';
  end if;
  if exists (
    select 1 from public.queue_entries d join public.queue_entries s on s.child_id = p_survivor and s.clinic_id = d.clinic_id and s.service_date = d.service_date
     where d.child_id = p_duplicate and d.status in ('waiting','called','in_service','held') and s.status in ('waiting','called','in_service','held')
  ) then raise exception 'both records have an active ticket; resolve arrivals before merging' using errcode = 'CV409'; end if;
  if exists (
    select 1 from public.appointments d join public.appointments s on s.child_id = p_survivor and s.session_id = d.session_id
     where d.child_id = p_duplicate and d.status = 'checked_in' and s.status in ('confirmed','checked_in','fulfilled')
  ) then raise exception 'both records have an active booking; resolve arrivals before merging' using errcode = 'CV409'; end if;

  v_result := public.merge_children_prev(p_operation_key, p_clinic_id, p_survivor, p_duplicate, p_reason);
  -- Preserve one usable booking per session. The cancelled duplicate stays as an
  -- auditable historical row, while its queued confirmation is withdrawn.
  for a in select d.id from public.appointments d where d.child_id = p_duplicate and d.status = 'confirmed'
    and exists (select 1 from public.appointments s where s.child_id = p_survivor and s.session_id = d.session_id and s.status in ('confirmed','checked_in','fulfilled'))
  loop
    update public.appointments set status = 'cancelled', reason = 'duplicate child record merged with existing booking', updated_by = auth.uid() where id = a.id;
    update private.outbox_jobs set status = 'cancelled', updated_at = now() where organization_id = v_org and status = 'queued' and dedupe_key = 'appt-confirm:' || a.id;
    perform private.audit(v_org, 'review.resolve', 'appointment.merge_collision', 'appointment', a.id, null, jsonb_build_object('survivorChildId', p_survivor), p_reason);
  end loop;
  update public.appointments set child_id = p_survivor, updated_by = auth.uid() where child_id = p_duplicate and status in ('confirmed','checked_in');
  update public.queue_entries set child_id = p_survivor, updated_by = auth.uid() where child_id = p_duplicate and status in ('waiting','called','in_service','held');
  perform private.audit(v_org, 'review.resolve', 'child.merge_scheduling', 'child', p_duplicate, null, jsonb_build_object('survivorId', p_survivor), p_reason);
  return v_result;
end $$;

-- The old command bodies remain definer-only; the public signatures retain their grants.
revoke all on function public.book_appointment_prev(uuid,uuid,uuid,text,text[]), public.reschedule_appointment_prev(uuid,uuid,uuid,text),
  public.check_in_prev(uuid,uuid,uuid,uuid,text), public.merge_children_prev(uuid,uuid,uuid,uuid,text),
  public.accept_record_transfer_prev(uuid,uuid,uuid) from public, anon, authenticated;
revoke all on function public.queue_transition_prev(uuid,uuid,uuid,text,integer,text,text,text), private.scheduling_replay(uuid,uuid,text,jsonb) from public, anon, authenticated;
revoke all on function public.book_appointment(uuid,uuid,uuid,text,text[]), public.reschedule_appointment(uuid,uuid,uuid,text),
  public.check_in(uuid,uuid,uuid,uuid,text), public.merge_children(uuid,uuid,uuid,uuid,text),
  public.accept_record_transfer(uuid,uuid,uuid) from public, anon, authenticated;
revoke all on function public.queue_transition(uuid,uuid,uuid,text,integer,text,text,text) from public, anon, authenticated;
grant execute on function public.book_appointment(uuid,uuid,uuid,text,text[]), public.reschedule_appointment(uuid,uuid,uuid,text),
  public.check_in(uuid,uuid,uuid,uuid,text), public.merge_children(uuid,uuid,uuid,uuid,text),
  public.accept_record_transfer(uuid,uuid,uuid) to authenticated;
grant execute on function public.queue_transition(uuid,uuid,uuid,text,integer,text,text,text) to authenticated;

-- The same effective-date inputs are used for evaluation and backdated planned-dose checks.
create or replace function private.evaluate_rules(p_version uuid, p_dob date, p_dob_exact boolean, p_doses jsonb, p_holds jsonb, p_as_of date)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  r record; dep record; d record;
  v_state jsonb := '{}'::jsonb;         -- rule id -> {creditedOn, earliestEligibleOn}
  v_used text[] := '{}';
  v_flagged text[] := '{}';           -- doses already reported as outside limits: flagged once, at the first rule that rejects them
  v_out jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_unresolved jsonb := '[]'::jsonb;
  v_min_on date; v_max_on date; v_earliest date; v_cand date; v_projected boolean; v_pred_pending boolean;
  v_target date; v_ws date; v_we date; v_credit_id text; v_credit_on date; v_unval jsonb; v_status text; v_reasons jsonb;
  v_has_hold boolean; v_antigen text; v_dose_on date; v_bad text; v_recommended date; v_st jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_unresolved from jsonb_array_elements(p_doses) x where coalesce((x ->> 'unresolved')::boolean, false) and (x ->> 'on' is null or (x ->> 'on')::date <= p_as_of);

  for r in
    select sr.*, a.code as antigen_code from public.schedule_rules sr join public.antigens a on a.id = sr.antigen_id
     where sr.schedule_version_id = p_version order by sr.sequence_no
  loop
    v_reasons := '[]'::jsonb; v_unval := '[]'::jsonb; v_credit_id := null; v_credit_on := null;
    v_min_on := null; v_max_on := null; v_earliest := null; v_projected := false; v_pred_pending := false;
    v_target := null; v_ws := null; v_we := null; v_recommended := null;

    if p_dob_exact then
      v_min_on := private.add_age(p_dob, r.minimum_age);
      v_max_on := private.add_age(p_dob, r.maximum_age);
      v_earliest := v_min_on;
      for dep in select dd.*, dd.predecessor_rule_id as pid from public.schedule_rule_dependencies dd where dd.rule_id = r.id loop
        v_st := v_state -> dep.pid::text;
        if v_st ->> 'creditedOn' is not null then
          v_cand := private.add_interval((v_st ->> 'creditedOn')::date, dep.minimum_interval_value, dep.interval_unit);
        else
          v_pred_pending := true; v_projected := true;
          v_cand := private.add_interval((v_st ->> 'earliestEligibleOn')::date, dep.minimum_interval_value, dep.interval_unit);
        end if;
        v_earliest := greatest(v_earliest, v_cand);
      end loop;

      -- Credit the earliest unused dose that satisfies every limit of this rule.
      for d in
        select x.value as dose, (x.value ->> 'id') as did, (x.value ->> 'on')::date as don
          from jsonb_array_elements(p_doses) as x(value)
         where not coalesce((x.value ->> 'unresolved')::boolean, false)
           and (x.value ->> 'on')::date <= p_as_of
           and (x.value -> 'antigens') ? r.antigen_code
           and (jsonb_array_length(r.accepted_products) = 0 or r.accepted_products ? (x.value ->> 'product'))
         order by (x.value ->> 'on')::date, x.value ->> 'id'
      loop
        -- One physical dose may credit one requirement per antigen it contains (combination products, T08), never the same antigen twice.
        continue when (d.did || ':' || r.antigen_code) = any (v_used);
        v_bad := null;
        if v_pred_pending then v_bad := 'predecessor_not_credited';
        elsif v_min_on is not null and d.don < v_min_on then v_bad := 'given_before_minimum_age';
        elsif v_earliest is not null and d.don < v_earliest then v_bad := 'given_before_minimum_interval';
        elsif v_max_on is not null and d.don > v_max_on then v_bad := 'given_after_maximum_age';
        end if;
        if v_bad is null then
          v_credit_id := d.did; v_credit_on := d.don; v_used := v_used || (d.did || ':' || r.antigen_code);
          exit;
        else
          if not ((d.did || ':' || r.antigen_code) = any (v_flagged)) then
            v_unval := v_unval || jsonb_build_object('doseId', d.did, 'on', d.don, 'reason', v_bad);
            v_flagged := v_flagged || (d.did || ':' || r.antigen_code);
          end if;
        end if;
      end loop;

      v_target := private.add_age(p_dob, r.target_offset);
      v_ws := coalesce(private.add_age(p_dob, r.due_window -> 'start'), v_target);
      v_we := private.add_age(p_dob, r.due_window -> 'end');
      v_recommended := greatest(v_target, v_earliest);
    end if;

    v_state := v_state || jsonb_build_object(r.id::text, jsonb_build_object('creditedOn', v_credit_on, 'earliestEligibleOn', v_earliest));

    select exists (select 1 from jsonb_array_elements(p_holds) h where h ->> 'ruleId' is null or (h ->> 'ruleId') = r.id::text) into v_has_hold;

    if v_credit_id is not null then
      v_status := 'completed';
      v_reasons := jsonb_build_array(jsonb_build_object('code', 'credited_by_verified_dose', 'doseId', v_credit_id, 'on', v_credit_on));
    elsif not p_dob_exact then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'birth_date_not_exact'));
    elsif v_has_hold then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'clinical_hold'));
    elsif jsonb_array_length(v_unval) > 0 then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'dose_outside_rule_limits', 'doses', v_unval));
    elsif exists (select 1 from jsonb_array_elements(v_unresolved) u where (u -> 'antigens') ? r.antigen_code) then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'unresolved_history'));
    elsif r.review_conditions <> '[]'::jsonb then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'rule_requires_review', 'conditions', r.review_conditions));
    elsif v_max_on is not null and p_as_of > v_max_on then
      v_status := 'staff_review_needed'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'beyond_maximum_age', 'on', v_max_on));
    elsif v_pred_pending then
      v_status := 'not_yet_eligible'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'predecessor_pending'));
    elsif v_earliest is not null and p_as_of < v_earliest then
      v_status := 'not_yet_eligible'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'before_earliest_eligible', 'on', v_earliest));
    elsif v_we is not null and p_as_of > v_we then
      v_status := 'overdue'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'after_due_window', 'on', v_we));
    elsif v_target is not null and p_as_of = v_target then
      v_status := 'due_today'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'target_date_is_today'));
    elsif v_ws is not null and v_we is not null and p_as_of >= v_ws then
      v_status := 'due_now'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'within_due_window'));
    elsif v_target is not null and p_as_of > v_target then
      -- No approved overdue threshold: never invent one (BP16). "Past recommended date — review with clinic".
      v_status := 'past_recommended_date'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'past_target_without_overdue_threshold', 'on', v_target));
    elsif v_ws is not null and p_as_of >= v_ws then
      v_status := 'due_now'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'window_open'));
    elsif v_target is null and v_ws is null then
      v_status := 'due_now'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'eligible_no_timing_guidance'));
    else
      v_status := 'upcoming'; v_reasons := jsonb_build_array(jsonb_build_object('code', 'target_in_future'));
    end if;

    v_summary := v_summary || jsonb_build_object(v_status, coalesce((v_summary ->> v_status)::int, 0) + 1);
    v_out := v_out || jsonb_build_object(
      'ruleId', r.id, 'requirement', r.requirement_code, 'antigen', r.antigen_code, 'series', r.series_code, 'ordinal', r.dose_ordinal,
      'status', v_status, 'reasons', v_reasons, 'earliestEligibleOn', v_earliest, 'projected', v_projected,
      'targetOn', v_target, 'recommendedOn', v_recommended, 'windowStart', v_ws, 'windowEnd', v_we, 'maximumAgeOn', v_max_on,
      'creditedDoseId', v_credit_id, 'creditedOn', v_credit_on);
  end loop;

  return jsonb_build_object('engineVersion', 'plpgsql-2', 'versionId', p_version, 'asOf', p_as_of, 'birthDateExact', p_dob_exact,
                            'requirements', v_out, 'summary', v_summary, 'unresolvedHistory', v_unresolved);
end $$;

create or replace function private.child_eval_inputs(p_child uuid, p_as_of date) returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_dob date; v_prec text; v_doses jsonb; v_holds jsonb; v_pending int; v_rev jsonb;
begin
  select dob, birth_date_precision into v_dob, v_prec from public.children where id = p_child;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', cr.id::text,
      'revisionId', cr.id, 'eventId', cr.event_id,
      'product', p.code,
      'antigens', coalesce((select jsonb_agg(a.code order by a.code) from public.product_antigens pa join public.antigens a on a.id = pa.antigen_id where pa.product_id = cr.product_id), '[]'::jsonb),
      'on', case when cr.date_precision = 'exact' then cr.administered_on end,
      'unresolved', cr.date_precision <> 'exact' or cr.administered_on is null or cr.product_id is null)
    order by cr.administered_on nulls last, cr.id), '[]'::jsonb)
    into v_doses
    from private.current_revisions cr left join public.vaccine_products p on p.id = cr.product_id
   where cr.child_id in (select private.child_ids_with_aliases(p_child))
     and cr.event_status = 'active' and cr.verification_status = 'verified'
     and (cr.administered_on is null or cr.administered_on <= p_as_of);
  select coalesce(jsonb_agg(jsonb_build_object('ruleId', h.rule_id, 'reason', h.reason_code)), '[]'::jsonb) into v_holds
    from public.clinical_holds h where h.child_id = p_child
      and (h.starts_at at time zone coalesce((select c.timezone from public.clinics c where c.id = h.placed_clinic_id), 'UTC'))::date <= p_as_of
      and (h.resolved_at is null or (h.resolved_at at time zone coalesce((select c.timezone from public.clinics c where c.id = h.placed_clinic_id), 'UTC'))::date > p_as_of);
  -- Unverified/pending evidence is counted for staff visibility but NEVER credited (T09).
  select count(*) into v_pending from private.current_revisions cr
   where cr.child_id in (select private.child_ids_with_aliases(p_child)) and cr.event_status = 'active' and cr.verification_status = 'pending_verification' and (cr.administered_on is null or cr.administered_on <= p_as_of);
  return jsonb_build_object('dob', v_dob, 'dobExact', v_prec = 'exact' and v_dob is not null, 'doses', v_doses, 'holds', v_holds, 'pendingEvidence', v_pending);
end $$;

create or replace function private.compute_child_schedule(p_child uuid, p_as_of date, p_persist boolean, p_program text default 'routine') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.children; v_ver uuid; v_in jsonb; v_res jsonb; v_hash text; v_eval uuid; sv public.schedule_versions; x jsonb; rr jsonb; v_dose jsonb;
begin
  select * into c from public.children where id = p_child;
  v_in := private.child_eval_inputs(p_child, p_as_of);
  v_ver := private.active_schedule_for(c.organization_id, p_program, c.dob, p_as_of);
  if v_ver is null then
    return jsonb_build_object('status', 'no_active_schedule', 'pendingEvidence', v_in -> 'pendingEvidence');
  end if;
  select * into sv from public.schedule_versions where id = v_ver;
  v_res := private.evaluate_rules(v_ver, c.dob, (v_in ->> 'dobExact')::boolean, v_in -> 'doses', v_in -> 'holds', p_as_of);
  v_res := v_res || jsonb_build_object('status', 'evaluated', 'versionLabel', sv.version_label, 'programCode', sv.program_code, 'isDemo', sv.is_demo,
                                       'pendingEvidence', v_in -> 'pendingEvidence', 'childId', p_child, 'dob', c.dob);
  if p_persist then
    v_hash := encode(sha256(convert_to(jsonb_build_object('dob', c.dob, 'exact', v_in -> 'dobExact', 'doses', v_in -> 'doses', 'holds', v_in -> 'holds',
                                                          'version', v_ver, 'engine', 'plpgsql-2')::text, 'UTF8')), 'hex');
    insert into public.schedule_evaluations (organization_id, child_id, schedule_version_id, as_of_date, engine_version, input_hash, result, created_by)
    values (c.organization_id, p_child, v_ver, p_as_of, 'plpgsql-2', v_hash, v_res, auth.uid())
    on conflict (child_id, schedule_version_id, as_of_date, engine_version, input_hash) do nothing returning id into v_eval;
    if v_eval is null then
      select id into v_eval from public.schedule_evaluations
       where child_id = p_child and schedule_version_id = v_ver and as_of_date = p_as_of and engine_version = 'plpgsql-2' and input_hash = v_hash;
    else
      for rr in select * from jsonb_array_elements(v_res -> 'requirements') loop
        if rr ->> 'creditedDoseId' is not null then
          insert into public.dose_credits (organization_id, evaluation_id, rule_id, vaccination_revision_id, credit_status, reason)
          values (c.organization_id, v_eval, (rr ->> 'ruleId')::uuid, (rr ->> 'creditedDoseId')::uuid, 'credited', 'credited_by_verified_dose');
        elsif jsonb_array_length(coalesce(rr -> 'reasons' -> 0 -> 'doses', '[]'::jsonb)) > 0 then
          v_dose := rr -> 'reasons' -> 0 -> 'doses' -> 0;
          insert into public.dose_credits (organization_id, evaluation_id, rule_id, vaccination_revision_id, credit_status, reason)
          values (c.organization_id, v_eval, (rr ->> 'ruleId')::uuid, (v_dose ->> 'doseId')::uuid, 'not_credited', v_dose ->> 'reason');
        end if;
      end loop;
    end if;
      -- Historical/future snapshots must not change the child's current assignment.
      -- A preview may already have persisted today's evaluation: assignment must
      -- also reconcile when the INSERT reuses that cached snapshot.
      if p_as_of = coalesce((select private.local_today(e.clinic_id) from public.child_clinic_enrollments e
                             where e.child_id = p_child and e.status = 'active'
                             order by e.is_primary desc, e.created_at limit 1), current_date) then
        update public.child_programs set status = 'ended', ends_on = p_as_of, updated_by = auth.uid()
         where child_id = p_child and program_code = sv.program_code and status = 'active' and schedule_version_id <> v_ver;
        insert into public.child_programs (organization_id, child_id, schedule_version_id, program_code, starts_on, assignment_reason, created_by, updated_by)
        values (c.organization_id, p_child, v_ver, sv.program_code, p_as_of, 'automatic', auth.uid(), auth.uid())
        on conflict do nothing;
      end if;
    v_res := v_res || jsonb_build_object('evaluationId', v_eval, 'inputHash', v_hash);
  end if;
  return v_res;
end $$;

create or replace function private.check_planned_dose(p_child uuid, p_product uuid, p_on date) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  c public.children; v_ver uuid; v_in jsonb; v_codes jsonb; v_pcode text; v_res jsonb; v_credited jsonb; v_flagged jsonb; v_blocking jsonb := '[]'::jsonb;
begin
  select * into c from public.children where id = p_child;
  v_ver := private.active_schedule_for(c.organization_id, 'routine', c.dob, p_on);
  if v_ver is null then return jsonb_build_object('evaluated', false, 'blocked', false, 'credited', '[]'::jsonb, 'reasons', '[]'::jsonb); end if;
  v_in := private.child_eval_inputs(p_child, p_on);
  if exists (select 1 from jsonb_array_elements(v_in -> 'holds') h) then
    return jsonb_build_object('evaluated', true, 'blocked', true, 'credited', '[]'::jsonb, 'reasons', jsonb_build_array('clinical_hold'));
  end if;
  if not (v_in ->> 'dobExact')::boolean then
    return jsonb_build_object('evaluated', true, 'blocked', true, 'credited', '[]'::jsonb, 'reasons', jsonb_build_array('birth_date_not_exact'));
  end if;
  select coalesce(jsonb_agg(a.code order by a.code), '[]'::jsonb), max(p.code) into v_codes, v_pcode
    from public.vaccine_products p left join public.product_antigens pa on pa.product_id = p.id left join public.antigens a on a.id = pa.antigen_id where p.id = p_product;
  v_res := private.evaluate_rules(v_ver, c.dob, true, (v_in -> 'doses') || jsonb_build_array(jsonb_build_object('id', 'new', 'antigens', v_codes, 'product', v_pcode, 'on', p_on, 'unresolved', false)), v_in -> 'holds', p_on);
  select coalesce(jsonb_agg(x ->> 'requirement'), '[]'::jsonb) into v_credited from jsonb_array_elements(v_res -> 'requirements') x where x ->> 'creditedDoseId' = 'new';
  select coalesce(jsonb_agg(jsonb_build_object('requirement', x ->> 'requirement', 'reason', d ->> 'reason')), '[]'::jsonb) into v_flagged
    from jsonb_array_elements(v_res -> 'requirements') x, jsonb_array_elements(coalesce(x -> 'reasons' -> 0 -> 'doses', '[]'::jsonb)) d where d ->> 'doseId' = 'new';
  return jsonb_build_object('evaluated', true, 'blocked', jsonb_array_length(v_flagged) > 0, 'credited', v_credited, 'reasons', v_flagged);
end $$;

create or replace function private.child_eval_inputs(p_child uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select private.child_eval_inputs(p_child, coalesce(
    (select private.local_today(e.clinic_id) from public.child_clinic_enrollments e
      where e.child_id = p_child and e.status = 'active' order by e.is_primary desc, e.created_at limit 1),
    current_date))
$$;

revoke all on function private.evaluate_rules(uuid,date,boolean,jsonb,jsonb,date), private.child_eval_inputs(uuid,date),
  private.child_eval_inputs(uuid), private.compute_child_schedule(uuid,date,boolean,text), private.check_planned_dose(uuid,uuid,date)
  from public, anon, authenticated;
-- END 0025_scheduling_integrity.sql

-- =====================================================================================================================
-- BEGIN 0026_ledger_reports_sms_integrity.sql  sha256=196fc19cc69049e062552070d3ce6fd6de7f8d69e01bb1d211da4bb5ff25e5ba
-- =====================================================================================================================
-- Ledger repair, report exports, and SMS lease completion. Forward-only integrity fixes.

-- Every inventory command resolves its organization before touching a balance. The organization
-- advisory lock precedes every balance lock, including first postings and count approvals.
create function private.stock_org_lock(p_org uuid, p_exclusive boolean default false) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  if p_org is null then raise exception 'organization is required' using errcode = 'CV422'; end if;
  if p_exclusive then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_org::text, 2605));
  else
    perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended(p_org::text, 2605));
  end if;
end $$;

-- Placeholder anchor for generated report replacements.

create or replace function private.inventory_org(p_clinic uuid, p_cap text default 'inventory.manage') returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare v_org uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic, p_cap);
  perform private.stock_org_lock(v_org);
  return v_org;
end $$;

-- Clinical administrations and corrections reach the primitive without inventory_org. This
-- check also covers any future command that uses the primitive directly.
create or replace function private.post_movement(p_org uuid, p_tx uuid, p_location uuid, p_lot uuid, p_delta numeric, p_key text) returns void
language plpgsql security definer set search_path = '' as $$
declare v_unit text; v_on numeric;
begin
  perform private.stock_org_lock(p_org);
  if p_delta = 0 then raise exception 'quantity must not be zero' using errcode = 'CV422'; end if;
  select p.stock_unit into v_unit from public.vaccine_lots l join public.vaccine_products p on p.id = l.product_id where l.id = p_lot and l.organization_id = p_org;
  if v_unit is null then raise exception 'unknown lot' using errcode = 'CV404'; end if;
  if p_delta < 0 then
    select on_hand into v_on from public.stock_balances where location_id = p_location and lot_id = p_lot for update;
    if coalesce(v_on, 0) + p_delta < 0 then raise exception 'insufficient stock' using errcode = 'CV409'; end if;
  end if;
  insert into public.stock_movements (organization_id, transaction_id, location_id, lot_id, quantity_delta, unit, movement_key, created_by)
  values (p_org, p_tx, p_location, p_lot, p_delta, v_unit, p_key, auth.uid());
end $$;

-- Defensive coverage for direct administrative inserts into the ledger. The trigger runs before
-- it takes the balance row lock; public roles still have no table write grant.
create or replace function private.apply_movement() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  perform private.stock_org_lock(new.organization_id);
  update public.stock_balances set on_hand = on_hand + new.quantity_delta, updated_at = now()
   where location_id = new.location_id and lot_id = new.lot_id;
  if not found then
    begin
      insert into public.stock_balances (organization_id, location_id, lot_id, on_hand) values (new.organization_id, new.location_id, new.lot_id, new.quantity_delta);
    exception when unique_violation then
      update public.stock_balances set on_hand = on_hand + new.quantity_delta, updated_at = now() where location_id = new.location_id and lot_id = new.lot_id;
    end;
  end if;
  return new;
end $$;

-- Reconciliation must not call inventory_org: a shared-to-exclusive advisory lock upgrade can
-- deadlock with another repair. Validate first, then take the required lock before the snapshot.
create or replace function public.reconcile_stock(p_operation_key uuid, p_clinic_id uuid, p_repair boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_diff jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'inventory.approve');
  perform private.stock_org_lock(v_org, coalesce(p_repair, false));
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.reconcile', jsonb_build_object('c', p_clinic_id, 'repair', p_repair));
  if v_prev is not null then return v_prev; end if;
  select coalesce(jsonb_agg(jsonb_build_object('locationId', x.location_id, 'lotId', x.lot_id, 'ledger', x.ledger, 'projection', x.projection)), '[]'::jsonb) into v_diff from (
    select coalesce(l.location_id, b.location_id) location_id, coalesce(l.lot_id, b.lot_id) lot_id, coalesce(l.q, 0) ledger, coalesce(b.on_hand, 0) projection
      from (select m.location_id, m.lot_id, sum(m.quantity_delta) q from public.stock_movements m join public.stock_locations s on s.id = m.location_id where s.clinic_id = p_clinic_id group by 1, 2) l
      full join (select b2.location_id, b2.lot_id, b2.on_hand from public.stock_balances b2 join public.stock_locations s on s.id = b2.location_id where s.clinic_id = p_clinic_id) b
        on b.location_id = l.location_id and b.lot_id = l.lot_id
     where coalesce(l.q, 0) <> coalesce(b.on_hand, 0)) x;
  if p_repair and jsonb_array_length(v_diff) > 0 then
    insert into public.stock_balances (organization_id, location_id, lot_id, on_hand)
    select v_org, (d ->> 'locationId')::uuid, (d ->> 'lotId')::uuid, (d ->> 'ledger')::numeric from jsonb_array_elements(v_diff) d
    on conflict (location_id, lot_id) do update set on_hand = excluded.on_hand, allocated = least(public.stock_balances.allocated, excluded.on_hand), updated_at = now();
  end if;
  update public.stock_balances b set reconciled_at = now() from public.stock_locations s where s.id = b.location_id and s.clinic_id = p_clinic_id and (p_repair or jsonb_array_length(v_diff) = 0);
  perform private.audit(v_org, 'inventory.approve', 'stock.reconciled', 'clinic', p_clinic_id, null, jsonb_build_object('mismatches', jsonb_array_length(v_diff), 'repaired', p_repair and jsonb_array_length(v_diff) > 0), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('mismatches', v_diff, 'repaired', p_repair and jsonb_array_length(v_diff) > 0));
end $$;

create function private.audit_report_access(p_org uuid, p_clinic uuid, p_report text, p_from date, p_to date, p_export boolean) returns void
language plpgsql security definer set search_path = '' as $$
begin
  perform private.audit(p_org, 'report.run', case when p_export then 'report.exported' else 'report.viewed' end,
    'clinic', p_clinic, null, jsonb_build_object('report', p_report, 'from', p_from, 'to', p_to,
    'smallCellThreshold', case when p_export then (select value from private.settings where key = 'report_small_cell_threshold') else null end), null);
end $$;

-- Report function replacements follow below.

create or replace function public.report_daily_activity(p_clinic_id uuid, p_from date, p_to date, p_export boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id); v_tz text; v_rows jsonb; v_supp boolean;
begin
  perform private.report_range(p_clinic_id, p_from, p_to);
  select timezone into v_tz from public.clinics where id = p_clinic_id;
  with days as (select d::date d from generate_series(p_from, p_to, interval '1 day') d),
  appt as (select s.service_date d,
             count(*) filter (where a.status in ('confirmed','checked_in','fulfilled')) booked,
             count(*) filter (where a.status = 'cancelled') cancelled,
             count(*) filter (where a.status = 'no_show') no_show
             from public.appointments a join public.clinic_sessions s on s.id = a.session_id
            where s.clinic_id = p_clinic_id and s.service_date between p_from and p_to group by 1),
  q as (select service_date d,
          count(*) filter (where status <> 'cancelled') arrivals,
          count(*) filter (where walk_in and status <> 'cancelled') walk_ins,
          count(*) filter (where status = 'completed') completed,
          count(*) filter (where status = 'deferred') deferred,
          count(*) filter (where status = 'left') left_n
          from public.queue_entries where clinic_id = p_clinic_id and service_date between p_from and p_to group by 1),
  v as (select cr.administered_on d, count(*) n from private.current_revisions cr
         where cr.clinic_id = p_clinic_id and cr.source = 'clinic_administered' and cr.event_status = 'active' and cr.administered_on between p_from and p_to group by 1),
  c as (select (ce.issued_at at time zone v_tz)::date d, count(*) n from public.certificates ce
         where ce.clinic_id = p_clinic_id and ce.issued_at is not null and (ce.issued_at at time zone v_tz)::date between p_from and p_to group by 1)
  select jsonb_agg(jsonb_build_object('date', days.d, 'booked', coalesce(appt.booked, 0), 'cancelled', coalesce(appt.cancelled, 0), 'noShow', coalesce(appt.no_show, 0),
           'arrivals', coalesce(q.arrivals, 0), 'walkIns', coalesce(q.walk_ins, 0), 'completed', coalesce(q.completed, 0), 'deferred', coalesce(q.deferred, 0), 'left', coalesce(q.left_n, 0),
           'vaccinationsGiven', private.export_cell(coalesce(v.n, 0), p_export), 'certificatesIssued', coalesce(c.n, 0)) order by days.d)
    into v_rows from days left join appt on appt.d = days.d left join q on q.d = days.d left join v on v.d = days.d left join c on c.d = days.d;
  v_supp := exists (select 1 from jsonb_array_elements(v_rows) r where r -> 'vaccinationsGiven' = 'null'::jsonb);
  perform private.audit_report_access(v_org, p_clinic_id, 'daily_activity', p_from, p_to, p_export);
  return jsonb_build_object('report', 'daily_activity', 'from', p_from, 'to', p_to, 'asOf', now(), 'suppressed', v_supp, 'definitions', private.report_definitions(), 'rows', coalesce(v_rows, '[]'::jsonb),
    'totals', case when v_supp then null else (select jsonb_build_object(
       'booked', sum((r ->> 'booked')::int), 'cancelled', sum((r ->> 'cancelled')::int), 'noShow', sum((r ->> 'noShow')::int), 'arrivals', sum((r ->> 'arrivals')::int), 'walkIns', sum((r ->> 'walkIns')::int),
       'completed', sum((r ->> 'completed')::int), 'deferred', sum((r ->> 'deferred')::int), 'left', sum((r ->> 'left')::int),
       'vaccinationsGiven', sum((r ->> 'vaccinationsGiven')::int), 'certificatesIssued', sum((r ->> 'certificatesIssued')::int)) from jsonb_array_elements(v_rows) r) end);
end $$;

create or replace function public.report_vaccinations_by_product(p_clinic_id uuid, p_from date, p_to date, p_export boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id); v_rows jsonb; v_supp boolean;
begin
  perform private.report_range(p_clinic_id, p_from, p_to);
  select coalesce(jsonb_agg(jsonb_build_object('productCode', x.code, 'product', x.name, 'count', private.export_cell(x.n, p_export)) order by x.name), '[]'::jsonb) into v_rows from (
    select p.code, p.name, count(*) n from private.current_revisions cr join public.vaccine_products p on p.id = cr.product_id
     where cr.clinic_id = p_clinic_id and cr.source = 'clinic_administered' and cr.event_status = 'active' and cr.administered_on between p_from and p_to group by p.code, p.name) x;
  v_supp := exists (select 1 from jsonb_array_elements(v_rows) r where r -> 'count' = 'null'::jsonb);
  perform private.audit_report_access(v_org, p_clinic_id, 'vaccinations_by_product', p_from, p_to, p_export);
  return jsonb_build_object('report', 'vaccinations_by_product', 'from', p_from, 'to', p_to, 'asOf', now(), 'suppressed', v_supp, 'definitions', private.report_definitions(), 'rows', v_rows,
    'total', case when v_supp then null else (select coalesce(sum((r ->> 'count')::int), 0) from jsonb_array_elements(v_rows) r) end);
end $$;

create or replace function public.report_stock_summary(p_clinic_id uuid, p_from date, p_to date, p_export boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id); v_tz text; v_rows jsonb;
begin
  perform private.report_range(p_clinic_id, p_from, p_to);
  select timezone into v_tz from public.clinics where id = p_clinic_id;
  select coalesce(jsonb_agg(jsonb_build_object('productCode', p.code, 'product', p.name, 'lot', l.manufacturer_lot, 'expiresOn', l.expires_on, 'disposition', l.global_disposition,
           'received', x.received, 'issued', x.issued, 'wastage', x.wastage, 'adjustments', x.adjustments, 'onHand', x.on_hand, 'ledgerTotal', x.ledger_total,
           'reconciles', x.on_hand = x.ledger_total) order by p.name, l.expires_on, l.manufacturer_lot), '[]'::jsonb) into v_rows
    from (select m.lot_id,
            coalesce(sum(m.quantity_delta) filter (where t.type = 'receipt' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) received,
            -coalesce(sum(m.quantity_delta) filter (where t.type in ('issue_administration') and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0)
              - coalesce(sum(m.quantity_delta) filter (where t.type = 'reversal' and t.reason like 'correction:%' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) issued,
            -coalesce(sum(m.quantity_delta) filter (where t.type = 'wastage' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) wastage,
            coalesce(sum(m.quantity_delta) filter (where t.type = 'adjustment' and (m.occurred_at at time zone v_tz)::date between p_from and p_to), 0) adjustments,
            coalesce((select sum(b.on_hand) from public.stock_balances b join public.stock_locations s2 on s2.id = b.location_id where b.lot_id = m.lot_id and s2.clinic_id = p_clinic_id), 0) on_hand,
            sum(m.quantity_delta) ledger_total
            from public.stock_movements m join public.stock_transactions t on t.id = m.transaction_id join public.stock_locations s on s.id = m.location_id
           where s.clinic_id = p_clinic_id group by m.lot_id) x
    join public.vaccine_lots l on l.id = x.lot_id join public.vaccine_products p on p.id = l.product_id;
  perform private.audit_report_access(v_org, p_clinic_id, 'stock_summary', p_from, p_to, p_export);
  return jsonb_build_object('report', 'stock_summary', 'from', p_from, 'to', p_to, 'asOf', now(), 'suppressed', false, 'definitions', private.report_definitions(), 'rows', v_rows);
end $$;

create or replace function public.report_paper_reconciliation(p_clinic_id uuid, p_from date, p_to date, p_export boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_rows jsonb; v_suppressed boolean;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if p_export then
    perform private.require_capability(p_clinic_id, 'report.run');
  elsif not (private.has_capability(p_clinic_id, 'report.run') or private.has_capability(p_clinic_id, 'vaccination.record')) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
  perform private.report_range(p_clinic_id, p_from, p_to);
  select coalesce(jsonb_agg(jsonb_build_object(
      'date', k.d, 'productCode', p.code, 'product', p.name,
      'paperCount', case when k.paper is null then null else private.export_cell(k.paper, p_export) end,
      'systemCount', private.export_cell(k.sys, p_export),
      'difference', case when p_export and (private.export_cell(k.paper, true) is null or private.export_cell(k.sys, true) is null)
                     then null else k.sys - coalesce(k.paper, 0) end,
      'status', case when p_export and (private.export_cell(k.paper, true) is null or private.export_cell(k.sys, true) is null)
                     then null when k.paper is null then 'no_paper_tally' when k.sys = k.paper then 'matches'
                     when k.sys > k.paper then 'system_higher' else 'paper_higher' end)
      || case when p_export then '{}'::jsonb else jsonb_build_object('note', k.note) end
      order by k.d, p.name), '[]'::jsonb) into v_rows
  from (
    select coalesce(s.d, t.d) d, coalesce(s.product_id, t.product_id) product_id, coalesce(s.n, 0) sys, t.paper_count paper, t.note
      from (select cr.administered_on d, cr.product_id, count(*) n from private.current_revisions cr
             where cr.clinic_id = p_clinic_id and cr.source = 'clinic_administered' and cr.event_status = 'active' and cr.administered_on between p_from and p_to group by 1, 2) s
      full join (select distinct on (service_date, product_id) service_date d, product_id, paper_count, note from public.paper_tallies
                  where clinic_id = p_clinic_id and service_date between p_from and p_to order by service_date, product_id, entered_at desc, id desc) t
        on t.d = s.d and t.product_id = s.product_id) k
  join public.vaccine_products p on p.id = k.product_id;
  v_suppressed := exists (select 1 from jsonb_array_elements(v_rows) r where r -> 'paperCount' = 'null'::jsonb or r -> 'systemCount' = 'null'::jsonb);
  perform private.audit_report_access(v_org, p_clinic_id, 'paper_reconciliation', p_from, p_to, p_export);
  return jsonb_build_object('report', 'paper_reconciliation', 'from', p_from, 'to', p_to, 'asOf', now(), 'suppressed', p_export and v_suppressed,
    'definitions', private.report_definitions(), 'rows', v_rows,
    'unresolved', case when p_export and v_suppressed then null else (select count(*) from jsonb_array_elements(v_rows) r where r ->> 'status' <> 'matches') end);
end $$;

-- Lease completion is bound to the claim generation. Remove the old five-argument entry point
-- so callers cannot bypass the generation check through a retained overload.
drop function private.mark_sms(uuid, text, text, text, text);
create function private.mark_sms(p_id uuid, p_expected_attempt integer, p_outcome text, p_provider text default null, p_provider_message_id text default null, p_error text default null) returns boolean
language plpgsql security definer set search_path = '' as $$
declare m public.sms_messages;
begin
  select * into m from public.sms_messages where id = p_id for update;
  if m.id is null or m.status <> 'sending' or m.attempt_count is distinct from p_expected_attempt
     or m.locked_until is null or m.locked_until <= now() then return false; end if;
  if p_outcome = 'sent' then
    update public.sms_messages set status = 'sent', provider = p_provider, provider_message_id = p_provider_message_id, locked_until = null, last_error_code = null, updated_at = now() where id = m.id;
  elsif p_outcome = 'retry' and m.attempt_count < 5 then
    update public.sms_messages set status = 'queued', locked_until = null, last_error_code = left(p_error, 60), available_at = now() + make_interval(mins => power(2, m.attempt_count)::int), updated_at = now() where id = m.id;
  else
    update public.sms_messages set status = 'failed', locked_until = null, last_error_code = left(coalesce(p_error, 'failed'), 60), updated_at = now() where id = m.id;
  end if;
  return true;
end $$;

revoke all on function private.stock_org_lock(uuid, boolean), private.inventory_org(uuid, text), private.post_movement(uuid, uuid, uuid, uuid, numeric, text),
  private.apply_movement(), private.audit_report_access(uuid, uuid, text, date, date, boolean), private.mark_sms(uuid, integer, text, text, text, text)
  from public, anon, authenticated;
-- END 0026_ledger_reports_sms_integrity.sql

-- =====================================================================================================================
-- BEGIN 0027_certificate_attestation.sql  sha256=41c288a0e876f943714c81be7f304041cf63648efef83c0f764abdc319c5f072
-- =====================================================================================================================
-- Bind each stored PDF to the frozen snapshot and the latest render token. Provision
-- the matching application/DB secret outside migrations; an absent secret fails closed.
create table private.certificate_render_secrets (
  id boolean primary key default true check (id),
  secret text not null check (length(secret) >= 32)
);
revoke all on private.certificate_render_secrets from public, anon, authenticated, service_role;

create or replace function public.begin_certificate_render(p_certificate_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.certificates; v_token text; v_hash text;
begin
  select * into c from public.certificates where id = p_certificate_id for update;
  if c.id is null or not private.has_capability(c.clinic_id, 'certificate.issue') then return null; end if;
  if c.status <> 'pending' then raise exception 'this certificate has already been issued' using errcode = 'CV409'; end if;
  v_token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  v_hash := encode(sha256(convert_to(v_token, 'UTF8')), 'hex');
  update public.certificates set verification_token_hash = v_hash where id = c.id;
  return jsonb_build_object('certificateId', c.id, 'certificateNo', c.certificate_no, 'token', v_token,
    'snapshot', c.snapshot, 'contentHash', c.content_hash, 'tokenHash', v_hash);
end $$;

drop function public.store_certificate_pdf(uuid, uuid, text, text);

create function public.store_certificate_pdf(
  p_operation_key uuid, p_certificate_id uuid, p_content_hash text, p_token_hash text,
  p_pdf_base64 text, p_sha256 text, p_attestation text
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare c public.certificates; v_prev jsonb; v_bytes bytea; old public.certificates;
  v_secret text; v_expected text; v_hash text := lower(p_sha256);
begin
  select * into c from public.certificates where id = p_certificate_id for update;
  if c.id is null or not private.has_capability(c.clinic_id, 'certificate.issue') then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(c.organization_id, p_operation_key, 'certificate.store',
    jsonb_build_object('c', p_certificate_id, 'content', p_content_hash, 'token', p_token_hash, 'pdf', v_hash));
  if v_prev is not null then return v_prev; end if;
  if c.status <> 'pending' then raise exception 'this certificate has already been issued' using errcode = 'CV409'; end if;
  if c.verification_token_hash is null then raise exception 'start rendering first' using errcode = 'CV409'; end if;
  if p_content_hash is distinct from c.content_hash or p_token_hash is distinct from c.verification_token_hash then
    raise exception 'this rendering was superseded' using errcode = 'CV409';
  end if;
  select secret into v_secret from private.certificate_render_secrets where id = true;
  if v_secret is null or length(v_secret) < 32 then raise exception 'certificate renderer is not configured' using errcode = 'CV503'; end if;
  if p_pdf_base64 is null or length(p_pdf_base64) > 2800000 then raise exception 'the document is too large' using errcode = 'CV422'; end if;
  begin v_bytes := decode(p_pdf_base64, 'base64'); exception when others then raise exception 'the document is not valid' using errcode = 'CV422'; end;
  if convert_from(substring(v_bytes from 1 for 5), 'SQL_ASCII') <> '%PDF-' then raise exception 'the document is not a PDF' using errcode = 'CV422'; end if;
  if encode(sha256(v_bytes), 'hex') <> coalesce(v_hash, '') then raise exception 'the document did not match its checksum' using errcode = 'CV422'; end if;
  v_expected := encode(extensions.hmac(convert_to(c.id::text || ':' || c.content_hash || ':' || c.verification_token_hash || ':' || v_hash, 'UTF8'),
    convert_to(v_secret, 'UTF8'), 'sha256'), 'hex');
  if p_attestation is null or p_attestation !~ '^[0-9a-f]{64}$' or p_attestation <> v_expected then
    raise exception 'certificate render attestation rejected' using errcode = 'CV403';
  end if;
  insert into private.certificate_documents (certificate_id, pdf, sha256) values (c.id, v_bytes, v_hash);
  update public.certificates set status = 'issued', issued_at = now() where id = c.id;
  if c.replaces_id is not null then
    select * into old from public.certificates where id = c.replaces_id for update;
    if old.status <> 'revoked' then
      update public.certificates set status = 'revoked', revoked_at = now(), revoked_by = auth.uid(),
        revocation_reason = 'Replaced by ' || c.certificate_no, review_needed = false where id = old.id;
      perform private.enqueue(c.organization_id, 'certificate.revoked', 'certificate', old.id, 'cert-revoked:' || old.id,
        jsonb_build_object('replacedBy', c.certificate_no));
    end if;
  end if;
  perform private.enqueue(c.organization_id, 'certificate.issued', 'certificate', c.id, 'cert-issued:' || c.id, '{}'::jsonb);
  perform private.audit(c.organization_id, 'certificate.issue', 'certificate.issued', 'certificate', c.id,
    jsonb_build_object('status', 'pending'), jsonb_build_object('status', 'issued', 'sha256', v_hash), null);
  return private.finish_command(c.organization_id, p_operation_key,
    jsonb_build_object('certificateId', c.id, 'certificateNo', c.certificate_no, 'status', 'issued'));
end $$;
revoke all on function public.store_certificate_pdf(uuid, uuid, text, text, text, text, text) from public, anon, authenticated;
grant execute on function public.store_certificate_pdf(uuid, uuid, text, text, text, text, text) to authenticated;
-- END 0027_certificate_attestation.sql

-- =====================================================================================================================
-- BEGIN 0028_runtime_roles.sql  sha256=298b80752ac6d0f90188c4aecb5b546b89e4122a366a8f22233de73c6b3db4f9
-- =====================================================================================================================
-- Non-login privilege groups. Provision login credentials separately; never embed passwords in migrations.
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'cvsrs_outbox_worker') then
    create role cvsrs_outbox_worker nologin nosuperuser nocreatedb nocreaterole noinherit nobypassrls;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'cvsrs_sms_webhook') then
    create role cvsrs_sms_webhook nologin nosuperuser nocreatedb nocreaterole noinherit nobypassrls;
  end if;
end $$;
grant usage on schema private to cvsrs_outbox_worker, cvsrs_sms_webhook;
grant execute on function private.process_outbox(integer), private.claim_sms(integer),
  private.mark_sms(uuid, integer, text, text, text, text) to cvsrs_outbox_worker;
grant execute on function private.record_sms_event(text, text, text, text, timestamptz) to cvsrs_sms_webhook;
-- No table grants or API membership. SECURITY DEFINER functions retain their existing empty search paths.
-- END 0028_runtime_roles.sql

-- =====================================================================================================================
-- BEGIN 0029_clinic_timezones.sql  sha256=6895986f78741a0d0313505d5e9d3c97f9c3d7ac59bcf41a8843dbad780484f8
-- =====================================================================================================================
-- Read-only timezone metadata for existing authorized views. Calendar dates remain dates.
create or replace function public.get_my_context() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'profileId', p.id, 'displayName', p.display_name, 'locale', p.locale, 'status', p.status,
    'mfa', private.mfa_ok(), 'demoMode', private.setting_bool('demo_mode'),
    'memberships', coalesce((
      select jsonb_agg(jsonb_build_object('membershipId', m.id, 'clinicId', m.clinic_id, 'clinicName', c.name,
        'clinicTimezone', c.timezone, 'role', m.role_code, 'status', m.status, 'validUntil', m.valid_until,
        'capabilities', to_jsonb(private.role_preset(m.role_code) || m.capabilities)))
      from public.staff_memberships m join public.clinics c on c.id = m.clinic_id and c.organization_id = m.organization_id
      where m.profile_id = p.id and c.status = 'active'
        and (m.status = 'pending_approval' or (m.status = 'active' and m.valid_from <= now() and (m.valid_until is null or m.valid_until > now())))), '[]'::jsonb))
  from public.profiles p where p.id = auth.uid() and p.status = 'active'
$$;

create or replace function public.my_children() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'childId', c.id, 'displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob, 'dobPrecision', c.birth_date_precision,
    'recordStatus', c.record_status, 'relationshipStatus', r.status, 'accessScope', r.access_scope, 'relationship', r.relationship,
    'clinicId', (select e.clinic_id from public.child_clinic_enrollments e where e.child_id = c.id and e.status in ('pending','active') order by e.is_primary desc, e.created_at limit 1),
    'clinicName', (select cl.name from public.child_clinic_enrollments e join public.clinics cl on cl.id = e.clinic_id
                    where e.child_id = c.id and e.status in ('pending','active') order by e.is_primary desc, e.created_at limit 1),
    'clinicTimezone', (select cl.timezone from public.child_clinic_enrollments e join public.clinics cl on cl.id = e.clinic_id
                    where e.child_id = c.id and e.status in ('pending','active') order by e.is_primary desc, e.created_at limit 1)
  ) order by c.display_name), '[]'::jsonb)
  from public.guardian_child_relationships r join public.children c on c.id = r.child_id
  where r.guardian_id in (select private.my_guardian_ids()) and r.status in ('provisional','active') and c.record_status <> 'merged'
$$;

create or replace function public.my_appointments() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('appointmentId', a.id, 'status', a.status, 'childId', c.id, 'childName', c.display_name, 'sessionId', s.id,
      'serviceDate', s.service_date, 'startsAt', s.starts_at, 'endsAt', s.ends_at, 'clinicId', s.clinic_id, 'clinicName', cl.name,
      'clinicTimezone', cl.timezone, 'serviceCode', s.service_code, 'version', a.version) order by s.starts_at desc), '[]'::jsonb)
    from public.appointments a join public.clinic_sessions s on s.id = a.session_id join public.children c on c.id = a.child_id join public.clinics cl on cl.id = s.clinic_id
   where private.guardian_has_full_access(a.child_id) and a.status in ('confirmed','checked_in','fulfilled','no_show','cancelled','rescheduled') and s.service_date >= current_date - 60
$$;

-- Existing grants on replaced functions are preserved by CREATE OR REPLACE.

create or replace function public.my_record_transfers(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then return null; end if;
  return jsonb_build_object(
    'transfers', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'status', t.status, 'toClinic', dst.name, 'fromClinic', src.name,
                  'fromClinicTimezone', src.timezone, 'requestedAt', t.created_at, 'completedAt', t.completed_at, 'note', t.decision_note) order by t.created_at desc)
      from public.record_transfers t join public.clinics src on src.id = t.from_clinic_id join public.clinics dst on dst.id = t.to_clinic_id
      where t.child_id = v_canon), '[]'::jsonb),
    'clinics', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name) order by x.name) from public.clinics x where x.organization_id = (select organization_id from public.children where id = v_canon) and x.status = 'active'
                          and x.id not in (select clinic_id from public.child_clinic_enrollments where child_id = v_canon and status in ('pending','active'))), '[]'::jsonb));
end $$;
-- END 0029_clinic_timezones.sql

-- =====================================================================================================================
-- BEGIN 0030_pending_certificate_retirement.sql  sha256=f9a34e5eb887f41ee5ba9913aa52c93315ae23c0680564ac540e396d943778df
-- =====================================================================================================================
-- A failed render leaves an immutable pending snapshot. Authorized staff can retire
-- that unpublished artifact, correct the source record, then prepare a fresh one.
create or replace function public.revoke_certificate(p_operation_key uuid, p_clinic_id uuid, p_certificate_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; c public.certificates;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'certificate.issue');
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'certificate.revoke', jsonb_build_object('c', p_clinic_id, 'cert', p_certificate_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into c from public.certificates where id = p_certificate_id and organization_id = v_org and clinic_id = p_clinic_id for update;
  if c.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if c.status = 'revoked' then raise exception 'already revoked' using errcode = 'CV409'; end if;
  if c.status = 'pending' then
    -- Clear even a rotated render token. No pending certificate was ever public or issued.
    update public.certificates set status = 'revoked', verification_token_hash = null,
      revoked_at = now(), revoked_by = auth.uid(), revocation_reason = left(btrim(p_reason), 300), review_needed = false
      where id = c.id;
    perform private.audit(v_org, 'certificate.issue', 'certificate.retired_pending', 'certificate', c.id,
      jsonb_build_object('status', 'pending'), jsonb_build_object('status', 'revoked'), p_reason);
    return private.finish_command(v_org, p_operation_key,
      jsonb_build_object('certificateId', c.id, 'status', 'revoked', 'retiredPending', true));
  end if;
  update public.certificates set status = 'revoked', revoked_at = now(), revoked_by = auth.uid(), revocation_reason = left(btrim(p_reason), 300), review_needed = false where id = c.id;
  perform private.enqueue(v_org, 'certificate.revoked', 'certificate', c.id, 'cert-revoked:' || c.id, '{}'::jsonb);
  perform private.audit(v_org, 'certificate.issue', 'certificate.revoked', 'certificate', c.id, jsonb_build_object('status', c.status), jsonb_build_object('status', 'revoked'), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('certificateId', c.id, 'status', 'revoked'));
end $$;

-- A retired draft has no issued document and must never appear in the family list.
create or replace function public.guardian_list_certificates(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then return null; end if;
  return (select coalesce(jsonb_agg(private.certificate_json(c, false) order by c.created_at desc), '[]'::jsonb)
    from public.certificates c
    where c.child_id in (select private.child_ids_with_aliases(v_canon))
      and c.status in ('issued','revoked') and c.issued_at is not null);
end $$;
-- END 0030_pending_certificate_retirement.sql

-- =====================================================================================================================
-- BEGIN 0031_pending_privacy_notices.sql  sha256=274e7e1cc978f33323c4f57def5c2e92d8826d077b1c8ecb44d613d73c12526a
-- =====================================================================================================================
-- CVSRS Migration 0031: Batch Pending Privacy Notices (Eliminates N+1 query loop on guardian dashboard)
create or replace function public.get_pending_privacy_notices() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r record;
  v_res jsonb := '[]'::jsonb;
  v_n jsonb;
  v_ver text;
  v_text text;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  for r in (
    select id, name, organization_id, operational_policy -> 'privacyNotice' as pn
    from public.clinics
    where status = 'active'
    order by name asc
  ) loop
    v_n := r.pn;
    if v_n is not null and (v_n ->> 'version') is not null and (v_n ->> 'text') is not null then
      v_ver := v_n ->> 'version';
      v_text := v_n ->> 'text';
      if not private.guardian_ack_version(r.organization_id, v_ver) then
        v_res := v_res || jsonb_build_object(
          'clinicId', r.id,
          'clinicName', r.name,
          'version', v_ver,
          'text', v_text
        );
      end if;
    end if;
  end loop;
  return v_res;
end $$;

revoke all on function public.get_pending_privacy_notices() from public, anon, authenticated;
grant execute on function public.get_pending_privacy_notices() to authenticated;
-- END 0031_pending_privacy_notices.sql

-- =====================================================================================================================
-- BEGIN 0032_pending_inventory_visibility.sql  sha256=b27c0c88b4731e764888f763b7c1732d89a917c60ee154225a56e47dd610438f
-- =====================================================================================================================
-- Pending work must not disappear behind bounded history windows.
-- Keep existing authorization and immutable records; expose actor IDs only to the
-- same authorized inventory readers so the UI can explain two-person decisions.

create or replace function public.list_stock_transfers(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['inventory.manage','inventory.approve']);
  return jsonb_build_object(
    'outgoing', coalesce((select jsonb_agg(private.transfer_json(t) || jsonb_build_object('sentBy', t.sent_by) order by t.sent_at desc, t.id)
      from (
        select pending.* from public.stock_transfers pending
         where pending.from_clinic_id = p_clinic_id and pending.status in ('in_transit','received_short')
        union all
        (select closed.* from public.stock_transfers closed
          where closed.from_clinic_id = p_clinic_id and closed.status not in ('in_transit','received_short')
          order by closed.sent_at desc, closed.id limit 50)
      ) t), '[]'::jsonb),
    'incoming', coalesce((select jsonb_agg(private.transfer_json(t) || jsonb_build_object('sentBy', t.sent_by) order by t.sent_at desc, t.id)
      from (
        select pending.* from public.stock_transfers pending
         where pending.to_clinic_id = p_clinic_id and pending.status in ('in_transit','received_short')
        union all
        (select closed.* from public.stock_transfers closed
          where closed.to_clinic_id = p_clinic_id and closed.status not in ('in_transit','received_short')
          order by closed.sent_at desc, closed.id limit 50)
      ) t), '[]'::jsonb),
    'clinics', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name) order by c.name)
      from public.clinics c where c.organization_id = v_org and c.status = 'active' and c.id <> p_clinic_id), '[]'::jsonb));
end $$;

create or replace function public.list_temperature(p_clinic_id uuid, p_days integer default 14) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_days int := least(greatest(coalesce(p_days, 14), 1), 90);
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['inventory.manage','inventory.approve']);
  return jsonb_build_object(
    'limits', (select jsonb_build_object('minC', l.min_c, 'maxC', l.max_c, 'policyReference', l.policy_reference, 'setAt', l.set_at)
      from public.cold_chain_limits l where l.clinic_id = p_clinic_id order by l.set_at desc limit 1),
    'readings', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'location', s.name, 'locationId', r.location_id,
        'observedAt', r.observed_at, 'minC', r.min_c, 'maxC', r.max_c, 'status', r.status, 'note', r.note,
        'limitMinC', r.limit_min_c, 'limitMaxC', r.limit_max_c, 'recordedBy', r.recorded_by,
        'reviewed', rv.reading_id is not null, 'reviewAction', rv.action, 'reviewNote', rv.note) order by r.observed_at desc, r.id)
      from public.temperature_readings r
      join public.stock_locations s on s.id = r.location_id
      left join public.temperature_reviews rv on rv.reading_id = r.id
      where r.clinic_id = p_clinic_id
        and (r.observed_at >= now() - make_interval(days => v_days) or (r.status = 'excursion' and rv.reading_id is null))), '[]'::jsonb),
    'openExcursions', (select count(*) from public.temperature_readings r
      where r.clinic_id = p_clinic_id and r.status = 'excursion'
        and not exists (select 1 from public.temperature_reviews rv where rv.reading_id = r.id)));
end $$;
-- END 0032_pending_inventory_visibility.sql

-- =====================================================================================================================
-- BEGIN 0033_operation_key_reuse_feedback.sql  sha256=979638a95f7ed1f7debf8458eebe4d4af3604c4d0a066098662a8619c9b4562a
-- =====================================================================================================================
-- A reused operation key with different content means an earlier attempt of the same form was
-- already saved (typically after a lost response). Keep the CV409 rejection, but say so plainly and
-- tag it so the application can tell staff that something was recorded instead of "nothing saved".
-- Idempotent: replaces the function body in place; ownership and grants are preserved.

create or replace function private.begin_command(p_org uuid, p_key uuid, p_type text, p_payload jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_hash text := encode(sha256(convert_to(coalesce(p_payload, '{}'::jsonb)::text, 'UTF8')), 'hex');
  v_id uuid;
  r private.command_receipts;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if p_key is null then raise exception 'operation key is required' using errcode = 'CV400'; end if;
  insert into private.command_receipts (organization_id, operation_key, actor_id, command_type, payload_hash)
  values (p_org, p_key, auth.uid(), p_type, v_hash)
  on conflict (organization_id, operation_key) do nothing
  returning id into v_id;
  if v_id is not null then return null; end if;
  select * into r from private.command_receipts where organization_id = p_org and operation_key = p_key;
  if r.actor_id <> auth.uid() or r.command_type <> p_type or r.payload_hash <> v_hash then
    raise exception 'An earlier attempt of this form was already saved with different details. Reload the page and check what was recorded before changing anything.'
      using errcode = 'CV409', hint = 'cvsrs:operation_key_reused';
  end if;
  return r.result;
end $$;
-- END 0033_operation_key_reuse_feedback.sql

-- =====================================================================================================================
-- BEGIN 0034_integrity_performance.sql  sha256=0ef59af06d1e75e3e2e4f5a3a46aa0e9633ac7830dfe249ce4024fcb1db382af
-- =====================================================================================================================
-- 0034: integrity, isolation and performance fixes from the 2026-10 audit (docs/engineering/discovery/*.md).
--   DB-01  clinical holds survive a duplicate merge (alias-aware readers, re-point on merge, backfill)
--   SEC-05 merge_children resolves both records inside the caller's organization and clinic before locking or inspecting them
--   DB-02  child-scoped readers select revisions by the child's own events instead of the whole-table view; supporting indexes
--   FE-01  approve_stock_adjustment approves count proposals only
--   DB-03  privacy acknowledgements bind clinic + version + SHA-256 of the notice text; acknowledging creates no guardian row
--   DB-04  lot traces and audit search are limited to the caller's clinic (restrictive, reversible default)
--   DB-05  five commands raise CV404 instead of committing an in-progress receipt
--   DB-06  audit search index and (server_time, id) keyset
--   SUP-02 operator-only, audited, one-time bootstrap of the first organization, clinic and staff
-- Every replaced function keeps its signature and therefore its grants (create or replace), except public.search_audit, which
-- gains an optional trailing parameter and is re-granted below exactly as 0024 granted it.

-- ---------------------------------------------------------------------------------------------
-- Indexes (DB-02, DB-06)
-- ---------------------------------------------------------------------------------------------
create index if not exists children_merged_into_idx on public.children (merged_into_id) where merged_into_id is not null;
create index if not exists vaccination_revisions_lot_idx on public.vaccination_revisions (lot_id) where lot_id is not null;
create index if not exists audit_org_time_idx on private.audit_logs (organization_id, server_time desc, id desc);

-- ---------------------------------------------------------------------------------------------
-- DB-02: current revisions of one child's alias set, selected through that child's own events.
-- Same rows as `private.current_revisions where child_id = any(p_children)`: an event belongs to the set when its LATEST
-- revision names one of the ids, and every such event has at least one revision naming one of them.
-- ---------------------------------------------------------------------------------------------
create function private.child_current_revisions(p_children uuid[]) returns setof public.vaccination_revisions
language sql stable security definer set search_path = '' as $$
  select c.* from (
    select distinct on (r.event_id) r.*
      from public.vaccination_revisions r
     where r.event_id in (select x.event_id from public.vaccination_revisions x where x.child_id = any (p_children))
     order by r.event_id, r.revision_no desc
  ) c
  where c.child_id = any (p_children)
$$;

create or replace function private.child_eval_inputs(p_child uuid, p_as_of date) returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_dob date; v_prec text; v_doses jsonb; v_holds jsonb; v_pending int; v_ids uuid[];
begin
  select dob, birth_date_precision into v_dob, v_prec from public.children where id = p_child;
  v_ids := array(select private.child_ids_with_aliases(p_child));
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', cr.id::text,
      'revisionId', cr.id, 'eventId', cr.event_id,
      'product', p.code,
      'antigens', coalesce((select jsonb_agg(a.code order by a.code) from public.product_antigens pa join public.antigens a on a.id = pa.antigen_id where pa.product_id = cr.product_id), '[]'::jsonb),
      'on', case when cr.date_precision = 'exact' then cr.administered_on end,
      'unresolved', cr.date_precision <> 'exact' or cr.administered_on is null or cr.product_id is null)
    order by cr.administered_on nulls last, cr.id), '[]'::jsonb)
    into v_doses
    from private.child_current_revisions(v_ids) cr left join public.vaccine_products p on p.id = cr.product_id
   where cr.event_status = 'active' and cr.verification_status = 'verified'
     and (cr.administered_on is null or cr.administered_on <= p_as_of);
  -- DB-01: holds are read through the alias set, so a hold placed on a record that was later merged still applies.
  select coalesce(jsonb_agg(jsonb_build_object('ruleId', h.rule_id, 'reason', h.reason_code)), '[]'::jsonb) into v_holds
    from public.clinical_holds h where h.child_id = any (v_ids)
      and (h.starts_at at time zone coalesce((select c.timezone from public.clinics c where c.id = h.placed_clinic_id), 'UTC'))::date <= p_as_of
      and (h.resolved_at is null or (h.resolved_at at time zone coalesce((select c.timezone from public.clinics c where c.id = h.placed_clinic_id), 'UTC'))::date > p_as_of);
  -- Unverified/pending evidence is counted for staff visibility but NEVER credited (T09).
  select count(*) into v_pending from private.child_current_revisions(v_ids) cr
   where cr.event_status = 'active' and cr.verification_status = 'pending_verification' and (cr.administered_on is null or cr.administered_on <= p_as_of);
  return jsonb_build_object('dob', v_dob, 'dobExact', v_prec = 'exact' and v_dob is not null, 'doses', v_doses, 'holds', v_holds, 'pendingEvidence', v_pending);
end $$;

create or replace function public.list_child_history(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_canon uuid; v_res jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'child.read_clinical');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then
    perform private.audit(v_org, 'child.read_clinical', 'history.view', 'child', p_child_id, null, null, null, 'denied');
    return null;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'eventId', cr.event_id, 'revisionNo', cr.revision_no, 'origin', e.origin, 'source', cr.source, 'verificationStatus', cr.verification_status,
    'eventStatus', cr.event_status, 'administeredOn', cr.administered_on, 'datePrecision', cr.date_precision,
    'product', p.name, 'productCode', p.code, 'reportedProduct', cr.reported_product_text, 'reportedLot', cr.reported_lot, 'provider', cr.external_vaccinator,
    'amended', cr.revision_no > 1) order by cr.administered_on desc nulls last, cr.created_at desc), '[]'::jsonb) into v_res
    from private.child_current_revisions(array(select private.child_ids_with_aliases(v_canon))) cr
    join public.vaccination_events e on e.id = cr.event_id left join public.vaccine_products p on p.id = cr.product_id;
  perform private.audit(v_org, 'child.read_clinical', 'history.view', 'child', v_canon, null, null, null);
  return v_res;
end $$;

create or replace function public.guardian_child_history(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.guardian_has_full_access(v_canon) then return null; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
    'eventId', cr.event_id, 'administeredOn', cr.administered_on, 'datePrecision', cr.date_precision, 'product', coalesce(p.name, cr.reported_product_text),
    -- Provenance stays visible: reported-elsewhere is never presented as a clinic-verified dose.
    'status', case when cr.verification_status = 'verified' then 'verified' when cr.verification_status = 'pending_verification' then 'pending_verification' else 'not_accepted' end,
    'source', case when cr.source = 'clinic_administered' then 'clinic' else 'recorded_elsewhere' end)
    order by cr.administered_on desc nulls last), '[]'::jsonb)
    from private.child_current_revisions(array(select private.child_ids_with_aliases(v_canon))) cr left join public.vaccine_products p on p.id = cr.product_id
   where cr.event_status = 'active');
end $$;

-- DB-02 + DB-05: certificate preparation reads the child's own events; a child outside the clinic is CV404 (no receipt kept).
create or replace function public.issue_certificate(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_replaces_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_prev jsonb; v_canon uuid; v_child public.children; v_clinic public.clinics; v_entries jsonb; v_snap jsonb; v_id uuid := gen_random_uuid(); v_no text; v_issuer text; old public.certificates;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'certificate.issue');
  v_prev := private.begin_command(v_org, p_operation_key, 'certificate.issue', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 'rp', p_replaces_id));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if p_replaces_id is not null then
    select * into old from public.certificates where id = p_replaces_id and organization_id = v_org and child_id in (select private.child_ids_with_aliases(v_canon)) for update;
    if old.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
    if old.status = 'pending' then raise exception 'a certificate that is still pending cannot be replaced' using errcode = 'CV409'; end if;
    if exists (select 1 from public.certificates x where x.replaces_id = old.id and x.status <> 'revoked') then raise exception 'a replacement for this certificate is already in progress' using errcode = 'CV409'; end if;
  end if;
  select * into v_child from public.children where id = v_canon;
  select * into v_clinic from public.clinics where id = p_clinic_id;
  select coalesce(jsonb_agg(jsonb_build_object(
           'eventId', cr.event_id, 'revisionId', cr.id, 'revisionNo', cr.revision_no, 'administeredOn', cr.administered_on, 'datePrecision', cr.date_precision,
           'product', coalesce(p.name, cr.reported_product_text),
           'source', case when cr.source = 'clinic_administered' then 'clinic' else 'recorded_elsewhere' end,
           'lot', case when cr.source = 'clinic_administered' then coalesce(l.manufacturer_lot, cr.reported_lot) else null end,
           'provider', case when cr.source = 'clinic_administered' then null else cr.external_vaccinator end)
         order by cr.administered_on, cr.created_at), '[]'::jsonb) into v_entries
    from private.child_current_revisions(array(select private.child_ids_with_aliases(v_canon))) cr
    left join public.vaccine_products p on p.id = cr.product_id left join public.vaccine_lots l on l.id = cr.lot_id
   where cr.event_status = 'active' and cr.verification_status = 'verified' and cr.administered_on is not null;
  if jsonb_array_length(v_entries) = 0 then raise exception 'there are no verified vaccinations to certify yet' using errcode = 'CV422'; end if;
  select display_name into v_issuer from public.profiles where id = auth.uid();
  v_no := private.next_certificate_no(v_org);
  v_snap := jsonb_build_object('version', 1, 'certificateNo', v_no,
    'clinic', jsonb_build_object('name', v_clinic.name, 'address', v_clinic.address, 'contact', v_clinic.contact_text, 'timezone', v_clinic.timezone),
    'child', jsonb_build_object('displayName', v_child.display_name, 'dob', v_child.dob, 'datePrecision', v_child.birth_date_precision, 'recordNo', v_child.local_record_no),
    'entries', v_entries, 'issuedBy', coalesce(nullif(v_issuer, ''), 'Clinic staff'), 'preparedAt', now());
  insert into public.certificates (id, organization_id, clinic_id, child_id, certificate_no, snapshot, content_hash, issuer_id, replaces_id)
  values (v_id, v_org, p_clinic_id, v_canon, v_no, v_snap, encode(sha256(convert_to(v_snap::text, 'UTF8')), 'hex'), auth.uid(), p_replaces_id);
  insert into public.certificate_items (certificate_id, vaccination_revision_id)
  select v_id, (e ->> 'revisionId')::uuid from jsonb_array_elements(v_entries) e;
  perform private.audit(v_org, 'certificate.issue', 'certificate.prepared', 'certificate', v_id, null, jsonb_build_object('no', v_no, 'entries', jsonb_array_length(v_entries), 'replaces', p_replaces_id), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('certificateId', v_id, 'certificateNo', v_no, 'status', 'pending'));
end $$;

-- DB-02: pendingOutsideDoses is scoped through this clinic's enrollments first (was: every organization's revisions).
create or replace function public.report_backlog(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.report_org(p_clinic_id); v_ids uuid[];
begin
  -- Every id whose canonical record is enrolled here (canonical records are the unmerged ones; aliases are their merged duplicates).
  v_ids := array(select a.id from public.child_clinic_enrollments e join public.children c on c.id = e.child_id and c.merged_into_id is null
                  cross join lateral private.child_ids_with_aliases(e.child_id) a(id)
                  where e.clinic_id = p_clinic_id and e.status in ('pending','active'));
  perform private.audit(v_org, 'report.run', 'report.viewed', 'clinic', p_clinic_id, null, jsonb_build_object('report', 'backlog'), null);
  return jsonb_build_object('report', 'backlog', 'asOf', now(), 'definitions', jsonb_build_object('version', 'r1', 'terms', jsonb_build_object(
      'openReviewCases', 'Review cases still open or in review, by type.', 'pendingOutsideDoses', 'Doses reported as given elsewhere that staff have not yet verified or rejected.',
      'provisionalChildren', 'Children enrolled here whose identity has not been confirmed.', 'pendingGuardianLinks', 'Guardian links waiting for in-person verification.',
      'pendingCertificates', 'Certificates prepared but not yet issued (document not stored).', 'failedMessages', 'Notification jobs that failed permanently.',
      'openTemperatureExcursions', 'Fridge readings outside the approved limits that nobody has reviewed.', 'transfersNeedingDecision', 'Stock transfers that arrived short and still need a decision.',
      'transfersInTransit', 'Stock sent to or from this clinic that has not been received yet.',
      'plansAwaitingReview', 'Catch-up plans submitted and waiting for a second person.', 'openCheckins', 'Questions from families that no one has answered yet.')),
    'openReviewCases', (select coalesce(jsonb_object_agg(kind, n), '{}'::jsonb) from (select kind, count(*) n from public.record_review_cases where clinic_id = p_clinic_id and status in ('open','in_review') group by kind) k),
    'pendingOutsideDoses', (select count(*) from private.child_current_revisions(v_ids) cr where cr.verification_status = 'pending_verification' and cr.event_status = 'active'),
    'provisionalChildren', (select count(*) from public.children c join public.child_clinic_enrollments e on e.child_id = c.id and e.clinic_id = p_clinic_id and e.status in ('pending','active') where c.record_status = 'provisional' and c.merged_into_id is null),
    'pendingGuardianLinks', (select count(*) from public.guardian_child_relationships r join public.child_clinic_enrollments e on e.child_id = r.child_id and e.clinic_id = p_clinic_id and e.status in ('pending','active') where r.status = 'provisional'),
    'pendingCertificates', (select count(*) from public.certificates where clinic_id = p_clinic_id and status = 'pending'),
    'failedMessages', (select count(*) from private.outbox_jobs where organization_id = v_org and status = 'failed'),
    'openTemperatureExcursions', (select count(*) from public.temperature_readings r where r.clinic_id = p_clinic_id and r.status = 'excursion' and not exists (select 1 from public.temperature_reviews rv where rv.reading_id = r.id)),
    'transfersNeedingDecision', (select count(*) from public.stock_transfers where from_clinic_id = p_clinic_id and status = 'received_short'),
    'transfersInTransit', (select count(*) from public.stock_transfers where (from_clinic_id = p_clinic_id or to_clinic_id = p_clinic_id) and status = 'in_transit'),
    'plansAwaitingReview', (select count(*) from public.catchup_plans where clinic_id = p_clinic_id and status = 'submitted'),
    'openCheckins', (select count(*) from public.checkins where clinic_id = p_clinic_id and status = 'open'));
end $$;

-- DB-02: the repeat-dose guard on the recording path reads the child's own events. Body otherwise identical to 0015.
create or replace function public.record_administration(p_operation_key uuid, p_clinic_id uuid, p_encounter_id uuid, p_admin jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_tz text; v_prev jsonb; enc public.encounters; v_child uuid; c public.children; v_by uuid; v_at timestamptz; v_on date;
  v_lot public.vaccine_lots; v_prod public.vaccine_products; v_loc uuid; v_doses numeric; v_check jsonb; v_event uuid; v_rev uuid; v_tx uuid;
  v_route text; v_site text; v_res jsonb; v_credited jsonb; v_eval uuid; v_confirm boolean;
begin
  select organization_id, timezone into v_org, v_tz from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  -- Lock the encounter first (consistent order: encounter -> stock row), serialising concurrent recording for one visit.
  select * into enc from public.encounters where id = p_encounter_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_child := private.canonical_child(enc.child_id);
  if not private.child_in_clinic(v_child, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'vaccination.record', jsonb_build_object('c', p_clinic_id, 'enc', p_encounter_id, 'a', p_admin));
  if v_prev is not null then return v_prev; end if;
  if enc.status <> 'open' then raise exception 'the visit is not open' using errcode = 'CV409'; end if;
  select * into c from public.children where id = v_child;
  if c.record_status <> 'active' then raise exception 'confirm the child''s identity before recording care' using errcode = 'CV409'; end if;
  if p_admin is null or jsonb_typeof(p_admin) <> 'object' then raise exception 'administration details required' using errcode = 'CV400'; end if;

  begin
    v_by := coalesce(nullif(p_admin ->> 'administeredBy', '')::uuid, auth.uid());
    v_at := coalesce(nullif(p_admin ->> 'administeredAt', '')::timestamptz, now());
    v_loc := (p_admin ->> 'locationId')::uuid;
    v_doses := coalesce(nullif(p_admin ->> 'doses', '')::numeric, 1);
    v_confirm := coalesce((p_admin ->> 'confirmRepeat')::boolean, false);
    select * into v_lot from public.vaccine_lots where id = (p_admin ->> 'lotId')::uuid and organization_id = v_org;
  exception when others then raise exception 'administration details are invalid' using errcode = 'CV422';
  end;
  if v_lot.id is null or v_loc is null then raise exception 'choose the lot and stock location used' using errcode = 'CV422'; end if;
  select * into v_prod from public.vaccine_products where id = v_lot.product_id;
  if nullif(p_admin ->> 'productId', '') is not null and (p_admin ->> 'productId')::uuid <> v_prod.id then raise exception 'the lot belongs to a different product' using errcode = 'CV422'; end if;
  if v_by <> auth.uid() and not private.profile_has_cap(v_by, p_clinic_id, 'vaccination.record') then raise exception 'the named vaccinator is not authorised to vaccinate at this clinic' using errcode = 'CV422'; end if;
  if v_doses <> 1 then raise exception 'record one administration at a time (single-dose presentations)' using errcode = 'CV422'; end if;
  if v_at > now() + interval '5 minutes' then raise exception 'the administration time cannot be in the future' using errcode = 'CV422'; end if;
  v_on := (v_at at time zone v_tz)::date;
  v_route := nullif(left(btrim(coalesce(p_admin ->> 'route', '')), 40), '');
  v_site := nullif(left(btrim(coalesce(p_admin ->> 'site', '')), 40), '');

  -- Possible duplicate: same child + product + local date. A genuine repeat is allowed only when explicitly confirmed (BP39);
  -- it must then still satisfy the schedule below, otherwise it goes through the exception path (facts preserved, no credit).
  if not v_confirm and exists (
      select 1 from private.child_current_revisions(array(select private.child_ids_with_aliases(v_child))) cr where cr.product_id = v_prod.id
         and cr.event_status = 'active' and cr.verification_status <> 'rejected' and cr.administered_on = v_on) then
    raise exception 'a similar administration already exists for this child today; confirm only if this is a genuine repeat' using errcode = 'CV409';
  end if;
  -- Timing/eligibility per the APPROVED schedule (planned path). Explained, never silently overridden.
  v_check := private.check_planned_dose(v_child, v_prod.id, v_on);
  if (v_check ->> 'blocked')::boolean then
    raise exception 'not allowed by the approved schedule (%). If the vaccine was already given, use "record care already given".', private.reasons_text(v_check -> 'reasons') using errcode = 'CV422';
  end if;

  insert into public.vaccination_events (organization_id, original_child_id, encounter_id, origin, source_operation_id, created_by)
  values (v_org, v_child, enc.id, 'clinic_administered', p_operation_key, auth.uid()) returning id into v_event;
  insert into public.vaccination_revisions (organization_id, event_id, revision_no, child_id, product_id, administered_on, administered_at, date_precision, lot_id, expiry_snapshot,
                                             quantity, unit, route, site, administered_by, clinic_id, source, verification_status, signed_at, created_by)
  values (v_org, v_event, 1, v_child, v_prod.id, v_on, v_at, 'exact', v_lot.id, v_lot.expires_on, 1, 'dose', v_route, v_site, v_by, p_clinic_id, 'clinic_administered', 'verified', now(), auth.uid())
  returning id into v_rev;

  -- Stock in the SAME transaction: exactly one physical issue. Failure here rolls the clinical record back too (T04).
  v_tx := private.issue_for_administration(v_org, p_clinic_id, v_loc, v_lot.id, v_doses, v_event, p_operation_key);

  update public.encounters set assessment_reference = coalesce(nullif(left(btrim(coalesce(p_admin ->> 'assessmentReference', '')), 200), ''), assessment_reference),
         consent_reference = coalesce(nullif(left(btrim(coalesce(p_admin ->> 'consentReference', '')), 200), ''), consent_reference), updated_by = auth.uid() where id = enc.id;

  v_res := private.compute_child_schedule(v_child, private.local_today(p_clinic_id), true);
  v_eval := nullif(v_res ->> 'evaluationId', '')::uuid;
  select coalesce(jsonb_agg(x ->> 'requirement'), '[]'::jsonb) into v_credited from jsonb_array_elements(coalesce(v_res -> 'requirements', '[]'::jsonb)) x where x ->> 'creditedDoseId' = v_rev::text;

  perform private.enqueue(v_org, 'vaccination.recorded', 'vaccination_event', v_event, 'vax-recorded:' || v_event, jsonb_build_object('childId', v_child, 'clinicId', p_clinic_id));
  perform private.audit(v_org, 'vaccination.record', 'vaccination.recorded', 'vaccination_event', v_event, null,
                        jsonb_build_object('child', v_child, 'product', v_prod.code, 'lot', v_lot.manufacturer_lot, 'on', v_on, 'credited', v_credited, 'stockTransaction', v_tx), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('eventId', v_event, 'revisionId', v_rev, 'stockTransactionId', v_tx, 'evaluationId', v_eval,
      'creditedRequirements', v_credited, 'scheduleEvaluated', coalesce((v_check ->> 'evaluated')::boolean, false), 'administeredOn', v_on));
end $$;

-- ---------------------------------------------------------------------------------------------
-- DB-01: clinical holds follow the record through a merge
-- ---------------------------------------------------------------------------------------------
create or replace function public.place_clinical_hold(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_reason_code text, p_restricted_note text default null, p_review_on date default null, p_rule_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_canon uuid; v_id uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  v_prev := private.begin_command(v_org, p_operation_key, 'hold.place', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 'r', p_reason_code, 'n', p_restricted_note, 'd', p_review_on, 'rule', p_rule_id));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if p_reason_code is null or length(btrim(p_reason_code)) < 3 or length(p_reason_code) > 80 then raise exception 'name the reason for the hold (3 to 80 characters)' using errcode = 'CV422'; end if;
  if p_review_on is not null and p_review_on < private.local_today(p_clinic_id) then raise exception 'the review date cannot be in the past' using errcode = 'CV422'; end if;
  if p_rule_id is not null and not exists (select 1 from public.schedule_rules where id = p_rule_id and organization_id = v_org) then raise exception 'unknown schedule item' using errcode = 'CV422'; end if;
  if exists (select 1 from public.clinical_holds where child_id in (select private.child_ids_with_aliases(v_canon)) and status = 'active'
               and coalesce(rule_id, '00000000-0000-0000-0000-000000000000') = coalesce(p_rule_id, '00000000-0000-0000-0000-000000000000')) then
    raise exception 'this hold already exists' using errcode = 'CV409';
  end if;
  insert into public.clinical_holds (organization_id, child_id, rule_id, reason_code, restricted_note, review_on, placed_clinic_id, created_by, updated_by)
  values (v_org, v_canon, p_rule_id, btrim(p_reason_code), left(nullif(btrim(coalesce(p_restricted_note, '')), ''), 500), p_review_on, p_clinic_id, auth.uid(), auth.uid()) returning id into v_id;
  perform private.audit(v_org, 'vaccination.record', 'hold.placed', 'child', v_canon, null, jsonb_build_object('holdId', v_id, 'rule', p_rule_id, 'reviewOn', p_review_on), p_reason_code);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('holdId', v_id, 'status', 'active'));
end $$;

-- release_clinical_hold is unchanged: it already authorises through private.canonical_child(h.child_id), which resolves a merged record.

create or replace function public.list_clinical_holds(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  perform private.require_capability(p_clinic_id, 'child.read_clinical');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'status', h.status, 'reason', h.reason_code, 'note', h.restricted_note, 'reviewOn', h.review_on, 'startsAt', h.starts_at,
            'ruleRequirement', (select r.requirement_code from public.schedule_rules r where r.id = h.rule_id), 'resolvedAt', h.resolved_at, 'resolutionNote', h.resolution_note,
            'placedBy', (select display_name from public.profiles where id = h.created_by)) order by h.starts_at desc), '[]'::jsonb)
            from public.clinical_holds h where h.child_id in (select private.child_ids_with_aliases(v_canon)));
end $$;

-- Re-points active holds that still sit on a merged record to its surviving record (one audit row per hold). Used once below
-- for holds left behind by merges made before this migration; the merge wrapper does the same for new merges.
create function private.repoint_merged_holds() returns integer
language plpgsql security definer set search_path = '' as $$
declare h record; v_to uuid; n integer := 0;
begin
  for h in select ch.id, ch.organization_id, ch.child_id from public.clinical_holds ch join public.children c on c.id = ch.child_id
            where ch.status = 'active' and c.merged_into_id is not null for update of ch
  loop
    v_to := private.canonical_child(h.child_id);
    continue when v_to = h.child_id;
    update public.clinical_holds set child_id = v_to, updated_by = coalesce(auth.uid(), updated_by) where id = h.id;
    perform private.audit(h.organization_id, null, 'hold.merged', 'clinical_hold', h.id, jsonb_build_object('childId', h.child_id), jsonb_build_object('childId', v_to),
                          'hold moved to the surviving record of an earlier merge');
    n := n + 1;
  end loop;
  return n;
end $$;

-- SEC-05 + DB-01: ownership is resolved before any lock or state check; active holds move to the survivor with the merge.
create or replace function public.merge_children(p_operation_key uuid, p_clinic_id uuid, p_survivor uuid, p_duplicate uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_result jsonb; v_org uuid; v_replay jsonb; a record; h record;
begin
  perform private.require_capability(p_clinic_id, 'review.resolve');
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  v_replay := private.scheduling_replay(v_org, p_operation_key, 'child.merge', jsonb_build_object('clinic', p_clinic_id, 's', p_survivor, 'd', p_duplicate, 'reason', p_reason));
  if v_replay is not null then return v_replay; end if;
  -- Both records must be this organization's and enrolled at this clinic before anything about them is locked or inspected.
  if not exists (select 1 from public.children where id = p_survivor and organization_id = v_org)
     or not exists (select 1 from public.children where id = p_duplicate and organization_id = v_org)
     or not private.child_in_clinic(p_survivor, p_clinic_id) or not private.child_in_clinic(p_duplicate, p_clinic_id) then
    raise exception 'not found' using errcode = 'CV404';
  end if;
  perform 1 from public.children where id in (p_survivor, p_duplicate) order by id for update;
  if exists (select 1 from public.encounters where child_id in (p_survivor, p_duplicate) and status = 'open') then
    raise exception 'finish active visits before merging records' using errcode = 'CV409';
  end if;
  if exists (
    select 1 from public.queue_entries d join public.queue_entries s on s.child_id = p_survivor and s.clinic_id = d.clinic_id and s.service_date = d.service_date
     where d.child_id = p_duplicate and d.status in ('waiting','called','in_service','held') and s.status in ('waiting','called','in_service','held')
  ) then raise exception 'both records have an active ticket; resolve arrivals before merging' using errcode = 'CV409'; end if;
  if exists (
    select 1 from public.appointments d join public.appointments s on s.child_id = p_survivor and s.session_id = d.session_id
     where d.child_id = p_duplicate and d.status = 'checked_in' and s.status in ('confirmed','checked_in','fulfilled')
  ) then raise exception 'both records have an active booking; resolve arrivals before merging' using errcode = 'CV409'; end if;

  v_result := public.merge_children_prev(p_operation_key, p_clinic_id, p_survivor, p_duplicate, p_reason);
  -- Preserve one usable booking per session. The cancelled duplicate stays as an
  -- auditable historical row, while its queued confirmation is withdrawn.
  for a in select d.id from public.appointments d where d.child_id = p_duplicate and d.status = 'confirmed'
    and exists (select 1 from public.appointments s where s.child_id = p_survivor and s.session_id = d.session_id and s.status in ('confirmed','checked_in','fulfilled'))
  loop
    update public.appointments set status = 'cancelled', reason = 'duplicate child record merged with existing booking', updated_by = auth.uid() where id = a.id;
    update private.outbox_jobs set status = 'cancelled', updated_at = now() where organization_id = v_org and status = 'queued' and dedupe_key = 'appt-confirm:' || a.id;
    perform private.audit(v_org, 'review.resolve', 'appointment.merge_collision', 'appointment', a.id, null, jsonb_build_object('survivorChildId', p_survivor), p_reason);
  end loop;
  update public.appointments set child_id = p_survivor, updated_by = auth.uid() where child_id = p_duplicate and status in ('confirmed','checked_in');
  update public.queue_entries set child_id = p_survivor, updated_by = auth.uid() where child_id = p_duplicate and status in ('waiting','called','in_service','held');
  -- A clinician's hold keeps blocking: it moves to the surviving record (resolved holds stay where they were, read through aliases).
  for h in select id, child_id from public.clinical_holds where child_id in (select private.child_ids_with_aliases(p_duplicate)) and status = 'active' for update loop
    update public.clinical_holds set child_id = p_survivor, updated_by = auth.uid() where id = h.id;
    perform private.audit(v_org, 'review.resolve', 'hold.merged', 'clinical_hold', h.id, jsonb_build_object('childId', h.child_id), jsonb_build_object('childId', p_survivor), p_reason);
  end loop;
  perform private.audit(v_org, 'review.resolve', 'child.merge_scheduling', 'child', p_duplicate, null, jsonb_build_object('survivorId', p_survivor), p_reason);
  return v_result;
end $$;

-- ---------------------------------------------------------------------------------------------
-- FE-01: only count proposals can be approved and posted
-- ---------------------------------------------------------------------------------------------
create or replace function public.approve_stock_adjustment(p_operation_key uuid, p_clinic_id uuid, p_case_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id, 'inventory.approve'); v_prev jsonb; k public.record_review_cases; v_book numeric; v_tx uuid; v_delta numeric; v_loc uuid; v_lot uuid;
begin
  select * into k from public.record_review_cases where id = p_case_id and organization_id = v_org and clinic_id = p_clinic_id and kind = 'stock' for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.approve_adjustment', jsonb_build_object('c', p_clinic_id, 'case', p_case_id));
  if v_prev is not null then return v_prev; end if;
  if k.status not in ('open','in_review') then raise exception 'case already decided' using errcode = 'CV409'; end if;
  -- Short deliveries and care-without-stock cases are also kind 'stock' but carry no count: they are decided where they came from.
  if k.evidence ->> 'observed' is null or k.evidence ->> 'locationId' is null or k.evidence ->> 'lotId' is null then
    raise exception 'this stock case is not a count adjustment; decide it from the transfer or the visit record it came from' using errcode = 'CV409';
  end if;
  if k.created_by = auth.uid() then raise exception 'the proposer cannot approve their own adjustment' using errcode = 'CV403'; end if;
  v_loc := (k.evidence ->> 'locationId')::uuid; v_lot := (k.evidence ->> 'lotId')::uuid;
  -- Re-derive the delta from the observed count against the CURRENT book balance (stock may have moved since the proposal).
  select coalesce(on_hand, 0) into v_book from public.stock_balances where location_id = v_loc and lot_id = v_lot for update;
  v_book := coalesce(v_book, 0);
  v_delta := (k.evidence ->> 'observed')::numeric - v_book;
  if v_delta <> 0 then
    insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, approved_by, operation_id, created_by)
    values (v_org, p_clinic_id, 'adjustment', k.evidence ->> 'countReference', k.evidence ->> 'reason', auth.uid(), p_operation_key, k.created_by) returning id into v_tx;
    perform private.post_movement(v_org, v_tx, v_loc, v_lot, v_delta, 'adjust:' || p_operation_key);
  end if;
  update public.record_review_cases set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', 'approved', 'postedDelta', v_delta, 'transactionId', v_tx) where id = k.id;
  perform private.audit(v_org, 'inventory.approve', 'stock.adjustment_approved', 'review_case', k.id, null, jsonb_build_object('delta', v_delta), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'posted', 'delta', v_delta, 'transactionId', v_tx));
end $$;

-- ---------------------------------------------------------------------------------------------
-- DB-05: a child outside the clinic is CV404 (the receipt rolls back) instead of `return null` after begin_command
-- ---------------------------------------------------------------------------------------------
create or replace function public.save_catchup_draft(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_plan_id uuid, p_rationale text, p_policy_reference text, p_items jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_canon uuid; p public.catchup_plans;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'vaccination.record');
  v_prev := private.begin_command(v_org, p_operation_key, 'catchup.save', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 'p', p_plan_id, 'r', p_rationale, 'pr', p_policy_reference, 'i', p_items));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if p_rationale is null or length(btrim(p_rationale)) < 10 then raise exception 'explain why this plan is needed (at least a sentence)' using errcode = 'CV422'; end if;
  if p_policy_reference is null or length(btrim(p_policy_reference)) < 3 then raise exception 'name the clinical policy or advice this plan follows' using errcode = 'CV422'; end if;
  if p_plan_id is null then
    if exists (select 1 from public.catchup_plans where child_id = v_canon and status in ('draft','submitted')) then raise exception 'this child already has a plan being prepared' using errcode = 'CV409'; end if;
    insert into public.catchup_plans (organization_id, clinic_id, child_id, rationale, policy_reference, authored_by) values (v_org, p_clinic_id, v_canon, btrim(p_rationale), btrim(p_policy_reference), auth.uid()) returning * into p;
  else
    select * into p from public.catchup_plans where id = p_plan_id and organization_id = v_org and clinic_id = p_clinic_id and child_id = v_canon for update;
    if p.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
    if p.status <> 'draft' then raise exception 'only a draft can be edited' using errcode = 'CV409'; end if;
    if p.authored_by <> auth.uid() then raise exception 'only the author can edit a draft' using errcode = 'CV403'; end if;
    update public.catchup_plans set rationale = btrim(p_rationale), policy_reference = btrim(p_policy_reference) where id = p.id;
    delete from public.catchup_plan_items where plan_id = p.id;
  end if;
  perform private.catchup_items_insert(v_org, p.id, p_items);
  perform private.audit(v_org, 'vaccination.record', 'catchup.drafted', 'catchup_plan', p.id, null, jsonb_build_object('child', v_canon, 'items', jsonb_array_length(p_items)), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('planId', p.id, 'status', 'draft'));
end $$;

create or replace function public.log_followup_attempt(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_outcome text, p_note text default null, p_next_try_on date default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_canon uuid; v_id uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['bhw.followup','child.read_clinical']);
  v_prev := private.begin_command(v_org, p_operation_key, 'followup.attempt', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 'o', p_outcome, 'n', p_note, 'd', p_next_try_on));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if p_outcome not in ('reached','no_answer','wrong_number','refused','will_visit','moved_away','other') then raise exception 'choose what happened' using errcode = 'CV422'; end if;
  if p_next_try_on is not null and (p_next_try_on <= private.local_today(p_clinic_id) or p_next_try_on > private.local_today(p_clinic_id) + 180) then raise exception 'choose a date within the next 6 months' using errcode = 'CV422'; end if;
  insert into public.followup_attempts (organization_id, clinic_id, child_id, outcome, note, next_try_on, recorded_by, operation_id)
  values (v_org, p_clinic_id, v_canon, p_outcome, left(nullif(btrim(coalesce(p_note, '')), ''), 300), p_next_try_on, auth.uid(), p_operation_key) returning id into v_id;
  perform private.audit(v_org, 'bhw.followup', 'followup.attempt', 'child', v_canon, null, jsonb_build_object('outcome', p_outcome), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('attemptId', v_id));
end $$;

create or replace function public.initiate_record_transfer_out(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_to_clinic_id uuid, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_canon uuid; v_id uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'guardian.verify');
  v_prev := private.begin_command(v_org, p_operation_key, 'transfer.initiate_out', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 'to', p_to_clinic_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not exists (select 1 from public.child_clinic_enrollments where child_id = v_canon and clinic_id = p_clinic_id and status = 'active') then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.transfer_target_ok(v_org, p_clinic_id, p_to_clinic_id);
  if not exists (select 1 from public.guardian_child_relationships where child_id = v_canon and status = 'active' and access_scope = 'full') then raise exception 'a verified guardian must ask for the transfer' using errcode = 'CV409'; end if;
  if exists (select 1 from public.record_transfers where child_id = v_canon and status in ('requested','ready')) then raise exception 'a transfer for this child is already in progress' using errcode = 'CV409'; end if;
  insert into public.record_transfers (organization_id, child_id, from_clinic_id, to_clinic_id, initiated_by, consent_method, reason)
  values (v_org, v_canon, p_clinic_id, p_to_clinic_id, auth.uid(), 'in_person', left(nullif(btrim(coalesce(p_reason, '')), ''), 300)) returning id into v_id;
  perform private.audit(v_org, 'guardian.verify', 'transfer.initiated', 'child', v_canon, null, jsonb_build_object('transferId', v_id, 'to', p_to_clinic_id), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('transferId', v_id, 'status', 'requested'));
end $$;

-- ---------------------------------------------------------------------------------------------
-- DB-03: acknowledgements bind clinic + version + SHA-256 of the exact notice text, and belong to the signed-in person
-- (profile), so accepting a clinic's notice no longer creates a guardian identity in that clinic's organization.
-- ---------------------------------------------------------------------------------------------
alter table public.privacy_records
  add column clinic_id uuid,
  add column profile_id uuid references public.profiles (id),
  add column notice_sha256 text check (notice_sha256 is null or notice_sha256 ~ '^[0-9a-f]{64}$'),
  add constraint privacy_records_org_clinic_fkey foreign key (organization_id, clinic_id) references public.clinics (organization_id, id);
alter table public.privacy_records drop constraint privacy_records_check;
alter table public.privacy_records add constraint privacy_records_subject_check check (guardian_id is not null or child_id is not null or profile_id is not null);
create index privacy_records_ack_idx on public.privacy_records (profile_id, clinic_id) where record_type = 'notice_acknowledgement';

create function private.notice_digest(p_text text) returns text language sql immutable set search_path = '' as $$
  select pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_text, 'UTF8')), 'hex')
$$;

-- True when the caller accepted exactly the notice this clinic shows now (same clinic, version label and text).
create function private.notice_acknowledged(p_clinic uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.clinics c join public.privacy_records pr on pr.clinic_id = c.id
     where c.id = p_clinic and pr.profile_id = auth.uid() and pr.record_type = 'notice_acknowledgement' and pr.decision = 'acknowledged'
       and pr.notice_version = c.operational_policy -> 'privacyNotice' ->> 'version'
       and pr.notice_sha256 = private.notice_digest(c.operational_policy -> 'privacyNotice' ->> 'text'))
$$;

create or replace function public.get_privacy_notice(p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.clinics; v_n jsonb;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select * into c from public.clinics where id = p_clinic_id and status = 'active';
  if c.id is null then return null; end if;
  v_n := c.operational_policy -> 'privacyNotice';
  if v_n is null then return jsonb_build_object('configured', false, 'acknowledged', true); end if;
  return jsonb_build_object('configured', true, 'version', v_n ->> 'version', 'text', v_n ->> 'text', 'acknowledged', private.notice_acknowledged(c.id));
end $$;

create or replace function public.acknowledge_clinic_privacy_notice(p_operation_key uuid, p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.clinics; v_prev jsonb; v_ver text; v_text text; v_sha text; v_g uuid; v_id uuid;
begin
  if auth.uid() is null or not private.session_ok() then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select * into c from public.clinics where id = p_clinic_id and status = 'active';
  if c.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_ver := c.operational_policy -> 'privacyNotice' ->> 'version';
  v_text := c.operational_policy -> 'privacyNotice' ->> 'text';
  if v_ver is null or v_text is null then raise exception 'this clinic has no privacy notice to accept' using errcode = 'CV409'; end if;
  v_prev := private.begin_command(c.organization_id, p_operation_key, 'privacy.acknowledge_clinic', jsonb_build_object('c', p_clinic_id, 'v', v_ver));
  if v_prev is not null then return v_prev; end if;
  if not private.notice_acknowledged(c.id) then
    v_sha := private.notice_digest(v_text);
    -- Link the guardian identity only if one already exists; never create one just for reading a notice.
    select id into v_g from public.guardians where organization_id = c.organization_id and profile_id = auth.uid();
    insert into public.privacy_records (organization_id, guardian_id, clinic_id, profile_id, purpose, record_type, notice_version, notice_sha256, decision, created_by)
    values (c.organization_id, v_g, c.id, auth.uid(), 'care_records', 'notice_acknowledgement', v_ver, v_sha, 'acknowledged', auth.uid()) returning id into v_id;
    perform private.audit(c.organization_id, 'guardian', 'privacy.acknowledged', 'clinic', p_clinic_id, null, jsonb_build_object('version', v_ver, 'sha256', v_sha), null);
  end if;
  return private.finish_command(c.organization_id, p_operation_key, jsonb_build_object('version', v_ver, 'acknowledged', true));
end $$;

-- The older per-version command (0003) records the clinic too; the text digest is recorded only when the version named is
-- the clinic's current notice, so naming any other label never satisfies the gate.
create or replace function public.acknowledge_privacy_notice(p_operation_key uuid, p_clinic_id uuid, p_notice_version text, p_purpose text default 'care_records') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_g uuid; v_id uuid; v_n jsonb;
begin
  if auth.uid() is null or not private.session_ok() then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select organization_id, operational_policy -> 'privacyNotice' into v_org, v_n from public.clinics where id = p_clinic_id and status = 'active';
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'privacy.acknowledge', jsonb_build_object('clinic', p_clinic_id, 'v', p_notice_version, 'p', p_purpose));
  if v_prev is not null then return v_prev; end if;
  if p_notice_version is null or length(btrim(p_notice_version)) = 0 then raise exception 'notice version required' using errcode = 'CV422'; end if;
  select id into v_g from public.guardians where organization_id = v_org and profile_id = auth.uid();
  insert into public.privacy_records (organization_id, guardian_id, clinic_id, profile_id, purpose, record_type, notice_version, notice_sha256, decision, created_by)
  values (v_org, v_g, p_clinic_id, auth.uid(), left(p_purpose, 100), 'notice_acknowledgement', left(p_notice_version, 50),
          case when v_n ->> 'version' = p_notice_version and v_n ->> 'text' is not null then private.notice_digest(v_n ->> 'text') end,
          'acknowledged', auth.uid()) returning id into v_id;
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('privacyRecordId', v_id));
end $$;

create or replace function private.require_privacy_ack(p_clinic uuid) returns void language plpgsql stable security definer set search_path = '' as $$
declare c public.clinics; v_ver text;
begin
  select * into c from public.clinics where id = p_clinic;
  if c.id is null then return; end if;
  v_ver := c.operational_policy -> 'privacyNotice' ->> 'version';
  if v_ver is not null and auth.uid() is not null and not private.notice_acknowledged(c.id) then
    raise exception 'please read and accept the clinic''s privacy notice first' using errcode = 'CV409';
  end if;
end $$;

-- Same JSON shape as 0031 ([{clinicId, clinicName, version, text}]). Bounded to 100 notices; clinics where the family already
-- has a child come first. The list still covers other active clinics because the add-a-child and link forms let a family
-- choose any public clinic, and that clinic's notice must be accepted first. Once those forms show the chosen clinic's notice
-- inline (get_privacy_notice), this can be narrowed to related clinics only.
create or replace function public.get_pending_privacy_notices() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_res jsonb;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('clinicId', x.id, 'clinicName', x.name, 'version', x.ver, 'text', x.txt) order by x.mine desc, x.name, x.id), '[]'::jsonb)
    into v_res
    from (
      select c.id, c.name, c.operational_policy -> 'privacyNotice' ->> 'version' as ver, c.operational_policy -> 'privacyNotice' ->> 'text' as txt,
             exists (select 1 from public.guardians g
                       join public.guardian_child_relationships r on r.guardian_id = g.id and r.status in ('provisional','active','suspended')
                       join public.child_clinic_enrollments e on e.child_id = r.child_id and e.clinic_id = c.id and e.status in ('pending','active')
                      where g.profile_id = auth.uid()) as mine
        from public.clinics c
       where c.status = 'active'
         and c.operational_policy -> 'privacyNotice' ->> 'version' is not null and c.operational_policy -> 'privacyNotice' ->> 'text' is not null
         and not private.notice_acknowledged(c.id)
       order by mine desc, c.name, c.id
       limit 100) x;
  return v_res;
end $$;

drop function private.guardian_ack_version(uuid, text);

-- Binds acknowledgements written before this migration to the clinic their command receipt proves (receipt and record are
-- written in one transaction, so received_at = recorded_at, and the receipt's payload hash names the clinic). The digest is
-- recorded only when that clinic still shows the same version and its text was set before the acknowledgement. Rows that
-- cannot be attributed keep clinic_id null and no longer satisfy the gate: those families are asked to accept again.
create function private.backfill_privacy_acknowledgements() returns integer
language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  alter table public.privacy_records disable trigger privacy_records_immutable;
  with cand as (
    select distinct on (pr.id) pr.id, cl.id as clinic_id
      from public.privacy_records pr
      join private.command_receipts r on r.organization_id = pr.organization_id and r.actor_id = pr.created_by and r.received_at = pr.recorded_at
                                     and r.command_type in ('privacy.acknowledge_clinic', 'privacy.acknowledge')
      join public.clinics cl on cl.organization_id = pr.organization_id
     where pr.record_type = 'notice_acknowledgement' and pr.clinic_id is null
       and r.payload_hash = case r.command_type
             when 'privacy.acknowledge_clinic' then encode(sha256(convert_to(jsonb_build_object('c', cl.id, 'v', pr.notice_version)::text, 'UTF8')), 'hex')
             else encode(sha256(convert_to(jsonb_build_object('clinic', cl.id, 'v', pr.notice_version, 'p', pr.purpose)::text, 'UTF8')), 'hex') end
     order by pr.id, cl.id
  )
  update public.privacy_records pr
     set clinic_id = cand.clinic_id,
         notice_sha256 = case when cl.operational_policy -> 'privacyNotice' ->> 'version' = pr.notice_version
                                and cl.operational_policy -> 'privacyNotice' ->> 'text' is not null
                                and coalesce((cl.operational_policy -> 'privacyNotice' ->> 'setAt')::timestamptz, '-infinity'::timestamptz) <= pr.recorded_at
                              then private.notice_digest(cl.operational_policy -> 'privacyNotice' ->> 'text') end
    from cand join public.clinics cl on cl.id = cand.clinic_id
   where pr.id = cand.id;
  get diagnostics n = row_count;
  update public.privacy_records pr set profile_id = g.profile_id
    from public.guardians g where g.id = pr.guardian_id and pr.profile_id is null and pr.record_type = 'notice_acknowledgement';
  alter table public.privacy_records enable trigger privacy_records_immutable;
  return n;
end $$;

-- ---------------------------------------------------------------------------------------------
-- DB-04: clinic-scoped visibility (restrictive, reversible default; see the handoff and known-limitations)
-- ---------------------------------------------------------------------------------------------
alter table private.audit_logs add column clinic_id uuid;

-- The clinic whose capability authorised the current command is remembered for the rest of the transaction, so audit rows
-- written by that command record it without changing the 126 private.audit call sites.
create or replace function private.require_capability(p_clinic uuid, p_cap text) returns void
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.has_capability(p_clinic, p_cap) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
  perform pg_catalog.set_config('cvsrs.audit_clinic', p_clinic::text, true);
end $$;

create or replace function private.require_any(p_clinic uuid, p_caps text[]) returns void
language plpgsql stable security definer set search_path = '' as $$
declare c text;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  foreach c in array p_caps loop
    if private.has_capability(p_clinic, c) then
      perform pg_catalog.set_config('cvsrs.audit_clinic', p_clinic::text, true);
      return;
    end if;
  end loop;
  raise exception 'forbidden' using errcode = 'CV403';
end $$;

create or replace function private.audit(
  p_org uuid, p_capability text, p_action text, p_entity_type text, p_entity_id uuid,
  p_before jsonb, p_after jsonb, p_reason text, p_outcome text default 'success'
) returns void language plpgsql security definer set search_path = '' as $$
declare v_clinic uuid := nullif(pg_catalog.current_setting('cvsrs.audit_clinic', true), '')::uuid;
begin
  if v_clinic is not null and not exists (select 1 from public.clinics c where c.id = v_clinic and c.organization_id is not distinct from p_org) then
    v_clinic := null;
  end if;
  insert into private.audit_logs (organization_id, clinic_id, actor_id, actor_capability, action, entity_type, entity_id,
                                  before, after, reason, request_id, outcome, system_job_id)
  values (p_org, v_clinic, auth.uid(), p_capability, p_action, p_entity_type, p_entity_id, p_before, p_after, p_reason,
          private.request_id(), p_outcome, case when auth.uid() is null then 'system' end);
end $$;

-- Whether an audit row belongs to a clinic: its recorded clinic when it has one; otherwise (rows written before this
-- migration, or by families) the clinic its entity resolves to. Organization-wide rows with no clinic belong to none:
-- no organization-level capability exists in the capability vocabulary, so nobody can search them through the API.
create function private.audit_row_in_clinic(p_clinic uuid, p_row_clinic uuid, p_entity_type text, p_entity_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select case
    when p_row_clinic is not null then p_row_clinic = p_clinic
    when p_entity_id is null then false
    when p_entity_type = 'clinic' then p_entity_id = p_clinic
    when p_entity_type = 'child' then private.child_in_clinic(private.canonical_child(p_entity_id), p_clinic)
    when p_entity_type = 'certificate' then exists (select 1 from public.certificates x where x.id = p_entity_id and x.clinic_id = p_clinic)
    when p_entity_type = 'review_case' then exists (select 1 from public.record_review_cases x where x.id = p_entity_id and x.clinic_id = p_clinic)
    when p_entity_type = 'staff_membership' then exists (select 1 from public.staff_memberships x where x.id = p_entity_id and x.clinic_id = p_clinic)
    when p_entity_type = 'appointment' then exists (select 1 from public.appointments x join public.clinic_sessions s on s.id = x.session_id where x.id = p_entity_id and s.clinic_id = p_clinic)
    when p_entity_type = 'queue_entry' then exists (select 1 from public.queue_entries x where x.id = p_entity_id and x.clinic_id = p_clinic)
    when p_entity_type = 'catchup_plan' then exists (select 1 from public.catchup_plans x where x.id = p_entity_id and x.clinic_id = p_clinic)
    when p_entity_type = 'checkin' then exists (select 1 from public.checkins x where x.id = p_entity_id and x.clinic_id = p_clinic)
    when p_entity_type = 'clinic_session' then exists (select 1 from public.clinic_sessions x where x.id = p_entity_id and x.clinic_id = p_clinic)
    when p_entity_type = 'stock_location' then exists (select 1 from public.stock_locations x where x.id = p_entity_id and x.clinic_id = p_clinic)
    when p_entity_type = 'stock_transfer' then exists (select 1 from public.stock_transfers x where x.id = p_entity_id and p_clinic in (x.from_clinic_id, x.to_clinic_id))
    when p_entity_type = 'clinical_hold' then exists (select 1 from public.clinical_holds x where x.id = p_entity_id and private.child_in_clinic(private.canonical_child(x.child_id), p_clinic))
    when p_entity_type = 'relationship' then exists (select 1 from public.guardian_child_relationships x where x.id = p_entity_id and private.child_in_clinic(private.canonical_child(x.child_id), p_clinic))
    when p_entity_type = 'vaccination_event' then exists (select 1 from public.vaccination_revisions x where x.event_id = p_entity_id
                                                           and (x.clinic_id = p_clinic or private.child_in_clinic(private.canonical_child(x.child_id), p_clinic)))
    else false
  end
$$;

-- Lot trace: identities only for children of this clinic; other clinics' uses are counted, never named.
create or replace function public.trace_lot_use(p_clinic_id uuid, p_lot_id uuid) returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_res jsonb; v_other jsonb; v_other_n bigint;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'inventory.approve');
  perform private.require_capability(p_clinic_id, 'child.read_clinical');
  with cur as (
    select distinct on (r.event_id) r.* from public.vaccination_revisions r
     where r.event_id in (select x.event_id from public.vaccination_revisions x where x.lot_id = p_lot_id and x.organization_id = v_org)
     order by r.event_id, r.revision_no desc
  ), t as materialized (
    select cr.event_id, cr.revision_no, k.canon, cr.administered_on, cr.verification_status, cr.event_status, cr.source, cr.clinic_id,
           private.child_in_clinic(k.canon, p_clinic_id) as here
      from cur cr cross join lateral (select private.canonical_child(cr.child_id) as canon) k
     where cr.lot_id = p_lot_id and cr.organization_id = v_org
  )
  select (select coalesce(jsonb_agg(jsonb_build_object('scope', 'this_clinic', 'eventId', t.event_id, 'childId', c.id, 'childName', c.display_name, 'recordNo', c.local_record_no,
                    'administeredOn', t.administered_on, 'status', t.verification_status, 'eventStatus', t.event_status, 'source', t.source, 'revisionNo', t.revision_no, 'clinicId', t.clinic_id)
                    order by t.administered_on, c.display_name), '[]'::jsonb)
            from t join public.children c on c.id = t.canon where t.here),
         (select coalesce(jsonb_agg(jsonb_build_object('scope', 'other_clinic', 'clinicId', o.clinic_id, 'clinicName', o.name, 'records', o.n) order by o.name nulls last, o.clinic_id), '[]'::jsonb)
            from (select t.clinic_id, cl.name, count(*) n from t left join public.clinics cl on cl.id = t.clinic_id where not t.here group by t.clinic_id, cl.name) o),
         (select count(*) from t where not t.here)
    into v_res, v_other, v_other_n;
  perform private.audit(v_org, 'inventory.approve', 'lot.traced', 'vaccine_lot', p_lot_id, null,
                        jsonb_build_object('records', jsonb_array_length(v_res), 'otherClinicRecords', v_other_n), null);
  return v_res || v_other;
end $$;

-- DB-04 + DB-06: clinic-scoped rows, index-ordered newest first, keyset on (server_time, id). p_before_id is optional:
-- the original seven-argument call keeps its meaning (server_time < p_before); nextBeforeId is returned for gap-free paging.
drop function public.search_audit(uuid, text, uuid, timestamptz, timestamptz, timestamptz, integer);
create function public.search_audit(p_clinic_id uuid, p_action text default null, p_actor uuid default null, p_from timestamptz default null, p_to timestamptz default null,
                                    p_before timestamptz default null, p_limit integer default 50, p_before_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_lim int := least(greatest(coalesce(p_limit, 50), 1), 100); v_rows jsonb; v_last jsonb; v_kids uuid[];
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'audit.read');
  if p_from is not null and p_to is not null and p_to < p_from then raise exception 'the end of the period is before its start' using errcode = 'CV422'; end if;
  -- Children of this clinic (and their merged aliases), resolved once: rows without a recorded clinic about a child are matched
  -- against this set with a hashed lookup instead of a per-row enrollment check (same rule as private.audit_row_in_clinic).
  v_kids := array(select a.id from public.child_clinic_enrollments e join public.children c on c.id = e.child_id and c.merged_into_id is null
                   cross join lateral private.child_ids_with_aliases(e.child_id) a(id)
                   where e.clinic_id = p_clinic_id and e.status in ('pending','active'));
  select coalesce(jsonb_agg(x.j order by x.t desc, x.id desc), '[]'::jsonb) into v_rows from (
    select a.server_time t, a.id, jsonb_build_object('id', a.id, 'at', a.server_time, 'action', a.action, 'capability', a.actor_capability, 'entityType', a.entity_type, 'entityId', a.entity_id, 'outcome', a.outcome, 'reason', a.reason,
             'actor', (select display_name from public.profiles where id = a.actor_id), 'actorId', a.actor_id, 'system', a.system_job_id, 'before', a.before, 'after', a.after) j
      from private.audit_logs a
     where a.organization_id = v_org and (p_action is null or a.action like replace(replace(p_action, '%', ''), '_', '\_') || '%') and (p_actor is null or a.actor_id = p_actor)
       and (p_from is null or a.server_time >= p_from) and (p_to is null or a.server_time <= p_to)
       and (p_before is null or (p_before_id is null and a.server_time < p_before) or (p_before_id is not null and (a.server_time, a.id) < (p_before, p_before_id)))
       and (a.clinic_id = p_clinic_id
            or (a.clinic_id is null and (
                  (a.entity_type = 'clinic' and a.entity_id = p_clinic_id)
               or (a.entity_type = 'child' and a.entity_id in (select k.id from pg_catalog.unnest(v_kids) k(id)))
               or (a.entity_type not in ('clinic', 'child') and private.audit_row_in_clinic(p_clinic_id, null, a.entity_type, a.entity_id)))))
     order by a.server_time desc, a.id desc limit v_lim) x;
  perform private.audit(v_org, 'audit.read', 'audit.searched', 'clinic', p_clinic_id, null, jsonb_build_object('action', p_action, 'actor', p_actor, 'from', p_from, 'to', p_to, 'returned', jsonb_array_length(v_rows)), null);
  v_last := case when jsonb_array_length(v_rows) = v_lim then v_rows -> (v_lim - 1) end;
  return jsonb_build_object('rows', v_rows, 'nextBefore', v_last ->> 'at', 'nextBeforeId', v_last ->> 'id');
end $$;
revoke all on function public.search_audit(uuid, text, uuid, timestamptz, timestamptz, timestamptz, integer, uuid) from public, anon, authenticated;
grant execute on function public.search_audit(uuid, text, uuid, timestamptz, timestamptz, timestamptz, integer, uuid) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- SUP-02: first organization, clinic and staff on an empty project. Run once by the operator in the SQL Editor (as postgres);
-- never callable through the API. Both people must already have signed up (so their profiles exist), and each approves the
-- other's grant, which satisfies the two-person check on staff_memberships.
-- ---------------------------------------------------------------------------------------------
create function private.bootstrap_initial_staff(p_org_name text, p_clinic_name text, p_timezone text, p_admin_email text, p_lead_email text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_admin uuid; v_lead uuid; v_org uuid; v_clinic uuid; v_m_admin uuid; v_m_lead uuid;
begin
  lock table public.staff_memberships in share row exclusive mode;
  if exists (select 1 from public.staff_memberships where status in ('active','pending_approval')) then
    raise exception 'staff access already exists; grant further access with the in-app two-person process' using errcode = 'CV409';
  end if;
  if coalesce(btrim(p_org_name), '') = '' or coalesce(btrim(p_clinic_name), '') = '' then
    raise exception 'name the organization and its first clinic' using errcode = 'CV422';
  end if;
  select p.id into v_admin from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = lower(btrim(p_admin_email)) and p.status = 'active';
  select p.id into v_lead from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = lower(btrim(p_lead_email)) and p.status = 'active';
  if v_admin is null or v_lead is null or v_admin = v_lead then
    raise exception 'two different people who have already signed up are required' using errcode = 'CV422';
  end if;
  insert into public.organizations (name) values (btrim(p_org_name)) returning id into v_org;
  insert into public.clinics (organization_id, name, timezone) values (v_org, btrim(p_clinic_name), coalesce(nullif(btrim(p_timezone), ''), 'Asia/Manila')) returning id into v_clinic;
  insert into public.staff_memberships (organization_id, profile_id, clinic_id, role_code, status, requested_by, approved_by)
  values (v_org, v_admin, v_clinic, 'tech_admin', 'active', v_lead, v_lead) returning id into v_m_admin;
  insert into public.staff_memberships (organization_id, profile_id, clinic_id, role_code, status, requested_by, approved_by)
  values (v_org, v_lead, v_clinic, 'clinical_lead', 'active', v_admin, v_admin) returning id into v_m_lead;
  perform private.audit(v_org, null, 'staff.bootstrap', 'clinic', v_clinic, null,
                        jsonb_build_object('techAdmin', v_admin, 'clinicalLead', v_lead, 'memberships', jsonb_build_array(v_m_admin, v_m_lead)),
                        'operator bootstrap of the first organization, clinic and staff');
  return jsonb_build_object('organizationId', v_org, 'clinicId', v_clinic, 'techAdminMembershipId', v_m_admin, 'clinicalLeadMembershipId', v_m_lead);
end $$;

-- ---------------------------------------------------------------------------------------------
-- Grants for the new private helpers: no API role may execute any of them.
-- ---------------------------------------------------------------------------------------------
revoke all on function private.child_current_revisions(uuid[]), private.repoint_merged_holds(), private.notice_digest(text), private.notice_acknowledged(uuid),
  private.backfill_privacy_acknowledgements(), private.audit_row_in_clinic(uuid, uuid, text, uuid)
  from public, anon, authenticated;
revoke all on function private.bootstrap_initial_staff(text, text, text, text, text) from public, anon, authenticated, service_role;

-- ---------------------------------------------------------------------------------------------
-- One-time data repair for state written before this migration.
-- ---------------------------------------------------------------------------------------------
select private.repoint_merged_holds();
select private.backfill_privacy_acknowledgements();
-- END 0034_integrity_performance.sql

-- =====================================================================================================================
-- BEGIN 0035_staff_applications.sql  sha256=fb01aa6a72a4a2f4abff20f17d1c9ab3559aebfb1bb759131d9f87c3061249b7
-- =====================================================================================================================
-- 0035: Staff applications. A person creating a staff account (or a signed-in person later) applies to one health center for a role.
-- An access administrator of that clinic accepts or rejects the application. Accepting does NOT grant access: it files the ordinary
-- staff-membership request (requested_by = the accepting administrator), which still needs independent approval by a different person
-- under 0002's two-person rule (clinical roles by a clinical lead). An application is a request, never an authorization source.

create table public.staff_applications (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  clinic_id uuid not null,
  profile_id uuid not null references public.profiles (id),
  requested_role text not null check (requested_role in ('assistant','clinical_staff','clinical_lead','inventory','bhw','tech_admin')),
  position_title text check (position_title is null or length(btrim(position_title)) between 1 and 80),
  note text check (note is null or length(note) <= 500),
  status text not null default 'pending' check (status in ('pending','accepted','rejected','withdrawn')),
  decided_by uuid references public.profiles (id),
  decided_at timestamptz,
  decision_reason text check (decision_reason is null or length(decision_reason) <= 500),
  membership_id uuid references public.staff_memberships (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  foreign key (organization_id, clinic_id) references public.clinics (organization_id, id),
  check (status = 'pending' or decided_at is not null),
  check (status <> 'accepted' or (membership_id is not null and decided_by is not null)),
  check (status <> 'rejected' or (decided_by is not null and decision_reason is not null)),
  -- Nobody decides their own application.
  check (decided_by is null or decided_by <> profile_id)
);
create trigger staff_applications_touch before update on public.staff_applications for each row execute function private.touch_row();
create unique index staff_applications_one_pending_uq on public.staff_applications (profile_id, clinic_id) where status = 'pending';
create index staff_applications_clinic_status_idx on public.staff_applications (clinic_id, status, created_at desc);
create index staff_applications_profile_idx on public.staff_applications (profile_id, created_at desc);

alter table public.staff_applications enable row level security;
revoke all on public.staff_applications from anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- Shared validation and insert (used by the sign-up trigger and by submit_staff_application)
-- ---------------------------------------------------------------------------------------------
create function private.create_staff_application(p_profile uuid, p_clinic uuid, p_role text, p_title text, p_note text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_id uuid; v_title text := nullif(btrim(coalesce(p_title, '')), ''); v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  select organization_id into v_org from public.clinics where id = p_clinic and status = 'active';
  if v_org is null then raise exception 'That health center is not accepting staff applications.' using errcode = 'CV404'; end if;
  if p_role is null or p_role not in ('assistant','clinical_staff','clinical_lead','inventory','bhw','tech_admin') then
    raise exception 'Choose the role you are applying for.' using errcode = 'CV422';
  end if;
  if v_title is not null and length(v_title) > 80 then raise exception 'Keep the job title under 80 characters.' using errcode = 'CV422'; end if;
  if v_note is not null and length(v_note) > 500 then raise exception 'Keep the note under 500 characters.' using errcode = 'CV422'; end if;
  if not exists (select 1 from public.profiles where id = p_profile and status = 'active') then
    raise exception 'This account cannot apply right now.' using errcode = 'CV422';
  end if;
  if exists (select 1 from public.staff_memberships m where m.profile_id = p_profile and m.clinic_id = p_clinic
              and m.status in ('active','pending_approval') and (m.valid_until is null or m.valid_until > now())) then
    raise exception 'You already have access, or an access request in progress, at this health center.' using errcode = 'CV409';
  end if;
  if exists (select 1 from public.staff_applications a where a.profile_id = p_profile and a.clinic_id = p_clinic and a.status = 'pending') then
    raise exception 'You already have an application waiting at this health center.' using errcode = 'CV409';
  end if;
  if (select count(*) from public.staff_applications a where a.profile_id = p_profile and a.status = 'pending') >= 5 then
    raise exception 'You have five applications waiting. Withdraw one before applying again.' using errcode = 'CV422';
  end if;

  insert into public.staff_applications (organization_id, clinic_id, profile_id, requested_role, position_title, note)
  values (v_org, p_clinic, p_profile, p_role, v_title, v_note)
  returning id into v_id;
  perform private.audit(v_org, null, 'staff_application.submitted', 'staff_application', v_id, null,
                        jsonb_build_object('clinic', p_clinic, 'profile', p_profile, 'role', p_role), null);
  return v_id;
end $$;

-- Sign-up: the profile row as before, plus the application a staff sign-up carries in its metadata. The application is a request only;
-- a bad or stale detail (for example a clinic closed since the form loaded) must never block account creation, so it is skipped with a
-- warning and the person applies again from the clinic workspace, which shows that no application exists.
create or replace function private.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_app jsonb := new.raw_user_meta_data -> 'staff_application';
begin
  insert into public.profiles (id, display_name)
  values (new.id, left(coalesce(new.raw_user_meta_data ->> 'display_name', ''), 120))
  on conflict (id) do nothing;
  if jsonb_typeof(v_app) = 'object' then
    begin
      perform private.create_staff_application(new.id, (v_app ->> 'clinic_id')::uuid, v_app ->> 'role', v_app ->> 'position_title', v_app ->> 'note');
    exception when others then
      raise warning 'staff application from sign-up was not recorded: %', sqlerrm;
    end;
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Applicant commands
-- ---------------------------------------------------------------------------------------------
create function public.submit_staff_application(p_operation_key uuid, p_clinic_id uuid, p_role text, p_position_title text default null, p_note text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; v_id uuid;
begin
  if not private.session_ok() then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select organization_id into v_org from public.clinics where id = p_clinic_id and status = 'active';
  if v_org is null then raise exception 'That health center is not accepting staff applications.' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'staff_application.submit',
                                  jsonb_build_object('c', p_clinic_id, 'r', p_role, 't', p_position_title, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  v_id := private.create_staff_application(auth.uid(), p_clinic_id, p_role, p_position_title, p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('applicationId', v_id, 'status', 'pending'));
end $$;

create function public.withdraw_staff_application(p_operation_key uuid, p_application_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare a public.staff_applications; v_prev jsonb;
begin
  if not private.session_ok() then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select * into a from public.staff_applications where id = p_application_id and profile_id = auth.uid() for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(a.organization_id, p_operation_key, 'staff_application.withdraw', jsonb_build_object('a', p_application_id));
  if v_prev is not null then return v_prev; end if;
  if a.status <> 'pending' then raise exception 'This application has already been decided.' using errcode = 'CV409'; end if;
  update public.staff_applications set status = 'withdrawn', decided_at = now() where id = a.id;
  perform private.audit(a.organization_id, null, 'staff_application.withdrawn', 'staff_application', a.id,
                        jsonb_build_object('status', a.status), jsonb_build_object('status', 'withdrawn'), null);
  return private.finish_command(a.organization_id, p_operation_key, jsonb_build_object('applicationId', a.id, 'status', 'withdrawn'));
end $$;

-- The caller's own applications, newest first, with the state of any access request an acceptance created.
create function public.my_staff_applications() returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'applicationId', a.id, 'clinicId', a.clinic_id, 'clinicName', c.name, 'clinicTimezone', c.timezone, 'requestedRole', a.requested_role,
      'positionTitle', a.position_title, 'status', a.status, 'decisionReason', a.decision_reason,
      'createdAt', a.created_at, 'decidedAt', a.decided_at, 'membershipStatus', m.status, 'grantedRole', m.role_code)
    order by a.created_at desc), '[]'::jsonb)
    from public.staff_applications a
    join public.clinics c on c.id = a.clinic_id
    left join public.staff_memberships m on m.id = a.membership_id
   where private.session_ok() and a.profile_id = auth.uid()
$$;

-- ---------------------------------------------------------------------------------------------
-- Administrator commands (admin.users or grant.approve.clinical at the application's clinic)
-- ---------------------------------------------------------------------------------------------
create function private.can_review_applications(p_clinic uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select private.has_capability(p_clinic, 'admin.users') or private.has_capability(p_clinic, 'grant.approve.clinical')
$$;

-- p_view: 'pending' (default) or 'decided' (the 50 most recent accepted, rejected or withdrawn).
create function public.list_staff_applications(p_clinic_id uuid, p_view text default 'pending') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_res jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if not private.can_review_applications(p_clinic_id) then raise exception 'forbidden' using errcode = 'CV403'; end if;
  if p_view not in ('pending','decided') then raise exception 'Unknown list.' using errcode = 'CV422'; end if;
  select coalesce(jsonb_agg(item order by sort_at desc), '[]'::jsonb) into v_res from (
    select jsonb_build_object(
        'applicationId', a.id, 'profileId', a.profile_id, 'displayName', p.display_name, 'email', u.email,
        -- Supabase records email confirmation; the local stand-in table has no such column, so the answer is unknown (null) there.
        'emailConfirmed', case when to_jsonb(u) ? 'email_confirmed_at' then (to_jsonb(u) ->> 'email_confirmed_at') is not null end,
        'requestedRole', a.requested_role, 'positionTitle', a.position_title, 'note', a.note, 'status', a.status, 'version', a.version,
        'createdAt', a.created_at, 'decidedAt', a.decided_at, 'decidedByName', d.display_name, 'decisionReason', a.decision_reason,
        'membershipId', a.membership_id, 'membershipStatus', m.status, 'grantedRole', m.role_code,
        'requiresClinicalApproval', private.membership_is_clinical(a.requested_role, '{}')) as item,
        coalesce(a.decided_at, a.created_at) as sort_at
      from public.staff_applications a
      join public.profiles p on p.id = a.profile_id
      join auth.users u on u.id = a.profile_id
      left join public.profiles d on d.id = a.decided_by
      left join public.staff_memberships m on m.id = a.membership_id
     where a.clinic_id = p_clinic_id
       and (case when p_view = 'pending' then a.status = 'pending' else a.status <> 'pending' end)
     order by coalesce(a.decided_at, a.created_at) desc
     limit case when p_view = 'pending' then 500 else 50 end
  ) s;
  return v_res;
end $$;

-- Accept: files the staff-membership request for the chosen role (default: the role applied for). The membership is pending until a
-- different person approves it (0002); this administrator cannot approve it themselves because they are its requester.
create function public.accept_staff_application(p_operation_key uuid, p_clinic_id uuid, p_application_id uuid, p_expected_version integer,
                                                p_role text, p_capabilities text[] default '{}')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare a public.staff_applications; v_prev jsonb; v_req jsonb; v_role text := coalesce(nullif(p_role, ''), null);
begin
  select * into a from public.staff_applications where id = p_application_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if not private.can_review_applications(a.clinic_id) then raise exception 'forbidden' using errcode = 'CV403'; end if;
  v_role := coalesce(v_role, a.requested_role);
  v_prev := private.begin_command(a.organization_id, p_operation_key, 'staff_application.accept',
                                  jsonb_build_object('a', p_application_id, 'v', p_expected_version, 'r', v_role, 'caps', to_jsonb(coalesce(p_capabilities, '{}'))));
  if v_prev is not null then return v_prev; end if;
  if a.status <> 'pending' then raise exception 'This application has already been decided.' using errcode = 'CV409'; end if;
  if a.version <> p_expected_version then raise exception 'This application changed while you were reviewing it. Reload and try again.' using errcode = 'CV409'; end if;
  if a.profile_id = auth.uid() then raise exception 'You cannot decide your own application.' using errcode = 'CV403'; end if;
  if v_role not in ('assistant','clinical_staff','clinical_lead','inventory','bhw','tech_admin') then
    raise exception 'Choose a role.' using errcode = 'CV422';
  end if;
  if exists (select 1 from public.staff_memberships m where m.profile_id = a.profile_id and m.clinic_id = a.clinic_id and m.role_code = v_role
              and m.status in ('active','pending_approval')) then
    raise exception 'This person already has this role, or a request for it, at this health center.' using errcode = 'CV409';
  end if;

  -- The ordinary request command: same checks (requester capability, active profile), same audit entry, same two-person approval.
  v_req := public.request_staff_membership(gen_random_uuid(), a.clinic_id, a.profile_id, v_role, coalesce(p_capabilities, '{}'), null);
  update public.staff_applications
     set status = 'accepted', decided_by = auth.uid(), decided_at = now(), membership_id = (v_req ->> 'membershipId')::uuid
   where id = a.id;
  perform private.audit(a.organization_id, case when private.has_capability(a.clinic_id, 'admin.users') then 'admin.users' else 'grant.approve.clinical' end,
                        'staff_application.accepted', 'staff_application', a.id, jsonb_build_object('status', a.status),
                        jsonb_build_object('status', 'accepted', 'role', v_role, 'membership', v_req ->> 'membershipId'), null);
  return private.finish_command(a.organization_id, p_operation_key, jsonb_build_object(
    'applicationId', a.id, 'status', 'accepted', 'membershipId', v_req ->> 'membershipId',
    'requiresClinicalApproval', (v_req ->> 'requiresClinicalApproval')::boolean));
end $$;

create function public.reject_staff_application(p_operation_key uuid, p_clinic_id uuid, p_application_id uuid, p_expected_version integer, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare a public.staff_applications; v_prev jsonb; v_reason text := btrim(coalesce(p_reason, ''));
begin
  select * into a from public.staff_applications where id = p_application_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if not private.can_review_applications(a.clinic_id) then raise exception 'forbidden' using errcode = 'CV403'; end if;
  v_prev := private.begin_command(a.organization_id, p_operation_key, 'staff_application.reject',
                                  jsonb_build_object('a', p_application_id, 'v', p_expected_version, 'reason', v_reason));
  if v_prev is not null then return v_prev; end if;
  if length(v_reason) < 3 then raise exception 'Give the applicant a short reason.' using errcode = 'CV422'; end if;
  if length(v_reason) > 500 then raise exception 'Keep the reason under 500 characters.' using errcode = 'CV422'; end if;
  if a.status <> 'pending' then raise exception 'This application has already been decided.' using errcode = 'CV409'; end if;
  if a.version <> p_expected_version then raise exception 'This application changed while you were reviewing it. Reload and try again.' using errcode = 'CV409'; end if;
  if a.profile_id = auth.uid() then raise exception 'You cannot decide your own application.' using errcode = 'CV403'; end if;
  update public.staff_applications set status = 'rejected', decided_by = auth.uid(), decided_at = now(), decision_reason = v_reason where id = a.id;
  perform private.audit(a.organization_id, case when private.has_capability(a.clinic_id, 'admin.users') then 'admin.users' else 'grant.approve.clinical' end,
                        'staff_application.rejected', 'staff_application', a.id, jsonb_build_object('status', a.status),
                        jsonb_build_object('status', 'rejected'), v_reason);
  return private.finish_command(a.organization_id, p_operation_key, jsonb_build_object('applicationId', a.id, 'status', 'rejected'));
end $$;

revoke all on function private.create_staff_application(uuid, uuid, text, text, text), private.can_review_applications(uuid) from public, anon, authenticated;
revoke all on function public.submit_staff_application(uuid, uuid, text, text, text), public.withdraw_staff_application(uuid, uuid),
  public.my_staff_applications(), public.list_staff_applications(uuid, text),
  public.accept_staff_application(uuid, uuid, uuid, integer, text, text[]), public.reject_staff_application(uuid, uuid, uuid, integer, text)
  from public, anon, authenticated;
grant execute on function public.submit_staff_application(uuid, uuid, text, text, text), public.withdraw_staff_application(uuid, uuid),
  public.my_staff_applications(), public.list_staff_applications(uuid, text),
  public.accept_staff_application(uuid, uuid, uuid, integer, text, text[]), public.reject_staff_application(uuid, uuid, uuid, integer, text)
  to authenticated;
-- END 0035_staff_applications.sql

-- =====================================================================================================================
-- BEGIN 0036_staff_application_messages.sql  sha256=ba8d67875f73e5851fa8a5292ec679abc5d6f52e7c447d1f78305adce2134704
-- =====================================================================================================================
-- 0036: tell staff applicants about a decision in their in-app inbox. accept/reject keep 0035's signatures (and therefore their grants);
-- the only change is the message, written in the same transaction as the decision (no external delivery, like 0021's check-in replies).

create function private.staff_role_label(p_role text) returns text language sql immutable set search_path = '' as $$
  select case p_role
    when 'clinical_staff' then 'Clinical staff (nurse or midwife)'
    when 'assistant' then 'Registration assistant'
    when 'bhw' then 'Barangay health worker'
    when 'inventory' then 'Inventory clerk'
    when 'clinical_lead' then 'Clinical lead'
    when 'tech_admin' then 'Technical administrator'
    else replace(p_role, '_', ' ')
  end
$$;
revoke all on function private.staff_role_label(text) from public, anon, authenticated;

create or replace function public.accept_staff_application(p_operation_key uuid, p_clinic_id uuid, p_application_id uuid, p_expected_version integer,
                                                p_role text, p_capabilities text[] default '{}')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare a public.staff_applications; v_prev jsonb; v_req jsonb; v_role text := coalesce(nullif(p_role, ''), null);
begin
  select * into a from public.staff_applications where id = p_application_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if not private.can_review_applications(a.clinic_id) then raise exception 'forbidden' using errcode = 'CV403'; end if;
  v_role := coalesce(v_role, a.requested_role);
  v_prev := private.begin_command(a.organization_id, p_operation_key, 'staff_application.accept',
                                  jsonb_build_object('a', p_application_id, 'v', p_expected_version, 'r', v_role, 'caps', to_jsonb(coalesce(p_capabilities, '{}'))));
  if v_prev is not null then return v_prev; end if;
  if a.status <> 'pending' then raise exception 'This application has already been decided.' using errcode = 'CV409'; end if;
  if a.version <> p_expected_version then raise exception 'This application changed while you were reviewing it. Reload and try again.' using errcode = 'CV409'; end if;
  if a.profile_id = auth.uid() then raise exception 'You cannot decide your own application.' using errcode = 'CV403'; end if;
  if v_role not in ('assistant','clinical_staff','clinical_lead','inventory','bhw','tech_admin') then
    raise exception 'Choose a role.' using errcode = 'CV422';
  end if;
  if exists (select 1 from public.staff_memberships m where m.profile_id = a.profile_id and m.clinic_id = a.clinic_id and m.role_code = v_role
              and m.status in ('active','pending_approval')) then
    raise exception 'This person already has this role, or a request for it, at this health center.' using errcode = 'CV409';
  end if;

  -- The ordinary request command: same checks (requester capability, active profile), same audit entry, same two-person approval.
  v_req := public.request_staff_membership(gen_random_uuid(), a.clinic_id, a.profile_id, v_role, coalesce(p_capabilities, '{}'), null);
  update public.staff_applications
     set status = 'accepted', decided_by = auth.uid(), decided_at = now(), membership_id = (v_req ->> 'membershipId')::uuid
   where id = a.id;
  -- Tell the applicant in their inbox (same transaction, no external delivery). The status page shows the same facts.
  insert into public.messages (organization_id, recipient_profile_id, child_id, kind, title, body, dedupe_key)
  select a.organization_id, a.profile_id, null, 'staff_application', 'Your staff application was accepted',
         left('Your application to ' || c.name || ' was accepted for the role ' || private.staff_role_label(v_role) ||
              '. A second person approves your access next; the clinic workspace opens once they do.', 600),
         'staff_application:' || a.id || ':accepted'
    from public.clinics c where c.id = a.clinic_id
  on conflict (recipient_profile_id, dedupe_key) do nothing;
  perform private.audit(a.organization_id, case when private.has_capability(a.clinic_id, 'admin.users') then 'admin.users' else 'grant.approve.clinical' end,
                        'staff_application.accepted', 'staff_application', a.id, jsonb_build_object('status', a.status),
                        jsonb_build_object('status', 'accepted', 'role', v_role, 'membership', v_req ->> 'membershipId'), null);
  return private.finish_command(a.organization_id, p_operation_key, jsonb_build_object(
    'applicationId', a.id, 'status', 'accepted', 'membershipId', v_req ->> 'membershipId',
    'requiresClinicalApproval', (v_req ->> 'requiresClinicalApproval')::boolean));
end $$;

create or replace function public.reject_staff_application(p_operation_key uuid, p_clinic_id uuid, p_application_id uuid, p_expected_version integer, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare a public.staff_applications; v_prev jsonb; v_reason text := btrim(coalesce(p_reason, ''));
begin
  select * into a from public.staff_applications where id = p_application_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if not private.can_review_applications(a.clinic_id) then raise exception 'forbidden' using errcode = 'CV403'; end if;
  v_prev := private.begin_command(a.organization_id, p_operation_key, 'staff_application.reject',
                                  jsonb_build_object('a', p_application_id, 'v', p_expected_version, 'reason', v_reason));
  if v_prev is not null then return v_prev; end if;
  if length(v_reason) < 3 then raise exception 'Give the applicant a short reason.' using errcode = 'CV422'; end if;
  if length(v_reason) > 500 then raise exception 'Keep the reason under 500 characters.' using errcode = 'CV422'; end if;
  if a.status <> 'pending' then raise exception 'This application has already been decided.' using errcode = 'CV409'; end if;
  if a.version <> p_expected_version then raise exception 'This application changed while you were reviewing it. Reload and try again.' using errcode = 'CV409'; end if;
  if a.profile_id = auth.uid() then raise exception 'You cannot decide your own application.' using errcode = 'CV403'; end if;
  update public.staff_applications set status = 'rejected', decided_by = auth.uid(), decided_at = now(), decision_reason = v_reason where id = a.id;
  insert into public.messages (organization_id, recipient_profile_id, child_id, kind, title, body, dedupe_key)
  select a.organization_id, a.profile_id, null, 'staff_application', 'Your staff application was declined',
         left('Your application to ' || c.name || ' was declined. Reason: ' || v_reason || ' You can apply again from the clinic workspace.', 600),
         'staff_application:' || a.id || ':rejected'
    from public.clinics c where c.id = a.clinic_id
  on conflict (recipient_profile_id, dedupe_key) do nothing;
  perform private.audit(a.organization_id, case when private.has_capability(a.clinic_id, 'admin.users') then 'admin.users' else 'grant.approve.clinical' end,
                        'staff_application.rejected', 'staff_application', a.id, jsonb_build_object('status', a.status),
                        jsonb_build_object('status', 'rejected'), v_reason);
  return private.finish_command(a.organization_id, p_operation_key, jsonb_build_object('applicationId', a.id, 'status', 'rejected'));
end $$;
-- END 0036_staff_application_messages.sql

-- =====================================================================================================================
-- BEGIN 0037_operational_gaps.sql  sha256=7e1f46f3bfbc15f6890345db76ccf23d99b80ba62ed4e3e47e46bdba47afce25
-- =====================================================================================================================
-- 0037 Operational gaps found by the 2026-10-04 whole-system audit (docs/audit/2026-10-04-capstone-production-audit.md, F40-F50).
--
--  F40 A service day closes: unfinished tickets and visits reach a final state, missed bookings become no-shows, sessions close.
--      Staff close past days from Today; the worker closes them automatically (private.run_daily_maintenance).
--      A vaccination can no longer be recorded against an open visit from an earlier day.
--  F41 Staff read a child's bookings (list_child_appointments); booking, moving and cancelling reuse the existing commands.
--  F42 A cancelled session cancels its bookings (families already got the message); capacity can be changed; staff see who is booked.
--  F43 A schedule under clinical review can be sent back to draft (reviewer) or withdrawn (proposer).
--  F44 A stock count awaiting approval can be rejected.
--  F45 Families are told when the clinic verifies, pauses, restores or ends their access, and when a link request, an edit
--      request or a reported vaccine is decided.
--  F46 Reminders: the day before a booked visit, and once a week while a vaccine is due or overdue.
--  F47 People can correct their own name and language (update_my_profile).
--  F48 The phone number and language entered at sign-up are kept and become the guardian's (unverified) contact.
--  F49 An account created without a name is asked for one; the name falls back to the email's local part meanwhile.
--  F50 Real-world end states: a child marked inactive (moved, died), a guardian phone marked not working, a stock location
--      closed, and an operator-only account status change.
--
-- Conventions as in 0001: SECURITY DEFINER with an empty search_path, idempotent commands keyed by p_operation_key, stable
-- SQLSTATEs (CV4xx), one audit row per decision, explicit grants.

-- ---------------------------------------------------------------------------------------------
-- Schema additions
-- ---------------------------------------------------------------------------------------------
alter table public.profiles add column needs_name boolean not null default false;
alter table public.profiles add column signup_phone text check (signup_phone is null or length(signup_phone) <= 20);

alter table public.children add column inactive_reason text check (inactive_reason is null or inactive_reason in ('moved','deceased','other'));
alter table public.children add column inactive_note text check (inactive_note is null or length(inactive_note) <= 300);
alter table public.children add column inactive_at timestamptz;

-- When the daily jobs last ran (at most every ten minutes) and which children were checked for due reminders today.
create table private.maintenance_runs (
  job text primary key,
  last_run_at timestamptz not null
);
create table private.reminder_checks (
  child_id uuid primary key references public.children (id) on delete restrict,
  checked_on date not null
);
revoke all on private.maintenance_runs, private.reminder_checks from public, anon, authenticated;

-- Day closure scans only rows that are still open.
create index encounters_open_idx on public.encounters (clinic_id, service_date) where status = 'open';
create index clinic_sessions_open_idx on public.clinic_sessions (clinic_id, service_date) where status = 'open';
-- Guardian lookups by account (my_guardian_ids, contact preferences, care content) filter by profile_id alone.
create index guardians_profile_idx on public.guardians (profile_id) where deleted_at is null;

-- ---------------------------------------------------------------------------------------------
-- F40 Day closure
-- ---------------------------------------------------------------------------------------------
create function private.close_service_day_core(p_clinic uuid, p_date date, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; q public.queue_entries; v_done boolean;
  v_left int := 0; v_completed int := 0; v_unserved int := 0; v_no_show int := 0; v_cancelled int := 0; v_sessions int := 0; v_encounters int := 0;
begin
  select organization_id into v_org from public.clinics where id = p_clinic;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if p_date is null or p_date >= private.local_today(p_clinic) then raise exception 'only a past service day can be closed' using errcode = 'CV422'; end if;
  perform pg_catalog.set_config('cvsrs.audit_clinic', p_clinic::text, true);

  for q in select * from public.queue_entries where clinic_id = p_clinic and service_date = p_date and status in ('waiting','called','held','in_service')
            order by ticket_no for update loop
    if q.status = 'in_service' then
      -- A visit in service ends as vaccinated only when a vaccination was actually recorded in it; otherwise it ends unserved.
      v_done := q.encounter_id is not null and exists (select 1 from public.vaccination_events v where v.encounter_id = q.encounter_id);
      if v_done then
        update public.queue_entries set status = 'completed', completed_at = now(), updated_by = auth.uid() where id = q.id;
        update public.encounters set status = 'completed', outcome = 'vaccinated', ended_at = coalesce(ended_at, now()), updated_by = auth.uid()
         where id = q.encounter_id and status = 'open';
        if q.appointment_id is not null then
          update public.appointments set status = 'fulfilled', updated_by = auth.uid() where id = q.appointment_id and status in ('confirmed','checked_in');
        end if;
        perform private.queue_event(q, q.status, 'completed', q.station, p_reason);
        v_completed := v_completed + 1;
      else
        update public.queue_entries set status = 'left', completed_at = now(), updated_by = auth.uid() where id = q.id;
        update public.encounters set status = 'cancelled', outcome = 'left', ended_at = coalesce(ended_at, now()), updated_by = auth.uid()
         where id = q.encounter_id and status = 'open';
        perform private.queue_event(q, q.status, 'left', q.station, p_reason);
        v_unserved := v_unserved + 1;
      end if;
    else
      update public.queue_entries set status = 'left', completed_at = now(), updated_by = auth.uid() where id = q.id;
      perform private.queue_event(q, q.status, 'left', q.station, p_reason);
      v_left := v_left + 1;
    end if;
  end loop;

  -- Any other visit still open on that day (for example one opened before a ticket was cancelled elsewhere).
  with closed as (
    update public.encounters e
       set status = case when exists (select 1 from public.vaccination_events v where v.encounter_id = e.id) then 'completed' else 'cancelled' end,
           outcome = case when exists (select 1 from public.vaccination_events v where v.encounter_id = e.id) then 'vaccinated' else 'left' end,
           ended_at = coalesce(e.ended_at, now()), updated_by = auth.uid()
     where e.clinic_id = p_clinic and e.service_date = p_date and e.status = 'open'
    returning 1)
  select count(*) into v_encounters from closed;

  -- Bookings in a session the clinic cancelled were never missed by the family.
  with c as (
    update public.appointments a set status = 'cancelled', updated_by = auth.uid()
      from public.clinic_sessions s
     where s.id = a.session_id and s.clinic_id = p_clinic and s.service_date = p_date and s.status = 'cancelled' and a.status = 'confirmed'
    returning 1)
  select count(*) into v_cancelled from c;
  -- A booking that never arrived is a no-show. An arrival that was not served keeps its 'checked_in' status: the family came.
  with n as (
    update public.appointments a set status = 'no_show', updated_by = auth.uid()
      from public.clinic_sessions s
     where s.id = a.session_id and s.clinic_id = p_clinic and s.service_date = p_date and a.status = 'confirmed'
    returning 1)
  select count(*) into v_no_show from n;
  with s as (
    update public.clinic_sessions set status = 'closed', updated_by = auth.uid()
     where clinic_id = p_clinic and service_date = p_date and status = 'open'
    returning 1)
  select count(*) into v_sessions from s;

  if v_left + v_completed + v_unserved + v_no_show + v_cancelled + v_sessions + v_encounters > 0 then
    perform private.audit(v_org, 'queue.manage', 'day.closed', 'clinic', p_clinic, null,
      jsonb_build_object('date', p_date, 'ticketsLeft', v_left, 'visitsCompleted', v_completed, 'visitsUnserved', v_unserved + v_encounters,
                         'noShows', v_no_show, 'bookingsCancelled', v_cancelled, 'sessionsClosed', v_sessions), p_reason);
  end if;
  return jsonb_build_object('serviceDate', p_date, 'ticketsLeft', v_left, 'visitsCompleted', v_completed, 'visitsUnserved', v_unserved + v_encounters,
                            'noShows', v_no_show, 'bookingsCancelled', v_cancelled, 'sessionsClosed', v_sessions);
end $$;

create function public.close_service_day(p_operation_key uuid, p_clinic_id uuid, p_service_date date) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'queue.manage');
  v_prev := private.begin_command(v_org, p_operation_key, 'day.close', jsonb_build_object('c', p_clinic_id, 'd', p_service_date));
  if v_prev is not null then return v_prev; end if;
  return private.finish_command(v_org, p_operation_key, private.close_service_day_core(p_clinic_id, p_service_date, 'Day closed by staff'));
end $$;

-- What is still open from earlier days, and what was closed in the last week (staff review it on Today).
create function public.service_day_backlog(p_clinic_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_today date;
begin
  perform private.require_any(p_clinic_id, array['queue.manage','appointment.manage']);
  v_today := private.local_today(p_clinic_id);
  return jsonb_build_object(
    'open', coalesce((select jsonb_agg(jsonb_build_object('serviceDate', d.service_date,
        'openTickets', (select count(*) from public.queue_entries q where q.clinic_id = p_clinic_id and q.service_date = d.service_date and q.status in ('waiting','called','held','in_service')),
        'openVisits', (select count(*) from public.encounters e where e.clinic_id = p_clinic_id and e.service_date = d.service_date and e.status = 'open'),
        'unconfirmedBookings', (select count(*) from public.appointments a join public.clinic_sessions s on s.id = a.session_id
                                 where s.clinic_id = p_clinic_id and s.service_date = d.service_date and a.status = 'confirmed'),
        'openSessions', (select count(*) from public.clinic_sessions s where s.clinic_id = p_clinic_id and s.service_date = d.service_date and s.status = 'open'))
        order by d.service_date desc)
      from (select distinct service_date from (
              select q.service_date from public.queue_entries q where q.clinic_id = p_clinic_id and q.service_date < v_today and q.status in ('waiting','called','held','in_service')
              union select e.service_date from public.encounters e where e.clinic_id = p_clinic_id and e.service_date < v_today and e.status = 'open'
              union select s.service_date from public.clinic_sessions s where s.clinic_id = p_clinic_id and s.service_date < v_today and s.status = 'open') x
            order by service_date desc limit 30) d), '[]'::jsonb),
    'recentlyClosed', coalesce((select jsonb_agg(jsonb_build_object('closedAt', l.server_time, 'automatic', l.actor_id is null, 'summary', l.after) order by l.server_time desc)
      from (select * from private.audit_logs a where a.clinic_id = p_clinic_id and a.action = 'day.closed' and a.server_time > now() - interval '7 days'
            order by a.server_time desc limit 14) l), '[]'::jsonb));
end $$;

-- Worker: closes every past day still open, oldest first, a bounded number per run.
create function private.auto_close_service_days(p_limit integer default 50) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r record; v_n int := 0;
begin
  for r in
    select x.clinic_id, x.service_date from (
      select q.clinic_id, q.service_date from public.queue_entries q where q.status in ('waiting','called','held','in_service')
      union select e.clinic_id, e.service_date from public.encounters e where e.status = 'open'
      union select s.clinic_id, s.service_date from public.clinic_sessions s where s.status = 'open') x
    join public.clinics c on c.id = x.clinic_id and c.status = 'active'
    where x.service_date < private.local_today(x.clinic_id)
    order by x.service_date, x.clinic_id
    limit least(greatest(coalesce(p_limit, 50), 1), 500)
  loop
    perform private.close_service_day_core(r.clinic_id, r.service_date, 'Day closed automatically');
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('daysClosed', v_n);
end $$;

-- A vaccination belongs to today's visit. Care given on an earlier day is recorded as care already given (late entry).
create function private.vaccination_on_current_visit() returns trigger
language plpgsql security definer set search_path = '' as $$
declare e public.encounters;
begin
  if new.encounter_id is null then return new; end if;
  select * into e from public.encounters where id = new.encounter_id;
  if e.id is not null and e.service_date <> private.local_today(e.clinic_id) then
    raise exception 'this visit belongs to an earlier day; record the vaccination as care already given' using errcode = 'CV409';
  end if;
  return new;
end $$;
create trigger vaccination_events_current_visit before insert on public.vaccination_events
  for each row when (new.origin = 'clinic_administered') execute function private.vaccination_on_current_visit();

-- ---------------------------------------------------------------------------------------------
-- F41 / F42 Bookings and sessions for staff
-- ---------------------------------------------------------------------------------------------
create function public.list_child_appointments(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_canon uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['appointment.manage','queue.manage']);
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  perform private.audit(v_org, 'appointment.manage', 'appointments.view', 'child', v_canon, null, null, null);
  return coalesce((select jsonb_agg(jsonb_build_object('appointmentId', a.id, 'status', a.status, 'channel', a.channel, 'sessionId', s.id,
      'serviceDate', s.service_date, 'startsAt', s.starts_at, 'endsAt', s.ends_at, 'sessionStatus', s.status, 'reason', a.reason, 'version', a.version)
      order by s.starts_at desc)
    from public.appointments a join public.clinic_sessions s on s.id = a.session_id
   where a.child_id in (select private.child_ids_with_aliases(v_canon)) and s.clinic_id = p_clinic_id
     and s.service_date >= private.local_today(p_clinic_id) - 30), '[]'::jsonb);
end $$;

create function public.list_session_roster(p_clinic_id uuid, p_session_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; s public.clinic_sessions;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['appointment.manage','queue.manage']);
  select * into s from public.clinic_sessions where id = p_session_id and clinic_id = p_clinic_id;
  if s.id is null then return null; end if;
  perform private.audit(v_org, 'appointment.manage', 'appointments.view', 'clinic_session', s.id, null, null, null);
  return coalesce((select jsonb_agg(jsonb_build_object('appointmentId', a.id, 'status', a.status, 'channel', a.channel, 'childId', c.id,
      'childName', c.display_name, 'recordNo', c.local_record_no) order by c.display_name)
    from public.appointments a join public.children c on c.id = a.child_id
   where a.session_id = s.id and a.status in ('confirmed','checked_in','fulfilled','no_show')), '[]'::jsonb);
end $$;

-- Same checks as create_session, and never below the families already booked.
create function public.update_session_capacity(p_operation_key uuid, p_clinic_id uuid, p_session_id uuid, p_expected_version integer,
                                               p_total integer, p_online integer, p_walkin integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; s public.clinic_sessions; v_booked int;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'appointment.manage');
  v_prev := private.begin_command(v_org, p_operation_key, 'session.capacity',
    jsonb_build_object('c', p_clinic_id, 's', p_session_id, 'v', p_expected_version, 't', p_total, 'o', p_online, 'w', p_walkin));
  if v_prev is not null then return v_prev; end if;
  select * into s from public.clinic_sessions where id = p_session_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if s.version <> p_expected_version then raise exception 'the session changed; reload and try again' using errcode = 'CV409'; end if;
  if s.status <> 'open' or s.ends_at <= now() then raise exception 'only an open, upcoming session can be changed' using errcode = 'CV409'; end if;
  if p_total is null or p_online is null or p_walkin is null or p_total < 0 or p_online < 0 or p_walkin < 0 or p_online + p_walkin > p_total then
    raise exception 'online plus walk-in capacity cannot exceed total capacity' using errcode = 'CV422';
  end if;
  v_booked := private.session_booked(s.id);
  if p_online < v_booked then
    raise exception '% families are already booked; bookable places cannot go below that', v_booked using errcode = 'CV409';
  end if;
  update public.clinic_sessions set total_capacity = p_total, online_capacity = p_online, walkin_capacity = p_walkin, updated_by = auth.uid() where id = s.id;
  perform private.audit(v_org, 'appointment.manage', 'session.capacity_changed', 'clinic_session', s.id,
    jsonb_build_object('total', s.total_capacity, 'online', s.online_capacity, 'walkin', s.walkin_capacity),
    jsonb_build_object('total', p_total, 'online', p_online, 'walkin', p_walkin), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('sessionId', s.id, 'booked', v_booked));
end $$;

-- list_sessions also returns the version, so capacity changes are made against the row the person saw.
create or replace function public.list_sessions(p_clinic_id uuid, p_from date default null::date, p_to date default null::date) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_from date; v_to date; v_res jsonb;
begin
  perform private.require_any(p_clinic_id, array['appointment.manage','queue.manage','child.search']);
  v_from := coalesce(p_from, private.local_today(p_clinic_id)); v_to := coalesce(p_to, v_from + 14);
  if v_to < v_from or v_to - v_from > 92 then raise exception 'date range must be 0-92 days' using errcode = 'CV422'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'sessionId', s.id, 'serviceDate', s.service_date, 'startsAt', s.starts_at, 'endsAt', s.ends_at, 'serviceCode', s.service_code, 'status', s.status,
      'totalCapacity', s.total_capacity, 'onlineCapacity', s.online_capacity, 'walkinCapacity', s.walkin_capacity, 'version', s.version,
      'booked', private.session_booked(s.id), 'remainingOnline', greatest(s.online_capacity - private.session_booked(s.id), 0)) order by s.starts_at), '[]'::jsonb)
    into v_res from public.clinic_sessions s where s.clinic_id = p_clinic_id and s.service_date between v_from and v_to;
  return v_res;
end $$;

-- A cancelled session now cancels its bookings, so families no longer see them as booked (they are told by message, as before).
create or replace function public.cancel_session(p_operation_key uuid, p_clinic_id uuid, p_session_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; s public.clinic_sessions; a record; v_n int := 0;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'appointment.manage');
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'session.cancel', jsonb_build_object('c', p_clinic_id, 's', p_session_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into s from public.clinic_sessions where id = p_session_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if s.status <> 'open' then raise exception 'session is not open' using errcode = 'CV409'; end if;
  update public.clinic_sessions set status = 'cancelled', cancel_reason = p_reason, updated_by = auth.uid() where id = s.id;
  for a in select * from public.appointments where session_id = s.id and status = 'confirmed' for update loop
    update public.appointments set status = 'cancelled', reason = left('Session cancelled: ' || btrim(p_reason), 300), updated_by = auth.uid() where id = a.id;
    update private.outbox_jobs set status = 'cancelled', updated_at = now()
     where organization_id = v_org and status = 'queued' and (dedupe_key like 'appt-remind:' || a.id || '%' or dedupe_key = 'appt-confirm:' || a.id);
    insert into public.record_review_cases (organization_id, clinic_id, kind, child_id, reason, evidence, created_by, updated_by)
    values (v_org, p_clinic_id, 'appointment', a.child_id, 'session cancelled: contact family to rebook', jsonb_build_object('appointmentId', a.id, 'sessionId', s.id, 'serviceDate', s.service_date), auth.uid(), auth.uid());
    perform private.enqueue(v_org, 'appointment.session_cancelled', 'appointment', a.id, 'appt-session-cancelled:' || a.id, jsonb_build_object('sessionId', s.id));
    v_n := v_n + 1;
  end loop;
  perform private.audit(v_org, 'appointment.manage', 'session.cancelled', 'clinic_session', s.id, jsonb_build_object('status', s.status), jsonb_build_object('status', 'cancelled', 'affectedBookings', v_n), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('sessionId', s.id, 'affectedBookings', v_n));
end $$;

-- ---------------------------------------------------------------------------------------------
-- F43 Send a schedule under review back to draft
-- ---------------------------------------------------------------------------------------------
create function public.return_schedule_to_draft(p_operation_key uuid, p_clinic_id uuid, p_version_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; sv public.schedule_versions; v_reviewer boolean;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['rules.approve','rules.propose']);
  v_prev := private.begin_command(v_org, p_operation_key, 'schedule.return', jsonb_build_object('c', p_clinic_id, 'v', p_version_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into sv from public.schedule_versions where id = p_version_id and organization_id = v_org for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if sv.status <> 'clinical_review' then raise exception 'only a schedule awaiting review can be sent back' using errcode = 'CV409'; end if;
  v_reviewer := private.has_capability(p_clinic_id, 'rules.approve') and sv.proposed_by is distinct from auth.uid();
  if not v_reviewer and sv.proposed_by is distinct from auth.uid() then
    raise exception 'only a reviewer or the person who submitted it can send it back' using errcode = 'CV403';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  update public.schedule_versions set status = 'draft', reviewed_by = case when v_reviewer then auth.uid() else reviewed_by end, updated_by = auth.uid() where id = sv.id;
  perform private.audit(v_org, case when v_reviewer then 'rules.approve' else 'rules.propose' end, case when v_reviewer then 'schedule.returned' else 'schedule.withdrawn' end,
                        'schedule_version', sv.id, jsonb_build_object('status', sv.status), jsonb_build_object('status', 'draft'), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('versionId', sv.id, 'status', 'draft'));
end $$;

-- ---------------------------------------------------------------------------------------------
-- F44 Reject a stock count awaiting approval
-- ---------------------------------------------------------------------------------------------
create function public.reject_stock_adjustment(p_operation_key uuid, p_clinic_id uuid, p_case_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id, 'inventory.approve'); v_prev jsonb; k public.record_review_cases;
begin
  select * into k from public.record_review_cases where id = p_case_id and organization_id = v_org and clinic_id = p_clinic_id and kind = 'stock' for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.reject_adjustment', jsonb_build_object('c', p_clinic_id, 'case', p_case_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if k.status not in ('open','in_review') then raise exception 'case already decided' using errcode = 'CV409'; end if;
  if k.evidence ->> 'observed' is null then
    raise exception 'this stock case is not a count adjustment; decide it from the transfer or the visit record it came from' using errcode = 'CV409';
  end if;
  if k.created_by = auth.uid() then raise exception 'the person who counted cannot decide their own count' using errcode = 'CV403'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  update public.record_review_cases set status = 'rejected', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', 'rejected', 'reason', left(btrim(p_reason), 500)) where id = k.id;
  perform private.audit(v_org, 'inventory.approve', 'stock.adjustment_rejected', 'review_case', k.id, null, null, p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'rejected'));
end $$;

-- ---------------------------------------------------------------------------------------------
-- F45 / F46 Family notifications and reminders
-- ---------------------------------------------------------------------------------------------
-- One in-app message to one account (for people who are not yet verified guardians, such as a declined link request).
create function private.notify_profile(p_org uuid, p_profile uuid, p_child uuid, p_kind text, p_title text, p_body text, p_dedupe text) returns integer
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  if p_profile is null then return 0; end if;
  insert into public.messages (organization_id, recipient_profile_id, child_id, kind, title, body, dedupe_key)
  select p_org, p.id, p_child, p_kind, p_title, p_body, p_dedupe from public.profiles p where p.id = p_profile and p.status = 'active'
  on conflict (recipient_profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- Messages about a child marked inactive (moved away or died) are never sent.
create or replace function private.notify_guardians(p_org uuid, p_child uuid, p_kind text, p_title text, p_body text, p_dedupe text, p_sms text default null::text) returns integer
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  if exists (select 1 from public.children c where c.id = private.canonical_child(p_child) and c.record_status = 'inactive') then return 0; end if;
  insert into public.messages (organization_id, recipient_profile_id, child_id, kind, title, body, dedupe_key)
  select distinct p_org, g.profile_id, private.canonical_child(p_child), p_kind, p_title, p_body, p_dedupe
    from public.guardian_child_relationships r join public.guardians g on g.id = r.guardian_id
   where r.child_id = private.canonical_child(p_child) and r.status = 'active' and r.access_scope = 'full' and (r.ends_at is null or r.ends_at > now())
     and g.profile_id is not null and g.deleted_at is null
  on conflict (recipient_profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count;
  if p_sms is not null then
    insert into public.sms_messages (organization_id, guardian_id, kind, body, dedupe_key)
    select distinct p_org, g.id, p_kind, p_sms, p_dedupe
      from public.guardian_child_relationships r join public.guardians g on g.id = r.guardian_id
     where r.child_id = private.canonical_child(p_child) and r.status = 'active' and r.access_scope = 'full' and (r.ends_at is null or r.ends_at > now())
       and g.deleted_at is null and g.sms_opt_in and g.contact_phone is not null and g.contact_verified_at is not null
    on conflict (guardian_id, dedupe_key) do nothing;
  end if;
  return v_n;
end $$;

-- Access decisions are queued when the relationship row changes, whichever command changed it.
create function private.relationship_status_notify() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_type text;
begin
  if tg_op = 'INSERT' then
    if new.status = 'active' then v_type := 'relationship.verified'; end if;
  elsif new.status is distinct from old.status then
    v_type := case
      when new.status = 'active' and old.status = 'provisional' then 'relationship.verified'
      when new.status = 'active' and old.status = 'suspended' then 'relationship.restored'
      when new.status = 'suspended' then 'relationship.paused'
      when new.status in ('revoked','rejected') then 'relationship.ended'
    end;
  end if;
  if v_type is not null then
    perform private.enqueue(new.organization_id, v_type, 'relationship', new.id, v_type || ':' || new.id || ':' || new.version, '{}'::jsonb);
  end if;
  return null;
end $$;
create trigger guardian_child_relationships_notify after insert or update of status on public.guardian_child_relationships
  for each row execute function private.relationship_status_notify();

create function private.review_case_notify() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.guardian_id is null or old.status not in ('open','in_review') or new.status not in ('resolved','rejected') then return null; end if;
  if (new.kind = 'link' and new.status = 'rejected') or new.kind = 'identity_edit' or (new.kind = 'clinical' and new.vaccination_event_id is not null) then
    perform private.enqueue(new.organization_id, 'family_request.decided', 'review_case', new.id, 'case-decided:' || new.id, '{}'::jsonb);
  end if;
  return null;
end $$;
create trigger record_review_cases_notify after update of status on public.record_review_cases
  for each row execute function private.review_case_notify();

create or replace function private.handle_outbox_job(j private.outbox_jobs) returns text
language plpgsql security definer set search_path = '' as $$
declare
  v_child public.children; v_clinic text; r public.guardian_child_relationships; g public.guardians; k public.record_review_cases;
  a public.appointments; s public.clinic_sessions; cl public.clinics; v_when text; v_name text;
begin
  if j.job_type = 'record.transferred' then
    select * into v_child from public.children where id = (j.payload ->> 'childId')::uuid;
    select name into v_clinic from public.clinics where id = (j.payload ->> 'toClinicId')::uuid;
    if v_child.id is null or v_clinic is null then return 'cancelled'; end if;
    perform private.notify_guardians(j.organization_id, v_child.id, 'record', 'Record moved to another clinic', format('%s''s record now belongs to %s. Book any new visits there.', v_child.display_name, v_clinic), j.dedupe_key,
      format('%s: your child''s record moved here. Details are in the app.', v_clinic));
    return 'done';
  end if;

  if j.job_type in ('relationship.verified','relationship.restored','relationship.paused','relationship.ended') then
    select * into r from public.guardian_child_relationships where id = j.aggregate_id;
    if r.id is null then return 'cancelled'; end if;
    select * into g from public.guardians where id = r.guardian_id and deleted_at is null;
    select * into v_child from public.children where id = r.child_id;
    -- Merges retire the duplicate's relationships; the family keeps access on the surviving record, so nothing is said.
    if g.profile_id is null or v_child.id is null or v_child.record_status in ('merged','inactive') then return 'cancelled'; end if;
    perform private.notify_profile(j.organization_id, g.profile_id, case when j.job_type = 'relationship.ended' then null else v_child.id end, 'access',
      case j.job_type when 'relationship.verified' then 'Access verified' when 'relationship.restored' then 'Access restored'
                      when 'relationship.paused' then 'Access paused' else 'Access ended' end,
      case j.job_type
        when 'relationship.verified' then format('The clinic verified you as %s''s guardian. You can now see the vaccination history and book visits.', v_child.display_name)
        when 'relationship.restored' then format('Your access to %s''s record is available again.', v_child.display_name)
        when 'relationship.paused' then format('The clinic paused your access to %s''s record. Contact the clinic if you think this is a mistake.', v_child.display_name)
        else format('Your access to %s''s record has ended. Contact the clinic if you have questions.', v_child.display_name) end,
      j.dedupe_key);
    return 'done';
  end if;

  if j.job_type = 'family_request.decided' then
    select * into k from public.record_review_cases where id = j.aggregate_id;
    if k.id is null then return 'cancelled'; end if;
    select * into g from public.guardians where id = k.guardian_id and deleted_at is null;
    if g.profile_id is null then return 'cancelled'; end if;
    if k.child_id is not null then select * into v_child from public.children where id = private.canonical_child(k.child_id); end if;
    if v_child.id is not null and v_child.record_status = 'inactive' then return 'cancelled'; end if;
    if k.kind = 'link' then
      v_name := coalesce(nullif(btrim(k.evidence ->> 'childName'), ''), 'your child');
      perform private.notify_profile(j.organization_id, g.profile_id, null, 'access', 'Link request not approved',
        format('The clinic could not match your request to link %s. Bring the child''s Immunization Card and a valid ID to the health center so staff can help.', v_name), j.dedupe_key);
    elsif k.kind = 'identity_edit' then
      perform private.notify_profile(j.organization_id, g.profile_id, v_child.id, 'record', 'Change request reviewed',
        format('The clinic reviewed your request to correct %s''s details. Open the record to see the details as they are now.', coalesce(v_child.display_name, 'your child')), j.dedupe_key);
    else
      perform private.notify_profile(j.organization_id, g.profile_id, v_child.id, 'record',
        case when k.status = 'resolved' then 'Reported vaccine verified' else 'Reported vaccine not verified' end,
        case when k.status = 'resolved'
          then format('The clinic verified the vaccine you reported for %s. It now counts in the schedule.', coalesce(v_child.display_name, 'your child'))
          else format('The clinic could not verify the vaccine you reported for %s. Bring the Immunization Card on your next visit.', coalesce(v_child.display_name, 'your child')) end,
        j.dedupe_key);
    end if;
    return 'done';
  end if;

  if j.job_type = 'appointment.reminder' then
    select * into a from public.appointments where id = j.aggregate_id;
    if a.id is null or a.status <> 'confirmed' then return 'cancelled'; end if;
    select * into s from public.clinic_sessions where id = a.session_id;
    if s.status <> 'open' then return 'cancelled'; end if;
    select * into cl from public.clinics where id = s.clinic_id;
    select * into v_child from public.children where id = a.child_id;
    v_when := to_char(s.starts_at at time zone cl.timezone, 'FMDay, FMDD FMMonth "at" FMHH12:MI AM');
    perform private.notify_guardians(j.organization_id, a.child_id, 'appointment', 'Visit tomorrow',
      format('Reminder: %s has a visit on %s at %s. Bring the Immunization Card.', v_child.display_name, v_when, cl.name), j.dedupe_key,
      format('%s: reminder of a visit on %s. Bring the Immunization Card.', cl.name, v_when));
    return 'done';
  end if;

  if j.job_type = 'dose.due' then
    select * into v_child from public.children where id = j.aggregate_id;
    if v_child.id is null or v_child.record_status <> 'active' then return 'cancelled'; end if;
    select * into cl from public.clinics where id = (j.payload ->> 'clinicId')::uuid;
    perform private.notify_guardians(j.organization_id, v_child.id, 'record', 'A vaccine is due',
      format('%s has a vaccine due or overdue. Open the record to see which one, then book a visit or walk in at %s.', v_child.display_name, coalesce(cl.name, 'the health center')), j.dedupe_key,
      format('%s: a vaccine is due for your child. Details are in the app.', coalesce(cl.name, 'Health center')));
    return 'done';
  end if;

  return private.handle_outbox_job_prev(j);
end $$;

-- Day-before visit reminders, and a weekly due-vaccine reminder per child, checked once per clinic-local day in bounded batches.
create function private.enqueue_daily_reminders(p_limit integer default 300) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r record; v_res jsonb; v_today date; v_appt int := 0; v_due int := 0; v_checked int := 0;
begin
  for r in
    select a.id, a.organization_id from public.appointments a
      join public.clinic_sessions s on s.id = a.session_id and s.status = 'open'
      join public.clinics c on c.id = s.clinic_id and c.status = 'active'
     where a.status = 'confirmed' and s.service_date = private.local_today(s.clinic_id) + 1
       and not exists (select 1 from private.outbox_jobs o where o.organization_id = a.organization_id and o.dedupe_key = 'appt-remind:' || a.id)
     limit 1000
  loop
    perform private.enqueue(r.organization_id, 'appointment.reminder', 'appointment', r.id, 'appt-remind:' || r.id, '{}'::jsonb);
    v_appt := v_appt + 1;
  end loop;

  for r in
    select c.id, c.organization_id, e.clinic_id from public.children c
      join public.child_clinic_enrollments e on e.child_id = c.id and e.status = 'active' and e.is_primary
      join public.clinics cl on cl.id = e.clinic_id and cl.status = 'active'
      left join private.reminder_checks k on k.child_id = c.id
     where c.record_status = 'active' and c.merged_into_id is null and c.deleted_at is null
       and (k.child_id is null or k.checked_on < private.local_today(e.clinic_id))
       and exists (select 1 from public.guardian_child_relationships gr join public.guardians g on g.id = gr.guardian_id
                    where gr.child_id = c.id and gr.status = 'active' and gr.access_scope = 'full' and g.profile_id is not null and g.deleted_at is null)
     order by k.checked_on nulls first
     limit least(greatest(coalesce(p_limit, 300), 1), 2000)
  loop
    v_today := private.local_today(r.clinic_id);
    v_res := private.compute_child_schedule(r.id, v_today, false);
    if v_res ->> 'status' = 'evaluated' and exists (select 1 from jsonb_array_elements(coalesce(v_res -> 'requirements', '[]'::jsonb)) x
                                                     where x ->> 'status' in ('due_today','due_now','overdue')) then
      perform private.enqueue(r.organization_id, 'dose.due', 'child', r.id, 'dose-due:' || r.id || ':' || to_char(v_today, 'IYYY-IW'), jsonb_build_object('clinicId', r.clinic_id));
      v_due := v_due + 1;
    end if;
    insert into private.reminder_checks (child_id, checked_on) values (r.id, v_today)
    on conflict (child_id) do update set checked_on = excluded.checked_on;
    v_checked := v_checked + 1;
  end loop;
  return jsonb_build_object('visitReminders', v_appt, 'childrenChecked', v_checked, 'dueReminders', v_due);
end $$;

-- Called by the worker on every pass; does real work at most every ten minutes.
create function private.run_daily_maintenance() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_ran boolean;
begin
  insert into private.maintenance_runs (job, last_run_at) values ('daily', now())
  on conflict (job) do update set last_run_at = excluded.last_run_at where private.maintenance_runs.last_run_at < now() - interval '10 minutes'
  returning true into v_ran;
  if not coalesce(v_ran, false) then return jsonb_build_object('skipped', true); end if;
  return private.auto_close_service_days(50) || private.enqueue_daily_reminders(300);
end $$;

-- ---------------------------------------------------------------------------------------------
-- F47 / F48 / F49 Accounts
-- ---------------------------------------------------------------------------------------------
-- A phone number as people type it: digits with optional +, spaces and dashes. Anything else is not kept.
create function private.clean_signup_phone(p_phone text) returns text
language sql immutable set search_path = '' as $$
  select case when btrim(coalesce(p_phone, '')) ~ '^\+?[0-9][0-9 -]{6,18}$' then btrim(p_phone) end
$$;

create or replace function private.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_app jsonb := new.raw_user_meta_data -> 'staff_application';
  v_name text := left(btrim(coalesce(new.raw_user_meta_data ->> 'display_name', '')), 120);
begin
  insert into public.profiles (id, display_name, locale, needs_name, signup_phone)
  values (new.id,
          case when v_name <> '' then v_name else left(split_part(coalesce(new.email, ''), '@', 1), 120) end,
          case when new.raw_user_meta_data ->> 'preferred_language' = 'fil' then 'fil' else 'en' end,
          v_name = '',
          private.clean_signup_phone(new.raw_user_meta_data ->> 'phone'))
  on conflict (id) do nothing;
  if jsonb_typeof(v_app) = 'object' then
    begin
      perform private.create_staff_application(new.id, (v_app ->> 'clinic_id')::uuid, v_app ->> 'role', v_app ->> 'position_title', v_app ->> 'note');
    exception when others then
      raise warning 'staff application from sign-up was not recorded: %', sqlerrm;
    end;
  end if;
  return new;
end $$;

-- The guardian created for an online family starts with the phone they gave at sign-up, unverified until the clinic checks it.
create or replace function private.ensure_guardian(p_org uuid, p_name text default null::text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v uuid;
begin
  select id into v from public.guardians where organization_id = p_org and profile_id = auth.uid();
  if v is not null then return v; end if;
  insert into public.guardians (organization_id, profile_id, full_name, preferred_language, contact_phone, created_by, updated_by)
  select p_org, p.id, coalesce(nullif(btrim(p_name), ''), nullif(btrim(p.display_name), ''), 'Guardian'), p.locale, p.signup_phone, p.id, p.id
    from public.profiles p where p.id = auth.uid()
  returning id into v;
  return v;
end $$;

create or replace function public.get_my_context() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'profileId', p.id, 'displayName', p.display_name, 'locale', p.locale, 'status', p.status, 'needsName', p.needs_name,
    'mfa', private.mfa_ok(), 'demoMode', private.setting_bool('demo_mode'),
    'memberships', coalesce((
      select jsonb_agg(jsonb_build_object('membershipId', m.id, 'clinicId', m.clinic_id, 'clinicName', c.name,
        'clinicTimezone', c.timezone, 'role', m.role_code, 'status', m.status, 'validUntil', m.valid_until,
        'capabilities', to_jsonb(private.role_preset(m.role_code) || m.capabilities)))
      from public.staff_memberships m join public.clinics c on c.id = m.clinic_id and c.organization_id = m.organization_id
      where m.profile_id = p.id and c.status = 'active'
        and (m.status = 'pending_approval' or (m.status = 'active' and m.valid_from <= now() and (m.valid_until is null or m.valid_until > now())))), '[]'::jsonb))
  from public.profiles p where p.id = auth.uid() and p.status = 'active'
$$;

-- The account holder's own name and language. The name on a verified guardian record stays as the clinic recorded it.
create function public.update_my_profile(p_display_name text, p_locale text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p public.profiles; v_name text := left(btrim(coalesce(p_display_name, '')), 121);
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if v_name = '' or length(v_name) > 120 then raise exception 'enter your full name (up to 120 characters)' using errcode = 'CV422'; end if;
  if p_locale is null or p_locale not in ('en','fil') then raise exception 'choose English or Filipino' using errcode = 'CV422'; end if;
  select * into p from public.profiles where id = auth.uid() and status = 'active' for update;
  if p.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if (p.display_name, p.locale, p.needs_name) is distinct from (v_name, p_locale, false) then
    update public.profiles set display_name = v_name, locale = p_locale, needs_name = false where id = p.id;
    update public.guardians set preferred_language = p_locale, updated_by = auth.uid() where profile_id = p.id and deleted_at is null and preferred_language <> p_locale;
    perform private.audit(null, 'self', 'profile.updated', 'profile', p.id,
      jsonb_build_object('displayName', p.display_name, 'locale', p.locale), jsonb_build_object('displayName', v_name, 'locale', p_locale), null);
  end if;
  return jsonb_build_object('displayName', v_name, 'locale', p_locale);
end $$;

-- ---------------------------------------------------------------------------------------------
-- F50 Real-world end states
-- ---------------------------------------------------------------------------------------------
create function public.set_child_record_status(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_status text, p_reason text, p_note text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; c public.children; v_canon uuid;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'review.resolve');
  v_prev := private.begin_command(v_org, p_operation_key, 'child.record_status', jsonb_build_object('c', p_clinic_id, 'ch', p_child_id, 's', p_status, 'r', p_reason, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  select * into c from public.children where id = v_canon for update;
  if p_status = 'inactive' then
    if c.record_status <> 'active' then raise exception 'only a confirmed, active record can be marked inactive' using errcode = 'CV409'; end if;
    if p_reason is null or p_reason not in ('moved','deceased','other') then raise exception 'choose why the record is inactive' using errcode = 'CV422'; end if;
    if p_reason = 'other' and length(btrim(coalesce(p_note, ''))) < 3 then raise exception 'describe the reason' using errcode = 'CV422'; end if;
    if exists (select 1 from public.encounters e where e.child_id = v_canon and e.status = 'open') then
      raise exception 'a visit is in progress; finish it first' using errcode = 'CV409';
    end if;
    update public.children set record_status = 'inactive', inactive_reason = p_reason, inactive_note = nullif(left(btrim(coalesce(p_note, '')), 300), ''),
           inactive_at = now(), updated_by = auth.uid() where id = c.id;
    -- Future bookings are cancelled without telling the family (they may be bereaved); staff see them in the audit trail.
    update public.appointments a set status = 'cancelled', reason = 'Record marked inactive', updated_by = auth.uid()
      from public.clinic_sessions s where s.id = a.session_id and a.child_id = c.id and a.status = 'confirmed' and s.ends_at > now();
    update private.outbox_jobs o set status = 'cancelled', updated_at = now()
     where o.organization_id = v_org and o.status = 'queued' and o.aggregate_id in (select a.id from public.appointments a where a.child_id = c.id);
  elsif p_status = 'active' then
    if c.record_status <> 'inactive' then raise exception 'the record is not inactive' using errcode = 'CV409'; end if;
    update public.children set record_status = 'active', inactive_reason = null, inactive_note = null, inactive_at = null, updated_by = auth.uid() where id = c.id;
  else
    raise exception 'unknown status' using errcode = 'CV422';
  end if;
  perform private.audit(v_org, 'review.resolve', case when p_status = 'inactive' then 'child.marked_inactive' else 'child.reactivated' end, 'child', c.id,
    jsonb_build_object('status', c.record_status), jsonb_build_object('status', p_status, 'reason', p_reason), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('childId', c.id, 'recordStatus', p_status));
end $$;

create function public.mark_guardian_contact_invalid(p_operation_key uuid, p_clinic_id uuid, p_guardian_id uuid, p_note text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; g public.guardians;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id, array['guardian.verify','bhw.followup']);
  v_prev := private.begin_command(v_org, p_operation_key, 'contact.invalid', jsonb_build_object('c', p_clinic_id, 'g', p_guardian_id, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  select * into g from public.guardians where id = p_guardian_id and organization_id = v_org and deleted_at is null for update;
  if g.id is null or not exists (select 1 from public.guardian_child_relationships r join public.child_clinic_enrollments e on e.child_id = r.child_id and e.clinic_id = p_clinic_id and e.status in ('pending','active')
                                   where r.guardian_id = g.id and r.status in ('provisional','active','suspended')) then
    raise exception 'not found' using errcode = 'CV404';
  end if;
  if g.contact_phone is null then raise exception 'there is no phone number on file' using errcode = 'CV422'; end if;
  if p_note is null or length(btrim(p_note)) < 3 then raise exception 'say what happened when you called' using errcode = 'CV422'; end if;
  update public.guardians set contact_status = 'invalid', contact_verified_at = null, contact_verified_by = null, sms_opt_in = false, updated_by = auth.uid() where id = g.id;
  perform private.audit(v_org, 'guardian.verify', 'contact.marked_invalid', 'guardian', g.id, jsonb_build_object('status', g.contact_status),
    jsonb_build_object('status', 'invalid', 'phone', private.mask_phone(g.contact_phone)), p_note);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('guardianId', g.id, 'contactStatus', 'invalid'));
end $$;

-- Staff see whether a number was found not to work (contactStatus).
create or replace function public.list_child_guardian_contacts(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid;
begin
  perform private.require_capability(p_clinic_id, 'guardian.verify');
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('relationshipId', r.id, 'guardianId', g.id, 'phoneMasked', private.mask_phone(g.contact_phone), 'hasPhone', g.contact_phone is not null,
            'phoneChecked', g.contact_verified_at is not null and g.contact_phone is not null, 'smsOptIn', g.sms_opt_in, 'contactStatus', g.contact_status) order by g.full_name), '[]'::jsonb)
            from public.guardian_child_relationships r join public.guardians g on g.id = r.guardian_id where r.child_id = v_canon and r.status in ('provisional','active') and g.deleted_at is null);
end $$;

create function public.close_stock_location(p_operation_key uuid, p_clinic_id uuid, p_location_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id, 'inventory.manage'); v_prev jsonb; l public.stock_locations;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.location_close', jsonb_build_object('c', p_clinic_id, 'l', p_location_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into l from public.stock_locations where id = p_location_id and organization_id = v_org and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if l.status <> 'active' then raise exception 'the location is already closed' using errcode = 'CV409'; end if;
  if l.kind = 'in_transit' then raise exception 'the transit location is managed by the system' using errcode = 'CV409'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  if exists (select 1 from public.stock_balances b where b.location_id = l.id and (b.on_hand <> 0 or b.allocated <> 0)) then
    raise exception 'move or record all stock at this location before closing it' using errcode = 'CV409';
  end if;
  if exists (select 1 from public.stock_transfers t where (t.from_location_id = l.id or t.to_location_id = l.id) and t.status = 'in_transit') then
    raise exception 'a transfer to or from this location is still in transit' using errcode = 'CV409';
  end if;
  update public.stock_locations set status = 'closed', updated_by = auth.uid() where id = l.id;
  perform private.audit(v_org, 'inventory.manage', 'stock.location_closed', 'stock_location', l.id, jsonb_build_object('status', 'active'), jsonb_build_object('status', 'closed'), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('locationId', l.id, 'status', 'closed'));
end $$;

-- Operator-only (database owner, from a maintenance connection): suspend, deactivate or reactivate an account.
-- A non-active profile has no session (private.session_ok) and therefore no capability anywhere.
create function private.set_profile_status(p_profile uuid, p_status text, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p public.profiles;
begin
  if p_status not in ('active','suspended','deactivated') then raise exception 'unknown status' using errcode = 'CV422'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  select * into p from public.profiles where id = p_profile for update;
  if p.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  update public.profiles set status = p_status where id = p.id;
  perform private.audit(null, 'operator', 'profile.status_changed', 'profile', p.id, jsonb_build_object('status', p.status), jsonb_build_object('status', p_status), p_reason);
  return jsonb_build_object('profileId', p.id, 'status', p_status);
end $$;

-- ---------------------------------------------------------------------------------------------
-- Grants. Private helpers stay private; the worker may run the daily jobs.
-- ---------------------------------------------------------------------------------------------
revoke all on function
  private.close_service_day_core(uuid, date, text), private.auto_close_service_days(integer), private.vaccination_on_current_visit(),
  private.notify_profile(uuid, uuid, uuid, text, text, text, text), private.relationship_status_notify(), private.review_case_notify(),
  private.enqueue_daily_reminders(integer), private.run_daily_maintenance(), private.clean_signup_phone(text), private.set_profile_status(uuid, text, text)
  from public, anon, authenticated;
grant execute on function private.run_daily_maintenance() to cvsrs_outbox_worker;

revoke all on function
  public.close_service_day(uuid, uuid, date), public.service_day_backlog(uuid), public.list_child_appointments(uuid, uuid),
  public.list_session_roster(uuid, uuid), public.update_session_capacity(uuid, uuid, uuid, integer, integer, integer, integer),
  public.return_schedule_to_draft(uuid, uuid, uuid, text), public.reject_stock_adjustment(uuid, uuid, uuid, text),
  public.update_my_profile(text, text), public.set_child_record_status(uuid, uuid, uuid, text, text, text),
  public.mark_guardian_contact_invalid(uuid, uuid, uuid, text), public.close_stock_location(uuid, uuid, uuid, text)
  from public, anon, authenticated;
grant execute on function
  public.close_service_day(uuid, uuid, date), public.service_day_backlog(uuid), public.list_child_appointments(uuid, uuid),
  public.list_session_roster(uuid, uuid), public.update_session_capacity(uuid, uuid, uuid, integer, integer, integer, integer),
  public.return_schedule_to_draft(uuid, uuid, uuid, text), public.reject_stock_adjustment(uuid, uuid, uuid, text),
  public.update_my_profile(text, text), public.set_child_record_status(uuid, uuid, uuid, text, text, text),
  public.mark_guardian_contact_invalid(uuid, uuid, uuid, text), public.close_stock_location(uuid, uuid, uuid, text)
  to authenticated;
-- END 0037_operational_gaps.sql

-- =====================================================================================================================
-- BEGIN 0038_open_visit_today.sql  sha256=4bb4b725dda0587e4d7c4482b799566ef05b949d5a4b84113098e3cfb6b136d4
-- =====================================================================================================================
-- 0038 Only today's visit is "open" for recording.
--
-- Until a past day is closed (0037), an encounter from an earlier day can still have status 'open'. get_open_encounter returned
-- it, so the child page offered "Give a vaccine" against yesterday's visit and the exception form attached care to it, which the
-- 0037 guard then refused with a conflict. A visit belongs to the clinic's current day; earlier care is recorded as care already
-- given (late entry), which needs no visit.
create or replace function public.get_open_encounter(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_canon uuid; e public.encounters;
begin
  perform private.require_any(p_clinic_id, array['vaccination.record','queue.manage','child.read_clinical']);
  v_canon := private.canonical_child(p_child_id);
  if not private.child_in_clinic(v_canon, p_clinic_id) then return null; end if;
  select * into e from public.encounters
   where child_id = v_canon and clinic_id = p_clinic_id and status = 'open' and service_date = private.local_today(p_clinic_id)
   order by started_at desc nulls last limit 1;
  if not found then return null; end if;
  return jsonb_build_object('encounterId', e.id, 'serviceDate', e.service_date, 'startedAt', e.started_at, 'assessmentReference', e.assessment_reference, 'consentReference', e.consent_reference,
                            'administrations', (select count(*) from public.vaccination_events v where v.encounter_id = e.id));
end $$;

-- Today reads the last week's day closures on every refresh. Day closures are rare rows in a large, fast-growing audit log, so they
-- get their own small index, and the read filters on the indexed columns.
create index audit_day_closed_idx on private.audit_logs (entity_id, server_time desc) where action = 'day.closed';

create or replace function public.service_day_backlog(p_clinic_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_today date;
begin
  perform private.require_any(p_clinic_id, array['queue.manage','appointment.manage']);
  v_today := private.local_today(p_clinic_id);
  return jsonb_build_object(
    'open', coalesce((select jsonb_agg(jsonb_build_object('serviceDate', d.service_date,
        'openTickets', (select count(*) from public.queue_entries q where q.clinic_id = p_clinic_id and q.service_date = d.service_date and q.status in ('waiting','called','held','in_service')),
        'openVisits', (select count(*) from public.encounters e where e.clinic_id = p_clinic_id and e.service_date = d.service_date and e.status = 'open'),
        'unconfirmedBookings', (select count(*) from public.appointments a join public.clinic_sessions s on s.id = a.session_id
                                 where s.clinic_id = p_clinic_id and s.service_date = d.service_date and a.status = 'confirmed'),
        'openSessions', (select count(*) from public.clinic_sessions s where s.clinic_id = p_clinic_id and s.service_date = d.service_date and s.status = 'open'))
        order by d.service_date desc)
      from (select distinct service_date from (
              select q.service_date from public.queue_entries q where q.clinic_id = p_clinic_id and q.service_date < v_today and q.status in ('waiting','called','held','in_service')
              union select e.service_date from public.encounters e where e.clinic_id = p_clinic_id and e.service_date < v_today and e.status = 'open'
              union select s.service_date from public.clinic_sessions s where s.clinic_id = p_clinic_id and s.service_date < v_today and s.status = 'open') x
            order by service_date desc limit 30) d), '[]'::jsonb),
    'recentlyClosed', coalesce((select jsonb_agg(jsonb_build_object('closedAt', l.server_time, 'automatic', l.actor_id is null, 'summary', l.after) order by l.server_time desc)
      from (select * from private.audit_logs a
             where a.action = 'day.closed' and a.entity_id = p_clinic_id and a.entity_type = 'clinic' and a.server_time > now() - interval '7 days'
             order by a.server_time desc limit 14) l), '[]'::jsonb));
end $$;
-- END 0038_open_visit_today.sql

-- =====================================================================================================================
-- BEGIN 0039_bootstrap_confirmed_email.sql  sha256=854065756d76cb8f31e4cf4f302b6a3febb44ef152bb65025b658aaa408060f7
-- =====================================================================================================================
-- ---------------------------------------------------------------------------------------------
-- The one-time operator bootstrap (0034) now refuses a person whose email address is not confirmed, so the SQL Editor path
-- has the same protection as `npm run setup:first-staff`: an unconfirmed account could belong to someone who only typed
-- that address. Supabase records confirmation in auth.users.email_confirmed_at; the column is read through to_jsonb so the
-- function also compiles on the local test bootstrap, whose auth.users has no such column (the check is then skipped).
-- Everything else is unchanged from 0034.
-- ---------------------------------------------------------------------------------------------
create or replace function private.bootstrap_initial_staff(p_org_name text, p_clinic_name text, p_timezone text, p_admin_email text, p_lead_email text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_admin uuid; v_lead uuid; v_org uuid; v_clinic uuid; v_m_admin uuid; v_m_lead uuid;
begin
  lock table public.staff_memberships in share row exclusive mode;
  if exists (select 1 from public.staff_memberships where status in ('active','pending_approval')) then
    raise exception 'staff access already exists; grant further access with the in-app two-person process' using errcode = 'CV409';
  end if;
  if coalesce(btrim(p_org_name), '') = '' or coalesce(btrim(p_clinic_name), '') = '' then
    raise exception 'name the organization and its first clinic' using errcode = 'CV422';
  end if;
  select p.id into v_admin from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = lower(btrim(p_admin_email)) and p.status = 'active';
  select p.id into v_lead from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = lower(btrim(p_lead_email)) and p.status = 'active';
  if v_admin is null or v_lead is null or v_admin = v_lead then
    raise exception 'two different people who have already signed up are required' using errcode = 'CV422';
  end if;
  if exists (select 1 from auth.users u
              where u.id in (v_admin, v_lead) and to_jsonb(u) ? 'email_confirmed_at' and (to_jsonb(u) ->> 'email_confirmed_at') is null) then
    raise exception 'both people must confirm their email address first' using errcode = 'CV422';
  end if;
  insert into public.organizations (name) values (btrim(p_org_name)) returning id into v_org;
  insert into public.clinics (organization_id, name, timezone) values (v_org, btrim(p_clinic_name), coalesce(nullif(btrim(p_timezone), ''), 'Asia/Manila')) returning id into v_clinic;
  insert into public.staff_memberships (organization_id, profile_id, clinic_id, role_code, status, requested_by, approved_by)
  values (v_org, v_admin, v_clinic, 'tech_admin', 'active', v_lead, v_lead) returning id into v_m_admin;
  insert into public.staff_memberships (organization_id, profile_id, clinic_id, role_code, status, requested_by, approved_by)
  values (v_org, v_lead, v_clinic, 'clinical_lead', 'active', v_admin, v_admin) returning id into v_m_lead;
  perform private.audit(v_org, null, 'staff.bootstrap', 'clinic', v_clinic, null,
                        jsonb_build_object('techAdmin', v_admin, 'clinicalLead', v_lead, 'memberships', jsonb_build_array(v_m_admin, v_m_lead)),
                        'operator bootstrap of the first organization, clinic and staff');
  return jsonb_build_object('organizationId', v_org, 'clinicId', v_clinic, 'techAdminMembershipId', v_m_admin, 'clinicalLeadMembershipId', v_m_lead);
end $$;

revoke all on function private.bootstrap_initial_staff(text, text, text, text, text) from public, anon, authenticated, service_role;
-- END 0039_bootstrap_confirmed_email.sql

-- =====================================================================================================================
-- BEGIN 0040_iteration4_integrity.sql  sha256=b15578106e82e49c7611ee26dac47982019aa783275c737220f9ee895ed410bc
-- =====================================================================================================================
-- 0040 Iteration-4 integrity fixes (docs/engineering/audit.md "Iteration 4").
--
--  I4-03 A revoke that would leave a health center unable to grant staff access is refused (CV409, hint
--        cvsrs:last_access_holder). Granting needs two DIFFERENT people (0002): one files the request (admin.users or
--        grant.approve.clinical) and another approves it (admin.users for a non-clinical grant, grant.approve.clinical for a
--        clinical one). The revoke is refused when that is possible for either kind of grant before it and not after it; a
--        health center that already cannot grant is not made worse, so its revokes are not refused. Revokes at one health center
--        are serialized so that two concurrent revokes cannot together break it.
--  I4-04 Least privilege: acknowledge_privacy_notice (superseded by acknowledge_clinic_privacy_notice, 0022/0034) and
--        record_report_export (superseded by the p_export flag of the report functions, 0026) are no longer executable by API
--        roles (anon, authenticated, service_role). Both remain as definitions only; nothing in the application or the database
--        calls them.
--  I4-05 The duplicate-session booking conflict carries a stable hint (cvsrs:duplicate_session_booking), so the application no
--        longer matches the message text. Only the RAISE changes; the bodies are 0013's, reproduced verbatim (0025 renamed them
--        to *_prev and wraps them; grants and ownership are kept by CREATE OR REPLACE).
--  I4-12 list_review_cases and my_messages break created_at ties by id, so rows created in one transaction keep one order and
--        the same rows fall inside the limit on every call.
--  I4-18 private.restore_clinic_approver: a database-owner-only break-glass that gives one confirmed account the tech_admin or
--        clinical_lead role at a health center that can no longer grant that kind of access (and only then). Adds
--        staff_memberships.operator_restored_at, which the two-person check accepts in place of an approver.
--  QA-02 update_session_capacity says "1 family is already booked" instead of "1 families are already booked".
--  QA-03 private.add_clinic: a database-owner-only command that adds another health center to an existing organization
--        (record and stock transfers need a second clinic); its first staff are seeded with private.restore_clinic_approver.
--
-- Conventions as in 0001: SECURITY DEFINER with an empty search_path, idempotent commands keyed by p_operation_key, stable
-- SQLSTATEs (CV4xx), explicit grants. Rollback: re-run the previous definitions (0002 revoke_staff_membership, 0013 bodies, 0016
-- list_review_cases, 0017 my_messages) and re-grant the two superseded functions to authenticated only if they are needed again.
-- The service_role revoke on them is intended to stay: nothing uses service_role for them (or at all in src/).
-- I4-18 rollback: drop private.restore_clinic_approver; restoring the original check (status <> 'active' or approved_by is not
-- null) needs every operator-restored active membership approved or revoked first; then drop operator_restored_at.

-- ---------------------------------------------------------------------------------------------
-- I4-03 Access-granting guard on revoke_staff_membership
-- ---------------------------------------------------------------------------------------------
-- A membership that currently gives p_cap to its holder, by the same rule as private.has_capability (active, inside its validity
-- window, role preset or explicit capability) and only for a person whose account is active.
create function private.membership_holds(p_membership_id uuid, p_cap text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
      from public.staff_memberships m
      join public.profiles p on p.id = m.profile_id
     where m.id = p_membership_id
       and m.status = 'active' and p.status = 'active'
       and m.valid_from <= now() and (m.valid_until is null or m.valid_until > now())
       and (p_cap = any (private.role_preset(m.role_code)) or p_cap = any (m.capabilities))
  )
$$;

-- Whether the health center can still grant access of one kind without membership p_except (null: as it is now): some person can
-- approve it (p_approver_cap) and a DIFFERENT person can request it (0002: request needs admin.users or grant.approve.clinical;
-- approve needs p_approver_cap, an approver other than the requester and the grantee). Capabilities are combined per person
-- across their memberships, counting only active memberships of active accounts inside their validity window, as in
-- private.has_capability.
create function private.clinic_can_grant(p_clinic uuid, p_approver_cap text, p_except uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  with people as (
    select m.profile_id,
           bool_or(p_approver_cap = any (private.role_preset(m.role_code)) or p_approver_cap = any (m.capabilities)) as can_approve,
           bool_or(array['admin.users','grant.approve.clinical'] && (private.role_preset(m.role_code) || m.capabilities)) as can_request
      from public.staff_memberships m
      join public.profiles p on p.id = m.profile_id
     where m.clinic_id = p_clinic and (p_except is null or m.id <> p_except)
       and m.status = 'active' and p.status = 'active'
       and m.valid_from <= now() and (m.valid_until is null or m.valid_until > now())
     group by m.profile_id
  )
  select exists (
    select 1 from people approver join people requester on requester.profile_id <> approver.profile_id
     where approver.can_approve and requester.can_request
  )
$$;

create or replace function public.revoke_staff_membership(p_operation_key uuid, p_membership_id uuid, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  m public.staff_memberships;
  v_prev jsonb;
  v_needed text;
  v_staff_breaks boolean;
  v_clinical_breaks boolean;
begin
  select * into m from public.staff_memberships where id = p_membership_id;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_needed := case when private.membership_is_clinical(m.role_code, m.capabilities) then 'grant.approve.clinical' else 'admin.users' end;
  if not private.has_capability(m.clinic_id, v_needed) then raise exception 'forbidden' using errcode = 'CV403'; end if;
  -- One revoke at a time per health center, always clinic row first and membership row second (a fixed order, so no deadlock).
  -- Two administrators revoking each other therefore run one after the other, and the second one sees the first one's result.
  -- NO KEY UPDATE does not block inserts that reference the clinic (they take KEY SHARE).
  perform 1 from public.clinics where id = m.clinic_id for no key update;
  select * into m from public.staff_memberships where id = p_membership_id for update;
  -- Checked again after the wait: the caller's own access may have been revoked meanwhile.
  if not private.has_capability(m.clinic_id, v_needed) then raise exception 'forbidden' using errcode = 'CV403'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(m.organization_id, p_operation_key, 'staff_membership.revoke',
                                  jsonb_build_object('membership', p_membership_id, 'reason', p_reason));
  if v_prev is not null then return v_prev; end if;
  if m.status not in ('active','pending_approval','suspended') then raise exception 'already closed' using errcode = 'CV409'; end if;
  -- A membership that holds neither capability (including every pending or suspended one) cannot change who can grant access.
  if private.membership_holds(m.id, 'admin.users') or private.membership_holds(m.id, 'grant.approve.clinical') then
    v_staff_breaks := private.clinic_can_grant(m.clinic_id, 'admin.users', null) and not private.clinic_can_grant(m.clinic_id, 'admin.users', m.id);
    v_clinical_breaks := private.clinic_can_grant(m.clinic_id, 'grant.approve.clinical', null) and not private.clinic_can_grant(m.clinic_id, 'grant.approve.clinical', m.id);
    -- When both would break, name the kind of approval this membership gives (a clinical approver hears about clinical access).
    if v_clinical_breaks and (not v_staff_breaks or private.membership_holds(m.id, 'grant.approve.clinical')) then
      raise exception 'Revoking this access would leave this health center without two different people who can request and approve clinical access. Approve a replacement clinical approver first, then revoke this access.'
        using errcode = 'CV409', hint = 'cvsrs:last_access_holder';
    elsif v_staff_breaks then
      raise exception 'Revoking this access would leave this health center without two different people who can request and approve staff access. Approve a replacement access administrator first, then revoke this access.'
        using errcode = 'CV409', hint = 'cvsrs:last_access_holder';
    end if;
  end if;
  update public.staff_memberships set status = 'revoked', updated_by = auth.uid() where id = m.id;
  perform private.audit(m.organization_id, v_needed, 'staff_membership.revoked', 'staff_membership', m.id,
                        jsonb_build_object('status', m.status), jsonb_build_object('status', 'revoked'), p_reason);
  return private.finish_command(m.organization_id, p_operation_key, jsonb_build_object('membershipId', m.id, 'status', 'revoked'));
end $$;

revoke all on function private.membership_holds(uuid, text), private.clinic_can_grant(uuid, text, uuid) from public, anon, authenticated;
-- CREATE OR REPLACE keeps 0002's grants; restated so the intended ACL is visible here.
revoke all on function public.revoke_staff_membership(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.revoke_staff_membership(uuid, uuid, text) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- I4-04 Superseded commands are no longer executable by API roles
-- ---------------------------------------------------------------------------------------------
revoke all on function public.acknowledge_privacy_notice(uuid, uuid, text, text) from public, anon, authenticated, service_role;
revoke all on function public.record_report_export(uuid, uuid, text, date, date) from public, anon, authenticated, service_role;

-- ---------------------------------------------------------------------------------------------
-- I4-05 Stable hint on the duplicate-session booking conflict (bodies verbatim from 0013 except the RAISE)
-- ---------------------------------------------------------------------------------------------
create or replace function public.book_appointment_prev(p_operation_key uuid, p_child_id uuid, p_session_id uuid, p_reason text default null, p_rule_codes text[] default '{}') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_canon uuid; s public.clinic_sessions; v_channel text; v_prev jsonb; v_id uuid; c public.children; v_ver uuid; v_code text; v_rule uuid; a public.appointments;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  v_canon := private.canonical_child(p_child_id);
  -- Lock the session row first: this serialises every booking, cancellation and move touching this session.
  select * into s from public.clinic_sessions where id = p_session_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_channel := private.can_book_for(v_canon, s.clinic_id);
  if v_channel is null then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(s.organization_id, p_operation_key, 'appointment.book', jsonb_build_object('child', p_child_id, 'session', p_session_id, 'reason', p_reason, 'rules', to_jsonb(coalesce(p_rule_codes, '{}'))));
  if v_prev is not null then return v_prev; end if;
  select * into c from public.children where id = v_canon;
  if c.record_status not in ('provisional','active') then raise exception 'record is not open for booking' using errcode = 'CV409'; end if;
  if s.status <> 'open' or s.ends_at <= now() then raise exception 'this session is not open for booking' using errcode = 'CV409'; end if;
  if exists (select 1 from public.appointments where child_id = v_canon and session_id = s.id and status in ('confirmed','checked_in','fulfilled')) then
    raise exception 'this child already has an appointment in this session' using errcode = 'CV409', hint = 'cvsrs:duplicate_session_booking';
  end if;
  if private.session_booked(s.id) >= s.online_capacity then raise exception 'this session is full' using errcode = 'CV409'; end if;

  insert into public.appointments (organization_id, child_id, session_id, booked_by, channel, reason, created_by, updated_by)
  values (s.organization_id, v_canon, s.id, auth.uid(), v_channel, left(p_reason, 300), auth.uid(), auth.uid()) returning id into v_id;

  -- Optional: which schedule requirements this visit is for. Must exist in the version in force; never implies clearance.
  if coalesce(array_length(p_rule_codes, 1), 0) > 0 then
    v_ver := private.active_schedule_for(s.organization_id, 'routine', c.dob, s.service_date);
    if v_ver is null then raise exception 'no approved schedule is in force for those requirements' using errcode = 'CV422'; end if;
    foreach v_code in array p_rule_codes loop
      select id into v_rule from public.schedule_rules where schedule_version_id = v_ver and requirement_code = v_code;
      if v_rule is null then raise exception 'unknown requirement %', v_code using errcode = 'CV422'; end if;
      insert into public.appointment_items (organization_id, appointment_id, rule_id) values (s.organization_id, v_id, v_rule) on conflict do nothing;
    end loop;
  end if;
  perform private.enqueue(s.organization_id, 'appointment.confirmation', 'appointment', v_id, 'appt-confirm:' || v_id, jsonb_build_object('sessionId', s.id));
  perform private.audit(s.organization_id, case when v_channel = 'online' then 'guardian' else 'appointment.manage' end, 'appointment.booked', 'appointment', v_id, null,
                        jsonb_build_object('session', s.id, 'channel', v_channel), p_reason);
  select * into a from public.appointments where id = v_id;
  return private.finish_command(s.organization_id, p_operation_key, private.appointment_json(a, s));
end $$;

-- Atomic move: if the new session cannot take the child, the original booking is untouched (BP17).
create or replace function public.reschedule_appointment_prev(p_operation_key uuid, p_appointment_id uuid, p_new_session_id uuid, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare a public.appointments; so public.clinic_sessions; sn public.clinic_sessions; v_prev jsonb; v_channel text; v_new uuid; a2 public.appointments;
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  select a0.* into a from public.appointments a0 where a0.id = p_appointment_id;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  -- lock both sessions in a stable id order to avoid deadlocks between opposite moves
  perform 1 from public.clinic_sessions where id in (a.session_id, p_new_session_id) order by id for update;
  select * into so from public.clinic_sessions where id = a.session_id;
  select * into sn from public.clinic_sessions where id = p_new_session_id;
  if sn.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  select * into a from public.appointments where id = p_appointment_id for update;
  v_channel := private.can_book_for(a.child_id, so.clinic_id);
  if v_channel is null or sn.clinic_id <> so.clinic_id then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(a.organization_id, p_operation_key, 'appointment.reschedule', jsonb_build_object('a', p_appointment_id, 'n', p_new_session_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if a.status <> 'confirmed' then raise exception 'only a confirmed appointment can be moved' using errcode = 'CV409'; end if;
  if sn.id = so.id then raise exception 'choose a different session' using errcode = 'CV422'; end if;
  if sn.status <> 'open' or sn.ends_at <= now() then raise exception 'that session is not open for booking' using errcode = 'CV409'; end if;
  if exists (select 1 from public.appointments where child_id = a.child_id and session_id = sn.id and status in ('confirmed','checked_in','fulfilled')) then raise exception 'this child already has an appointment in that session' using errcode = 'CV409', hint = 'cvsrs:duplicate_session_booking'; end if;
  if private.session_booked(sn.id) >= sn.online_capacity then raise exception 'that session is full' using errcode = 'CV409'; end if;
  update public.appointments set status = 'rescheduled', updated_by = auth.uid() where id = a.id;
  insert into public.appointments (organization_id, child_id, session_id, booked_by, channel, reason, replaces_id, created_by, updated_by)
  values (a.organization_id, a.child_id, sn.id, auth.uid(), v_channel, coalesce(left(p_reason, 300), a.reason), a.id, auth.uid(), auth.uid()) returning id into v_new;
  insert into public.appointment_items (organization_id, appointment_id, rule_id, purpose) select organization_id, v_new, rule_id, purpose from public.appointment_items where appointment_id = a.id;
  update private.outbox_jobs set status = 'cancelled', updated_at = now() where organization_id = a.organization_id and status = 'queued' and (dedupe_key like 'appt-remind:' || a.id || '%' or dedupe_key = 'appt-confirm:' || a.id);
  perform private.enqueue(a.organization_id, 'appointment.confirmation', 'appointment', v_new, 'appt-confirm:' || v_new, jsonb_build_object('sessionId', sn.id, 'rescheduledFrom', a.id));
  perform private.audit(a.organization_id, case when v_channel = 'online' then 'guardian' else 'appointment.manage' end, 'appointment.rescheduled', 'appointment', v_new,
                        jsonb_build_object('from', a.id, 'session', so.id), jsonb_build_object('session', sn.id), p_reason);
  select * into a2 from public.appointments where id = v_new;
  return private.finish_command(a.organization_id, p_operation_key, private.appointment_json(a2, sn) || jsonb_build_object('replaces', a.id));
end $$;

revoke all on function public.book_appointment_prev(uuid, uuid, uuid, text, text[]), public.reschedule_appointment_prev(uuid, uuid, uuid, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- I4-12 Deterministic ordering for rows created in one transaction (created_at = now() is equal for all of them)
-- ---------------------------------------------------------------------------------------------
-- cancel_session opens one review case per booking and one outbox run writes many messages, all with the same created_at. The id
-- breaks the tie, so the order and the rows inside the limit are the same on every call. Bodies are 0016's and 0017's except the
-- ORDER BY clauses (list_review_cases now aggregates by the row's own columns instead of the createdAt text).
create or replace function public.list_review_cases(p_clinic_id uuid, p_status text default 'open', p_limit integer default 50)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_res jsonb;
begin
  if not (private.has_capability(p_clinic_id, 'guardian.verify') or private.has_capability(p_clinic_id, 'review.resolve') or private.has_capability(p_clinic_id, 'correction.approve')
          or private.has_capability(p_clinic_id, 'inventory.approve')) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
  select coalesce(jsonb_agg(s.x order by s.sort_at, s.sort_id), '[]'::jsonb) into v_res from (
    select jsonb_build_object('caseId', k.id, 'kind', k.kind, 'status', k.status, 'reason', k.reason, 'createdAt', k.created_at, 'version', k.version,
             'evidence', k.evidence, 'childId', k.child_id, 'candidateChildId', k.candidate_child_id, 'eventId', k.vaccination_event_id, 'createdBy', k.created_by,
             'child', (select jsonb_build_object('displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob) from public.children c where c.id = k.child_id),
             'candidate', (select jsonb_build_object('displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob) from public.children c where c.id = k.candidate_child_id
                             and private.child_in_clinic(c.id, p_clinic_id)),
             'guardianName', (select g.full_name from public.guardians g where g.id = k.guardian_id)) x,
           k.created_at as sort_at, k.id as sort_id
      from public.record_review_cases k
     where k.clinic_id = p_clinic_id and k.status = p_status
     order by k.created_at, k.id limit least(greatest(coalesce(p_limit, 50), 1), 100)) s;
  return v_res;
end $$;

create or replace function public.my_messages(p_limit integer default 50) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.session_ok() then return null; end if;
  return jsonb_build_object(
    'unread', (select count(*) from public.messages where recipient_profile_id = auth.uid() and read_at is null),
    'items', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'kind', x.kind, 'title', x.title, 'body', x.body, 'childId', x.child_id, 'createdAt', x.created_at, 'read', x.read_at is not null) order by x.created_at desc, x.id desc), '[]'::jsonb)
                from (select * from public.messages where recipient_profile_id = auth.uid() order by created_at desc, id desc limit least(greatest(coalesce(p_limit, 50), 1), 100)) x));
end $$;

-- CREATE OR REPLACE keeps the grants of 0016/0017; restated so the intended ACL is visible here.
revoke all on function public.list_review_cases(uuid, text, integer), public.my_messages(integer) from public, anon, authenticated;
grant execute on function public.list_review_cases(uuid, text, integer), public.my_messages(integer) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- I4-18 Operator break-glass: restore an approver at a health center that can no longer grant access
-- ---------------------------------------------------------------------------------------------
-- The revoke guard (I4-03) cannot stop an operator suspending an account, nor a membership expiring. When a health center then
-- has no two different people who can request and approve a kind of access, the in-app two-person path is closed for good.
-- private.restore_clinic_approver lets the DATABASE OWNER (same execution model as private.bootstrap_initial_staff, 0034/0039)
-- give one confirmed, active account the role that reopens that path, and only then: it refuses whenever the path still works.
--
-- A restored membership has no approver (nobody at the health center could approve it), so it is marked by
-- operator_restored_at instead; the two-person check on active memberships accepts either an approver or that marker.
-- Existing rows: an active, currently valid membership of that person with that role is refused (CV409). A pending request or
-- an active-but-expired membership with that role (at most one, staff_memberships_one_live_uq) is reused and made active
-- without an end date; revoked, rejected and suspended rows are never reactivated, they stay as history and a new row is added.
alter table public.staff_memberships add column operator_restored_at timestamptz;

do $$
declare v_name text;
begin
  select c.conname into v_name
    from pg_catalog.pg_constraint c
   where c.conrelid = 'public.staff_memberships'::regclass and c.contype = 'c'
     and pg_catalog.pg_get_constraintdef(c.oid) like '%status <> ''active''%'
     and pg_catalog.pg_get_constraintdef(c.oid) like '%approved_by IS NOT NULL%';
  if v_name is null then raise exception '0040: the two-person check on public.staff_memberships was not found'; end if;
  execute pg_catalog.format('alter table public.staff_memberships drop constraint %I', v_name);
end $$;
alter table public.staff_memberships add constraint staff_memberships_active_approved_check
  check (status <> 'active' or approved_by is not null or operator_restored_at is not null);

create function private.restore_clinic_approver(p_clinic_id uuid, p_email text, p_role text, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.clinics; v_email text := lower(btrim(coalesce(p_email, ''))); v_reason text := btrim(coalesce(p_reason, ''));
  v_cap text; v_profile uuid; m public.staff_memberships; v_id uuid;
begin
  if p_role is null or p_role not in ('tech_admin','clinical_lead') then
    raise exception 'restore a tech_admin (staff access) or a clinical_lead (clinical access)' using errcode = 'CV422';
  end if;
  if length(v_reason) < 10 then raise exception 'give a reason of at least 10 characters' using errcode = 'CV422'; end if;
  -- Same order as revoke_staff_membership: the clinic row first, so restores and revokes at one health center run one at a time.
  select * into c from public.clinics where id = p_clinic_id for no key update;
  if c.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if c.status <> 'active' then raise exception 'this health center is not active' using errcode = 'CV409'; end if;
  v_cap := case p_role when 'tech_admin' then 'admin.users' else 'grant.approve.clinical' end;
  if private.clinic_can_grant(c.id, v_cap, null) then
    raise exception 'this health center can still approve access through the app; use the normal two-person request' using errcode = 'CV409';
  end if;
  select p.id into v_profile from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = v_email and p.status = 'active';
  if v_profile is null then raise exception 'no active account uses that email address' using errcode = 'CV422'; end if;
  -- As in 0039: Supabase records confirmation in auth.users.email_confirmed_at (read through to_jsonb so this compiles on the
  -- local test bootstrap, whose auth.users has no such column).
  if exists (select 1 from auth.users u where u.id = v_profile and to_jsonb(u) ? 'email_confirmed_at' and (to_jsonb(u) ->> 'email_confirmed_at') is null) then
    raise exception 'the person must confirm their email address first' using errcode = 'CV422';
  end if;
  select * into m from public.staff_memberships
   where profile_id = v_profile and clinic_id = c.id and role_code = p_role and status in ('pending_approval','active') for update;
  if m.id is not null and m.status = 'active' and m.valid_from <= now() and (m.valid_until is null or m.valid_until > now()) then
    raise exception 'this person already holds that role at this health center' using errcode = 'CV409';
  end if;
  if m.id is not null then
    update public.staff_memberships
       set status = 'active', valid_from = now(), valid_until = null, operator_restored_at = now(), updated_by = null
     where id = m.id returning id into v_id;
  else
    insert into public.staff_memberships (organization_id, profile_id, clinic_id, role_code, status, operator_restored_at)
    values (c.organization_id, v_profile, c.id, p_role, 'active', now()) returning id into v_id;
  end if;
  perform private.audit(c.organization_id, null, 'staff_membership.restored_by_operator', 'staff_membership', v_id,
                        case when m.id is null then null else jsonb_build_object('status', m.status, 'validUntil', m.valid_until) end,
                        jsonb_build_object('clinic', c.id, 'profile', v_profile, 'role', p_role, 'status', 'active',
                                           'emailDomain', split_part(v_email, '@', 2), 'dbUser', session_user::text,
                                           'reusedMembership', m.id is not null),
                        v_reason);
  return jsonb_build_object('membershipId', v_id, 'role', p_role, 'clinicId', c.id);
end $$;

revoke all on function private.restore_clinic_approver(uuid, text, text, text) from public, anon, authenticated, service_role;

-- ---------------------------------------------------------------------------------------------
-- QA-02 Plain singular wording in the capacity conflict ("1 family is already booked"); body is 0037's except that RAISE
-- ---------------------------------------------------------------------------------------------
create or replace function public.update_session_capacity(p_operation_key uuid, p_clinic_id uuid, p_session_id uuid, p_expected_version integer,
                                               p_total integer, p_online integer, p_walkin integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; s public.clinic_sessions; v_booked int;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'appointment.manage');
  v_prev := private.begin_command(v_org, p_operation_key, 'session.capacity',
    jsonb_build_object('c', p_clinic_id, 's', p_session_id, 'v', p_expected_version, 't', p_total, 'o', p_online, 'w', p_walkin));
  if v_prev is not null then return v_prev; end if;
  select * into s from public.clinic_sessions where id = p_session_id and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if s.version <> p_expected_version then raise exception 'the session changed; reload and try again' using errcode = 'CV409'; end if;
  if s.status <> 'open' or s.ends_at <= now() then raise exception 'only an open, upcoming session can be changed' using errcode = 'CV409'; end if;
  if p_total is null or p_online is null or p_walkin is null or p_total < 0 or p_online < 0 or p_walkin < 0 or p_online + p_walkin > p_total then
    raise exception 'online plus walk-in capacity cannot exceed total capacity' using errcode = 'CV422';
  end if;
  v_booked := private.session_booked(s.id);
  if p_online < v_booked then
    raise exception '%', case when v_booked = 1 then '1 family is already booked' else v_booked || ' families are already booked' end || '; bookable places cannot go below that' using errcode = 'CV409';
  end if;
  update public.clinic_sessions set total_capacity = p_total, online_capacity = p_online, walkin_capacity = p_walkin, updated_by = auth.uid() where id = s.id;
  perform private.audit(v_org, 'appointment.manage', 'session.capacity_changed', 'clinic_session', s.id,
    jsonb_build_object('total', s.total_capacity, 'online', s.online_capacity, 'walkin', s.walkin_capacity),
    jsonb_build_object('total', p_total, 'online', p_online, 'walkin', p_walkin), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('sessionId', s.id, 'booked', v_booked));
end $$;


-- CREATE OR REPLACE keeps 0037's grants; restated so the intended ACL is visible here.
revoke all on function public.update_session_capacity(uuid, uuid, uuid, integer, integer, integer, integer) from public, anon, authenticated;
grant execute on function public.update_session_capacity(uuid, uuid, uuid, integer, integer, integer, integer) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- QA-03 Operator command to add another health center to an existing organization
-- ---------------------------------------------------------------------------------------------
-- Until now the only supported clinic insert was the one-time bootstrap (0034/0039), so record transfers and inter-clinic stock
-- transfers had no second clinic to use. Database owner only, like private.bootstrap_initial_staff: the same columns and
-- defaults as its clinic insert (name trimmed, timezone defaulting to Asia/Manila, status active by default). The new clinic has
-- no staff; its first access administrator and clinical lead are seeded with private.restore_clinic_approver (a clinic with no
-- memberships cannot grant either kind of access), after which the normal two-person commands apply.
create function private.add_clinic(p_organization_id uuid, p_name text, p_timezone text, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  o public.organizations; v_name text := btrim(coalesce(p_name, '')); v_tz text := coalesce(nullif(btrim(coalesce(p_timezone, '')), ''), 'Asia/Manila');
  v_reason text := btrim(coalesce(p_reason, '')); v_clinic uuid;
begin
  if length(v_reason) < 10 then raise exception 'give a reason of at least 10 characters' using errcode = 'CV422'; end if;
  -- One add at a time per organization, so two concurrent adds cannot both pass the name check. NO KEY UPDATE does not block
  -- inserts that reference the organization (they take KEY SHARE).
  select * into o from public.organizations where id = p_organization_id for no key update;
  if o.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  if o.status <> 'active' then raise exception 'this organization is not active' using errcode = 'CV409'; end if;
  if length(v_name) < 3 or length(v_name) > 120 then raise exception 'name the health center (3 to 120 characters)' using errcode = 'CV422'; end if;
  if not exists (select 1 from pg_catalog.pg_timezone_names n where n.name = v_tz) then
    raise exception 'choose a valid time zone name (for example Asia/Manila)' using errcode = 'CV422';
  end if;
  if exists (select 1 from public.clinics c where c.organization_id = o.id and lower(btrim(c.name)) = lower(v_name)) then
    raise exception 'this organization already has a health center with that name' using errcode = 'CV409';
  end if;
  insert into public.clinics (organization_id, name, timezone) values (o.id, v_name, v_tz) returning id into v_clinic;
  perform private.audit(o.id, null, 'clinic.added_by_operator', 'clinic', v_clinic, null,
                        jsonb_build_object('organization', o.id, 'name', v_name, 'timezone', v_tz, 'dbUser', session_user::text), v_reason);
  return jsonb_build_object('clinicId', v_clinic, 'name', v_name, 'timezone', v_tz);
end $$;

revoke all on function private.add_clinic(uuid, text, text, text) from public, anon, authenticated, service_role;
-- END 0040_iteration4_integrity.sql

-- =====================================================================================================================
-- BEGIN 0041_stock_location_lifecycle.sql  sha256=3afe0e87113a84917c13f577856d092112384e94c1cb4daeb465ca6147466bed
-- =====================================================================================================================
-- Closed locations cannot acquire stock. Inventory postings already hold the shared
-- organization lock; closing takes its exclusive counterpart before checking balances.
-- This avoids adding location row locks to multi-location transfers in inconsistent order.
create or replace function private.apply_movement() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  perform private.stock_org_lock(new.organization_id);
  if not exists (select 1 from public.stock_locations l
                  where l.id = new.location_id and l.organization_id = new.organization_id and l.status = 'active') then
    raise exception 'the stock location is closed or unavailable' using errcode = 'CV409';
  end if;
  update public.stock_balances set on_hand = on_hand + new.quantity_delta, updated_at = now()
   where location_id = new.location_id and lot_id = new.lot_id;
  if not found then
    begin
      insert into public.stock_balances (organization_id, location_id, lot_id, on_hand)
      values (new.organization_id, new.location_id, new.lot_id, new.quantity_delta);
    exception when unique_violation then
      update public.stock_balances set on_hand = on_hand + new.quantity_delta, updated_at = now()
       where location_id = new.location_id and lot_id = new.lot_id;
    end;
  end if;
  return new;
end $$;

create or replace function public.close_stock_location(p_operation_key uuid, p_clinic_id uuid, p_location_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; l public.stock_locations;
begin
  -- Do not call inventory_org here: upgrading a shared lock while another closer
  -- holds a shared lock would deadlock. Authorize, then acquire exclusive directly.
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'inventory.manage');
  perform private.stock_org_lock(v_org, true);
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.location_close', jsonb_build_object('c', p_clinic_id, 'l', p_location_id, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  select * into l from public.stock_locations where id = p_location_id and organization_id = v_org and clinic_id = p_clinic_id for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  if l.status <> 'active' then raise exception 'the location is already closed' using errcode = 'CV409'; end if;
  if l.kind = 'in_transit' then raise exception 'the transit location is managed by the system' using errcode = 'CV409'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'a reason is required' using errcode = 'CV422'; end if;
  if exists (select 1 from public.stock_balances b where b.location_id = l.id and (b.on_hand <> 0 or b.allocated <> 0)) then
    raise exception 'move or record all stock at this location before closing it' using errcode = 'CV409';
  end if;
  if exists (select 1 from public.stock_transfers t where (t.from_location_id = l.id or t.to_location_id = l.id) and t.status = 'in_transit') then
    raise exception 'a transfer to or from this location is still in transit' using errcode = 'CV409';
  end if;
  update public.stock_locations set status = 'closed', updated_by = auth.uid() where id = l.id;
  perform private.audit(v_org, 'inventory.manage', 'stock.location_closed', 'stock_location', l.id, jsonb_build_object('status', 'active'), jsonb_build_object('status', 'closed'), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('locationId', l.id, 'status', 'closed'));
end $$;

create or replace function public.propose_stock_adjustment(p_operation_key uuid, p_clinic_id uuid, p_location_id uuid, p_lot_id uuid, p_observed numeric, p_count_reference text, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid := private.inventory_org(p_clinic_id); v_prev jsonb; v_book numeric; v_delta numeric; v_thr numeric; v_case uuid; v_tx uuid; v_can_approve boolean;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.adjust', jsonb_build_object('c', p_clinic_id, 'loc', p_location_id, 'lot', p_lot_id, 'obs', p_observed, 'ref', p_count_reference, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if p_observed is null or p_observed < 0 then raise exception 'observed count must be zero or more' using errcode = 'CV422'; end if;
  if p_count_reference is null or length(btrim(p_count_reference)) = 0 or p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'count reference and reason are required' using errcode = 'CV422'; end if;
  if not exists (select 1 from public.stock_locations where id = p_location_id and organization_id = v_org and clinic_id = p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if not exists (select 1 from public.stock_locations where id = p_location_id and status = 'active') then
    raise exception 'the stock location is closed' using errcode = 'CV409';
  end if;
  select coalesce(on_hand, 0) into v_book from public.stock_balances where location_id = p_location_id and lot_id = p_lot_id;
  v_book := coalesce(v_book, 0);
  v_delta := p_observed - v_book;
  if v_delta = 0 then return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'no_difference', 'book', v_book)); end if;
  v_thr := coalesce((select (value)::text::numeric from private.settings where key = 'adjustment_auto_approve_units'), 0);
  v_can_approve := private.has_capability(p_clinic_id, 'inventory.approve');
  if abs(v_delta) <= v_thr or v_can_approve then
    insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, approved_by, operation_id, created_by)
    values (v_org, p_clinic_id, 'adjustment', p_count_reference, p_reason, case when v_can_approve then auth.uid() end, p_operation_key, auth.uid()) returning id into v_tx;
    perform private.post_movement(v_org, v_tx, p_location_id, p_lot_id, v_delta, 'adjust:' || p_operation_key);
    perform private.audit(v_org, 'inventory.manage', 'stock.adjusted', 'vaccine_lot', p_lot_id, jsonb_build_object('book', v_book), jsonb_build_object('observed', p_observed, 'delta', v_delta), p_reason);
    return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'posted', 'delta', v_delta, 'transactionId', v_tx));
  end if;
  insert into public.record_review_cases (organization_id, clinic_id, kind, reason, evidence, created_by, updated_by)
  values (v_org, p_clinic_id, 'stock', 'stock count difference awaiting approval',
          jsonb_build_object('locationId', p_location_id, 'lotId', p_lot_id, 'book', v_book, 'observed', p_observed, 'delta', v_delta, 'countReference', p_count_reference, 'reason', p_reason, 'operationKey', p_operation_key),
          auth.uid(), auth.uid()) returning id into v_case;
  perform private.audit(v_org, 'inventory.manage', 'stock.adjustment_proposed', 'review_case', v_case, jsonb_build_object('book', v_book), jsonb_build_object('observed', p_observed), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'pending_approval', 'caseId', v_case, 'delta', v_delta));
end $$;

-- CREATE OR REPLACE preserves the existing explicit ACLs.
revoke all on function private.apply_movement() from public, anon, authenticated;
revoke all on function public.close_stock_location(uuid, uuid, uuid, text),
  public.propose_stock_adjustment(uuid, uuid, uuid, uuid, numeric, text, text) from public, anon, authenticated;
grant execute on function public.close_stock_location(uuid, uuid, uuid, text),
  public.propose_stock_adjustment(uuid, uuid, uuid, uuid, numeric, text, text) to authenticated;
-- END 0041_stock_location_lifecycle.sql

-- =====================================================================================================================
-- BEGIN 0042_worklist_pagination.sql  sha256=ec6c4435bdd35a35275b989fa1426759060fcaae76fe60de4f259f42b9aff249
-- =====================================================================================================================
-- Keep existing result shapes and default calls; add paired keyset cursors to bounded worklists.
drop function public.my_messages(integer);
create function public.my_messages(p_limit integer default 50, p_before timestamptz default null, p_before_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  if not private.session_ok() then return null; end if;
  if (p_before is null) <> (p_before_id is null) then raise exception 'incomplete paging cursor' using errcode = 'CV422'; end if;
  return jsonb_build_object(
    'unread', (select count(*) from public.messages where recipient_profile_id = auth.uid() and read_at is null),
    'items', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'kind', x.kind, 'title', x.title, 'body', x.body, 'childId', x.child_id, 'createdAt', x.created_at, 'read', x.read_at is not null) order by x.created_at desc, x.id desc), '[]'::jsonb)
      from (select * from public.messages where recipient_profile_id = auth.uid()
        and (p_before is null or (created_at,id) < (p_before,p_before_id))
        order by created_at desc,id desc limit least(greatest(coalesce(p_limit,50),1),100)) x));
end $$;

drop function public.list_review_cases(uuid,text,integer);
create function public.list_review_cases(p_clinic_id uuid, p_status text default 'open', p_limit integer default 50,
  p_after timestamptz default null, p_after_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_res jsonb;
begin
  if not (private.has_capability(p_clinic_id,'guardian.verify') or private.has_capability(p_clinic_id,'review.resolve')
    or private.has_capability(p_clinic_id,'correction.approve') or private.has_capability(p_clinic_id,'inventory.approve')) then
    raise exception 'forbidden' using errcode = 'CV403';
  end if;
  if (p_after is null) <> (p_after_id is null) then raise exception 'incomplete paging cursor' using errcode = 'CV422'; end if;
  select coalesce(jsonb_agg(s.x order by s.sort_at,s.sort_id),'[]'::jsonb) into v_res from (
    select jsonb_build_object('caseId',k.id,'kind',k.kind,'status',k.status,'reason',k.reason,'createdAt',k.created_at,'version',k.version,
      'evidence',k.evidence,'childId',k.child_id,'candidateChildId',k.candidate_child_id,'eventId',k.vaccination_event_id,'createdBy',k.created_by,
      'child',(select jsonb_build_object('displayName',c.display_name,'localRecordNo',c.local_record_no,'dob',c.dob) from public.children c where c.id=k.child_id),
      'candidate',(select jsonb_build_object('displayName',c.display_name,'localRecordNo',c.local_record_no,'dob',c.dob) from public.children c where c.id=k.candidate_child_id and private.child_in_clinic(c.id,p_clinic_id)),
      'guardianName',(select g.full_name from public.guardians g where g.id=k.guardian_id)) x,
      k.created_at sort_at,k.id sort_id
    from public.record_review_cases k where k.clinic_id=p_clinic_id and k.status=p_status
      and (p_after is null or (k.created_at,k.id) > (p_after,p_after_id))
    order by k.created_at,k.id limit least(greatest(coalesce(p_limit,50),1),100)) s;
  return v_res;
end $$;

drop function public.list_followup_worklist(uuid,text,integer);
create function public.list_followup_worklist(p_clinic_id uuid, p_filter text default 'behind', p_limit integer default 50,
  p_after_behind integer default null, p_after_due integer default null, p_after_name text default null, p_after_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_res jsonb; v_lim int := least(greatest(coalesce(p_limit,50),1),100); v_today date; v_contact boolean;
begin
  select organization_id into v_org from public.clinics where id=p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_any(p_clinic_id,array['bhw.followup','child.read_clinical']);
  if p_filter not in ('behind','due','review','all') then raise exception 'unknown filter' using errcode = 'CV422'; end if;
  if num_nonnulls(p_after_behind,p_after_due,p_after_name,p_after_id) not in (0,4)
    or p_after_behind < 0 or p_after_due < 0 then raise exception 'invalid paging cursor' using errcode = 'CV422'; end if;
  v_today := private.local_today(p_clinic_id);
  v_contact := private.has_capability(p_clinic_id,'bhw.followup');
  select jsonb_build_object(
    'asOf',now(),
    'schedule',case when exists(select 1 from public.followup_snapshots where clinic_id=p_clinic_id and status='evaluated') then 'active' when exists(select 1 from public.followup_snapshots where clinic_id=p_clinic_id) then 'none' else 'unknown' end,
    'staleChildren',(select count(*) from public.children c join public.child_clinic_enrollments e on e.child_id=c.id and e.clinic_id=p_clinic_id and e.status='active'
      left join public.followup_snapshots s on s.child_id=c.id where c.merged_into_id is null and c.record_status='active' and private.followup_is_stale(c.organization_id,c.dob,v_today,s.computed_at,s.schedule_version_id,s.child_id is not null)),
    'items',coalesce((select jsonb_agg(x.item order by x.ord1 desc,x.ord2 desc,x.ord3,x.ord4) from (
      select jsonb_build_object('childId',c.id,'childName',c.display_name,'recordNo',c.local_record_no,'dob',c.dob,'behind',s.behind,'due',s.due,'review',s.review,'needs',s.needs,'computedAt',s.computed_at,
        'lastAttempt',(select jsonb_build_object('outcome',a.outcome,'at',a.recorded_at,'note',a.note,'nextTryOn',a.next_try_on) from public.followup_attempts a where a.child_id=c.id order by a.recorded_at desc limit 1),
        'attempts',(select count(*) from public.followup_attempts a where a.child_id=c.id),
        'guardian',(select jsonb_build_object('name',g.full_name,'phone',case when v_contact then g.contact_phone end,'phoneChecked',g.contact_verified_at is not null)
          from public.guardian_child_relationships r join public.guardians g on g.id=r.guardian_id where r.child_id=c.id and r.status='active' and g.deleted_at is null order by r.created_at limit 1)) item,
        s.behind ord1,s.due ord2,c.display_name ord3,c.id ord4
      from public.followup_snapshots s join public.children c on c.id=s.child_id
      where s.clinic_id=p_clinic_id and s.status='evaluated'
        and ((p_filter='behind' and s.behind>0) or (p_filter='due' and s.due>0) or (p_filter='review' and s.review>0) or (p_filter='all' and (s.behind+s.due+s.review)>0))
        and not exists(select 1 from public.followup_attempts a where a.child_id=c.id and a.next_try_on>v_today and a.recorded_at=(select max(a2.recorded_at) from public.followup_attempts a2 where a2.child_id=c.id))
        and (p_after_id is null or (-s.behind,-s.due,c.display_name,c.id) > (-p_after_behind,-p_after_due,p_after_name,p_after_id))
      order by s.behind desc,s.due desc,c.display_name,c.id limit v_lim) x),'[]'::jsonb)) into v_res;
  perform private.audit(v_org,case when v_contact then 'bhw.followup' else 'child.read_clinical' end,'followup.listed','clinic',p_clinic_id,null,jsonb_build_object('filter',p_filter,'shown',jsonb_array_length(v_res->'items')),null);
  return v_res;
end $$;

create index messages_inbox_paging_idx on public.messages(recipient_profile_id,created_at desc,id desc);
create index review_cases_paging_idx on public.record_review_cases(clinic_id,status,created_at,id);
revoke all on function public.my_messages(integer,timestamptz,uuid), public.list_review_cases(uuid,text,integer,timestamptz,uuid),
  public.list_followup_worklist(uuid,text,integer,integer,integer,text,uuid) from public,anon,authenticated;
grant execute on function public.my_messages(integer,timestamptz,uuid), public.list_review_cases(uuid,text,integer,timestamptz,uuid),
  public.list_followup_worklist(uuid,text,integer,integer,integer,text,uuid) to authenticated;
-- END 0042_worklist_pagination.sql

-- =====================================================================================================================
-- BEGIN 0043_reminder_freshness.sql  sha256=3f2d4bb04abe64ac81705eb8f78bfaecbd8630fb719e03d03052f9e426278436
-- =====================================================================================================================
-- Reminders are facts about the current clinic-local day and current schedule.
-- Recheck after queueing, both when creating messages and when claiming SMS.
create function private.reminder_is_current(j private.outbox_jobs) returns boolean
language plpgsql security definer set search_path = '' as $$
declare v_clinic uuid; v_schedule jsonb;
begin
  if j.job_type = 'appointment.reminder' then
    return exists (
      select 1 from public.appointments a
        join public.clinic_sessions s on s.id = a.session_id
        join public.clinics c on c.id = s.clinic_id
       where a.id = j.aggregate_id and a.organization_id = j.organization_id
         and a.status = 'confirmed' and s.status = 'open' and c.status = 'active'
         and s.service_date = private.local_today(s.clinic_id) + 1
    );
  elsif j.job_type = 'dose.due' then
    select e.clinic_id into v_clinic
      from public.children c
      join public.child_clinic_enrollments e on e.child_id = c.id and e.status = 'active' and e.is_primary
      join public.clinics cl on cl.id = e.clinic_id and cl.status = 'active'
     where c.id = j.aggregate_id and c.organization_id = j.organization_id
       and c.record_status = 'active' and c.merged_into_id is null and c.deleted_at is null
       and e.clinic_id = (j.payload ->> 'clinicId')::uuid;
    if v_clinic is null then return false; end if;
    v_schedule := private.compute_child_schedule(j.aggregate_id, private.local_today(v_clinic), false);
    return v_schedule ->> 'status' = 'evaluated' and exists (
      select 1 from jsonb_array_elements(coalesce(v_schedule -> 'requirements', '[]'::jsonb)) r
       where r ->> 'status' in ('due_today','due_now','overdue')
    );
  end if;
  return true;
end $$;

-- Preserve the existing dispatch bodies and their notification wording.
alter function private.handle_outbox_job(private.outbox_jobs) rename to handle_outbox_job_before_reminder_freshness;
create function private.handle_outbox_job(j private.outbox_jobs) returns text
language plpgsql security definer set search_path = '' as $$
begin
  if not private.reminder_is_current(j) then return 'cancelled'; end if;
  return private.handle_outbox_job_before_reminder_freshness(j);
end $$;

create or replace function private.claim_sms(p_limit integer default 20)
returns table (id uuid, phone text, body text, attempt integer)
language plpgsql security definer set search_path = '' as $$
declare m public.sms_messages; g public.guardians; j private.outbox_jobs;
begin
  update public.sms_messages set status = 'queued', updated_at = now()
   where status = 'sending' and locked_until < now();
  -- Only the bounded, claimable batch is evaluated. The outbox's unique dedupe
  -- key supplies structured reminder context without parsing phone-message text.
  for m in
    select sms.* from public.sms_messages sms join public.guardians guardian on guardian.id = sms.guardian_id
     where sms.status = 'queued' and sms.available_at <= now() and guardian.sms_opt_in
       and guardian.contact_phone is not null and guardian.contact_verified_at is not null
     order by sms.available_at, sms.created_at
     limit least(greatest(coalesce(p_limit, 20), 1), 100) for update of sms skip locked
  loop
    select o.* into j from private.outbox_jobs o
     where o.organization_id = m.organization_id and o.dedupe_key = m.dedupe_key
       and o.job_type in ('appointment.reminder','dose.due');
    if j.id is not null and not private.reminder_is_current(j) then
      update public.sms_messages sms set status = 'undeliverable', locked_until = null,
             last_error_code = 'stale_reminder', updated_at = now() where sms.id = m.id;
      continue;
    end if;
    select guardian.* into g from public.guardians guardian where guardian.id = m.guardian_id;
    update public.sms_messages sms
       set status = 'sending', attempt_count = sms.attempt_count + 1,
           locked_until = now() + interval '2 minutes', updated_at = now()
     where sms.id = m.id returning sms.id, g.contact_phone, sms.body, sms.attempt_count into id, phone, body, attempt;
    return next;
  end loop;
end $$;

revoke all on function private.reminder_is_current(private.outbox_jobs),
  private.handle_outbox_job_before_reminder_freshness(private.outbox_jobs),
  private.handle_outbox_job(private.outbox_jobs), private.claim_sms(integer) from public, anon, authenticated;
grant execute on function private.claim_sms(integer) to cvsrs_outbox_worker;
-- END 0043_reminder_freshness.sql

-- =====================================================================================================================
-- BEGIN 0044_privacy_acknowledgement.sql  sha256=1b90dfa72aedfb3ae398f06e6b5b05430aa75acf6a3baa101179bf8baaf87be6
-- =====================================================================================================================
-- The app acknowledges the exact notice it displayed. Keep the two-argument command for existing database callers.
create function public.acknowledge_clinic_privacy_notice(
  p_operation_key uuid, p_clinic_id uuid, p_notice_version text, p_notice_text text
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.clinics; v_prev jsonb; v_sha text; v_g uuid;
begin
  if auth.uid() is null or not private.session_ok() then raise exception 'unauthenticated' using errcode = 'CV401'; end if;
  -- Serialize with the clinic UPDATE in set_privacy_notice, including a publisher already holding this row.
  select * into c from public.clinics where id = p_clinic_id and status = 'active' for update;
  if c.id is null then raise exception 'not found' using errcode = 'CV404'; end if;
  -- A lost acknowledgement response must still replay after the clinic publishes
  -- another notice. Replaying v1 never records acceptance of the current v2.
  v_sha := private.notice_digest(p_notice_text);
  v_prev := private.begin_command(c.organization_id, p_operation_key, 'privacy.acknowledge_viewed',
    jsonb_build_object('c', p_clinic_id, 'v', p_notice_version, 'sha256', v_sha));
  if v_prev is not null then return v_prev; end if;
  if p_notice_version is null or p_notice_text is null
     or p_notice_version is distinct from c.operational_policy -> 'privacyNotice' ->> 'version'
     or p_notice_text is distinct from c.operational_policy -> 'privacyNotice' ->> 'text' then
    raise exception 'The privacy notice changed. Refresh and read the current notice before accepting it.' using errcode = 'CV409';
  end if;
  if not private.notice_acknowledged(c.id) then
    select id into v_g from public.guardians where organization_id = c.organization_id and profile_id = auth.uid();
    insert into public.privacy_records (organization_id, guardian_id, clinic_id, profile_id, purpose, record_type, notice_version, notice_sha256, decision, created_by)
    values (c.organization_id, v_g, c.id, auth.uid(), 'care_records', 'notice_acknowledgement', p_notice_version, v_sha, 'acknowledged', auth.uid());
    perform private.audit(c.organization_id, 'guardian', 'privacy.acknowledged', 'clinic', p_clinic_id, null,
      jsonb_build_object('version', p_notice_version, 'sha256', v_sha), null);
  end if;
  return private.finish_command(c.organization_id, p_operation_key, jsonb_build_object('version', p_notice_version, 'acknowledged', true));
end $$;
revoke all on function public.acknowledge_clinic_privacy_notice(uuid, uuid, text, text) from public, anon;
grant execute on function public.acknowledge_clinic_privacy_notice(uuid, uuid, text, text) to authenticated;
-- END 0044_privacy_acknowledgement.sql

-- =====================================================================================================================
-- BEGIN 0045_stock_count_serialization.sql  sha256=cbb7fa42ac5326feeda22f895805a042b6db77bc3db7e85341dd383a2001edf8
-- =====================================================================================================================
-- Serialize physical counts against the current balance, including the first count for a location and lot.
-- CREATE OR REPLACE retains the commands' existing authenticated-only grants.
create or replace function public.propose_stock_adjustment(p_operation_key uuid, p_clinic_id uuid, p_location_id uuid, p_lot_id uuid, p_observed numeric, p_count_reference text, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid := private.inventory_org(p_clinic_id); v_prev jsonb; v_book numeric; v_delta numeric; v_thr numeric; v_case uuid; v_tx uuid; v_can_approve boolean;
begin
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.adjust', jsonb_build_object('c', p_clinic_id, 'loc', p_location_id, 'lot', p_lot_id, 'obs', p_observed, 'ref', p_count_reference, 'r', p_reason));
  if v_prev is not null then return v_prev; end if;
  if p_observed is null or p_observed < 0 then raise exception 'observed count must be zero or more' using errcode = 'CV422'; end if;
  if p_count_reference is null or length(btrim(p_count_reference)) = 0 or p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'count reference and reason are required' using errcode = 'CV422'; end if;
  if not exists (select 1 from public.stock_locations where id = p_location_id and organization_id = v_org and clinic_id = p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  if not exists (select 1 from public.stock_locations where id = p_location_id and status = 'active') then
    raise exception 'the stock location is closed' using errcode = 'CV409';
  end if;
  if not exists (select 1 from public.vaccine_lots where id = p_lot_id and organization_id = v_org) then
    raise exception 'not found' using errcode = 'CV404';
  end if;
  -- A first count needs a row to lock too; concurrent postings wait on this same balance.
  insert into public.stock_balances (organization_id, location_id, lot_id, on_hand)
  values (v_org, p_location_id, p_lot_id, 0) on conflict (location_id, lot_id) do nothing;
  select coalesce(on_hand, 0) into v_book from public.stock_balances where location_id = p_location_id and lot_id = p_lot_id for update;
  v_book := coalesce(v_book, 0);
  v_delta := p_observed - v_book;
  if v_delta = 0 then return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'no_difference', 'book', v_book)); end if;
  v_thr := coalesce((select (value)::text::numeric from private.settings where key = 'adjustment_auto_approve_units'), 0);
  v_can_approve := private.has_capability(p_clinic_id, 'inventory.approve');
  if abs(v_delta) <= v_thr or v_can_approve then
    insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, approved_by, operation_id, created_by)
    values (v_org, p_clinic_id, 'adjustment', p_count_reference, p_reason, case when v_can_approve then auth.uid() end, p_operation_key, auth.uid()) returning id into v_tx;
    perform private.post_movement(v_org, v_tx, p_location_id, p_lot_id, v_delta, 'adjust:' || p_operation_key);
    perform private.audit(v_org, 'inventory.manage', 'stock.adjusted', 'vaccine_lot', p_lot_id, jsonb_build_object('book', v_book), jsonb_build_object('observed', p_observed, 'delta', v_delta), p_reason);
    return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'posted', 'delta', v_delta, 'transactionId', v_tx));
  end if;
  insert into public.record_review_cases (organization_id, clinic_id, kind, reason, evidence, created_by, updated_by)
  values (v_org, p_clinic_id, 'stock', 'stock count difference awaiting approval',
          jsonb_build_object('locationId', p_location_id, 'lotId', p_lot_id, 'book', v_book, 'observed', p_observed, 'delta', v_delta, 'countReference', p_count_reference, 'reason', p_reason, 'operationKey', p_operation_key),
          auth.uid(), auth.uid()) returning id into v_case;
  perform private.audit(v_org, 'inventory.manage', 'stock.adjustment_proposed', 'review_case', v_case, jsonb_build_object('book', v_book), jsonb_build_object('observed', p_observed), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'pending_approval', 'caseId', v_case, 'delta', v_delta));
end $$;

create or replace function public.approve_stock_adjustment(p_operation_key uuid, p_clinic_id uuid, p_case_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.inventory_org(p_clinic_id, 'inventory.approve'); v_prev jsonb; k public.record_review_cases; v_book numeric; v_tx uuid; v_delta numeric; v_loc uuid; v_lot uuid;
begin
  select * into k from public.record_review_cases where id = p_case_id and organization_id = v_org and clinic_id = p_clinic_id and kind = 'stock' for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'stock.approve_adjustment', jsonb_build_object('c', p_clinic_id, 'case', p_case_id));
  if v_prev is not null then return v_prev; end if;
  if k.status not in ('open','in_review') then raise exception 'case already decided' using errcode = 'CV409'; end if;
  -- Short deliveries and care-without-stock cases are also kind 'stock' but carry no count: they are decided where they came from.
  if k.evidence ->> 'observed' is null or k.evidence ->> 'locationId' is null or k.evidence ->> 'lotId' is null then
    raise exception 'this stock case is not a count adjustment; decide it from the transfer or the visit record it came from' using errcode = 'CV409';
  end if;
  if k.created_by = auth.uid() then raise exception 'the proposer cannot approve their own adjustment' using errcode = 'CV403'; end if;
  v_loc := (k.evidence ->> 'locationId')::uuid; v_lot := (k.evidence ->> 'lotId')::uuid;
  -- Re-derive the delta from the observed count against the CURRENT book balance (stock may have moved since the proposal).
  if not exists (select 1 from public.vaccine_lots where id = v_lot and organization_id = v_org) then
    raise exception 'not found' using errcode = 'CV404';
  end if;
  if not exists (select 1 from public.stock_locations where id = v_loc and organization_id = v_org and clinic_id = p_clinic_id and status = 'active') then
    raise exception 'the stock location is closed or unavailable' using errcode = 'CV409';
  end if;
  -- Materialize an empty balance before locking so simultaneous first approvals cannot double the count.
  insert into public.stock_balances (organization_id, location_id, lot_id, on_hand)
  values (v_org, v_loc, v_lot, 0) on conflict (location_id, lot_id) do nothing;
  select coalesce(on_hand, 0) into v_book from public.stock_balances where location_id = v_loc and lot_id = v_lot for update;
  v_book := coalesce(v_book, 0);
  v_delta := (k.evidence ->> 'observed')::numeric - v_book;
  if v_delta <> 0 then
    insert into public.stock_transactions (organization_id, clinic_id, type, source_reference, reason, approved_by, operation_id, created_by)
    values (v_org, p_clinic_id, 'adjustment', k.evidence ->> 'countReference', k.evidence ->> 'reason', auth.uid(), p_operation_key, k.created_by) returning id into v_tx;
    perform private.post_movement(v_org, v_tx, v_loc, v_lot, v_delta, 'adjust:' || p_operation_key);
  end if;
  update public.record_review_cases set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', 'approved', 'postedDelta', v_delta, 'transactionId', v_tx) where id = k.id;
  perform private.audit(v_org, 'inventory.approve', 'stock.adjustment_approved', 'review_case', k.id, null, jsonb_build_object('delta', v_delta), null);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('status', 'posted', 'delta', v_delta, 'transactionId', v_tx));
end $$;
-- END 0045_stock_count_serialization.sql

-- =====================================================================================================================
-- BEGIN 0046_search_inactive_records.sql  sha256=fffc0b84ee3e0554127b59f3c4b3292b3e9a43974ac30201a3b52d6d35add1aa
-- =====================================================================================================================
-- Keep inactive records discoverable so staff can read their history and reactivate a returning child's existing record.
-- Rank the full matching set before applying the existing result limit.
create or replace function public.staff_search_children(p_clinic_id uuid, p_query text, p_dob date default null, p_limit integer default 20)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_q text := private.norm_name(p_query); v_like text; v_res jsonb; v_lim int := least(greatest(coalesce(p_limit, 20), 1), 25);
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'forbidden' using errcode = 'CV403'; end if;
  perform private.require_capability(p_clinic_id, 'child.search');
  if length(v_q) < 2 and p_dob is null then raise exception 'query too short' using errcode = 'CV422'; end if;
  v_like := '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  select coalesce(jsonb_agg(x order by (x ->> 'rank')::real desc, x ->> 'displayName'), '[]'::jsonb) into v_res from (
    select jsonb_build_object('childId', c.id, 'displayName', c.display_name, 'localRecordNo', c.local_record_no, 'dob', c.dob,
                              'dobPrecision', c.birth_date_precision, 'recordStatus', c.record_status,
                              'rank', greatest(extensions.similarity(c.search_name, v_q), case when c.search_name like v_like then 0.9 else 0 end,
                                               case when upper(btrim(p_query)) = c.local_record_no then 1 else 0 end)) x
      from public.children c
     where c.record_status in ('provisional','active','inactive')
       and exists (select 1 from public.child_clinic_enrollments e where e.child_id = c.id and e.clinic_id = p_clinic_id and e.status in ('pending','active'))
       and (p_dob is null or c.dob = p_dob)
       and (length(v_q) < 2 or c.search_name like v_like or extensions.similarity(c.search_name, v_q) >= 0.3 or upper(btrim(p_query)) = c.local_record_no)
     order by greatest(extensions.similarity(c.search_name, v_q), case when c.search_name like v_like then 0.9 else 0 end,
                       case when upper(btrim(p_query)) = c.local_record_no then 1 else 0 end) desc, c.display_name, c.id
     limit v_lim) s;
  perform private.audit(v_org, 'child.search', 'child.search', 'clinic', p_clinic_id, null,
                        jsonb_build_object('queryLength', length(v_q), 'withDob', p_dob is not null, 'results', jsonb_array_length(v_res)), null);
  return v_res;
end $$;
-- END 0046_search_inactive_records.sql

-- =====================================================================================================================
-- BEGIN 0047_chained_correction_stock.sql  sha256=a3b0a7b56e5836812bb70b163b9d1575d755af3e27114faa5558f3dc4824b8b4
-- =====================================================================================================================
-- Reverse the outstanding stock issue for this event, never an issue an earlier correction already reversed.
-- CREATE OR REPLACE retains existing grants; all validation, event locking and receipt behavior is preserved.
create or replace function public.approve_correction(p_operation_key uuid, p_clinic_id uuid, p_case_id uuid, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_prev jsonb; k public.record_review_cases; cur public.vaccination_revisions; v_kind text; v_prop jsonb; v_new_lot uuid; v_new_loc uuid; v_old_tx public.stock_transactions; v_old_mv public.stock_movements;
  v_lot public.vaccine_lots; v_child uuid := null; v_tx uuid; v_rev uuid; v_on date; v_at timestamptz; v_route text; v_site text; v_status text; v_stock jsonb := '[]'::jsonb; v_tz text; v_eval1 jsonb; v_eval2 jsonb;
  v_prod uuid; v_effect text; v_new_child uuid; v_ev_status text;
begin
  select organization_id, timezone into v_org, v_tz from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'correction.approve');
  select * into k from public.record_review_cases where id = p_case_id and organization_id = v_org and clinic_id = p_clinic_id and kind = 'correction' for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'correction.approve', jsonb_build_object('c', p_clinic_id, 'case', p_case_id, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  if k.status not in ('open','in_review') then raise exception 'already decided' using errcode = 'CV409'; end if;
  if k.created_by = auth.uid() then raise exception 'the proposer cannot approve their own correction' using errcode = 'CV403'; end if;
  perform 1 from public.vaccination_events where id = k.vaccination_event_id for update;
  select * into cur from private.current_revisions where event_id = k.vaccination_event_id;
  if cur.revision_no <> (k.evidence ->> 'baseRevision')::int then raise exception 'the record changed since this correction was requested; request it again' using errcode = 'CV409'; end if;
  v_kind := k.evidence ->> 'kind'; v_prop := k.evidence -> 'proposal';
  v_on := cur.administered_on; v_at := cur.administered_at; v_route := cur.route; v_site := cur.site; v_prod := cur.product_id; v_new_lot := cur.lot_id; v_status := cur.verification_status; v_ev_status := cur.event_status;
  v_new_child := cur.child_id;

  if v_kind = 'correct_details' then
    if nullif(v_prop ->> 'administeredAt', '') is not null then v_at := (v_prop ->> 'administeredAt')::timestamptz; v_on := (v_at at time zone v_tz)::date; end if;
    if v_at > now() + interval '5 minutes' then raise exception 'the administration time cannot be in the future' using errcode = 'CV422'; end if;
    if v_prop ? 'route' then v_route := nullif(left(btrim(v_prop ->> 'route'), 40), ''); end if;
    if v_prop ? 'site' then v_site := nullif(left(btrim(v_prop ->> 'site'), 40), ''); end if;
    if nullif(v_prop ->> 'lotId', '') is not null and (v_prop ->> 'lotId')::uuid <> cur.lot_id then
      -- The physical fact changed (a different vial was used): compensate the ledger, do not rewrite it (BP19).
      select * into v_lot from public.vaccine_lots where id = (v_prop ->> 'lotId')::uuid and organization_id = v_org;
      if v_lot.id is null then raise exception 'unknown lot' using errcode = 'CV422'; end if;
      v_new_loc := nullif(v_prop ->> 'locationId', '')::uuid;
      if v_new_loc is null then raise exception 'name the stock location of the correct lot' using errcode = 'CV422'; end if;
      select t.* into v_old_tx from public.stock_transactions t where t.event_id = cur.event_id and t.type = 'issue_administration'
        and not exists (select 1 from public.stock_transactions reversed where reversed.reverses_id = t.id)
        order by t.created_at, t.id limit 1;
      if v_old_tx.id is not null then
        select m.* into v_old_mv from public.stock_movements m where m.transaction_id = v_old_tx.id limit 1;
        insert into public.stock_transactions (organization_id, clinic_id, type, event_id, reason, approved_by, operation_id, reverses_id, created_by)
        values (v_org, p_clinic_id, 'reversal', cur.event_id, 'correction: wrong lot recorded', auth.uid(), p_operation_key, v_old_tx.id, auth.uid()) returning id into v_tx;
        perform private.post_movement(v_org, v_tx, v_old_mv.location_id, v_old_mv.lot_id, -v_old_mv.quantity_delta, 'corr-rev:' || p_operation_key);
        v_stock := v_stock || jsonb_build_object('reversed', v_old_tx.id);
      end if;
      v_tx := private.issue_for_administration(v_org, p_clinic_id, v_new_loc, v_lot.id, 1, cur.event_id, p_operation_key); -- refuses if the correct lot cannot supply it
      v_stock := v_stock || jsonb_build_object('issued', v_tx);
      v_new_lot := v_lot.id; v_prod := v_lot.product_id;
    end if;
  elsif v_kind = 'reattribute_child' then
    v_new_child := private.canonical_child((v_prop ->> 'toChildId')::uuid);
    if not private.child_in_clinic(v_new_child, p_clinic_id) or v_new_child = cur.child_id then raise exception 'the correct child must be a different child enrolled at this clinic' using errcode = 'CV422'; end if;
  else -- void_duplicate
    v_effect := v_prop ->> 'stockEffect';
    v_ev_status := 'voided';
    select t.* into v_old_tx from public.stock_transactions t where t.event_id = cur.event_id and t.type = 'issue_administration'
        and not exists (select 1 from public.stock_transactions reversed where reversed.reverses_id = t.id)
        order by t.created_at, t.id limit 1;
    if v_old_tx.id is not null and v_effect in ('return_to_stock','wastage') then
      select m.* into v_old_mv from public.stock_movements m where m.transaction_id = v_old_tx.id limit 1;
      insert into public.stock_transactions (organization_id, clinic_id, type, event_id, reason, approved_by, operation_id, reverses_id, created_by)
      values (v_org, p_clinic_id, 'reversal', cur.event_id, 'correction: duplicate record voided', auth.uid(), p_operation_key, v_old_tx.id, auth.uid()) returning id into v_tx;
      perform private.post_movement(v_org, v_tx, v_old_mv.location_id, v_old_mv.lot_id, -v_old_mv.quantity_delta, 'void-rev:' || p_operation_key);
      v_stock := v_stock || jsonb_build_object('reversed', v_old_tx.id);
      if v_effect = 'wastage' then
        -- The vial was physically used or spoiled: it is NOT returned to usable stock, it is reclassified as wastage.
        insert into public.stock_transactions (organization_id, clinic_id, type, event_id, reason, approved_by, operation_id, created_by)
        values (v_org, p_clinic_id, 'wastage', cur.event_id, 'duplicate record: dose physically lost', auth.uid(), p_operation_key, auth.uid()) returning id into v_tx;
        perform private.post_movement(v_org, v_tx, v_old_mv.location_id, v_old_mv.lot_id, v_old_mv.quantity_delta, 'void-waste:' || p_operation_key);
        v_stock := v_stock || jsonb_build_object('wastage', v_tx);
      end if;
    end if;
  end if;

  insert into public.vaccination_revisions (organization_id, event_id, revision_no, child_id, product_id, reported_product_text, administered_on, administered_at, date_precision, lot_id, reported_lot, expiry_snapshot,
                                             quantity, unit, route, site, administered_by, external_vaccinator, clinic_id, source, verification_status, event_status, approved_by, signed_at, reason, created_by)
  values (v_org, cur.event_id, cur.revision_no + 1, v_new_child, v_prod, cur.reported_product_text, v_on, v_at, cur.date_precision, v_new_lot,
          cur.reported_lot, coalesce((select expires_on from public.vaccine_lots where id = v_new_lot), cur.expiry_snapshot), cur.quantity, cur.unit, v_route, v_site, cur.administered_by, cur.external_vaccinator, cur.clinic_id,
          cur.source, cur.verification_status, v_ev_status, auth.uid(), now(), coalesce(p_note, k.reason), auth.uid()) returning id into v_rev;

  update public.record_review_cases set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', 'approved', 'newRevision', cur.revision_no + 1, 'stock', v_stock, 'note', p_note) where id = k.id;
  -- Recalculate downstream credit for every child whose facts changed (T16); certificates are reviewed in the certificate module.
  v_eval1 := private.compute_child_schedule(private.canonical_child(cur.child_id), private.local_today(p_clinic_id), true);
  if v_new_child <> cur.child_id then v_eval2 := private.compute_child_schedule(v_new_child, private.local_today(p_clinic_id), true); end if;
  perform private.enqueue(v_org, 'certificate.review', 'vaccination_event', cur.event_id, 'cert-review:' || v_rev::text, jsonb_build_object('event', cur.event_id, 'revision', cur.revision_no + 1));
  perform private.audit(v_org, 'correction.approve', 'correction.approved', 'vaccination_event', cur.event_id,
                        jsonb_build_object('revision', cur.revision_no, 'lot', cur.lot_id, 'child', cur.child_id), jsonb_build_object('revision', cur.revision_no + 1, 'lot', v_new_lot, 'child', v_new_child, 'kind', v_kind, 'stock', v_stock), coalesce(p_note, k.reason));
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('eventId', cur.event_id, 'revisionNo', cur.revision_no + 1, 'kind', v_kind, 'stock', v_stock));
end $$;
-- END 0047_chained_correction_stock.sql

-- =====================================================================================================================
-- BEGIN 0048_guardian_merge_integrity.sql  sha256=3e676ba0872d08ad717fb9638a160ed7cd498c161d9663e365632a1271af4c1b
-- =====================================================================================================================
-- Keep verified guardian access when a merge collides with an unverified link.
-- Only the shared implementation changes; the scheduling/hold wrapper and existing ACLs remain.
create or replace function public.merge_children_prev(p_operation_key uuid, p_clinic_id uuid, p_survivor uuid, p_duplicate uuid, p_reason text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_prev jsonb; s public.children; d public.children; rel record; existing public.guardian_child_relationships;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'review.resolve');
  if p_survivor = p_duplicate then raise exception 'cannot merge a record into itself' using errcode = 'CV422'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'reason required' using errcode = 'CV422'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'child.merge', jsonb_build_object('clinic', p_clinic_id, 's', p_survivor, 'd', p_duplicate, 'reason', p_reason));
  if v_prev is not null then return v_prev; end if;
  -- Lock in a stable order to avoid deadlocks between concurrent merges.
  perform 1 from public.children where id in (p_survivor, p_duplicate) order by id for update;
  select * into s from public.children where id = p_survivor and organization_id = v_org;
  select * into d from public.children where id = p_duplicate and organization_id = v_org;
  if s.id is null or d.id is null or not private.child_in_clinic(s.id, p_clinic_id) or not private.child_in_clinic(d.id, p_clinic_id) then
    raise exception 'not found' using errcode = 'CV404';
  end if;
  if s.record_status = 'merged' or d.record_status = 'merged' then raise exception 'record already merged' using errcode = 'CV409'; end if;

  -- Retain current verified access over an unverified or expired link; preserve a survivor's suspension.
  for rel in select * from public.guardian_child_relationships where child_id = d.id and status in ('provisional','active','suspended') for update loop
    select * into existing from public.guardian_child_relationships x
     where x.child_id = s.id and x.guardian_id = rel.guardian_id and x.status in ('provisional','active','suspended') for update;
    if existing.id is not null and (existing.status = 'provisional'
       or (existing.status = 'active' and existing.ends_at <= now())) and rel.status = 'active'
       and (rel.ends_at is null or rel.ends_at > now()) then
      -- Retain the verified row and its evidence; a suspended survivor still requires explicit restoration.
      update public.guardian_child_relationships set status = 'revoked', ends_at = now(), updated_by = auth.uid() where id = existing.id;
      update public.guardian_child_relationships set child_id = s.id, updated_by = auth.uid() where id = rel.id;
    elsif existing.id is not null then
      update public.guardian_child_relationships set status = 'revoked', ends_at = now(), updated_by = auth.uid() where id = rel.id;
    else
      update public.guardian_child_relationships set child_id = s.id, updated_by = auth.uid() where id = rel.id;
    end if;
  end loop;
  -- Enrollments: survivor inherits the clinic enrollment if missing; the duplicate's are closed.
  insert into public.child_clinic_enrollments (organization_id, child_id, clinic_id, status, is_primary, access_scope, basis, created_by, updated_by)
  select v_org, s.id, e.clinic_id, case when s.record_status = 'active' then 'active' else 'pending' end, false,
         case when s.record_status = 'active' then 'care' else 'review_only' end, 'merge', auth.uid(), auth.uid()
    from public.child_clinic_enrollments e
   where e.child_id = d.id and e.status in ('pending','active')
     and not exists (select 1 from public.child_clinic_enrollments y where y.child_id = s.id and y.clinic_id = e.clinic_id and y.status in ('pending','active'));
  update public.child_clinic_enrollments set status = 'closed', is_primary = false, ends_at = now(), updated_by = auth.uid()
   where child_id = d.id and status in ('pending','active');
  update public.qr_passes set status = 'revoked', revoked_at = now(), updated_by = auth.uid() where child_id = d.id and status = 'active';
  update public.children set record_status = 'merged', merged_into_id = s.id, updated_by = auth.uid() where id = d.id;
  update public.record_review_cases set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', 'merged', 'survivor', s.id, 'duplicate', d.id)
   where kind = 'duplicate' and status in ('open','in_review') and least(child_id, candidate_child_id) = least(s.id, d.id) and greatest(child_id, candidate_child_id) = greatest(s.id, d.id);
  perform private.audit(v_org, 'review.resolve', 'child.merged', 'child', d.id,
                        jsonb_build_object('localRecordNo', d.local_record_no), jsonb_build_object('mergedInto', s.id, 'survivorRecordNo', s.local_record_no), p_reason);
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('survivorId', s.id, 'mergedId', d.id));
end $$;
-- END 0048_guardian_merge_integrity.sql

-- =====================================================================================================================
-- BEGIN 0049_correction_unknown_lot.sql  sha256=b4d44f401e597e4522c032126e5638c3399c83751cb0e91086478a5d728a640d
-- =====================================================================================================================
-- A newly identified lot differs from an unknown lot: validate, record and issue it atomically.
-- Preserve the full current correction command and its existing authenticated-only grants.
-- Reverse the outstanding stock issue for this event, never an issue an earlier correction already reversed.
-- CREATE OR REPLACE retains existing grants; all validation, event locking and receipt behavior is preserved.
create or replace function public.approve_correction(p_operation_key uuid, p_clinic_id uuid, p_case_id uuid, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_org uuid; v_prev jsonb; k public.record_review_cases; cur public.vaccination_revisions; v_kind text; v_prop jsonb; v_new_lot uuid; v_new_loc uuid; v_old_tx public.stock_transactions; v_old_mv public.stock_movements;
  v_lot public.vaccine_lots; v_child uuid := null; v_tx uuid; v_rev uuid; v_on date; v_at timestamptz; v_route text; v_site text; v_status text; v_stock jsonb := '[]'::jsonb; v_tz text; v_eval1 jsonb; v_eval2 jsonb;
  v_prod uuid; v_effect text; v_new_child uuid; v_ev_status text;
begin
  select organization_id, timezone into v_org, v_tz from public.clinics where id = p_clinic_id;
  if v_org is null then raise exception 'not found' using errcode = 'CV404'; end if;
  perform private.require_capability(p_clinic_id, 'correction.approve');
  select * into k from public.record_review_cases where id = p_case_id and organization_id = v_org and clinic_id = p_clinic_id and kind = 'correction' for update;
  if not found then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'correction.approve', jsonb_build_object('c', p_clinic_id, 'case', p_case_id, 'n', p_note));
  if v_prev is not null then return v_prev; end if;
  if k.status not in ('open','in_review') then raise exception 'already decided' using errcode = 'CV409'; end if;
  if k.created_by = auth.uid() then raise exception 'the proposer cannot approve their own correction' using errcode = 'CV403'; end if;
  perform 1 from public.vaccination_events where id = k.vaccination_event_id for update;
  select * into cur from private.current_revisions where event_id = k.vaccination_event_id;
  if cur.revision_no <> (k.evidence ->> 'baseRevision')::int then raise exception 'the record changed since this correction was requested; request it again' using errcode = 'CV409'; end if;
  v_kind := k.evidence ->> 'kind'; v_prop := k.evidence -> 'proposal';
  v_on := cur.administered_on; v_at := cur.administered_at; v_route := cur.route; v_site := cur.site; v_prod := cur.product_id; v_new_lot := cur.lot_id; v_status := cur.verification_status; v_ev_status := cur.event_status;
  v_new_child := cur.child_id;

  if v_kind = 'correct_details' then
    if nullif(v_prop ->> 'administeredAt', '') is not null then v_at := (v_prop ->> 'administeredAt')::timestamptz; v_on := (v_at at time zone v_tz)::date; end if;
    if v_at > now() + interval '5 minutes' then raise exception 'the administration time cannot be in the future' using errcode = 'CV422'; end if;
    if v_prop ? 'route' then v_route := nullif(left(btrim(v_prop ->> 'route'), 40), ''); end if;
    if v_prop ? 'site' then v_site := nullif(left(btrim(v_prop ->> 'site'), 40), ''); end if;
    if nullif(v_prop ->> 'lotId', '') is not null and (v_prop ->> 'lotId')::uuid is distinct from cur.lot_id then
      -- The physical fact changed (a different vial was used): compensate the ledger, do not rewrite it (BP19).
      select * into v_lot from public.vaccine_lots where id = (v_prop ->> 'lotId')::uuid and organization_id = v_org;
      if v_lot.id is null then raise exception 'unknown lot' using errcode = 'CV422'; end if;
      v_new_loc := nullif(v_prop ->> 'locationId', '')::uuid;
      if v_new_loc is null then raise exception 'name the stock location of the correct lot' using errcode = 'CV422'; end if;
      select t.* into v_old_tx from public.stock_transactions t where t.event_id = cur.event_id and t.type = 'issue_administration'
        and not exists (select 1 from public.stock_transactions reversed where reversed.reverses_id = t.id)
        order by t.created_at, t.id limit 1;
      if v_old_tx.id is not null then
        select m.* into v_old_mv from public.stock_movements m where m.transaction_id = v_old_tx.id limit 1;
        insert into public.stock_transactions (organization_id, clinic_id, type, event_id, reason, approved_by, operation_id, reverses_id, created_by)
        values (v_org, p_clinic_id, 'reversal', cur.event_id, 'correction: wrong lot recorded', auth.uid(), p_operation_key, v_old_tx.id, auth.uid()) returning id into v_tx;
        perform private.post_movement(v_org, v_tx, v_old_mv.location_id, v_old_mv.lot_id, -v_old_mv.quantity_delta, 'corr-rev:' || p_operation_key);
        v_stock := v_stock || jsonb_build_object('reversed', v_old_tx.id);
      end if;
      v_tx := private.issue_for_administration(v_org, p_clinic_id, v_new_loc, v_lot.id, 1, cur.event_id, p_operation_key); -- refuses if the correct lot cannot supply it
      v_stock := v_stock || jsonb_build_object('issued', v_tx);
      v_new_lot := v_lot.id; v_prod := v_lot.product_id;
    end if;
  elsif v_kind = 'reattribute_child' then
    v_new_child := private.canonical_child((v_prop ->> 'toChildId')::uuid);
    if not private.child_in_clinic(v_new_child, p_clinic_id) or v_new_child = cur.child_id then raise exception 'the correct child must be a different child enrolled at this clinic' using errcode = 'CV422'; end if;
  else -- void_duplicate
    v_effect := v_prop ->> 'stockEffect';
    v_ev_status := 'voided';
    select t.* into v_old_tx from public.stock_transactions t where t.event_id = cur.event_id and t.type = 'issue_administration'
        and not exists (select 1 from public.stock_transactions reversed where reversed.reverses_id = t.id)
        order by t.created_at, t.id limit 1;
    if v_old_tx.id is not null and v_effect in ('return_to_stock','wastage') then
      select m.* into v_old_mv from public.stock_movements m where m.transaction_id = v_old_tx.id limit 1;
      insert into public.stock_transactions (organization_id, clinic_id, type, event_id, reason, approved_by, operation_id, reverses_id, created_by)
      values (v_org, p_clinic_id, 'reversal', cur.event_id, 'correction: duplicate record voided', auth.uid(), p_operation_key, v_old_tx.id, auth.uid()) returning id into v_tx;
      perform private.post_movement(v_org, v_tx, v_old_mv.location_id, v_old_mv.lot_id, -v_old_mv.quantity_delta, 'void-rev:' || p_operation_key);
      v_stock := v_stock || jsonb_build_object('reversed', v_old_tx.id);
      if v_effect = 'wastage' then
        -- The vial was physically used or spoiled: it is NOT returned to usable stock, it is reclassified as wastage.
        insert into public.stock_transactions (organization_id, clinic_id, type, event_id, reason, approved_by, operation_id, created_by)
        values (v_org, p_clinic_id, 'wastage', cur.event_id, 'duplicate record: dose physically lost', auth.uid(), p_operation_key, auth.uid()) returning id into v_tx;
        perform private.post_movement(v_org, v_tx, v_old_mv.location_id, v_old_mv.lot_id, v_old_mv.quantity_delta, 'void-waste:' || p_operation_key);
        v_stock := v_stock || jsonb_build_object('wastage', v_tx);
      end if;
    end if;
  end if;

  insert into public.vaccination_revisions (organization_id, event_id, revision_no, child_id, product_id, reported_product_text, administered_on, administered_at, date_precision, lot_id, reported_lot, expiry_snapshot,
                                             quantity, unit, route, site, administered_by, external_vaccinator, clinic_id, source, verification_status, event_status, approved_by, signed_at, reason, created_by)
  values (v_org, cur.event_id, cur.revision_no + 1, v_new_child, v_prod, cur.reported_product_text, v_on, v_at, cur.date_precision, v_new_lot,
          cur.reported_lot, coalesce((select expires_on from public.vaccine_lots where id = v_new_lot), cur.expiry_snapshot), cur.quantity, cur.unit, v_route, v_site, cur.administered_by, cur.external_vaccinator, cur.clinic_id,
          cur.source, cur.verification_status, v_ev_status, auth.uid(), now(), coalesce(p_note, k.reason), auth.uid()) returning id into v_rev;

  update public.record_review_cases set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), updated_by = auth.uid(),
         resolution = jsonb_build_object('decision', 'approved', 'newRevision', cur.revision_no + 1, 'stock', v_stock, 'note', p_note) where id = k.id;
  -- Recalculate downstream credit for every child whose facts changed (T16); certificates are reviewed in the certificate module.
  v_eval1 := private.compute_child_schedule(private.canonical_child(cur.child_id), private.local_today(p_clinic_id), true);
  if v_new_child <> cur.child_id then v_eval2 := private.compute_child_schedule(v_new_child, private.local_today(p_clinic_id), true); end if;
  perform private.enqueue(v_org, 'certificate.review', 'vaccination_event', cur.event_id, 'cert-review:' || v_rev::text, jsonb_build_object('event', cur.event_id, 'revision', cur.revision_no + 1));
  perform private.audit(v_org, 'correction.approve', 'correction.approved', 'vaccination_event', cur.event_id,
                        jsonb_build_object('revision', cur.revision_no, 'lot', cur.lot_id, 'child', cur.child_id), jsonb_build_object('revision', cur.revision_no + 1, 'lot', v_new_lot, 'child', v_new_child, 'kind', v_kind, 'stock', v_stock), coalesce(p_note, k.reason));
  return private.finish_command(v_org, p_operation_key, jsonb_build_object('eventId', cur.event_id, 'revisionNo', cur.revision_no + 1, 'kind', v_kind, 'stock', v_stock));
end $$;

-- END 0049_correction_unknown_lot.sql

-- =====================================================================================================================
-- BEGIN 0050_staff_child_notes.sql  sha256=93588adaaf7c4f47566dc1c68b35cec0f74c3eba3d2082e28658f41f83491a23
-- =====================================================================================================================
-- Scoped staff observations for a child. Notes are append-only; corrections are new notes, preserving authorship and audit history.
create table public.child_staff_notes (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id),
  clinic_id uuid not null references public.clinics(id),
  child_id uuid not null references public.children(id),
  event_id uuid references public.vaccination_events(id),
  category text not null check (category in ('post_vaccination','follow_up','intake','operational')),
  note text not null check (char_length(btrim(note)) between 3 and 1000),
  family_visible boolean not null default true,
  created_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now()
);
create index child_staff_notes_child_idx on public.child_staff_notes (child_id, created_at desc);
alter table public.child_staff_notes enable row level security;
revoke all on public.child_staff_notes from anon, authenticated;

create function public.add_child_note(p_operation_key uuid, p_clinic_id uuid, p_child_id uuid, p_category text, p_note text, p_family_visible boolean default true, p_event_id uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_id uuid; v_prev jsonb; v_cap text;
begin
  select organization_id into v_org from public.clinics where id = p_clinic_id;
  if v_org is null or not private.child_in_clinic(p_child_id, p_clinic_id) then raise exception 'not found' using errcode = 'CV404'; end if;
  v_cap := case p_category when 'post_vaccination' then 'vaccination.record' when 'follow_up' then 'bhw.followup' when 'intake' then 'child.register' else 'admin.users' end;
  if p_category = 'follow_up' and private.has_capability(p_clinic_id, 'vaccination.record') then v_cap := 'vaccination.record'; end if;
  perform private.require_capability(p_clinic_id, v_cap);
  if p_category not in ('post_vaccination','follow_up','intake','operational') or char_length(btrim(coalesce(p_note,''))) not between 3 and 1000 then raise exception 'check the note details' using errcode = 'CV422'; end if;
  if p_event_id is not null and not exists (select 1 from public.vaccination_events where id=p_event_id and child_id=p_child_id and organization_id=v_org) then raise exception 'not found' using errcode = 'CV404'; end if;
  v_prev := private.begin_command(v_org, p_operation_key, 'child.note.add', jsonb_build_object('clinic',p_clinic_id,'child',p_child_id,'category',p_category,'note',btrim(p_note),'visible',p_family_visible,'event',p_event_id));
  if v_prev is not null then return v_prev; end if;
  insert into public.child_staff_notes(organization_id,clinic_id,child_id,event_id,category,note,family_visible,created_by)
  values(v_org,p_clinic_id,p_child_id,p_event_id,p_category,btrim(p_note),p_family_visible,auth.uid()) returning id into v_id;
  perform private.audit(v_org,v_cap,'child.note_added','child_staff_note',v_id,null,jsonb_build_object('childId',p_child_id,'category',p_category,'familyVisible',p_family_visible),null);
  return private.finish_command(v_org,p_operation_key,jsonb_build_object('noteId',v_id));
end $$;

create function public.list_child_notes(p_clinic_id uuid, p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_result jsonb;
begin
  select organization_id into v_org from public.clinics where id=p_clinic_id;
  if v_org is null or not private.child_in_clinic(p_child_id,p_clinic_id) then raise exception 'not found' using errcode='CV404'; end if;
  if not (private.has_capability(p_clinic_id,'child.search') or private.has_capability(p_clinic_id,'bhw.followup')) then raise exception 'forbidden' using errcode='CV403'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('noteId',n.id,'category',n.category,'note',n.note,'familyVisible',n.family_visible,'eventId',n.event_id,'createdAt',n.created_at,'authorName',p.display_name) order by n.created_at desc),'[]'::jsonb)
  into v_result from public.child_staff_notes n join public.profiles p on p.id=n.created_by where n.organization_id=v_org and n.clinic_id=p_clinic_id and n.child_id=p_child_id;
  return v_result;
end $$;

create function public.guardian_child_notes(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_result jsonb;
begin
  if not private.guardian_can_read_child(p_child_id) then raise exception 'not found' using errcode='CV404'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('noteId',n.id,'category',n.category,'note',n.note,'createdAt',n.created_at,'authorName',p.display_name,'clinicName',c.name) order by n.created_at desc),'[]'::jsonb)
  into v_result from public.child_staff_notes n join public.profiles p on p.id=n.created_by join public.clinics c on c.id=n.clinic_id where n.child_id=p_child_id and n.family_visible;
  return v_result;
end $$;

revoke all on function public.add_child_note(uuid,uuid,uuid,text,text,boolean,uuid), public.list_child_notes(uuid,uuid), public.guardian_child_notes(uuid) from public, anon, authenticated;
grant execute on function public.add_child_note(uuid,uuid,uuid,text,text,boolean,uuid), public.list_child_notes(uuid,uuid), public.guardian_child_notes(uuid) to authenticated;
-- END 0050_staff_child_notes.sql

-- =====================================================================================================================
-- BEGIN 0051_card_submissions.sql  sha256=268a7ef61cb928e6aaca3166b7479fd337a55c2ecf0d0b64d9d31a1cda9df176
-- =====================================================================================================================
-- Family card drafts remain separate from approved clinical history, including before guardian verification.
create table public.card_submissions (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id),
  clinic_id uuid not null references public.clinics(id),
  child_id uuid not null references public.children(id),
  submitted_by uuid not null references public.profiles(id),
  rows jsonb not null check (jsonb_typeof(rows)='array' and jsonb_array_length(rows) between 1 and 20),
  status text not null default 'pending' check (status in ('pending','changes_requested','approved','rejected','withdrawn')),
  version integer not null default 1,
  decision_note text,
  decided_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index card_submissions_clinic_idx on public.card_submissions(clinic_id,status,created_at);
alter table public.card_submissions enable row level security;
revoke all on public.card_submissions from anon,authenticated;

create function public.submit_card_record(p_operation_key uuid,p_child_id uuid,p_rows jsonb,p_submission_id uuid default null,p_expected_version integer default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_org uuid; v_clinic uuid; v_prev jsonb; v_id uuid; v_row jsonb; v_old public.card_submissions;
begin
  if not private.guardian_can_read_child(p_child_id) then raise exception 'not found' using errcode='CV404'; end if;
  select organization_id into v_org from public.children where id=p_child_id;
  select clinic_id into v_clinic from public.child_clinic_enrollments where child_id=p_child_id and status in ('pending','active') order by is_primary desc,created_at limit 1;
  if v_clinic is null then raise exception 'a clinic is required' using errcode='CV422'; end if;
  if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 20 or octet_length(p_rows::text)>40000 then raise exception 'enter 1 to 20 card rows' using errcode='CV422'; end if;
  for v_row in select value from jsonb_array_elements(p_rows) loop
    if jsonb_typeof(v_row) is distinct from 'object' then raise exception 'invalid card row' using errcode='CV422'; end if;
    perform private.clean_outside_dose(v_row);
    if char_length(coalesce(v_row->>'doseLabel',''))>40 or char_length(coalesce(v_row->>'notes',''))>500 or coalesce(v_row->>'source','manual') not in ('manual','ocr') then raise exception 'invalid card row' using errcode='CV422'; end if;
  end loop;
  v_prev:=private.begin_command(v_org,p_operation_key,'card.submit',jsonb_build_object('child',p_child_id,'rows',p_rows,'submission',p_submission_id,'version',p_expected_version));
  if v_prev is not null then return v_prev; end if;
  if p_submission_id is not null then
    select * into v_old from public.card_submissions where id=p_submission_id and child_id=p_child_id and submitted_by=auth.uid() for update;
    if not found then raise exception 'not found' using errcode='CV404'; end if;
    if v_old.status<>'changes_requested' or v_old.version is distinct from p_expected_version then raise exception 'submission changed; reload' using errcode='CV409'; end if;
    update public.card_submissions set rows=p_rows,status='pending',version=version+1,updated_at=now() where id=v_old.id returning id into v_id;
  else
    insert into public.card_submissions(organization_id,clinic_id,child_id,submitted_by,rows) values(v_org,v_clinic,p_child_id,auth.uid(),p_rows) returning id into v_id;
  end if;
  perform private.audit(v_org,'guardian','card.submitted','card_submission',v_id,to_jsonb(v_old),jsonb_build_object('rows',p_rows,'status','pending'),null);
  return private.finish_command(v_org,p_operation_key,jsonb_build_object('submissionId',v_id,'status','pending'));
end $$;

create function public.guardian_list_card_submissions(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
  if not private.guardian_can_read_child(p_child_id) then raise exception 'not found' using errcode='CV404'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('submissionId',s.id,'rows',s.rows,'status',s.status,'version',s.version,'decisionNote',s.decision_note,'createdAt',s.created_at) order by s.created_at desc) from public.card_submissions s where s.child_id=p_child_id and s.submitted_by=auth.uid()),'[]'::jsonb);
end $$;

create function public.staff_list_card_submissions(p_clinic_id uuid,p_child_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
  perform private.require_capability(p_clinic_id,'child.read_clinical');
  if not private.child_in_clinic(p_child_id,p_clinic_id) then raise exception 'not found' using errcode='CV404'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('submissionId',s.id,'rows',s.rows,'status',s.status,'version',s.version,'decisionNote',s.decision_note,'createdAt',s.created_at) order by s.created_at desc) from public.card_submissions s where s.child_id=p_child_id and s.clinic_id=p_clinic_id),'[]'::jsonb);
end $$;

create function public.review_card_submission(p_operation_key uuid,p_clinic_id uuid,p_submission_id uuid,p_decision text,p_note text,p_expected_version integer,p_reviewed_rows jsonb default '[]') returns jsonb
language plpgsql security definer set search_path='' as $$
declare s public.card_submissions; v_prev jsonb; v_row jsonb; v_events jsonb:='[]'; v_result jsonb;
begin
  perform private.require_capability(p_clinic_id,'evidence.verify');
  select * into s from public.card_submissions where id=p_submission_id and clinic_id=p_clinic_id for update;
  if not found or not private.child_in_clinic(s.child_id,p_clinic_id) then raise exception 'not found' using errcode='CV404'; end if;
  v_prev:=private.begin_command(s.organization_id,p_operation_key,'card.review',jsonb_build_object('submission',p_submission_id,'decision',p_decision,'note',p_note,'version',p_expected_version,'rows',p_reviewed_rows));
  if v_prev is not null then return v_prev; end if;
  if s.status<>'pending' or s.version<>p_expected_version then raise exception 'submission changed; reload' using errcode='CV409'; end if;
  if s.submitted_by=auth.uid() then raise exception 'the submitter cannot review their own card' using errcode='CV403'; end if;
  if p_decision not in ('approved','rejected','changes_requested') or char_length(btrim(coalesce(p_note,''))) not between 3 and 500 then raise exception 'choose a decision and write a review note' using errcode='CV422'; end if;
  if p_decision='approved' then
    if jsonb_typeof(p_reviewed_rows) is distinct from 'array' or jsonb_array_length(p_reviewed_rows)<>jsonb_array_length(s.rows) then raise exception 'review every card row' using errcode='CV422'; end if;
    for v_row in select value from jsonb_array_elements(p_reviewed_rows) loop
      v_result:=public.record_outside_dose_staff(gen_random_uuid(),p_clinic_id,s.child_id,v_row||jsonb_build_object('precision','exact'),nullif(v_row->>'productId','')::uuid,true);
      v_events:=v_events||jsonb_build_array(v_result->>'eventId');
    end loop;
  end if;
  update public.card_submissions set status=p_decision,decision_note=btrim(p_note),decided_by=auth.uid(),version=version+1,updated_at=now() where id=s.id;
  perform private.audit(s.organization_id,'evidence.verify','card.reviewed','card_submission',s.id,to_jsonb(s),jsonb_build_object('status',p_decision,'reviewedRows',p_reviewed_rows,'events',v_events),p_note);
  return private.finish_command(s.organization_id,p_operation_key,jsonb_build_object('submissionId',s.id,'status',p_decision,'events',v_events));
end $$;

create function public.withdraw_card_submission(p_operation_key uuid,p_submission_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare s public.card_submissions; v_prev jsonb;
begin
  select * into s from public.card_submissions where id=p_submission_id and submitted_by=auth.uid() for update;
  if not found or not private.guardian_can_read_child(s.child_id) then raise exception 'not found' using errcode='CV404'; end if;
  v_prev:=private.begin_command(s.organization_id,p_operation_key,'card.withdraw',jsonb_build_object('submission',p_submission_id));
  if v_prev is not null then return v_prev; end if;
  if s.status not in ('pending','changes_requested') then raise exception 'already decided' using errcode='CV409'; end if;
  update public.card_submissions set status='withdrawn',version=version+1,updated_at=now() where id=s.id;
  perform private.audit(s.organization_id,'guardian','card.withdrawn','card_submission',s.id,to_jsonb(s),jsonb_build_object('status','withdrawn'),null);
  return private.finish_command(s.organization_id,p_operation_key,jsonb_build_object('status','withdrawn'));
end $$;

revoke all on function public.submit_card_record(uuid,uuid,jsonb,uuid,integer),public.guardian_list_card_submissions(uuid),public.staff_list_card_submissions(uuid,uuid),public.review_card_submission(uuid,uuid,uuid,text,text,integer,jsonb),public.withdraw_card_submission(uuid,uuid) from public,anon,authenticated;
grant execute on function public.submit_card_record(uuid,uuid,jsonb,uuid,integer),public.guardian_list_card_submissions(uuid),public.staff_list_card_submissions(uuid,uuid),public.review_card_submission(uuid,uuid,uuid,text,text,integer,jsonb),public.withdraw_card_submission(uuid,uuid) to authenticated;

-- Fix the prior note function's event-child check: event ownership is represented by current revisions.
create or replace function public.add_child_note(p_operation_key uuid,p_clinic_id uuid,p_child_id uuid,p_category text,p_note text,p_family_visible boolean default true,p_event_id uuid default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_org uuid; v_id uuid; v_prev jsonb; v_cap text;
begin
  select organization_id into v_org from public.clinics where id=p_clinic_id;
  if v_org is null or not private.child_in_clinic(p_child_id,p_clinic_id) then raise exception 'not found' using errcode='CV404'; end if;
  v_cap:=case p_category when 'post_vaccination' then 'vaccination.record' when 'follow_up' then 'bhw.followup' else 'child.register' end;
  if p_category='follow_up' and private.has_capability(p_clinic_id,'vaccination.record') then v_cap:='vaccination.record'; end if;
  perform private.require_capability(p_clinic_id,v_cap);
  if p_category not in ('post_vaccination','follow_up','intake','operational') or char_length(btrim(coalesce(p_note,''))) not between 3 and 1000 or p_family_visible is null then raise exception 'check the note details' using errcode='CV422'; end if;
  if p_event_id is not null and not exists(select 1 from private.current_revisions where event_id=p_event_id and child_id=p_child_id and organization_id=v_org) then raise exception 'not found' using errcode='CV404'; end if;
  v_prev:=private.begin_command(v_org,p_operation_key,'child.note.add',jsonb_build_object('clinic',p_clinic_id,'child',p_child_id,'category',p_category,'note',btrim(p_note),'visible',p_family_visible,'event',p_event_id));
  if v_prev is not null then return v_prev; end if;
  insert into public.child_staff_notes(organization_id,clinic_id,child_id,event_id,category,note,family_visible,created_by) values(v_org,p_clinic_id,p_child_id,p_event_id,p_category,btrim(p_note),p_family_visible,auth.uid()) returning id into v_id;
  perform private.audit(v_org,v_cap,'child.note_added','child_staff_note',v_id,null,jsonb_build_object('childId',p_child_id,'category',p_category,'familyVisible',p_family_visible,'note',btrim(p_note)),null);
  return private.finish_command(v_org,p_operation_key,jsonb_build_object('noteId',v_id));
end $$;
create trigger child_staff_notes_immutable before update or delete on public.child_staff_notes for each row execute function private.forbid_change();
-- END 0051_card_submissions.sql

-- =====================================================================================================================
-- BEGIN 0052_guardian_search_note_access.sql  sha256=ae22e64095992d5cc3fb7b0e7c07e4205f3b3c8a667f6211c6e514546b47b345
-- =====================================================================================================================
create or replace function public.staff_search_children(p_clinic_id uuid,p_query text,p_dob date default null,p_limit integer default 20) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_org uuid; v_q text:=private.norm_name(p_query); v_like text; v_res jsonb; v_lim int:=least(greatest(coalesce(p_limit,20),1),25);
begin
  select organization_id into v_org from public.clinics where id=p_clinic_id;
  if v_org is null then raise exception 'forbidden' using errcode='CV403'; end if;
  perform private.require_capability(p_clinic_id,'child.search');
  if length(v_q)<2 and p_dob is null then raise exception 'query too short' using errcode='CV422'; end if;
  if char_length(coalesce(p_query,''))>200 then raise exception 'query too long' using errcode='CV422'; end if;
  v_like:='%'||replace(replace(replace(v_q,'\','\\'),'%','\%'),'_','\_')||'%';
  select coalesce(jsonb_agg(x order by (x->>'rank')::real desc,x->>'displayName'),'[]'::jsonb) into v_res from (
    select jsonb_build_object('childId',c.id,'displayName',c.display_name,'localRecordNo',c.local_record_no,'dob',c.dob,'dobPrecision',c.birth_date_precision,'recordStatus',c.record_status,
      'rank',greatest(extensions.similarity(c.search_name,v_q),case when c.search_name like v_like then 0.9 else 0 end,case when upper(btrim(p_query))=c.local_record_no then 1 else 0 end,coalesce(g.score,0))) x
    from public.children c
    left join lateral (
      select max(case when private.norm_name(gu.full_name) like v_like then 0.9 when private.has_capability(p_clinic_id,'guardian.verify') and (private.norm_name(coalesce(gu.contact_email,'')) like v_like or private.norm_name(coalesce(gu.contact_phone,'')) like v_like) then 0.8 else 0 end) score
      from public.guardian_child_relationships r join public.guardians gu on gu.id=r.guardian_id and gu.organization_id=c.organization_id
      where r.child_id=c.id and r.status in ('provisional','active') and (r.ends_at is null or r.ends_at>now()) and gu.deleted_at is null
    ) g on true
    where c.organization_id=v_org and c.record_status in ('provisional','active','inactive')
      and exists(select 1 from public.child_clinic_enrollments e where e.child_id=c.id and e.clinic_id=p_clinic_id and e.status in ('pending','active'))
      and (p_dob is null or c.dob=p_dob)
      and (length(v_q)<2 or c.search_name like v_like or extensions.similarity(c.search_name,v_q)>=0.3 or upper(btrim(p_query))=c.local_record_no or coalesce(g.score,0)>0)
    order by greatest(extensions.similarity(c.search_name,v_q),case when c.search_name like v_like then 0.9 else 0 end,case when upper(btrim(p_query))=c.local_record_no then 1 else 0 end,coalesce(g.score,0)) desc,c.display_name,c.id
    limit v_lim
  ) s;
  perform private.audit(v_org,'child.search','child.search','clinic',p_clinic_id,null,jsonb_build_object('queryLength',length(v_q),'withDob',p_dob is not null,'results',jsonb_array_length(v_res)),null);
  return v_res;
end $$;

create or replace function public.guardian_child_notes(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
  if not private.guardian_has_full_access(p_child_id) or not private.session_ok() then raise exception 'not found' using errcode='CV404'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('noteId',n.id,'category',n.category,'note',n.note,'createdAt',n.created_at,'authorName',p.display_name,'clinicName',c.name) order by n.created_at desc) from public.child_staff_notes n join public.profiles p on p.id=n.created_by join public.clinics c on c.id=n.clinic_id where n.child_id=p_child_id and n.family_visible),'[]'::jsonb);
end $$;

create or replace function public.list_child_notes(p_clinic_id uuid,p_child_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_org uuid; v_clinical boolean;
begin
  perform private.require_capability(p_clinic_id,'child.search');
  select organization_id into v_org from public.clinics where id=p_clinic_id;
  if v_org is null or not private.child_in_clinic(p_child_id,p_clinic_id) then raise exception 'not found' using errcode='CV404'; end if;
  v_clinical:=private.has_capability(p_clinic_id,'child.read_clinical');
  return coalesce((select jsonb_agg(jsonb_build_object('noteId',n.id,'category',n.category,'note',n.note,'familyVisible',n.family_visible,'eventId',n.event_id,'createdAt',n.created_at,'authorName',p.display_name) order by n.created_at desc) from public.child_staff_notes n join public.profiles p on p.id=n.created_by where n.organization_id=v_org and n.clinic_id=p_clinic_id and n.child_id=p_child_id and (v_clinical or n.category<>'post_vaccination')),'[]'::jsonb);
end $$;
-- END 0052_guardian_search_note_access.sql

-- =====================================================================================================================
-- BEGIN 0053_bhw_registry_access.sql  sha256=ca18d88f165b66d1592729dbee9d21015f858812e64d952ab697fb2a64100752
-- =====================================================================================================================
-- BHWs can find families and enter non-clinical registration details; clinical history and vaccine administration remain restricted.
create or replace function private.role_preset(p_role text) returns text[] language sql immutable as $$
  select case p_role
    when 'assistant' then array['child.search','child.register','guardian.verify','appointment.manage','queue.manage']
    when 'clinical_staff' then array['child.search','child.register','child.read_clinical','guardian.verify','appointment.manage','queue.manage','vaccination.record','evidence.verify','rules.propose']
    when 'clinical_lead' then array['child.search','child.register','child.read_clinical','guardian.verify','appointment.manage','queue.manage','vaccination.record','evidence.verify','rules.propose','correction.approve','rules.approve','review.resolve','certificate.issue','audit.read','export.identifiable','inventory.approve','grant.approve.clinical','report.run']
    when 'inventory' then array['inventory.manage']
    when 'bhw' then array['bhw.followup','child.search','child.register']
    when 'tech_admin' then array['admin.users','admin.config']
    else array[]::text[] end
$$;
-- END 0053_bhw_registry_access.sql

-- =====================================================================================================================
-- BEGIN 0054_admin_staff_creation.sql  sha256=fff29f40726efd63cd12ed3a72cf7b20ab9fe49ce030357ae9c4471729198be1
-- =====================================================================================================================
-- A server-side signup and its clinic access request are retried under one administrator-owned operation.
create table private.staff_account_creations (
  operation_key uuid primary key,
  clinic_id uuid not null references public.clinics(id),
  created_by uuid not null references public.profiles(id),
  email text not null,
  payload jsonb not null,
  result jsonb,
  created_at timestamptz not null default now()
);
revoke all on private.staff_account_creations from public,anon,authenticated;

create function public.prepare_staff_account_creation(p_operation_key uuid,p_clinic_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_org uuid; v_prev jsonb; v_email text:=lower(btrim(p_payload->>'email')); v_profile uuid; v_saved private.staff_account_creations;
begin
  perform private.require_capability(p_clinic_id,'admin.users');
  select organization_id into v_org from public.clinics where id=p_clinic_id;
  if char_length(coalesce(v_email,'')) not between 3 and 200 or position('@' in v_email)=0 or char_length(btrim(coalesce(p_payload->>'fullName',''))) not between 1 and 120
    or p_payload->>'role' not in ('assistant','clinical_staff','clinical_lead','inventory','bhw','tech_admin') or coalesce(p_payload->>'passwordHash','') !~ '^[a-f0-9]{64}$' then raise exception 'check the account details' using errcode='CV422'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('staff-create:'||v_email,0));
  v_prev:=private.begin_command(v_org,p_operation_key,'staff_account.create',jsonb_build_object('clinic',p_clinic_id,'payload',p_payload));
  if v_prev is not null then return v_prev; end if;
  select * into v_saved from private.staff_account_creations where operation_key=p_operation_key;
  if found and (v_saved.created_by<>auth.uid() or v_saved.clinic_id<>p_clinic_id) then raise exception 'operation key reused' using errcode='CV409'; end if;
  select id into v_profile from auth.users where lower(email)=v_email;
  if v_profile is not null and not exists(select 1 from auth.users where id=v_profile and raw_user_meta_data->>'staff_creation_key'=p_operation_key::text) then raise exception 'that email already has an account; use Staff access for existing accounts' using errcode='CV409'; end if;
  insert into private.staff_account_creations(operation_key,clinic_id,created_by,email,payload) values(p_operation_key,p_clinic_id,auth.uid(),v_email,p_payload) on conflict(operation_key) do nothing;
  return jsonb_build_object('profileId',v_profile,'status','creating');
end $$;

create function public.complete_staff_account_creation(p_operation_key uuid,p_clinic_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare c private.staff_account_creations; v_profile uuid; a public.staff_applications; v_result jsonb; v_org uuid;
begin
  perform private.require_capability(p_clinic_id,'admin.users');
  select * into c from private.staff_account_creations where operation_key=p_operation_key and clinic_id=p_clinic_id and created_by=auth.uid() for update;
  if not found then raise exception 'not found' using errcode='CV404'; end if;
  if c.result is not null then return c.result; end if;
  select id into v_profile from auth.users where lower(email)=c.email and raw_user_meta_data->>'staff_creation_key'=p_operation_key::text;
  if v_profile is null then raise exception 'account creation is not yet confirmed; retry with the same details' using errcode='CV409'; end if;
  select * into a from public.staff_applications where clinic_id=p_clinic_id and profile_id=v_profile and status='pending' order by created_at desc limit 1;
  if not found then raise exception 'the account exists but its staff application is unavailable; check Staff applications' using errcode='CV409'; end if;
  v_result:=public.accept_staff_application(gen_random_uuid(),p_clinic_id,a.id,a.version,c.payload->>'role','{}'::text[]);
  select organization_id into v_org from public.clinics where id=p_clinic_id;
  v_result:=v_result||jsonb_build_object('email',c.email,'role',c.payload->>'role','status','pending_approval','applicationStatus','accepted','mfaRequired',true);
  update private.staff_account_creations set result=v_result where operation_key=p_operation_key;
  perform private.audit(v_org,'admin.users','staff_account.created','profile',v_profile,null,jsonb_build_object('clinicId',p_clinic_id,'role',c.payload->>'role','membershipId',v_result->>'membershipId'),null);
  return private.finish_command(v_org,p_operation_key,v_result);
end $$;
revoke all on function public.prepare_staff_account_creation(uuid,uuid,jsonb),public.complete_staff_account_creation(uuid,uuid) from public,anon,authenticated;
grant execute on function public.prepare_staff_account_creation(uuid,uuid,jsonb),public.complete_staff_account_creation(uuid,uuid) to authenticated;
-- END 0054_admin_staff_creation.sql

-- =====================================================================================================================
-- BEGIN 0055_note_author_role.sql  sha256=866141b38e9153c5f1b1cc1a677c2d18e773262ba0c2db3b1af6588c47741ee4
-- =====================================================================================================================
alter table public.child_staff_notes add column author_role text;
create function private.stamp_note_role() returns trigger language plpgsql security definer set search_path='' as $$
declare v_cap text;
begin
  v_cap:=case new.category when 'post_vaccination' then 'vaccination.record' when 'follow_up' then case when private.has_capability(new.clinic_id,'vaccination.record') then 'vaccination.record' else 'bhw.followup' end else 'child.register' end;
  select m.role_code into new.author_role from public.staff_memberships m
  where m.profile_id=new.created_by and m.clinic_id=new.clinic_id and m.status='active' and m.valid_from<=now() and (m.valid_until is null or m.valid_until>now())
    and (v_cap=any(private.role_preset(m.role_code)) or v_cap=any(m.capabilities))
  order by m.created_at,m.id limit 1;
  return new;
end $$;
revoke all on function private.stamp_note_role() from public,anon,authenticated;
create trigger child_staff_notes_role before insert on public.child_staff_notes for each row execute function private.stamp_note_role();

create or replace function public.list_child_notes(p_clinic_id uuid,p_child_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_org uuid; v_clinical boolean;
begin
  perform private.require_capability(p_clinic_id,'child.search');
  select organization_id into v_org from public.clinics where id=p_clinic_id;
  if v_org is null or not private.child_in_clinic(p_child_id,p_clinic_id) then raise exception 'not found' using errcode='CV404'; end if;
  v_clinical:=private.has_capability(p_clinic_id,'child.read_clinical');
  return coalesce((select jsonb_agg(jsonb_build_object('noteId',n.id,'category',n.category,'note',n.note,'familyVisible',n.family_visible,'eventId',case when v_clinical then n.event_id end,'createdAt',n.created_at,'authorName',p.display_name,'authorRole',n.author_role) order by n.created_at desc) from public.child_staff_notes n join public.profiles p on p.id=n.created_by where n.organization_id=v_org and n.clinic_id=p_clinic_id and n.child_id=p_child_id and (v_clinical or n.category<>'post_vaccination')),'[]'::jsonb);
end $$;
create or replace function public.guardian_child_notes(p_child_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
  if not private.guardian_has_full_access(p_child_id) or not private.session_ok() then raise exception 'not found' using errcode='CV404'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('noteId',n.id,'category',n.category,'note',n.note,'eventId',n.event_id,'createdAt',n.created_at,'authorName',p.display_name,'authorRole',n.author_role,'clinicName',c.name) order by n.created_at desc) from public.child_staff_notes n join public.profiles p on p.id=n.created_by join public.clinics c on c.id=n.clinic_id where n.child_id=p_child_id and n.family_visible),'[]'::jsonb);
end $$;
-- END 0055_note_author_role.sql

-- =====================================================================================================================
-- BEGIN 0056_card_record_continuity.sql  sha256=68b00b640c93d5ff5c3ec85cfb301ca66f9b77a3ab87630363cd3eb730ec1674
-- =====================================================================================================================
-- Merge relinks note ownership only; the original content, author, role and time remain immutable.
create function private.note_change_guard() returns trigger language plpgsql set search_path='' as $$
begin
  if tg_op='UPDATE' and (to_jsonb(new)-'child_id')=(to_jsonb(old)-'child_id') and new.child_id<>old.child_id and new.child_id=private.canonical_child(old.child_id) then return new; end if;
  raise exception 'notes are immutable' using errcode='CV403';
end $$;
revoke all on function private.note_change_guard() from public,anon,authenticated;
drop trigger child_staff_notes_immutable on public.child_staff_notes;
create trigger child_staff_notes_immutable before update or delete on public.child_staff_notes for each row execute function private.note_change_guard();

create function private.card_note_merge_continuity() returns trigger language plpgsql security definer set search_path='' as $$
declare v_cards int; v_notes int;
begin
  update public.card_submissions set child_id=new.merged_into_id where child_id=new.id;
  get diagnostics v_cards=row_count;
  update public.child_staff_notes set child_id=new.merged_into_id where child_id=new.id;
  get diagnostics v_notes=row_count;
  if v_cards>0 or v_notes>0 then
    perform private.audit(new.organization_id,'review.resolve','child.card_notes_merged','child',new.id,null,jsonb_build_object('survivorId',new.merged_into_id,'cards',v_cards,'notes',v_notes),null);
  end if;
  return new;
end $$;
revoke all on function private.card_note_merge_continuity() from public,anon,authenticated;
create trigger children_card_notes_merge after update of merged_into_id on public.children for each row when(new.merged_into_id is not null and old.merged_into_id is distinct from new.merged_into_id) execute function private.card_note_merge_continuity();

create function private.card_transfer_continuity() returns trigger language plpgsql security definer set search_path='' as $$
declare v_count int;
begin
  update public.card_submissions set clinic_id=new.to_clinic_id,version=version+1,updated_at=now()
  where child_id=new.child_id and clinic_id=new.from_clinic_id and status in ('pending','changes_requested');
  get diagnostics v_count=row_count;
  if v_count>0 then
    perform private.audit(new.organization_id,'child.register','card.transfer_routed','record_transfer',new.id,null,jsonb_build_object('toClinicId',new.to_clinic_id,'cards',v_count),null);
  end if;
  return new;
end $$;
revoke all on function private.card_transfer_continuity() from public,anon,authenticated;
create trigger record_transfers_card_route after update of status on public.record_transfers for each row when(new.status='completed' and old.status is distinct from new.status) execute function private.card_transfer_continuity();

-- Share the merge/transfer child lock before final routing, so an in-flight draft cannot be inserted into an obsolete record.
create function private.card_write_route() returns trigger language plpgsql security definer set search_path='' as $$
begin
  perform 1 from public.children where id=private.canonical_child(new.child_id) for share;
  if tg_op='INSERT' or (new.rows is distinct from old.rows) then
    new.child_id:=private.canonical_child(new.child_id);
    if new.submitted_by<>auth.uid() or not private.guardian_can_read_child(new.child_id) then raise exception 'not found' using errcode='CV404'; end if;
    select clinic_id into new.clinic_id from public.child_clinic_enrollments where child_id=new.child_id and status in ('pending','active') order by is_primary desc,created_at limit 1;
    if new.clinic_id is null then raise exception 'a clinic is required' using errcode='CV422'; end if;
  end if;
  return new;
end $$;
revoke all on function private.card_write_route() from public,anon,authenticated;
create trigger card_submissions_route before insert or update of rows,child_id,clinic_id on public.card_submissions for each row execute function private.card_write_route();

-- Acquire the child lock before the submission-row lock, matching merge and transfer command order.
alter function public.submit_card_record(uuid,uuid,jsonb,uuid,integer) set schema private;
alter function private.submit_card_record(uuid,uuid,jsonb,uuid,integer) rename to submit_card_record_impl;
revoke all on function private.submit_card_record_impl(uuid,uuid,jsonb,uuid,integer) from public,anon,authenticated;
create function public.submit_card_record(p_operation_key uuid,p_child_id uuid,p_rows jsonb,p_submission_id uuid default null,p_expected_version integer default null) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
  perform 1 from public.children where id=p_child_id for share;
  return private.submit_card_record_impl(p_operation_key,p_child_id,p_rows,p_submission_id,p_expected_version);
end $$;
revoke all on function public.submit_card_record(uuid,uuid,jsonb,uuid,integer) from public,anon,authenticated;
grant execute on function public.submit_card_record(uuid,uuid,jsonb,uuid,integer) to authenticated;

create function private.note_write_lock() returns trigger language plpgsql security definer set search_path='' as $$
begin
  perform 1 from public.children where id=new.child_id for share;
  if not private.child_in_clinic(new.child_id,new.clinic_id) then raise exception 'not found' using errcode='CV404'; end if;
  return new;
end $$;
revoke all on function private.note_write_lock() from public,anon,authenticated;
create trigger child_staff_notes_lock before insert on public.child_staff_notes for each row execute function private.note_write_lock();
-- END 0056_card_record_continuity.sql

-- =====================================================================================================================
-- BEGIN 0057_card_review_lock_order.sql  sha256=91a9f05902f1d1ba510e95cd87ca4df0257299f9cbaf73e279c8db7effed2fae
-- =====================================================================================================================
-- Match merge and transfer lock order before touching a card submission.
alter function public.review_card_submission(uuid,uuid,uuid,text,text,integer,jsonb) set schema private;
alter function private.review_card_submission(uuid,uuid,uuid,text,text,integer,jsonb) rename to review_card_submission_impl;
revoke all on function private.review_card_submission_impl(uuid,uuid,uuid,text,text,integer,jsonb) from public,anon,authenticated;
create function public.review_card_submission(p_operation_key uuid,p_clinic_id uuid,p_submission_id uuid,p_decision text,p_note text,p_expected_version integer,p_reviewed_rows jsonb default '[]') returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_child uuid;
begin
  perform private.require_capability(p_clinic_id,'evidence.verify');
  select child_id into v_child from public.card_submissions where id=p_submission_id and clinic_id=p_clinic_id;
  if v_child is null then raise exception 'not found' using errcode='CV404'; end if;
  perform 1 from public.children where id=v_child for share;
  if not exists(select 1 from public.card_submissions where id=p_submission_id and child_id=v_child and clinic_id=p_clinic_id) then
    raise exception 'submission changed; reload' using errcode='CV409';
  end if;
  return private.review_card_submission_impl(p_operation_key,p_clinic_id,p_submission_id,p_decision,p_note,p_expected_version,p_reviewed_rows);
end $$;
revoke all on function public.review_card_submission(uuid,uuid,uuid,text,text,integer,jsonb) from public,anon,authenticated;
grant execute on function public.review_card_submission(uuid,uuid,uuid,text,text,integer,jsonb) to authenticated;
-- END 0057_card_review_lock_order.sql

